INSERT INTO `locales_spell` VALUES (71, 'Defensive Stance', '', '', '', '防御姿态', '', '', '', '', '', '', '', '', '', 'A defensive combat stance.  Decreases damage taken by $7376s1% and damage caused by $7376s2%.  Increases threat generated.', '', '', '', '防御型的战斗姿态，被击中时所受到的伤害降低$7376s1%，自身的攻击伤害降低$7376s2%。提高威胁值的产生速度。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (72, 'Shield Bash', '', '', '', '盾击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Bashes the target with your shield for $s2 damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for $d.', '', '', '', '使用你的盾牌重击目标，对其造成$s2点伤害，并使其无法施放法术，持续$d。', '', '', '', '', '', '', '', '', '');
