INSERT INTO `locales_spell` VALUES (89, 'Cripple', '', '', '', '残废术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Cripples the target, reducing movement speed by $s3%, increasing time between melee attacks by $s1% and increasing time between ranged attacks by $s2%.  Lasts $d.', '', '', '', '使目标残废，移动速度降低$s3%，近战攻击间隔延长$s1%，远程攻击间隔延长$s2%。持续$d。', '', '', 'Movement speed reduced by $s3%.  Time between melee attacks increased by $s1%.  Time between ranged attacks increased by $s2%.', '', '', '', '移动速度降低$s3%，近战攻击间隔延长$s1%，远程攻击间隔延长$s2%。', '', '');
