INSERT INTO `locales_spell` VALUES (99, 'Demoralizing Roar', '', '', '', '挫志咆哮', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The druid roars, decreasing nearby enemies\' melee attack power by $s1.  Lasts $d.', '', '', '', '德鲁伊发出咆哮，使附近所有敌人的近战攻击强度降低$s1点，持续$d。', '', '', 'Decreases melee attack power by $s1.', '', '', '', '近战攻击强度降低$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (100, 'Charge', '', '', '', '冲锋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Charge an enemy, generate $/10;s2 rage, and stun it for $7922d.  Cannot be used in combat.', '', '', '', '向敌人冲锋，产生$/10;s2点怒气值，并使其昏迷$7922d。无法在战斗中使用。', '', '', '', '', '', '', '', '', '');
