INSERT INTO `locales_spell` VALUES (113, 'Chains of Ice', '', '', '', '冰链术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Forms icy chains around the enemy, locking the target in place for $d.', '', '', '', '在敌人周围形成冰封的链条，将目标锁定在原地，持续$d。', '', '', 'Rooted in place.', '', '', '', '被定身在原地。', '', '');
INSERT INTO `locales_spell` VALUES (114, 'Frost Shield', '', '', '', '冰霜护盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Surrounds the target with a shield of frost, damaging and slowing the target\'s attackers.  Lasts $d.', '', '', '', '用冰霜护盾包围目标，对攻击目标的敌人造成伤害并减速。持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (116, 'Frostbolt', '', '', '', '寒冰箭', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Launches a bolt of frost at the enemy, causing $s2 Frost damage and slowing movement speed by $s1% for $d.', '', '', '', '向目标射出一支寒冰箭，对其造成$s2点冰霜伤害，并使其移动速度降低$s1%，持续$d。', '', '', 'Movement slowed by $s1%.', '', '', '', '移动速度降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (118, 'Polymorph', '', '', '', '变形术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (120, 'Cone of Cold', '', '', '', '冰锥术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Targets in a $a1 yard cone in front of the caster take $s2 Frost damage and are slowed by $s1% for $d.', '', '', '', '施法者前方 $a1 码锥形范围内的目标会受到 $s2 冰霜伤害，并减速 $s1%，持续 $d。', '', '', 'Movement slowed by $s1%.', '', '', '', '移动速度降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (122, 'Frost Nova', '', '', '', '冰霜新星', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Blasts enemies within $a1 yards near the caster for $s1 Frost damage and freezes them in place for up to $d.  Damage caused may interrupt the effect.', '', '', '', '对施法者附近 $a1 码内的敌人进行爆炸，造成 $s1 冰霜伤害，并将其冻结在原地，最多造成 $d。造成的伤害可能会中断效果。', '', '', 'Frozen in place.', '', '', '', '被冻结在原地。', '', '');
