INSERT INTO `locales_spell` VALUES (126, 'Eye of Kilrogg', '', '', '', '基尔罗格之眼', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons an Eye of Kilrogg and binds your vision to it.  The eye moves quickly but is very fragile.', '', '', '', '召唤一颗基尔罗格之眼，并让你以它的视角观察世界。基尔罗格之眼速度很快，但也非常脆弱。', '', '', 'Controlling Eye of Kilrogg.', '', '', '', '正在控制基尔罗格之眼。', '', '');
INSERT INTO `locales_spell` VALUES (128, 'Spellstone', '', '', '', '法术石', '', '', '', '', '', '', '', '', '', 'Removes all magic effects from the caster and will absorb $s2 magic damage for $d.', '', '', '', '移除附加在施法者身上的所有魔法效果，在接下来的$d内可吸收最多$s2点魔法伤害。', '', '', 'Absorbs magic damage.', '', '', '', '吸收魔法伤害。', '', '');
INSERT INTO `locales_spell` VALUES (130, 'Slow Fall', '', '', '', '缓落术', '', '', '', '', '', '', '', '', '', 'Slows falling speed for $d.', '', '', '', '减慢下落速度，持续$d。', '', '', 'Slows falling speed.', '', '', '', '减慢下落速度。', '', '');
INSERT INTO `locales_spell` VALUES (131, 'Water Breathing', '', '', '', '水下呼吸', '', '', '', '', '', '', '', '', '', 'Allows the target to breathe underwater for $d.', '', '', '', '使目标可以在水下自由呼吸，持续$d。', '', '', 'Waterbreathing.', '', '', '', '水下呼吸。', '', '');
INSERT INTO `locales_spell` VALUES (132, 'Detect Lesser Invisibility', '', '', '', '侦测次级隐形', '', '', '', '', '', '', '', '', '', 'Allows the friendly target to detect lesser invisibility for $d.', '', '', '', '让友方目标能够侦查到次级隐形术，持续$d。', '', '', 'Detect lesser invisibility.', '', '', '', '侦测次级隐形术。', '', '');
