INSERT INTO `locales_spell` VALUES (134, 'Fire Shield', '', '', '', '火焰之盾', '', '', '', '', '', '', '', '', '', 'Surrounds an ally with a shield of flame that inflicts $3052s1 Fire damage to nearby enemies every $t1 sec.  Lasts $d.', '', '', '', '为盟友施加火焰之盾，每$t1秒对施法者周围的所有敌人造成$3052s1点火焰伤害，持续$d。', '', '', 'Inflicting $3052s1 Fire damage to nearby enemies every $t1 sec.', '', '', '', '每$t1秒对施法者周围的所有敌人造成$3052s1点火焰伤害。', '', '');
