INSERT INTO `locales_spell` VALUES (324, 'Lightning Shield', '', '', '', '闪电之盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26364s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.  Only one elemental shield can be active on the Shaman at any one time.', '', '', '', '施法者被$n个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到$26364s1点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续$d。', '', '', 'Causes $26364s1 Nature damage to attacker on hit.', '', '', '', '在被击中后对攻击者造成$26364s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (325, 'Lightning Shield', '', '', '', '闪电之盾', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26365s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.  Only one elemental shield can be active on the Shaman at any one time.', '', '', '', '施法者被$n个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到$26365s1点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续$d。', '', '', 'Causes $26365s1 Nature damage to attacker on hit.', '', '', '', '在被击中后对攻击者造成$26365s1点自然伤害。', '', '');
