INSERT INTO `locales_spell` VALUES (547, 'Healing Wave', '', '', '', '治疗波', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Heals a friendly target for $s1.', '', '', '', '治疗友方目标，恢复$s1点生命值。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (548, 'Lightning Bolt', '', '', '', '闪电箭', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Casts a bolt of lightning at the target for $s1 Nature damage.', '', '', '', '向目标射出闪电箭，对其造成$s点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (549, 'Undying Strength', '', '', '', '永生力量', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Infuses the target with the spirits of the ancients, increasing $ghis:her; Strength by $s1 for $d.', '', '', '', '将古人的灵魂注入目标，在$d内为$ghis:her;提高$s1点力量。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (550, 'Nullify Poison', '', '', '', '消毒术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Target is immune to poison for $d and is cured of any existing poisons.', '', '', '', '目标对毒素免疫，并且治愈所有当前中毒状态，持续时间$d。', '', '', 'Immune to Poison.', '', '', '', '免疫毒药。', '', '');
INSERT INTO `locales_spell` VALUES (552, 'Abolish Disease', '', '', '', '驱除疾病', '', '', '', '', '', '', '', '', '', 'Attempts to cure $s2 disease effect on the target, and $10872s1 more disease effect every $t1 seconds for $d.', '', '', '', '尝试驱散目标身上的$s2个疾病效果，并每$t1秒驱散$10872s1个疾病效果，持续$d。', '', '', 'Attempts to dispel $10872s1 disease every $t1 seconds.', '', '', '', '每$t1秒驱散$10872s1个疾病效果。', '', '');
