INSERT INTO `locales_spell` VALUES (578, 'Black Wolf', '', '', '', '黑狼', '', '', '', '', '', '', '', '', '', 'Once thought to be nearly extinct, this wolf can still occasionally be seen in the company of a few Horde veterans.', '', '', '', '曾经被认为几乎灭绝的狼，现在仍然偶尔可以在一些部落老兵的陪伴下看到。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (579, 'Red Wolf', '', '', '', '赤狼', '', '', '', '', '', '', '', '', '', 'Almost none remain in the whole of Azeroth; only the most experienced will have seen one.', '', '', '', '整个艾泽拉斯几乎没有留下任何痕迹。只有最有经验的人才会看到它。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (580, 'Large Timber Wolf', '', '', '', '棕狼', '', '', '', '', '', '', '', '', '', 'Can howl loudly enough to be heard for miles.', '', '', '', '可以大声嚎叫，几英里之外都能听到。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (581, 'Winter Wolf', '', '', '', '冬狼', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable winter wolf.', '', '', '', '召唤或解散一头可供骑乘的冬狼。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (585, 'Smite', '', '', '', '惩击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Smite an enemy for $s1 Holy damage.', '', '', '', '对单体目标造成$s1点神圣伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (586, 'Fade', '', '', '', '渐隐术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fade out, discouraging enemies from attacking you for $d.', '', '', '', '渐渐消失，使敌人不再攻击你，持续$d。', '', '', 'Reduced threat level.', '', '', '', '降低威胁等级。', '', '');
INSERT INTO `locales_spell` VALUES (587, 'Conjure Food', '', '', '', '造食术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Conjures $s1 $lmuffin:muffins;, providing the mage and $ghis:her; allies with something to eat.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '用魔法合成$s1块魔法松饼以供法师和$g他:她;的盟友食用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (588, 'Inner Fire', '', '', '', '心灵之火', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A burst of Holy energy fills the caster, increasing armor by $s1 and attack power by $s2.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.', '', '', '', '圣洁的能量充满施法者的体内，使$g他:她;的防御值提高$s1点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续$d，或在$n次防护之后消失。', '', '', 'Increases armor by $s1.', '', '', '', '防御值提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (589, 'Shadow Word: Pain', '', '', '', '暗言术：痛', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A word of darkness that causes $o1 Shadow damage over $d.', '', '', '', '黑暗的咒语，在$d内造成总计$o1点暗影伤害。', '', '', '$s1 Shadow damage every $t1 seconds.', '', '', '', '每$t1秒$s1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (590, 'Holy Word: Might', '', '', '', '圣言术：力', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Holy might infuses the target increasing their strength by $s1 for $d.', '', '', '', '圣洁的能量充满目标全身，令其力量提高$s1点，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (591, 'Smite', '', '', '', '惩击', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Smite an enemy for $s1 Holy damage.', '', '', '', '对单体目标造成$s1点神圣伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (592, 'Power Word: Shield', '', '', '', '真言术：盾', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Draws on the soul of the party member to shield them, absorbing $s1 damage.  Lasts $d.  While the shield holds, spellcasting will not be interrupted by damage.  Once shielded, the target cannot be shielded again for $6788d.', '', '', '', '立即为队友加上魔法护盾，可吸收$s1点伤害，持续$d。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的$6788d内无法再被加上护盾。', '', '', 'Absorbs damage.', '', '', '', '吸收伤害。', '', '');
INSERT INTO `locales_spell` VALUES (593, 'Shadow Word: Fumble', '', '', '', '暗言术：拙', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A word of darkness that reduces the target\'s chance to hit by $s1% for $d.', '', '', '', '黑暗的咒语，使目标的命中率降低$s1%，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (594, 'Shadow Word: Pain', '', '', '', '暗言术：痛', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'A word of darkness that causes $o1 Shadow damage over $d.', '', '', '', '黑暗的咒语，在$d内造成总计$o1点暗影伤害。', '', '', '$s1 Shadow damage every $t1 seconds.', '', '', '', '每$t1秒$s1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (595, 'Prayer of Protection', '', '', '', '防护祷言', '', '', '', '', '', '', '', '', '', 'Increase party\'s armor until duration expires or the priest stops praying.', '', '', '', '提高队友的护甲值，直到法术生效期结束，或者牧师终止祈祷。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (596, 'Prayer of Healing', '', '', '', '治疗祷言', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A powerful prayer heals party members within $a1 yards for $s1.', '', '', '', '强大的祷言，可以治疗附近半径$a1码范围内的所有小队成员。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (597, 'Conjure Food', '', '', '', '造食术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Conjures $s1 $lloaf:loaves; of bread, providing the mage and $ghis:her; allies with something to eat.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '用魔法合成$s1块魔法面包以供法师和$g他:她;的盟友食用。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (598, 'Smite', '', '', '', '惩击', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Smite an enemy for $s1 Holy damage.', '', '', '', '对单体目标造成$s1点神圣伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (599, 'Holy Word: Might', '', '', '', '圣言术：力', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Holy might infuses the target increasing their strength by $s1 for $d.', '', '', '', '圣洁的能量充满目标全身，令其力量提高$s1点，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (600, 'Power Word: Shield', '', '', '', '真言术：盾', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Draws on the soul of the party member to shield them, absorbing $s1 damage.  Lasts $d.  While the shield holds, spellcasting will not be interrupted by damage.  Once shielded, the target cannot be shielded again for $6788d.', '', '', '', '立即为队友加上魔法护盾，可吸收$s1点伤害，持续$d。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的$6788d内无法再被加上护盾。', '', '', 'Absorbs damage.', '', '', '', '吸收伤害。', '', '');
INSERT INTO `locales_spell` VALUES (601, 'Sword Mastery', '', '', '', '剑类武器掌握', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases your attack rating with One-Handed Swords by $s1.', '', '', '', '使你的单手剑的攻击力提高$s1点。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (602, 'Inner Fire', '', '', '', '心灵之火', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'A burst of Holy energy fills the caster, increasing armor by $s1 and attack power by $s2.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.', '', '', '', '圣洁的能量充满施法者的体内，使$g他:她;的防御值提高$s1点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续$d，或在$n次防护之后消失。', '', '', 'Increases armor by $s1.', '', '', '', '防御值提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (603, 'Curse of Doom', '', '', '', '厄运诅咒', '', '', '', '', '', '', '', '', '', 'Curses the target with impending doom, causing $s1 Shadow damage after $d.  If the target dies from this damage, there is a chance that a Doomguard will be summoned.  Cannot be cast on players.', '', '', '', '对目标施加终极的诅咒，在$d后造成$s1点暗影伤害。如果目标死于该伤害，则有一定几率召唤出一个末日守卫来。无法对玩家施放。', '', '', 'Causes $s1 Shadow damage after $d.', '', '', '', '在$d后造成$s1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (604, 'Dampen Magic', '', '', '', '魔法抑制', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Dampens magic used against the targeted party member, decreasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.', '', '', '', '降低施放于目标小队成员身上的魔法效果，使其受到的法术伤害降低最多$s1点，治疗法术恢复生命值的效果降低最多$s2点，持续$d。', '', '', 'Reduces magic damage taken by up to $s1 and healing by up to $s2.', '', '', '', '降低法术伤害，最多$s1点。\n降低法术治疗效果，最多$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (605, 'Mind Control', '', '', '', '精神控制', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Controls a humanoid mind up to level $s1, but increases the time between its attacks by $s3%.  Lasts up to $d.', '', '', '', '控制一个最高等级为$s1的人型目标，但是使其攻击间隔延长$s3%。最多持续$d。', '', '', 'Charmed.  Time between attacks increased by $s3%.', '', '', '', '被魅惑，攻击间隔延长$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (606, 'Mind Rot', '', '', '', '心灵腐蚀', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Drains $o1 mana from the target over $d.', '', '', '', '从目标身上吸取$o1点法力值，持续$d。', '', '', 'Mana drain, $s1 points every 5 seconds.', '', '', '', '消耗魔法值，每5秒消耗$s1点。', '', '');
