INSERT INTO `locales_spell` VALUES (633, 'Lay on Hands', '', '', '', '圣疗术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Heals a friendly target for an amount equal to the Paladin\'s maximum health.  Drains all of the Paladin\'s remaining mana when used.', '', '', '', '治疗一个友方目标，为其恢复相当于圣骑士的最大生命值的生命值。使用这一法术将消耗圣骑士所有的法力值。', '', '', '', '', '', '', '', '', '');
