INSERT INTO `locales_spell` VALUES (642, 'Divine Shield', '', '', '', '圣盾术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Protects the paladin from all damage and spells for $d, but decreases the damage you deal with all attacks and spells by $s2%.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for $25771d.', '', '', '', '使圣骑士对所有的伤害和法术攻击免疫，持续$d，但你所有攻击所造成的伤害减少$s2%。在受保护之后，圣盾术、保护祝福或圣佑术在$25771d之内无法作用在你身上。', '', '', 'Immune to all attacks and spells, but decreases damage caused by $s2%.', '', '', '', '免疫所有攻击和法术，但减少 $s2% 造成的伤害。', '', '');
INSERT INTO `locales_spell` VALUES (643, 'Devotion Aura', '', '', '', '虔诚光环', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Gives $s1 additional armor to party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使半径$a1码范围内的所有小队成员获得$s1点额外的护甲。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Increases armor by $s1.', '', '', '', '护甲值提高$s1点。', '', '');
