INSERT INTO `locales_spell` VALUES (648, 'Blessing of Reckoning', '', '', '', '清算圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Places a Blessing on a friendly target that lasts $d.  Every time the Blessed character strikes an enemy, the Blessed character gains $1136s1 health.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加圣印，持续$d。被施加圣印的目标每次使用近战武器击中敌人，就可以恢复$1136s1点生命值。每个圣骑士在同一时间内只能给目标施加一个圣印，且同类型的圣印在同一个目标身上只能存在一个。', '', '', 'Every time you strike an enemy you get $1136s1 health.', '', '', '', '每次命中敌人，你都会恢复$1136s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (649, 'Healing Aura', '', '', '', '治疗光环', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the health regeneration of the Paladin and nearby group members by $s1 every 5 seconds.  Only works out of combat.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使圣骑士和附近所有小队成员每5秒钟恢复$s1点生命值，只有在非战斗状态下会发生作用。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Increases health regen by $s1 every 5 seconds when out of combat.', '', '', '', '非战斗状态下每5秒恢复$s1点生命值。', '', '');
