INSERT INTO `locales_spell` VALUES (689, 'Drain Life', '', '', '', '吸取生命', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Transfers $s1 health every second from the target to the caster.  Lasts $d.', '', '', '', '每秒钟吸取目标$s1点生命值，并将其转移给施法者，持续$d。', '', '', 'Drains $s1 health each second to the caster.', '', '', '', '每秒吸取$s1点生命值并将其转移给施法者。', '', '');
