INSERT INTO `locales_spell` VALUES (693, 'Create Soulstone (Minor)', '', '', '', '制造初级灵魂石', '', '', '', '', '', '', '', '', '', 'Creates a Minor Soulstone.  The Soulstone can be used to store one target\'s soul.  If the target dies while his soul is stored, he will be able to resurrect with $3026s1 health and $3026q1 mana.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块初级灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复$3026s1点生命值和$3026q1点法力值。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (694, 'Mocking Blow', '', '', '', '惩戒痛击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A mocking attack that causes $s1 damage, a moderate amount of threat and forces the target to focus attacks on you for $d.', '', '', '', '对目标造成$s1点额外伤害和中量的威胁，并迫使它在$d内一直攻击你。', '', '', 'Taunted.', '', '', '', '被嘲讽。', '', '');
INSERT INTO `locales_spell` VALUES (695, 'Shadow Bolt', '', '', '', '暗影箭', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Sends a shadowy bolt at the enemy, causing $s1 Shadow damage.', '', '', '', '向目标射出一支暗影箭，对其造成$s1点暗影伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (696, 'Demon Skin', '', '', '', '恶魔皮肤', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Protects the caster, increasing armor by $m1 and restores $s2 Health per 5 sec. for $d.', '', '', '', '使施法者的护甲提高$m1点，每5秒恢复$s2点生命值，持续$d。', '', '', 'Increases armor by $s1 and restores $s2 Health per 5 sec.', '', '', '', '护甲值提高$s1点，每5秒恢复$s2点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (697, 'Summon Voidwalker', '', '', '', '召唤虚空行者', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a Voidwalker under the command of the Warlock.', '', '', '', '召唤一个虚空行者为术士作战。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (698, 'Ritual of Summoning', '', '', '', '召唤仪式', '', '', '', '', '', '', '', '', '', 'Begins a ritual that summons the targeted group member.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.', '', '', '', '开启一个召唤指定队友的传送门。需要施法者和2名队友共同完成召唤仪式。所有参与召唤的队友都必须使用右键点击传送门，并且在召唤完成之前不得移动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (699, 'Drain Life', '', '', '', '吸取生命', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Transfers $s1 health every second from the target to the caster.  Lasts $d.', '', '', '', '每秒钟吸取目标$s1点生命值，并将其转移给施法者，持续$d。', '', '', 'Drains $s1 health each second to the caster.', '', '', '', '每秒吸取$s1点生命值并将其转移给施法者。', '', '');
INSERT INTO `locales_spell` VALUES (700, 'Sleep', '', '', '', '催眠术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Puts the enemy target to sleep for up to $d.  Any damage caused will awaken the target.  Only one target can be asleep at a time.', '', '', '', '使敌人进入睡眠状态，最多持续$d。任何对目标造成伤害的行为都会唤醒它。同一时间内只能有一个目标被催眠。', '', '', 'Asleep.', '', '', '', '沉睡。', '', '');
INSERT INTO `locales_spell` VALUES (701, 'Firebolt', '', '', '', '火焰箭', '', '', '', '', '', '', '', '', '', 'Blasts a target for $s1 Fire damage.', '', '', '', '冲击目标，对其造成$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (702, 'Curse of Weakness', '', '', '', '虚弱诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Damage caused by the target is reduced by $s1 for $d.  Only one Curse per Warlock can be active on any one target.', '', '', '', '目标所能造成的伤害降低$s1点，持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Physical damage done reduced by $s1.', '', '', '', '对目标造成的物理伤害降低$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (703, 'Garrote', '', '', '', '绞喉', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.', '', '', '', '猛勒敌人的脖子，在$d内对其造成总计$o1点伤害，该伤害会受到攻击强度的加成影响。必须在潜行状态下从目标背后发动。奖励$s2个连击点数。', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
INSERT INTO `locales_spell` VALUES (704, 'Curse of Recklessness', '', '', '', '鲁莽诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Curses the target with recklessness, increasing melee attack power by $s1 but reducing armor by $s2 for $d.  Cursed enemies will not flee and will ignore Fear and Horror effects.  Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加鲁莽的诅咒，使其近战攻击强度提高$s1点，但护甲降低$s2点，持续$d。被诅咒的敌人不会逃跑，也不会受到恐惧的影响。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Increases melee attack power by $s1 and decreases armor by $s2.   Target will not flee and will ignore Fear and Horror effects.', '', '', '', '近战攻击强度提高$s1点，护甲降低$s2点。目标不会逃跑，且免疫恐惧效果。', '', '');
INSERT INTO `locales_spell` VALUES (705, 'Shadow Bolt', '', '', '', '暗影箭', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Sends a shadowy bolt at the enemy, causing $s1 Shadow damage.', '', '', '', '向目标射出一支暗影箭，对其造成$s1点暗影伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (706, 'Demon Armor', '', '', '', '魔甲术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Protects the caster, increasing armor by $s1, Shadow resistance by $s2 and restores $s3 health every 5 sec. for $d.', '', '', '', '使施法者的护甲提高$s1点，暗影抗性提高$s2点，同时每5秒回复$s3点生命值，持续$d。', '', '', 'Increases armor by $s1, Shadow resistance by $s2 and restores $s3 health every 5 sec.', '', '', '', '护甲值提高$s1点，暗影抗性提高$s2点，每5秒回复$s3点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (707, 'Immolate', '', '', '', '献祭', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Burns the enemy for $s2 Fire damage and then an additional $o1 Fire damage over $d.', '', '', '', '灼烧敌人，对其造成$s2点火焰伤害，并在$d内造成额外的$o1点火焰伤害。', '', '', '$s1 Fire damage every $t1 seconds.', '', '', '', '每$t1秒$s1点火焰伤害。', '', '');
