INSERT INTO `locales_spell` VALUES (710, 'Banish', '', '', '', '放逐术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Banishes the enemy target, preventing all action but making it invulnerable for up to $d.  Only one target can be banished at a time.  Only works on Demons and Elementals.', '', '', '', '放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续$d。每个术士在同一时间内只能放逐一个目标，只能对恶魔和元素生物使用。', '', '', 'Invulnerable, but unable to act.', '', '', '', '不会受到任何伤害，但也无法做出任何动作。', '', '');
INSERT INTO `locales_spell` VALUES (711, 'Hellfire', '', '', '', '地狱烈焰', '', '', '', '', '', '', '', '', '', 'Blasts all enemies in a 10 yard radius with $s1 flame damage.', '', '', '', '冲击半径10码范围内的所有敌人，对它们造成各自$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
