INSERT INTO `locales_spell` VALUES (755, 'Health Funnel', '', '', '', '生命通道', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives $s1 health to the caster\'s pet every second for $d as long as the caster channels.', '', '', '', '只要施法者保持着引导法术的状态，就会每秒钟将$s1点生命值转移给施法者的宠物，最多持续$d。', '', '', 'Transferring Life.', '', '', '', '正在转移生命值。', '', '');
