INSERT INTO `locales_spell` VALUES (759, 'Conjure Mana Agate', '', '', '', '制造魔法玛瑙', '', '', '', '', '', '', '', '', '', 'Conjures a mana agate that can be used to instantly restore $5405s1 mana.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一颗魔法玛瑙，使用后可以立刻恢复$5405s1点法力值。\n\n这些物品会在持有者登出游戏超过15分钟之后消失。', '', '', '', '', '', '', '', '', '');
