INSERT INTO `locales_spell` VALUES (767, 'Minor Damage Shield', '', '', '', '微型反伤护盾', '', '', '', '', '', '', '', '', '', 'Deals $s1 damage to an attacker when they strike you with a melee attack.', '', '', '', '对近战攻击者造成$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (768, 'Cat Form', '', '', '', '猎豹形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Shapeshift into cat form, increasing melee attack power by $3025s1 plus Agility.  Also protects the caster from Polymorph effects and allows the use of various cat abilities.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.', '', '', '', '变成一头猎豹，近战攻击强度提高$3025s1点再加上敏捷数值，免疫变形魔法效果，并可使用多种猎豹形态下专有的技能。\n\n变身可以解除施法者身上的所有变形和移动限制效果。', '', '', 'Immunity to Polymorph effects.  Increases melee attack power by $3025s1 plus Agility.', '', '', '', '免疫变形效果。近战攻击强度提高$3025s1点加上敏捷数值。', '', '');
INSERT INTO `locales_spell` VALUES (769, 'Swipe', '', '', '', '挥击', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Swipe $x1 nearby enemies, inflicting $s1 damage.', '', '', '', '攻击附近的$x1个敌人，对它们造成$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (770, 'Faerie Fire', '', '', '', '精灵之火', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Decrease the armor of the target by $s1 for $d.  While affected, the target cannot stealth or turn invisible.', '', '', '', '使目标的护甲降低$s1点，持续$d。在效果持续期间，目标无法潜行或隐形。', '', '', 'Decreases armor by $s1.  Cannot stealth or turn invisible.', '', '', '', '护甲降低$s1点，无法潜行或隐形。', '', '');
INSERT INTO `locales_spell` VALUES (771, 'Charm Beast', '', '', '', '野兽蛊惑', '', '', '', '', '', '', '', '', '', 'Charms the target beast for $d.', '', '', '', '在$d内魅惑野兽。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (772, 'Rend', '', '', '', '撕裂', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Wounds the target causing them to bleed for $o1 damage over $d.', '', '', '', '使目标的伤口不断流血，在$d内造成累计$o1点伤害。', '', '', 'Bleeding for $s1 damage every $t1 seconds.', '', '', '', '因流血受到每$t1秒$s1点伤害。', '', '');
