INSERT INTO `locales_spell` VALUES (775, 'Tree Form', '', '', '', '树形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Transforms the druid into a tree form, removing all harmful physical effects and protecting from all physical attacks for $d, but during that time you cannot attack, move or cast spells.  Also protects the caster from polymorph effects.\n\nThe act of shapeshifting frees the caster of roots, snares, and freeze effects.', '', '', '', '德鲁伊变形成为一棵树，驱散一切有害的物理效果，并免疫物理攻击和变形效果，持续$d。但是在这段时间里，你无法攻击、移动或施法。\n\n变形成树可以让德鲁伊摆脱定身、诱捕和冻结效果。', '', '', 'Immune to all physical attacks and polymorph effects.  Cannot attack, move or cast spells.', '', '', '', '免疫物理攻击和变形效果，不能攻击、移动或施法。', '', '');
INSERT INTO `locales_spell` VALUES (776, 'Abolish Magic', '', '', '', '驱除魔法', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Abolishes all magic on the friendly target, and prevents any magic from affecting the target for $d.', '', '', '', '驱散友方目标身上的所有魔法效果，并使其免受任何魔法的影响，持续$d。', '', '', '', '', '', '', '', '', '');
