INSERT INTO `locales_spell` VALUES (782, 'Thorns', '', '', '', '荆棘术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Thorns sprout from the friendly target causing $s1 Nature damage to attackers when hit.  Lasts $d.', '', '', '', '使友方目标身上环绕着荆棘，对任何使用近战手段击中被保护者的敌人造成$s1点自然伤害，持续$d。', '', '', 'Causes $s1 Nature damage to attackers.', '', '', '', '对攻击者造成$s1点自然伤害。', '', '');
