INSERT INTO `locales_spell` VALUES (1006, 'Inner Fire', '', '', '', '心灵之火', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'A burst of Holy energy fills the caster, increasing armor by $s1 and attack power by $s2.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.', '', '', '', '圣洁的能量充满施法者的体内，使$g他:她;的防御值提高$s1点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续$d，或在$n次防护之后消失。', '', '', 'Increases armor by $s1.', '', '', '', '防御值提高$s1点。', '', '');
