INSERT INTO `locales_spell` VALUES (1008, 'Amplify Magic', '', '', '', '魔法增效', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Amplifies magic used against the targeted party member, increasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.', '', '', '', '增强施放于目标小队成员身上的魔法效果，使其受到的法术伤害最多提高$s1点，治疗法术所恢复的生命值最多提高$s2点，持续$d。', '', '', 'Increases magic damage taken by up to $s1 and healing by up to $s2.', '', '', '', '被法术攻击时所承受的伤害最多提高$s1点，被法术治疗时所恢复的生命值最多提高$s2点。', '', '');
