INSERT INTO `locales_spell` VALUES (1010, 'Curse of Idiocy', '', '', '', '痴呆诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Curse the target with idiocy, reducing Intellect and Spirit by $s1 every $t3 seconds until each is reduced by a total of $*15;s1.  Only one Curse per Warlock can be active on any one target.', '', '', '', '使目标受到痴呆的诅咒，每$t1降低$s1点智力和精神，直到这两种属性都被降低了$*15;s1点。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Intellect and Spirit reduced.', '', '', '', '智力和精神降低。', '', '');
