INSERT INTO `locales_spell` VALUES (1020, 'Divine Shield', '', '', '', '圣盾术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Protects the paladin from all damage and spells for $d, but decreases the damage you deal with all attacks and spells by $s2%.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for $25771d.', '', '', '', '使圣骑士对所有的伤害和法术攻击免疫，持续$d，但你所有攻击所造成的伤害减少$s2%。在受保护之后，圣盾术、保护祝福或圣佑术在$25771d之内无法作用在你身上。', '', '', 'Immune to all attacks and spells, but decreases damage caused by $s2%.', '', '', '', '免疫所有攻击和法术，但减少 $s2% 造成的伤害。', '', '');
