INSERT INTO `locales_spell` VALUES (1032, 'Devotion Aura', '', '', '', '虔诚光环', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Gives $s1 additional armor to party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使半径$a1码范围内的所有小队成员获得$s1点额外的护甲。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Increases armor by $s1.', '', '', '', '护甲值提高$s1点。', '', '');
