INSERT INTO `locales_spell` VALUES (1036, 'Blessing of Fury', '', '', '', '愤怒圣印', '', '', '', '', '', '', '', '', '', 'Places a Blessing on the party member, increasing threat caused by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为小队成员施加圣印，令其对怪物造成的威胁提高$s1%，持续$d。每个圣骑士在同一时间内只能给目标施加一个圣印，且同类型的圣印在同一个目标身上只能存在一个。', '', '', 'Increases threat you cause by $s1%.', '', '', '', '使你造成的威胁提高$s1%。', '', '');
