INSERT INTO `locales_spell` VALUES (1038, 'Blessing of Salvation', '', '', '', '拯救祝福', '', '', '', '', '', '', '', '', '', 'Places a Blessing on the party member, reducing the amount of all threat generated by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为小队成员施加祝福，令其对怪物造成的威胁降低$s1%，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Reduces threat generated by $s1%.', '', '', '', '威胁值降低$s1%。', '', '');
