INSERT INTO `locales_spell` VALUES (1062, 'Entangling Roots', '', '', '', '纠缠根须', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Roots the target in place and causes $o2 Nature damage over $d.  Damage caused may interrupt the effect.  Only useable outdoors.', '', '', '', '将目标固定在原地，在$d内对其造成总计$o2点自然伤害。任何伤害都可能会打断纠缠根须的效果。只能在户外使用。', '', '', 'Rooted.  Causes $s2 Nature damage every $t2 seconds.', '', '', '', '被缠绕，造成每$t2秒$s2点伤害。', '', '');
