INSERT INTO `locales_spell` VALUES (1064, 'Chain Heal', '', '', '', '治疗链', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Heals the friendly target for $s1, then jumps to heal additional nearby targets.  If cast on a party member, the heal will only jump to other party members.  Each jump is $*100;F1% as effective as the previous target.  Heals $x1 total targets.', '', '', '', '为友方目标回复$s1点生命值，然后转而治疗附近的下一个目标。如果施法者在一支小队中，则治疗链只会治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的$*100;F1%。总共可治疗$x1个目标。', '', '', '', '', '', '', '', '', '');
