INSERT INTO `locales_spell` VALUES (1066, 'Aquatic Form', '', '', '', '水栖形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Shapeshift into aquatic form, increasing swim speed by $5421s1% and allowing the druid to breathe underwater.  Also protects the caster from Polymorph effects.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.', '', '', '', '变身进入水栖形态，使德鲁伊的游泳速度提高$5421s1%，并使其可以在水下呼吸。免疫变形魔法效果。\n\n变身可以解除施法者身上的所有变形和移动限制效果。', '', '', 'Immune to Polymorph effects.  Increases swim speed by $5421s1% and allows underwater breathing.', '', '', '', '免疫变形效果。游泳速度提高$5421s1%，可在水下呼吸。', '', '');
INSERT INTO `locales_spell` VALUES (1069, 'Faerie Fire', '', '', '', 'zzOLDFaerie Fire', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Decrease the armor of the target by $s1 for $d.  While affected, the target cannot stealth or turn invisible.', '', '', '', '使目标的护甲降低$s1点，持续$d。在效果持续期间，目标无法潜行或隐形。', '', '', 'Decreases armor by $s1.  Cannot stealth or turn invisible.', '', '', '', '护甲降低$s1点，无法潜行或隐形。', '', '');
