INSERT INTO `locales_spell` VALUES (1079, 'Rip', '', '', '', '撕扯', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\n   1 point  : 42 damage over $d.\n   2 points: 66 damage over $d.\n   3 points: 90 damage over $d.\n   4 points: 114 damage over $d.\n   5 points: 138 damage over $d.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定伤害总量，该伤害会受到攻击强度的加成影响：\n   1点：$d内42伤害\n   2点：$d内66伤害\n   3点：$d内90伤害\n   4点：$d内114伤害\n   5点：$d内138伤害', '', '', 'Bleed damage every $t1 seconds.', '', '', '', '每$t1秒因流血受到一次伤害。', '', '');
