INSERT INTO `locales_spell` VALUES (1098, 'Enslave Demon', '', '', '', '奴役恶魔', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Enslaves the target demon, up to level $m1, forcing it to do your bidding.  While enslaved, the time between the demon\'s attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.  If you repeatedly enslave the same demon, it will become more difficult to control with each attempt.', '', '', '', '奴役等级不高于$m1级的恶魔，令其听从你的命令。被奴役的恶魔的攻击间隔延长$s2%，施法速度降低$s3%。奴役效果最多持续$d。如果你反复奴役同一个恶魔，它摆脱控制的几率会越来越大。', '', '', 'Enslaved.', '', '', '', '被奴役。', '', '');
