INSERT INTO `locales_spell` VALUES (1120, 'Drain Soul', '', '', '', '吸取灵魂', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Drains the soul of the target, causing $o2 Shadow damage over $d.  If the target dies while being drained, and yields experience or honor, the caster gains a Soul Shard.  Soul Shards are required for other spells.', '', '', '', '吸取目标的灵魂，在$d内对其造成累计$o2点暗影伤害。如果目标在被吸取灵魂的过程中死亡，且施法者因此获得经验值或荣誉，则施法者可以得到一块灵魂碎片。灵魂碎片是施放其它一些法术所必需的材料。', '', '', '$s2 Shadow damage every $t2 seconds.', '', '', '', '每$t2秒$s2点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (1121, 'Entangle', '', '', '', '纠缠', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Entangled', '', '', '', '被纠缠。', '', '');
INSERT INTO `locales_spell` VALUES (1122, 'Inferno', '', '', '', '地狱火', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a meteor from the Twisting Nether, causing $22699s1 Fire damage and stunning all enemy targets in the area for $20310d.  An Infernal rises from the crater, under the command of the caster for $20882d.  Once control is lost, the Infernal must be Enslaved to maintain control.', '', '', '', '从扭曲虚空中召来一颗流星，对其着陆区域的所有敌人造成$22699s1点火焰伤害，并使它们昏迷$20310d。一个巨大的地狱火恶魔将从着陆点出现，并被施法者控制$20882d。如果控制失效，则施法者必须奴役地狱火才能继续指挥它。只能在户外使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1123, 'Ritual of Doom', '', '', '', '末日仪式', '', '', '', '', '', '', '', '', '', 'Teaches Ritual of Doom.', '', '', '', '教你学会施放末日仪式。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1124, 'Hellfire II', '', '', '', '地狱烈焰 II', '', '', '', '', '', '', '', '', '', 'Blasts all enemies in a 10 yard radius with $s1 flame damage.', '', '', '', '冲击半径10码范围内的所有敌人，对它们造成各自$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
