INSERT INTO `locales_spell` VALUES (1127, 'Food', '', '', '', '进食', '', '', '', '', '', '', '', '', '', 'Restores $o1 health over $d.  Must remain seated while eating.', '', '', '', '在$d内恢复总计$o1点生命值，进食时必须保持坐姿。', '', '', 'Restores $/5;s1 health per second.', '', '', '', '每秒恢复$/5;s1点生命值。', '', '');
