INSERT INTO `locales_spell` VALUES (1490, 'Curse of the Elements', '', '', '', '元素诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Curses the target for $d, reducing Fire and Frost resistances by $s1 and increasing Fire and Frost damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.', '', '', '', '对目标施放诅咒，使其火焰和冰霜抗性降低$s1点，受到火焰和冰霜系攻击时所承受的伤害提高$s2%，效果持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Reduces Fire and Frost resistances by $s1.  Increases Fire and Frost damage taken by $s2%.', '', '', '', '火焰和冰霜抗性降低$s1点。受到火焰和冰霜系攻击时所承受的伤害提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (1491, 'Critical Shot', '', '', '', '致命射击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'All shots fired within the next $d will always hit for critical damage.', '', '', '', '在接下来的$d内发射的所有弹药都会造成致命伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1492, 'Critical Shot', '', '', '', '致命射击', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'All shots fired within the next $d will always hit for critical damage.', '', '', '', '在接下来的$d内发射的所有弹药都会造成致命伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1494, 'Track Beasts', '', '', '', '追踪野兽', '', '', '', '', '', '', '', '', '', 'Shows the location of all nearby beasts on the minimap.  Only one form of tracking can be active at a time.', '', '', '', '在微缩地图上显示附近所有野兽的位置。同一时间内只能激活一种追踪技能。', '', '', 'Tracking Beasts.', '', '', '', '正在追踪野兽。', '', '');
INSERT INTO `locales_spell` VALUES (1495, 'Mongoose Bite', '', '', '', '猫鼬撕咬', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Counterattack the enemy for $s1 damage.  Can only be performed after you dodge.', '', '', '', '反击敌人，对其造成$s1点伤害。只能在你成功躲闪之后使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1499, 'Freezing Trap', '', '', '', '冰冻陷阱', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Place a frost trap that freezes the first enemy that approaches, preventing all action for up to $3355d.  Any damage caused will break the ice.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.', '', '', '', '在地面上放置一个陷阱，它会冻结第一个接近它的敌人，使其在最多$3355d内无法行动，任何伤害都会取消冰冻效果。陷阱可存在$d。只能在非战斗状态中安置陷阱，每个猎人在同一时间内只能布置一个陷阱。', '', '', '', '', '', '', '', '', '');
