INSERT INTO `locales_spell` VALUES (1510, 'Volley', '', '', '', '乱射', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Continuously fires a volley of ammo at the target area, causing $s1 Arcane damage to enemy targets within $a1 yards every second for $d.', '', '', '', '持续向目标区域射击，每秒对半径$a1码范围内的敌人造成$s1点奥术伤害，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1513, 'Scare Beast', '', '', '', '恐吓野兽', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Scares a beast, causing it to run in fear for up to $d.  Damage caused may interrupt the effect.  Only one beast can be feared at a time.', '', '', '', '恐吓一头野兽，使其因恐慌而逃跑，最多持续$d。任何伤害都有可能打断这个效果。每个猎人在同一时间内只能恐吓一头野兽。', '', '', 'Feared.', '', '', '', '恐惧。', '', '');
INSERT INTO `locales_spell` VALUES (1515, 'Tame Beast', '', '', '', '驯服野兽', '', '', '', '', '', '', '', '', '', 'Begins taming a beast to be your companion. Your armor is reduced by $s3% while you focus on taming the beast for $d. Once tamed, the beast will be very unhappy and disloyal. Try feeding the pet immediately to make it happy.', '', '', '', '开始驯服野兽作为你的伴侣。当你专注于花费 $d 驯服野兽时，你的护甲会减少 $s3%。一旦被驯服，野兽就会非常不高兴并且不忠诚。尝试立即喂养宠物，让它开心。', '', '', 'Taming pet.', '', '', '', '正在驯服宠物。', '', '');
