INSERT INTO `locales_spell` VALUES (1698, 'Shockwave', '', '', '', '震荡波', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A rapid-fire attack that hits all nearby enemies in a cone in front of the warrior for weapon damage plus $s1 damage.', '', '', '', '快速攻击，对战士面前一个锥形范围内的所有敌人都造成武器伤害外加$s1点伤害。', '', '', '', '', '', '', '', '', '');
