INSERT INTO `locales_spell` VALUES (1706, 'Levitate', '', '', '', '漂浮术', '', '', '', '', '', '', '', '', '', 'Allows the caster to levitate, floating a few feet above the ground.  While levitating, you will fall at a reduced speed and travel over water-like surfaces.  Any damage will cancel the effect.  Lasts $d.', '', '', '', '让施法者可以漂浮在地面上，移动速度降低，但是能越过水体表面行走。任何伤害都会中断漂浮效果。持续$d。', '', '', 'Levitating.', '', '', '', '正在漂浮。', '', '');
INSERT INTO `locales_spell` VALUES (1707, 'Mind Bomb', '', '', '', '心灵炸弹', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Attaches a mind bomb to the target.  If the target casts a spell in the next $d, they take 200 damage.', '', '', '', '给目标施加一个心灵炸弹。如果目标在接下来的$d内施法，他们将受到200点伤害。', '', '', '', '', '', '', '', '', '');
