INSERT INTO `locales_spell` VALUES (1940, 'Rocket Blast', '', '', '', '火箭爆炸', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage in a 3 yard radius.', '', '', '', '对半径3码范围内的所有敌人造成$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (1941, 'Mana Funnel', '', '', '', '法力通道', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Transfers $s1 mana from the caster to $ghis:her; pet every second as long as the caster channels.', '', '', '', '只要施法者保持着引导法术的状态，就会每秒钟将$s1点法力值转移给$ghis:her;的宠物。', '', '', 'Transferring Mana.', '', '', '', '转移法力。', '', '');
