INSERT INTO `locales_spell` VALUES (1943, 'Rupture', '', '', '', '割裂', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\n   1 point  : 40 damage over 8 secs\n   2 points: 60 damage over 10 secs\n   3 points: 84 damage over 12 secs\n   4 points: 112 damage over 14 secs\n   5 points: 144 damage over 16 secs', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间，该伤害会受到攻击强度的加成影响：\n   1点：40伤害，持续8秒\n   2点：60伤害，持续10秒\n   3点：84伤害，持续12秒\n   4点：112伤害，持续14秒\n   5点：144伤害，持续16秒', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
