INSERT INTO `locales_spell` VALUES (1945, 'Ethereal Form', '', '', '', '灵体形态', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Makes the caster immune to physical damage, but unable to melee or use physical abilities for $d.', '', '', '', '使萨满祭司受到的物理伤害减少$s1%，期间无法施法，持续$d。', '', '', '', '', '', '', '', '', '');
