INSERT INTO `locales_spell` VALUES (1949, 'Hellfire', '', '', '', '地狱烈焰', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Ignites the area surrounding the caster, causing $s2 Fire damage to $ghimself:herself; and $5857s1 Fire damage to all nearby enemies within $s1 yards every $t2 sec.  Lasts $d.', '', '', '', '点燃施法者周围的区域，对 $ghimself:herself 造成 $s2 火焰伤害；每 $t2 秒对 $s1 码内所有附近敌人造成 $5857s1 火焰伤害。持续$d。', '', '', 'Damages self and all nearby enemies.', '', '', '', '对自己和周围的所有敌人造成伤害。', '', '');
