INSERT INTO `locales_spell` VALUES (1953, 'Blink', '', '', '', '闪现术', '', '', '', '', '', '', '', '', '', 'Teleports the caster 20 yards forward, unless something is in the way.  Also frees the caster from stuns and bonds.', '', '', '', '将施法者传送到正前方20码的位置，路线上有阻挡物则会停止，传送可以解除施法者身上一切形式的束缚。', '', '', 'Blinking.', '', '', '', '闪现。', '', '');
