INSERT INTO `locales_spell` VALUES (2006, 'Resurrection', '', '', '', '复活术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Brings a dead player back to life with $s1 health and $q1 mana.  Cannot be cast when in combat.', '', '', '', '复活一个死去的玩家，复活后该玩家拥有$s1点生命值和$q1点法力值。无法在战斗中施放。', '', '', '', '', '', '', '', '', '');
