INSERT INTO `locales_spell` VALUES (2011, 'Rebirth', '', '', '', '复生', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Returns the spirit to the body, restoring a dead target to life with $s1% of their health and mana.', '', '', '', '让已死的目标复活，并恢复$s1%生命值和法力值。', '', '', '', '', '', '', '', '', '');
