INSERT INTO `locales_spell` VALUES (2484, 'Earthbind Totem', '', '', '', '地缚图腾', '', '', '', '', '', '', '', '', '', 'Summons an Earthbind Totem with $s1 health at the feet of the caster for $d that slows the movement speed of enemies within $3600a1 yards.', '', '', '', '在施法者身边召唤一个生命值为$s1点的地缚图腾，持续$d。该图腾可以使它周围半径$3600a1码内的所有敌人的移动速度降低。', '', '', '', '', '', '', '', '', '');
