INSERT INTO `locales_spell` VALUES (2637, 'Hibernate', '', '', '', '休眠', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Forces the enemy target to sleep for up to $d.  Any damage will awaken the target.  Only one target can be forced to hibernate at a time.  Only works on Beasts and Dragonkin.', '', '', '', '使敌方目标沉睡，最多持续$d，任何伤害都会唤醒被催眠的目标。在同一时间内只能强制使一个目标进入休眠状态，只对野兽和龙类有效。', '', '', 'Asleep.', '', '', '', '沉睡。', '', '');
