INSERT INTO `locales_spell` VALUES (2651, 'Elune\'s Grace', '', '', '', '艾露恩的赐福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces ranged damage taken by $s1 and increases chance to dodge by $s2% for $d.\r\n\r\nMelee attacks dodged while this effect is active restore mana equal to your agility.', '', '', '', '使你受到的远程攻击伤害减少$s1，躲闪几率提高$s2%，持续$d。', '', '', 'Ranged damage taken reduced by $s1 and chance to dodge increased by $s2%.', '', '', '', '受到远程攻击时所承受的伤害降低$s1点，躲闪几率提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (2652, 'Touch of Weakness', '', '', '', '虚弱之触', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The next melee attack against the caster will cause $2943s1 Shadow damage and reduce the damage caused by the attacker by $2943s2 for $2943d.', '', '', '', '对施法者进行的下一次近战攻击会令攻击者承受$2943s1点暗影伤害，并使其所能造成的伤害减少$2943s2点，持续$2943d。', '', '', 'The next damaging melee attack against you will damage and weaken the target.', '', '', '', '下一次对你造成伤害的近战攻击可以削弱攻击者。', '', '');
