INSERT INTO `locales_spell` VALUES (2823, 'Deadly Poison', '', '', '', '致命毒药', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Coats a weapon with poison that lasts for 30 minutes.\nEach strike has a $h% chance of poisoning the enemy for $2818o1 Nature damage over $2818d.  Stacks up to 5 times on a single target.  60 charges.', '', '', '', '给一件武器浸毒，效果持续30分钟。\n每次攻击都有$h%的几率令敌人中毒，在$2818d内对其造成$2818o1点自然伤害，对单一目标最多可以叠加5次。可使用60次。', '', '', '', '', '', '', '', '', '');
