INSERT INTO `locales_spell` VALUES (3547, 'Enraging Memories', '', '', '', '愤怒的回忆', '', '', '', '', '', '', '', '', '', 'Drives the caster into a maddened frenzy for $d. Increases the caster\'s attack speed by $s1%, but slows its movement by $s2% and reduces the Physical damage it deals by $s3.', '', '', '', '使施法者进入疯狂状态，持续$d。施法者的攻击速度提高$s1%，移动速度降低$s2%，物理攻击所能造成的伤害降低$s3点。', '', '', 'Attack speed increased by $s1%.\nPhysical damage dealt is reduced by $s3.\nMovement speed reduced by $s2%.', '', '', '', '攻击速度提高$s1%。\n移动速度降低$s2%。\n物理攻击所能造成的伤害降低$s3点。', '', '');
