INSERT INTO `locales_spell` VALUES (4071, 'Target Dummy', '', '', '', '活动假人', '', '', '', '', '', '', '', '', '', 'Drops a target dummy on the ground that attracts nearby monsters to attack it.  Lasts for 15 seconds or until killed.', '', '', '', '在地上放置一个假人，吸引附近的怪物攻击它。持续时间为15秒，或者被摧毁。', '', '', '', '', '', '', '', '', '');
