INSERT INTO `locales_spell` VALUES (4511, 'Phase Shift', '', '', '', '相位变换', '', '', '', '', '', '', '', '', '', 'Shifts the imp out of phase with the world, making it unattackable unless it attacks.', '', '', '', '小鬼的实体形态脱离这个世界，从而不会受到攻击，除非小鬼自己发动攻击。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4512, 'Phase Shift', '', '', '', '相位变换', '', '', '', '', '', '', '', '', '', 'Adds a chance to turn invisible when hit.', '', '', '', '有一定几率在被击中时进入隐形状态。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4513, 'Curse', '', '', '', '诅咒', '', '', '', '', '', '', '', '', '', 'Reduces the target\'s chance to hit by $s1 for $d.', '', '', '', '在$d内使目标命中几率降低$s1点。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4514, 'Consuming Rage', '', '', '', '怒气爆发', '', '', '', '', '', '', '', '', '', 'Speeds the caster\'s attacks by $s2% and its movement by $s3% for $d., but also inflicts $s1 Shadow damage to the caster every $t1 sec.', '', '', '', '使施法者的攻击速度提高$s2%，移动速度提高$s3%，持续$d，但每$t1秒施法者会受到$s1点暗影伤害。', '', '', '$s1 Shadow damage inflicted every $t1 sec.\nAttack speed increased by $s2%.\nMovement speed increased by $s3%.', '', '', '', '攻击速度提高$s2%。\n移动速度提高$s3%。\n每$t1秒受到$s1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (4517, 'Meditation', '', '', '', '冥想', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Restores 12 mana per minute.', '', '', '', '每分钟恢复12点法力值。', '', '', '', '', '', '', '', '', '');
