INSERT INTO `locales_spell` VALUES (4520, 'Wide Sweep', '', '', '', '蛮力狂扫', '', '', '', '', '', '', '', '', '', 'Attacks all enemies in front of the Infernal doing it\'s normal damage plus $s1.', '', '', '', '攻击地狱火面前的所有敌人，造成普通伤害外加$s1点伤害。', '', '', '', '', '', '', '', '', '');
