INSERT INTO `locales_spell` VALUES (4525, 'Demonic Immolation Passive', '', '', '', '恶魔自燃被动', '', '', '', '', '', '', '', '', '', 'When the Infernal takes damage, it has a 15% chance of bursting into fire doing damage to all who strike it for $d.', '', '', '', '地狱火受到伤害时有15%的几率燃烧，令所有攻击它的敌人受到伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4526, 'Mass Dispell', '', '', '', '群体驱魔', '', '', '', '', '', '', '', '', '', 'Dispels $s1 hostile effects on friendly targets and $s1 positive effects on hostile targets from targets next to the infernal.', '', '', '', '驱散恶魔身边的友方身上的$s1个有害魔法效果，以及敌方身上的$s1个有益魔法效果。', '', '', '', '', '', '', '', '', '');
