INSERT INTO `locales_spell` VALUES (4731, 'Enraging Bite', '', '', '', '狂怒撕咬', '', '', 'Bear', '', '', '', '熊', '', '', 'Teaches your tamed bear the Enraging Bite ability. Enraging Bite reduces an enemy\'s resistance to physical attacks as well as drawing its attention.\nRequires: \nPet Level 13+', '', '', '', '教你的熊学会狂怒撕咬技能。该技能可以降低敌人的物理抗性，并吸引其注意力。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4732, 'Roar of Fortitude', '', '', '', '坚韧咆哮', '', '', 'Bear', '', '', '', '熊', '', '', 'Teaches your tamed bear the Roar of Fortitude ability. Roar of Fortitude increases the maximum health of everyone in your party.\nRequires: \nPet Level 36+', '', '', '', '教你的熊学会坚韧咆哮技能。该技能可以提高所有小队成员的生命值上限。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4733, 'Gore', '', '', '', '淤血', '', '', 'Boar', '', '', '', '野猪', '', '', 'Teaches your tamed boar the Gore ability. Gore deals physical damage over time to an enemy.\nRequires: \nPet Level 13+', '', '', '', '教你的野猪学会淤血技能。该技能可以对敌人造成持续的物理伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4734, 'Toughen Hide', '', '', '', '韧化外皮', '', '', 'Boar', '', '', '', '野猪', '', '', 'Teaches your tamed boar the Toughen Hide ability. Toughen Hide increases resistance to physical attacks.\nRequires: \nPet Level 22+', '', '', '', '教你的野猪学会韧化外皮技能。该技能可以提高对物理攻击的抗性。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4735, 'Vital Wound', '', '', '', '致命创伤', '', '', 'Boar', '', '', '', '野猪', '', '', 'Teaches your tamed boar the Vital Wound ability. Vital Wound slows the attack speed of an enemy.\nRequires: \nPet Level 36+', '', '', '', '教你的野猪学会致命创伤技能。该技能可以降低敌人的攻击速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4736, 'Flight of the Peregrine', '', '', '', '鹰隼飞翔', '', '', 'Bird', '', '', '', '鸟', '', '', 'Teaches your tamed bird the Flight of the Peregrine ability. Flight of the Peregrine increase the movement speed of the bird.\nRequires: \nPet Level 13+', '', '', '', '教你的鸟学会鹰隼飞翔技能。该技能可以提高鸟的移动速度。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4737, 'Eye Peck', '', '', '', '啄眼', '', '', 'Bird', '', '', '', '鸟', '', '', 'Teaches your tamed bird the Eye Peck ability. Eye Peck causes an enemy to miss more often in combat.\nRequires: \nPet Level 22+', '', '', '', '教你的鸟学会啄眼技能。该技能可以使敌人在战斗中更不容易击中目标。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4739, 'Pester', '', '', '', '缠斗', '', '', 'Bird', '', '', '', '鸟', '', '', 'Teaches your tamed bird the Pester ability. Pester greatly increases the attack speed of the bird at the cost of dealing less damage. Every successful attack while in this mode renders the target unable to cast spells for a short time.\nRequires: \nPet Level 36+', '', '', '', '教你的鸟学会缠斗技能。该技能可以明显提高鸟的攻击速度，但是会令其造成更少的伤害。鸟在此形态下每次击中目标，都会导致目标在一小段时间里不能施法。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4740, 'Ferocity', '', '', '', '凶暴', '', '', 'Cat', '', '', '', '豹', '', '', 'Teaches your tamed cat the Ferocity ability. Ferocity increases attack speed of the cat at the cost of receiving more damage when hit by phsical attacks.\nRequires: \nPet Level 13+', '', '', '', '教你的豹学会凶暴技能。该技能可以提高豹的移动速度，但是在受到物理攻击时会承受更多伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4741, 'Open Wound', '', '', '', '暴露伤口', '', '', 'Cat', '', '', '', '豹', '', '', 'Teaches your tamed cat the Open Wound ability. Open Wound deals physical damage over time to an enemy as well as increasing damage received by physical attacks for a short time.\nRequires: \nPet Level 36+', '', '', '', '教你的豹学会暴露伤口技能。这项技能有一定几率令目标的伤口暴露，对其造成持续的伤害，并使其在受到攻击时承受更多的伤害。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4742, 'Tough Shell', '', '', '', '硬壳', '', '', 'Crab - Rank 1', '', '', '', '螃蟹 - 等级 1', '', '', 'Teaches your tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 13+', '', '', '', '教你的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4743, 'Tough Shell', '', '', '', '硬壳', '', '', 'Crab', '', '', '', '螃蟹', '', '', 'Teaches your tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 21+', '', '', '', '教你的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 21+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4744, 'Tough Shell', '', '', '', '硬壳', '', '', 'Crab - Rank 3', '', '', '', '螃蟹 - 等级 3', '', '', 'Teaches your tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 28+', '', '', '', '教你的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 28+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4745, 'Tough Shell', '', '', '', '硬壳', '', '', 'Crab - Rank 4', '', '', '', '螃蟹 - 等级 4', '', '', 'Teaches your tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 36+', '', '', '', '教你的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4746, 'Tight Pinch', '', '', '', '紧钳', '', '', 'Crab', '', '', '', '螃蟹', '', '', 'Teaches your tamed crab the Tight Pinch ability. Tight Pinch deals additional damage on the crab\'s next hit as well as stunning the enemy.\nRequires: \nPet Level 22+', '', '', '', '教你的螃蟹学会紧钳技能。该技能使螃蟹下一次击中敌人时造成额外的伤害，并令其昏迷。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4747, 'Clenched Pinchers', '', '', '', '蟹钳夹', '', '', 'Crab', '', '', '', '螃蟹', '', '', 'Teaches your tamed crab the Clenched Pinchers ability. Clenched Pinchers holds an enemy in place while dealing physical damage over time to it. While holding the enemy, the crab will be unable to attack or perform any other actions.\nRequires: \nPet Level 36+', '', '', '', '教你的螃蟹学会蟹钳夹技能。该技能使螃蟹牢牢夹住一个敌人，令其无法移动，并对其造成持续伤害，同时螃蟹也无法攻击或进行任何其它行动。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4748, 'Quick Snap', '', '', '', '快速撕咬', '', '', 'Crocilisk', '', '', '', '鳄鱼', '', '', 'Teaches your tamed crocilisk the Quick Snap ability. Quick Snap gives your crocilisk a chance to counterattack when hit.\nRequires: \nPet Level 22+', '', '', '', '教你的鳄鱼学会快速撕咬技能。该技能使你的鳄鱼有一定几率在被击中时进行反击。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4750, 'Consume Flesh', '', '', '', '食肉', '', '', 'Crocilisk', '', '', '', '鳄鱼', '', '', 'Teaches your tamed crocilisk the Consume Flesh ability. Consume Flesh gives your crocilisk a chance to steal health from an enemy when attacking.\nRequires: \nPet Level 36+', '', '', '', '教你的鳄鱼学会食肉技能。该技能使你的鳄鱼有一定几率在击中敌人后偷取生命值。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
