INSERT INTO `locales_spell` VALUES (4766, 'Rapid Gallop', '', '', '', '疾速奔跑', '', '', 'Horse', '', '', '', '马', '', '', 'Teaches your tamed horse the Rapid Gallop ability. Rapid Gallop increases the movement speed of your horse.', '', '', '', '教你的马学会疾速奔跑技能。该技能可以提高马的移动速度。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4767, 'Stomp', '', '', '', '践踏', '', '', 'Horse', '', '', '', '马', '', '', 'Teaches your tamed horse the Stomp ability. Stomp deals additional damage as well as slowing the movement speed of the enemy.\nRequires: \nPet Level 36+', '', '', '', '教你的马学会践踏技能。该技能可以对敌人造成额外伤害，并降低其移动速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4768, 'Feast of Prey', '', '', '', '吞食猎物', '', '', 'Raptor', '', '', '', '迅猛龙', '', '', 'Teaches your tamed raptor the Feast of Prey ability. Feast of Prey allows your raptor to recover health every time it kills an enemy.\nRequires: \nPet Level 13+', '', '', '', '教你的迅猛龙学会吞食猎物技能。该技能可以使你的迅猛龙在杀死敌人之后回复生命值。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4769, 'Vulnerable', '', '', '', '易伤', '', '', 'Raptor', '', '', '', '迅猛龙', '', '', 'Teaches your tamed raptor the Vulnerable ability. Vulnerable increases all physical damage done to an enemy for a short time.\nRequires: \nPet Level 22+', '', '', '', '教你的迅猛龙学会易伤技能。该技能可以在短时间内提高所有物理攻击对一个目标所造成的伤害。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (4770, 'Tendon Slice', '', '', '', '挑筋', '', '', 'Raptor', '', '', '', '迅猛龙', '', '', 'Teaches your tamed raptor the Tendon Slice ability. Tendon Slice deals damage over time as well as slowing the enemies movement speed.\nRequires: \nPet Level 36+', '', '', '', '教你的迅猛龙学会挑筋技能。该技能可以对敌人造成持续伤害，并降低其移动速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
