INSERT INTO `locales_spell` VALUES (4804, 'Poisonous Spit', '', '', '', '含毒喷溅', '', '', 'Spider', '', '', '', '蜘蛛', '', '', 'Teaches your tamed spider the Poisonous Spit ability. Poisonous Spit ranged attack that deals damage over time to an enemy.\nRequires: \nPet Level 36+', '', '', '', '教你的蜘蛛学会含毒喷溅技能。该技能可以对敌人进行远程攻击，使其受到持续伤害。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
