INSERT INTO `locales_spell` VALUES (4806, 'Distracting Spit', '', '', '', '涣散喷吐', '', '', 'Tall Strider', '', '', '', '陆行鸟', '', '', 'Teaches your tamed tall strider the Distracting Spit ability. Distracting Spit increases physical damage dealt to an enemy.\nRequires: \nPet Level 13+', '', '', '', '教你的陆行鸟学会涣散喷吐技能。该技能可以提高对敌人造成的物理伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
