INSERT INTO `locales_spell` VALUES (4948, 'Kinelory\'s Bear Form', '', '', '', '基恩洛的熊形态', '', '', '', '', '', '', '', '', '', 'Shapeshifts into a bear for $d., increasing armor and hit points, as well as allowing the use of various bear abilities.', '', '', '', '变形成为一头熊，持续$d，提高护甲值和生命值，并可使用多种熊的技能。', '', '', 'Shapeshifted into bear.\nArmor and hit points increased.', '', '', '', '变形成为熊。\n护甲值和生命值提高。', '', '');
