INSERT INTO `locales_spell` VALUES (4955, 'Fist of Stone', '', '', '', '石拳', '', '', '', '', '', '', '', '', '', 'Gives the caster an additional $s3 damage per hit for $d., but reduces its movement speed by $s1% and increases the time between its attacks by $s2%.', '', '', '', '使施法者在$d内每次击中目标时对其造成的伤害提高$s3点，但施法者的移动速度降低$s1%，攻击间隔延长$s2%。', '', '', 'Physical damage dealt is increased by $s3.\nMovement speed reduced by $s1%.\nTime between attacks increased by $s2%.', '', '', '', '击中目标时对其造成的伤害提高$s3点。\n移动速度降低$s1%。\n攻击间隔延长$s2%。', '', '');
