INSERT INTO `locales_spell` VALUES (5569, 'Holy Strike', '', '', '', '神圣打击', '', '', 'Rank 6', '', '', '', '等级 6', '', '', 'Consecrates your weapon, inflicting $s1 additional damage on your next attack. All damage caused is considered holy damage.', '', '', '', '将圣洁的能量灌入武器，使你的下一次攻击造成$s1点额外伤害，且所有伤害都被计为神圣属性的伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5570, 'Insect Swarm', '', '', '', '虫群', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The enemy target is swarmed by insects, decreasing their chance to hit by $s2% and causing $o1 Nature damage over $d.', '', '', '', '敌人被飞虫围绕，攻击命中率降低$s2%，在$d内受到总计$o1点自然伤害。', '', '', 'Chance to hit decreased by $s2% and $s1 Nature damage every $t1 sec.', '', '', '', '攻击命中率降低$s2%，每$t1秒受到$s1点自然伤害。', '', '');
