INSERT INTO `locales_spell` VALUES (5573, 'Divine Protection', '', '', '', '圣佑术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'You are protected from all physical attacks and spells for $d, but during that time you cannot attack or use physical abilities yourself.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for $25771d.', '', '', '', '让你免受一切物理和法术攻击，持续$d，但是在这段时间内你不能攻击或者使用非法术类的能力。在使用圣佑术之后，圣盾术、保护祝福或圣佑术在$25771d之内无法作用在你身上。', '', '', 'Immune to all attacks and spells.  Cannot attack or use physical abilities.', '', '', '', '免疫一切物理和法术攻击，同时无法攻击或者使用物理技能。', '', '');
INSERT INTO `locales_spell` VALUES (5574, 'Divine Protection', '', '', '', '圣佑术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5575, 'Blessing of Reckoning', '', '', '', '清算圣印', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Places a Blessing on a friendly target that lasts $d.  Every time the Blessed character strikes an enemy, the Blessed character gains $5576s1 health.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加圣印，持续$d。被施加圣印的目标每次使用近战武器击中敌人，就可以恢复$5576s1点生命值。每个圣骑士在同一时间内只能给目标施加一个圣印，且同类型的圣印在同一个目标身上只能存在一个。', '', '', 'Every time you strike an enemy you get $5576s1 health.', '', '', '', '每次命中敌人，你都会恢复$5576s1点生命值。', '', '');
