INSERT INTO `locales_spell` VALUES (5990, 'Nimble Reflexes', '', '', '', '迅捷反射', '', '', '', '', '', '', '', '', '', 'Increases the caster\'s chance to parry by $s1% for $d.', '', '', '', '使施法者的招架几率提高$s1%，持续$d。', '', '', 'Chance to parry increased by $s1%.', '', '', '', '招架几率提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (5993, 'Enraging Bite', '', '', '', '狂怒撕咬', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bear the Enraging Bite ability. Enraging Bite reduces an enemy\'s resistance to physical attacks as well as drawing its attention.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的熊学会狂怒撕咬技能。该技能可以降低敌人的物理抗性，并吸引其注意力。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5994, 'Growl of Fortitude', '', '', '', '坚韧低吼', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bear the Growl of Fortitude ability. Growl of Fortitude increases the maximum health of the bear.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的熊学会坚韧低吼技能。该技能可以提高熊的生命值上限。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5995, 'Roar of Fortitude', '', '', '', '坚韧咆哮', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bear the Roar of Fortitude ability. Roar of Fortitude increases the maximum health of everyone in your party.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的熊学会坚韧咆哮技能。该技能可以提高所有小队成员的生命值上限。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5996, 'Flight of the Peregrine', '', '', '', '鹰隼飞翔', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bird the Flight of the Peregrine ability. Flight of the Peregrine increase the movement speed of the bird.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的鸟学会鹰隼飞翔技能。该技能可以提高鸟的移动速度。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5997, 'Eye Peck', '', '', '', '啄眼', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bird the Eye Peck ability. Eye Peck causes an enemy to miss more often in combat.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的鸟学会啄眼技能。该技能可以使敌人在战斗中更不容易击中目标。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5998, 'Pester', '', '', '', '缠斗', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed bird the Pester ability. Pester greatly increases the attack speed of the bird at the cost of dealing less damage. Every successful attack while in this mode renders the target unable to cast spells for a short time.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的鸟学会缠斗技能。该技能可以明显提高鸟的攻击速度，但是会令其造成更少的伤害。鸟在此形态下每次击中目标，都会导致目标在一小段时间里不能施法。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (5999, 'Ferocity', '', '', '', '凶暴', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed cat the Ferocity ability. Ferocity increases attack speed of the cat at the cost of receiving more damage when hit by phsical attacks.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的豹学会凶暴技能。该技能可以提高豹的移动速度，但是在受到物理攻击时会承受更多伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6000, 'Open Wound', '', '', '', '暴露伤口', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed cat the Open Wound ability. Open Wound deals physical damage over time to an enemy as well as increasing damage received by physical attacks for a short time.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的豹学会暴露伤口技能。这项技能有一定几率令目标的伤口暴露，对其造成持续的伤害，并使其在受到攻击时承受更多的伤害。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6001, 'Tough Shell', '', '', '', '硬壳', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6002, 'Tough Shell', '', '', '', '硬壳', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 21+', '', '', '', '使猎人可以教$g他:她;的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 21+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6003, 'Tough Shell', '', '', '', '硬壳', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 28+', '', '', '', '使猎人可以教$g他:她;的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 28+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6004, 'Tough Shell', '', '', '', '硬壳', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Tough Shell ability. Tough Shell gives your crab a chance to increase it\'s armor value when hit.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的螃蟹学会硬壳技能。该技能使你的螃蟹有一定几率在被击中时提高护甲值。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6005, 'Tight Pinch', '', '', '', '紧钳', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Tight Pinch ability.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的螃蟹学会紧钳技能。该技能使螃蟹下一次击中敌人时造成额外的伤害，并令其昏迷。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6006, 'Clenched Pinchers', '', '', '', '蟹钳夹', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed crab the Clenched Pinchers ability. Clenched Pinchers holds an enemy in place while dealing physical damage over time to it. While holding the enemy, the crab will be unable to attack or perform any other actions.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的教你的螃蟹学会蟹钳夹技能。该技能使螃蟹牢牢夹住一个敌人，令其无法移动，并对其造成持续伤害，同时螃蟹也无法攻击或进行任何其它行动。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6007, 'Quick Snap', '', '', '', '快速撕咬', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed crocilisk the Quick Snap ability. Quick Snap gives your crocilisk a chance to counterattack when hit.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的鳄鱼学会快速撕咬技能。该技能使你的鳄鱼有一定几率在被击中时进行反击。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6008, 'Consume Flesh', '', '', '', '食肉', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed crocilisk the Consume Flesh ability. Consume Flesh gives your crocilisk a chance to steal health from an enemy when attacking.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的鳄鱼学会食肉技能。该技能使你的鳄鱼有一定几率在击中敌人后偷取生命值。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6009, 'Bruise', '', '', '', '瘀伤', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的猩猩学会瘀伤技能。瘀伤使你的猩猩有一定几率在攻击时降低敌人的护甲值。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6010, 'Bruise', '', '', '', '瘀伤', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 18+', '', '', '', '使猎人可以教$g他:她;的猩猩学会瘀伤技能。瘀伤使你的猩猩有一定几率在攻击时降低敌人的护甲值。\n需要：\n宠物等级 18+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6011, 'Bruise', '', '', '', '瘀伤', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level +25', '', '', '', '使猎人可以教$g他:她;的猩猩学会瘀伤技能。瘀伤使你的猩猩有一定几率在攻击时降低敌人的护甲值。\n需要：\n宠物等级 25+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6012, 'Bruise', '', '', '', '瘀伤', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Bruise ability. Bruise gives your gorilla a chance to reduce the armor value of an enemy when attacking.\nRequires: \nPet Level 32+', '', '', '', '使猎人可以教$g他:她;的猩猩学会瘀伤技能。瘀伤使你的猩猩有一定几率在攻击时降低敌人的护甲值。\n需要：\n宠物等级 32+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6013, 'Throw Rock', '', '', '', '投掷石块', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Throw Rock ability. Throw Rock is a ranged attack.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的猩猩学会投掷石块技能。该技能是远程攻击技能。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6014, 'Throw Rock', '', '', '', '投掷石块', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Throw Rock ability. Throw Rock is a ranged attack.\nRequires: \nPet Level 29+', '', '', '', '使猎人可以教$g他:她;的猩猩学会投掷石块技能。该技能是远程攻击技能。\n需要：\n宠物等级 29+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6015, 'Quickness', '', '', '', '迅捷', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed gorilla the Quickness ability. Quickness is an attack that can hit multiple enemies.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的猩猩学会迅捷技能。该技能可以攻击多个敌人。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6016, 'Pierce Armor', '', '', '', '刺穿护甲', '', '', '', '', '', '', '', '', '', 'Reduces an enemy\'s armor by $s1% for $d.', '', '', '', '使敌人的护甲降低$s1%，持续$d。', '', '', 'Armor reduced by $s1%.', '', '', '', '护甲降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (6017, 'Rapid Gallop', '', '', '', '疾速奔跑', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed horse the Rapid Gallop ability. Rapid Gallop increases the movement speed of your horse.', '', '', '', '使猎人可以教$g他:她;的马学会疾速奔跑技能。该技能可以提高马的移动速度。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6019, 'Stomp', '', '', '', '践踏', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed horse the Stomp ability. Stomp deals additional damage as well as slowing the movement speed of the enemy.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的马学会践踏技能。该技能可以对敌人造成额外伤害，并降低其移动速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6020, 'Feast of Prey', '', '', '', '吞食猎物', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed raptor the Feast of Prey ability. Feast of Prey allows your raptor to recover health every time it kills an enemy.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的迅猛龙学会吞食猎物技能。该技能可以使你的迅猛龙在杀死敌人之后回复生命值。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6021, 'Vulnerable', '', '', '', '易伤', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed raptor the Vulnerable ability.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的迅猛龙学会易伤技能。该技能可以在短时间内提高所有物理攻击对一个目标所造成的伤害。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6022, 'Tendon Slice', '', '', '', '挑筋', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed Raptor the Tendon Slice ability. Tendon Slice deals damage over time as well as slowing the enemies movement speed.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的迅猛龙学会挑筋技能。该技能可以对敌人造成持续伤害，并降低其移动速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6023, 'Minor Scorpion Venom', '', '', '', '初级蝎毒', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed Scorpion the Minor Scorpion Venom ability. Minor Scorpion Venom deals damage over time to an enemy.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的蝎子学会初级蝎毒技能。该技能可以对敌人造成持续伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6024, 'Claw Cover', '', '', '', '利爪掩护', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed Scorpion the Claw Cover ability. Claw Cover increases your scorpion\'s chance to parry.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的蝎子学会利爪掩护技能。该技能可以提高蝎子招架敌人攻击的几率。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6025, 'Spider Poison', '', '', '', '蜘蛛毒', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed Spider the Spider Poison ability. Spider Poison deals damage over time to an enemy.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的蜘蛛学会蜘蛛毒技能。该技能可以对敌人造成持续伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6026, 'Web', '', '', '', '蛛网', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows a hunter to teach $ghis:her; tamed Spider the Web ability. Web renders an enemy unable to move.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的蜘蛛学会蛛网技能。该技能可以使敌人无法移动。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
