INSERT INTO `locales_spell` VALUES (6028, 'Web', '', '', '', '蛛网', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Allows a hunter to teach $ghis:her; tamed Spider the Web ability. Web renders an enemy unable to move.\nRequires: \nPet Level 37+', '', '', '', '使猎人可以教$g他:她;的蜘蛛学会蛛网技能。该技能可以使敌人无法移动。\n需要：\n宠物等级 37+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6029, 'Poisonous Spit', '', '', '', '含毒喷溅', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed Spider the Poisonous Spit ability. Poisonous Spit ranged attack that deals damage over time to an enemy.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的蜘蛛学会含毒喷溅技能。该技能可以对敌人进行远程攻击，使其受到持续伤害。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6030, 'Distracting Spit', '', '', '', '涣散喷吐', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed tall strider the Distracting Spit ability. Distracting Spit increases physical damage dealt to an enemy.\nRequires: \nPet Level 13+', '', '', '', '使猎人可以教$g他:她;的陆行鸟学会涣散喷吐技能。该技能可以提高对敌人造成的物理伤害。\n需要：\n宠物等级 13+', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6031, 'Healing Tongue', '', '', '', '治疗之舌', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows a hunter to teach $ghis:her; tamed tall strider the Healing Tongue ability. Healing Tongue heals friendly targets from a short range.\nRequires: \nPet Level 22+', '', '', '', '使猎人可以教$g他:她;的陆行鸟学会治疗之舌技能。该技能可以在短距离外治疗友方目标。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
