INSERT INTO `locales_spell` VALUES (6033, 'Strider Presence', '', '', '', '陆行鸟守护', '', '', '', '', '', '', '', '', '', 'Allows a hunter to teach $ghis:her; tamed tall strider the Strider Presence ability. Strider Presence helps regenerate health and mana.\nRequires: \nPet Level 36+', '', '', '', '使猎人可以教$g他:她;的陆行鸟学会陆行鸟守护技能。该技能可以提高生命值和法力值的回复速度。\n需要：\n宠物等级 36+', '', '', '', '', '', '', '', '', '');
