INSERT INTO `locales_spell` VALUES (6539, 'Dig Trap', '', '', '', '挖掘陷阱', '', '', 'Scorpion', '', '', '', '蝎子', '', '', 'Teaches your tamed scorpion the Dig Trap ability. Dig Trap allows the pet to enter stealth mode but will be rendered unable to move. If the scorpion attacks from this position it will deal additional damage.\nRequires: \nPet Level 22+', '', '', '', '教你的蝎子学会挖掘陷阱技能。该技能可以使你的蝎子可以进入潜行状态，但此时无法移动。如果它从该位置发动攻击，则可造成额外的伤害。\n需要：\n宠物等级 22+', '', '', '', '', '', '', '', '', '');
