INSERT INTO `locales_spell` VALUES (6760, 'Eviscerate', '', '', '', '剔骨', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Finishing move that causes damage per combo point, increased by Attack Power:\n   1 point  : 14-22 damage\n   2 points: 25-33 damage\n   3 points: 36-44 damage\n   4 points: 47-55 damage\n   5 points: 58-66 damage', '', '', '', '终结技，根据连击点数决定造成的伤害，该伤害会受到攻击强度的加成影响：\n   1点：14-22 伤害\n   2点：25-33 伤害\n   3点：36-44 伤害\n   4点：47-55 伤害\n   5点：58-66 伤害', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (6761, 'Eviscerate', '', '', '', '剔骨', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Finishing move that causes damage per combo point, increased by Attack Power:\n   1 point  : 25-39 damage\n   2 points: 44-58 damage\n   3 points: 63-77 damage\n   4 points: 82-96 damage\n   5 points: 101-115 damage', '', '', '', '终结技，根据连击点数决定造成的伤害，该伤害会受到攻击强度的加成影响：\n   1点：25-39 伤害\n   2点：44-58 伤害\n   3点：63-77 伤害\n   4点：82-96 伤害\n   5点：101-115 伤害', '', '', '', '', '', '', '', '', '');
