INSERT INTO `locales_spell` VALUES (6767, 'Mark of Shame', '', '', '', '耻辱印记', '', '', '', '', '', '', '', '', '', 'Marks the player with a purple arrow. Lasts for 10 minutes.', '', '', '', '将玩家用紫色箭头标记起来，持续10分钟。', '', '', 'You have failed the Test of Lore! You carry the Mark of Shame! For shame!!', '', '', '', '你在知识问答中失败了！你被打上了羞辱的印记！', '', '');
