INSERT INTO `locales_spell` VALUES (6774, 'Slice and Dice', '', '', '', '切割', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Finishing move that increases melee attack speed by $s2%.  Lasts longer per combo point:\n   1 point  : 9 seconds\n   2 points: 12 seconds\n   3 points: 15 seconds\n   4 points: 18 seconds\n   5 points: 21 seconds', '', '', '', '终结技，使近战攻击速度提高$s2%。根据连击点数的数量决定效果持续时间：\n   1点：9秒\n   2点：12秒\n   3点：15秒\n   4点：18秒\n   5点：21秒', '', '', 'Melee attack speed increased by $s2%.', '', '', '', '近战攻击速度提高$s2%。', '', '');
