INSERT INTO `locales_spell` VALUES (6898, 'White Ram', '', '', '', '白山羊', '', '', '', '', '', '', '', '', '', 'Male rams will often smash their thick skulls against each other for hours to impress a female. In that way, they\'re very similar to dwarves.', '', '', '', '雄性公羊经常会用厚厚的头骨互相撞击几个小时，以给雌性留下深刻印象。从这一点来说，他们与矮人非常相似。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (6899, 'Brown Ram', '', '', '', '棕山羊', '', '', '', '', '', '', '', '', '', 'Male rams will often smash their thick skulls against each other for hours to impress a female. In that way, they\'re very similar to dwarves.', '', '', '', '雄性公羊经常会用厚厚的头骨互相撞击几个小时，以给雌性留下深刻印象。从这一点来说，他们与矮人非常相似。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
