INSERT INTO `locales_spell` VALUES (6907, 'Diseased Slime', '', '', '', '疾病软泥', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s1% and its movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (6909, 'Curse of Thorns', '', '', '', '荆棘诅咒', '', '', '', '', '', '', '', '', '', 'Curses an enemy for $d., giving it $h% chance to take $6910s1 damage on attack.', '', '', '', '诅咒一个敌人，持续$d，使其有$h%的几率在击中目标时承受$6910s1点伤害。', '', '', '$h% chance to take $6910s1 damage on attack.', '', '', '', '有$h%的几率在击中目标时承受$6910s1点伤害。', '', '');
