INSERT INTO `locales_spell` VALUES (6917, 'Venom Spit', '', '', '', '毒液喷吐', '', '', '', '', '', '', '', '', '', 'Spits poison at an enemy, inflicting Nature damage, then additional damage every $t2 sec. for $d.', '', '', '', '向敌人喷出毒液，对其造成自然伤害，并每$t2秒对其造成一次额外伤害，持续$d。', '', '', 'Nature damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到一次自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (6918, 'Summon Snufflenose', '', '', '', '召唤地鼠', '', '', '', '', '', '', '', '', '', 'Use in Razorfen Kraul near buried tubers to summon a Snufflenose Gopher.', '', '', '', '在剃刀沼泽中的薯块附近使用以召唤地鼠。', '', '', '', '', '', '', '', '', '');
