INSERT INTO `locales_spell` VALUES (6921, 'Shadowhorn Charge', '', '', '', '暗角冲锋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the Physical damage dealt by the caster by $s2 and speeds its movement by $s1% for $d. Also curses an enemy on the first successful hit, reducing the Physical damage it deals by $6922s2, reducing the magical damage it deals by $6922s3, and increasing the Physical damage it takes by $6922s1 for $6922d.', '', '', '', '使施法者对敌人造成的物理伤害提高$s2点，移动速度提高$s1%，持续$d。在第一次成功击中敌人时诅咒敌人，使其物理伤害能力降低$6922s2点，魔法伤害能力降低$6922s3点，受到物理攻击时承受的伤害提高$6922s1点，持续$6922d。', '', '', 'Movement speed increased by $s1%.\nPhysical damage dealt is increased by $s2.', '', '', '', '对敌人造成的物理伤害提高$s2点。\n移动速度提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (6922, 'Curse of the Shadowhorn', '', '', '', '暗角诅咒', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Physical damage taken is increased by $s1.\nPhysical damage dealt is reduced by $s2.\nMagical damage dealt is reduced by $s3.', '', '', '', '受到物理攻击时承受的伤害提高$s1点。\n物理伤害能力降低$s2点。\n魔法伤害能力降低$s3点。', '', '');
