INSERT INTO `locales_spell` VALUES (7069, 'Enraging Aura', '', '', '', '狂怒光环', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by nearby party members by $s1. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.', '', '', '', '使附近队友对敌人造成的物理伤害提高$s1点。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。效果一直持续，直到主动取消。', '', '', 'Physical damage dealt is increased by $s1.', '', '', '', '对敌人造成的物理伤害提高$s1点。', '', '');
