INSERT INTO `locales_spell` VALUES (7121, 'Anti-Magic Shield', '', '', '', '反魔法盾', '', '', '', '', '', '', '', '', '', 'Creates an anti-magic shell around the caster, giving it magic immunity for $d.', '', '', '', '反魔法的护罩包围施法者，使其对魔法免疫，持续$d。', '', '', 'Immune to magic.', '', '', '', '免疫魔法。', '', '');
INSERT INTO `locales_spell` VALUES (7122, 'Blood Tap', '', '', '', '血液分流', '', '', '', '', '', '', '', '', '', 'Drains $s1 health from an enemy, healing the caster for up to twice that amount.', '', '', '', '从敌人身上吸取$s1点生命值，并使施法者恢复最多相当于该数值两倍的生命值。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7124, 'Arugal\'s Gift', '', '', '', '阿鲁高的礼物', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Shadow damage to an enemy every $t1 sec. for $d.', '', '', '', '每$t1秒对一个敌人造成$s1点暗影伤害，持续$d。', '', '', '$s1 Shadow damage inflicted every $t1 sec.', '', '', '', '每$t1秒受到$s1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (7125, 'Toxic Saliva', '', '', '', '毒性唾液', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Nature damage to an enemy every $t1 sec. Also drains $s2 mana every $t2 sec., transferring it to the caster. Lasts $d.', '', '', '', '每$t1秒对一个敌人造成$s1点自然伤害。每$t2秒吸取$s2点法力值，并将其转移给施法者。持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.\n$s2 mana leeched every $t2 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。\n每$t2秒吸取$s2点法力值。', '', '');
