INSERT INTO `locales_spell` VALUES (7127, 'Wavering Will', '', '', '', '摇摆意志', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks speed by $s1%, slows its casting speed by $s3%, and slows its movement by $s2%. Lasts $d.', '', '', '', '使敌人的攻击间隔延长$s1%，施法速度降低$s3%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nCasting speed reduced by $s3%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n施法速度降低$s3%。\n移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (7128, 'Inner Fire', '', '', '', '心灵之火', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'A burst of Holy energy fills the caster, increasing armor by $s1 and attack power by $s2.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.', '', '', '', '圣洁的能量充满施法者的体内，使$g他:她;的防御值提高$s1点。每次近战或远程伤害都会使牧师消耗一次防护能量。效果可持续$d，或在$n次防护之后消失。', '', '', 'Increases armor by $s1.', '', '', '', '防御值提高$s1点。', '', '');
