INSERT INTO `locales_spell` VALUES (7137, 'Shadow Charge', '', '', '', '暗影冲锋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Charge an enemy, increasing speed and causing an additional $s2 damage on the first attack.', '', '', '', '向敌人冲锋，提高移动速度，并使第一次攻击对目标造成$s2点额外伤害。', '', '', 'Movement speed increased by $s1%.\nInflicting an additional $s2 Physical damage on first attack.', '', '', '', '移动速度提高$s1%。\n第一次攻击可以造成$s2点额外物理伤害。', '', '');
INSERT INTO `locales_spell` VALUES (7139, 'Fel Stomp', '', '', '', '恶魔践踏', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to nearby enemies, stunning them for $d. and increasing the Physical damage they take by $s3.', '', '', '', '对附近的敌人造成普通武器伤害再加上$s1点额外伤害，使它们昏迷$d，并使它们受到物理攻击时所承受的伤害提高$s3。', '', '', 'Stunned.\nPhysical damage taken is increased by $s3.', '', '', '', '昏迷。\n受到物理攻击时承受的伤害提高$s3点。', '', '');
