INSERT INTO `locales_spell` VALUES (7144, 'Stone Slumber', '', '', '', '石化休眠', '', '', '', '', '', '', '', '', '', 'Invokes the power of stone for $d., rendering the caster immune to Physical attack, but unable to act. During this time, the caster heals $s2 damage every $t2 sec.', '', '', '', '引导岩石的能量，使施法者免疫物理攻击，但无法行动，持续$d。在这段时间里，施法者每$t2秒回复$s2点生命值。', '', '', '$s2 damage healed every $t2 sec.\nImmune to Physical attack, but unable to act.', '', '', '', '每$t2秒回复$s2点生命值。\n免疫物理攻击，但无法行动。', '', '');
INSERT INTO `locales_spell` VALUES (7145, 'Diving Sweep', '', '', '', '翻滚扫击', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to an enemy and its nearest allies, affecting up to $x1 targets.', '', '', '', '对目标和它身边最近的敌人造成你的武器伤害再加$s1点伤害，最多可影响$x1个目标。', '', '', '', '', '', '', '', '', '');
