INSERT INTO `locales_spell` VALUES (7160, 'Execute', '', '', '', '斩杀', '', '', '', '', '', '', '', '', '', 'Attempts to finish off a wounded enemy, inflicting normal damage plus $s1. Execute can only be used on enemies that have 20% or less health.', '', '', '', '尝试斩杀受伤的敌人，对其造成普通伤害外加$s1点伤害。斩杀只能对剩余生命值不高于20%的敌人使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7162, 'First Aid', '', '', '', '急救', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Heals a target for an amount equal to the caster\'s maximum health.', '', '', '', '为目标治疗相当于施法者生命值上限的伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7164, 'Defensive Stance', '', '', '', '防御姿态', '', '', '', '', '', '', '', '', '', 'Assumes a defensive stance that generates rage when the warrior is hit, as well as reducing rage decay while the warrior is out of combat. Lasts $d.', '', '', '', '进入防御性的姿态，当战士被击中时产生怒气值。战士不再处于战斗状态中时的怒气值衰减速度也会降低。持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7165, 'Battle Stance', '', '', '', '战斗姿态', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Assumes a balanced combat stance that generates rage when the warrior is hit, as well as when the warrior strikes an opponent. Lasts $d.', '', '', '', '攻守兼备的作战姿态，在击中敌人或被击中时均提高怒气值。', '', '', '', '', '', '', '', '', '');
