INSERT INTO `locales_spell` VALUES (7369, 'Cleave', '', '', '', '顺劈斩', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'A sweeping attack that does your weapon damage plus $s1 to the target and his nearest ally.', '', '', '', '横扫攻击，对目标和它身边最近的一个敌人造成武器伤害再加上$s1点伤害。', '', '', '', '', '', '', '', '', '');
