INSERT INTO `locales_spell` VALUES (7371, 'Charge', '', '', '', '冲锋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Charges an enemy, immobilizes it for $7922d, and adds $s2 melee attack power to the boar\'s next attack.', '', '', '', '向敌人发起冲锋，使其在$7922d内无法移动，并使你的野猪的下一次攻击获得$s2点近战攻击强度加成。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7372, 'Hamstring', '', '', '', '断筋', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Maims the enemy, causing $s1 damage and slowing the enemy\'s movement by $s2% for $d.', '', '', '', '使敌人残废，对其造成$s1点额外伤害，并使其移动速度降低$s2%，持续$d。', '', '', 'Movement slowed by $s2%.', '', '', '', '移动速度降低$s2%。', '', '');
