INSERT INTO `locales_spell` VALUES (7379, 'Revenge', '', '', '', '复仇', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Instantly counterattack an enemy for $s1 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.', '', '', '', '立即反击敌人，对其造成$s1点伤害，并造成大量的威胁。复仇只有在成功格挡、躲闪或招架之后才能使用。', '', '', '', '', '', '', '', '', '');
