INSERT INTO `locales_spell` VALUES (7645, 'Dominate Mind', '', '', '', '统御意志', '', '', '', '', '', '', '', '', '', 'Takes control of a humanoid enemy up to level $s1 for $d., but increases the time between its attacks by $s2%.', '', '', '', '控制一个等级不高于$s1级的敌对人型生物，持续$d。使其攻击间隔延长$s2%。', '', '', 'Charmed.\nTime between attacks increased by $s2%.', '', '', '', '被魅惑。\n攻击间隔延长$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (7646, 'Curse of Weakness', '', '', '', '虚弱诅咒', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Damage caused by the target is reduced by $s1 for $d.  Only one Curse per Warlock can be active on any one target.', '', '', '', '目标所能造成的伤害降低$s1点，持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Physical damage done reduced by $s1.', '', '', '', '对目标造成的物理伤害降低$s1点。', '', '');
