INSERT INTO `locales_spell` VALUES (7648, 'Corruption', '', '', '', '腐蚀术', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Corrupts the target, causing $o1 Shadow damage over $d.', '', '', '', '腐蚀目标，在$d内造成累计$o1点伤害。', '', '', '$s1 Shadow damage every $t1 seconds.', '', '', '', '每$t1秒$s1点暗影伤害。', '', '');
