INSERT INTO `locales_spell` VALUES (7651, 'Drain Life', '', '', '', '吸取生命', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Transfers $s1 health every second from the target to the caster.  Lasts $d.', '', '', '', '每秒钟吸取目标$s1点生命值，并将其转移给施法者，持续$d。', '', '', 'Drains $s1 health each second to the caster.', '', '', '', '每秒吸取$s1点生命值并将其转移给施法者。', '', '');
INSERT INTO `locales_spell` VALUES (7652, 'Drain Life', '', '', '', '吸取生命', '', '', 'Rank 4', '', '', '', '等级 4', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
