INSERT INTO `locales_spell` VALUES (7655, 'Hex of Ravenclaw', '', '', '', '鸦爪妖术', '', '', '', '', '', '', '', '', '', 'Curses an enemy, reducing the Physical damage it deals by $8320s1 and decreasing its magical damage by $8320s2 for $8320d. Also, the curse increases the Physical damage the caster deals by $7657s1 and enhances its magical damage by $7657s2 for $7657d.', '', '', '', '诅咒一个敌人，使其物理攻击所能造成的伤害降低$8320s1点，魔法攻击所能造成的伤害降低$8320s2点，持续$8320d。该诅咒还可以使施法者的物理攻击所能造成的伤害提高$7657s1点，魔法攻击所能造成的伤害提高$7657s2点，持续$7657d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7656, 'Hex of Ravenclaw', '', '', '', '鸦爪妖术', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Physical damage dealt is reduced by $s1.\nMagical damage dealt is reduced by $s2.', '', '', '', '物力伤害能力降低$s1点。\n魔法伤害能力降低$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (7657, 'Hex of Ravenclaw', '', '', '', '鸦爪妖术', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Physical damage dealt is increased by $s1.\nMagical damage dealt is increased by $s2.', '', '', '', '对敌人造成的物理伤害提高$s1点。\n对敌人造成的魔法伤害提高$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (7658, 'Curse of Recklessness', '', '', '', '鲁莽诅咒', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Curses the target with recklessness, increasing melee attack power by $s1 but reducing armor by $s2 for $d.  Cursed enemies will not flee and will ignore Fear and Horror effects.  Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加鲁莽的诅咒，使其近战攻击强度提高$s1点，但护甲降低$s2点，持续$d。被诅咒的敌人不会逃跑，也不会受到恐惧的影响。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Increases melee attack power by $s1 and decreases armor by $s2.   Target will not flee and will ignore Fear and Horror effects.', '', '', '', '近战攻击强度提高$s1点，护甲降低$s2点。目标不会逃跑，且免疫恐惧效果。', '', '');
INSERT INTO `locales_spell` VALUES (7659, 'Curse of Recklessness', '', '', '', '鲁莽诅咒', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Curses the target with recklessness, increasing melee attack power by $s1 but reducing armor by $s2 for $d.  Cursed enemies will not flee and will ignore Fear and Horror effects.  Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加鲁莽的诅咒，使其近战攻击强度提高$s1点，但护甲降低$s2点，持续$d。被诅咒的敌人不会逃跑，也不会受到恐惧的影响。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Increases melee attack power by $s1 and decreases armor by $s2.   Target will not flee and will ignore Fear and Horror effects.', '', '', '', '近战攻击强度提高$s1点，护甲降低$s2点。目标不会逃跑，且免疫恐惧效果。', '', '');
