INSERT INTO `locales_spell` VALUES (7731, 'Fishing', '', '', '', '钓鱼', '', '', 'Journeyman', '', '', '', '中级', '', '', 'Equip a fishing pole and find a body of water to fish.  Right-Click on the bob in the water when it splashes to catch your fish.  Higher skill increases your chance of fishing successfully in higher level areas.', '', '', '', '装备鱼竿之后可以寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7732, 'Fishing', '', '', '', '钓鱼', '', '', 'Expert', '', '', '', '高级', '', '', 'Equip a fishing pole and find a body of water to fish.  Right-Click on the bob in the water when it splashes to catch your fish.  Higher skill increases your chance of fishing successfully in higher level areas.', '', '', '', '装备鱼竿之后可以寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。', '', '', '', '', '', '', '', '', '');
