INSERT INTO `locales_spell` VALUES (7739, 'Inferno Shell', '', '', '', '地狱火罩', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to nearby enemies, and encases the caster in a shield of flame that lasts $d. and burns melee attackers for an additional $s2 damage.', '', '', '', '对附近的敌人造成$s1点火焰伤害，并使施法者被火焰之盾包围，持续$d。击中施法者的近战攻击者将承受$s2点额外的伤害。', '', '', '$s2 Fire damage inflicted to melee attackers.', '', '', '', '对近战攻击者造成$s2点火焰伤害。', '', '');
