INSERT INTO `locales_spell` VALUES (7965, 'Cobrahn Serpent Form', '', '', '', '考布莱恩毒蛇形态', '', '', '', '', '', '', '', '', '', 'Shapeshifts into a serpent for $d., increasing attack damage by $s2, and increasing the time between attacks by $s3%.', '', '', '', '变成一条毒蛇，持续$d。攻击伤害提高$s2点，但攻击间隔延长$s3%。', '', '', 'Transformed into serpent.\nPhysical damage dealt is increased by $s2.\nTime between attacks increased by $s3%.', '', '', '', '变成毒蛇。\n物理伤害提高$s2点。\n攻击间隔延长$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (7966, 'Thorns Aura', '', '', '', '荆棘光环', '', '', '', '', '', '', '', '', '', 'Causes $s1 Nature damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts $d.', '', '', '', '对任何使用近战武器攻击附近小队成员的生物造成$s1点自然伤害。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', '$s1 Nature damage inflicted to melee attackers.', '', '', '', '每$t1秒对近战攻击者造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (7967, 'Naralex\'s Nightmare', '', '', '', '纳拉雷克斯的梦魇', '', '', '', '', '', '', '', '', '', 'Puts the enemy target to sleep for up to $d. Any hostile action will awaken the target. Only one target can be slept at a time.', '', '', '', '使敌人进入睡眠状态，最多持续$d。任何对目标有敌意的行为都会唤醒它。同一时间内只能有一个目标被催眠。', '', '', 'Asleep.', '', '', '', '沉睡。', '', '');
