INSERT INTO `locales_spell` VALUES (7979, 'Compact Harvest Reaper', '', '', '', '微型收割机', '', '', '', '', '', '', '', '', '', 'Summons $s1 $lCompact Harvest Reaper:Compact Harvest Reapers; to aid the caster in battle for $d. A Reaper cannot be healed, but it can be looted after it has been destroyed.', '', '', '', '召唤$s1台微型收割机为施法者作战，持续$d。收割机无法被治疗，但可以在被摧毁之后回收一部分零件。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (7992, 'Slowing Poison', '', '', '', '减速毒药', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s1% and slows its movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
