INSERT INTO `locales_spell` VALUES (8024, 'Flametongue Weapon', '', '', '', '火舌武器', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Imbue the Shaman\'s weapon with fire.  Each hit causes $/77;8026m1 to $/25;8026M1 additional Fire damage, based on the speed of the weapon.  Slower weapons cause more fire damage per swing.  Lasts for 5 minutes.', '', '', '', '给萨满祭司的武器附加火焰的力量。每次击中敌人都会对其造成$/77;8026m1到$/25;8026M1点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。持续5分钟。', '', '', '', '', '', '', '', '', '');
