INSERT INTO `locales_spell` VALUES (8249, 'Flametongue Totem', '', '', '', '火舌图腾', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Summons a Flametongue Totem with $s1 health at the feet of the caster.  The totem enchants all party members\' main-hand weapons with fire if they are within $8250a1 yards.  Each hit causes $/77;8248m1 to $/25;8248M1 additional Fire damage, based on the speed of the weapon.  Slower weapons cause more fire damage per swing.  Lasts $d.', '', '', '', '在施法者身边召唤一个生命值为$s1点的火舌图腾。图腾令半径$8250a1码范围内的所有小队成员的主手武器都附有火焰效果，每次击中敌人都会对其造成$/77;8248m1到$/25;8248M1点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (8250, 'Flametongue Totem Effect', '', '', '', '火舌图腾效果', '', '', 'Rank 2', '', '', '', '等级 2', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
