INSERT INTO `locales_spell` VALUES (8255, 'Strong Cleave', '', '', '', '强力顺劈', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Inflicts normal damage plus $s1 to an enemy and its nearest allies, affecting up to $x1 targets and increasing the time between their attacks by $s2% for $d.', '', '', '', '对目标和它身边最近的敌人造成你的武器伤害再加$s1点伤害，最多可影响$x1个目标，使它们的攻击间隔延长$s2%。', '', '', 'Time between attacks increased by $s2%.', '', '', '', '攻击间隔延长$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (8256, 'Lethal Toxin', '', '', '', '致死毒素', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Nature damage to an enemy every $t1 sec. for $d.', '', '', '', '每$t1秒对敌人造成$s1点自然伤害，持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8257, 'Venom Sting', '', '', '', '毒性钉刺', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 Nature damage to an enemy, then an additional $s1 damage every $t1 sec. for $d.', '', '', '', '对目标造成$s2点自然伤害，并继续对其每$t1秒造成$s1点伤害，持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8258, 'Devotion Aura', '', '', '', '虔诚光环', '', '', '', '', '', '', '', '', '', 'Gives $s1 additional armor to nearby party members for $d. Players may only have one aura on them per paladin at any one time.', '', '', '', '使所有小队成员获得$M1点额外的护甲。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Armor increased by $s1.', '', '', '', '护甲提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (8259, 'Whirling Barrage', '', '', '', '旋风倾泻', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to nearby enemies.', '', '', '', '对附近的敌人造成普通武器伤害再加上$s1点额外伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (8260, 'Rushing Charge', '', '', '', '急速冲锋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the caster\'s movement speed by $s1% for $d. and causes it to inflict an additional $s2 damage on its first attack.', '', '', '', '使施法者的移动速度提高$s1%，持续$d，并使其在第一次攻击时所造成的伤害提高$s2点。', '', '', 'Movement speed increased by $s1%.\nInflicts an additional $s2 damage on first attack.', '', '', '', '移动速度提高$s1%。\n在第一次攻击时所造成的伤害提高$s2点。', '', '');
