INSERT INTO `locales_spell` VALUES (8288, 'Drain Soul', '', '', '', '吸取灵魂', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Drains the soul of the target, causing $o2 Shadow damage over $d.  If the target dies while being drained, and yields experience or honor, the caster gains a Soul Shard.  Soul Shards are required for other spells.', '', '', '', '吸取目标的灵魂，在$d内对其造成累计$o2点暗影伤害。如果目标在被吸取灵魂的过程中死亡，且施法者因此获得经验值或荣誉，则施法者可以得到一块灵魂碎片。灵魂碎片是施放其它一些法术所必需的材料。', '', '', '$s2 Shadow damage every $t2 seconds.', '', '', '', '每$t2秒$s2点暗影伤害。', '', '');
