INSERT INTO `locales_spell` VALUES (8292, 'Chain Bolt', '', '', '', '闪电链', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, causing $s1 Nature damage to each.', '', '', '', '向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，对每个目标造成$s1点自然伤害，最多可攻击$x1个目标。', '', '', '', '', '', '', '', '', '');
