INSERT INTO `locales_spell` VALUES (8344, 'Universal Remote', '', '', '', '通用遥控器', '', '', '', '', '', '', '', '', '', 'Allows control of a mechanical target for a short time.  It may not always work and may just root the machine or make it very very angry.  Gnomish engineering at its finest.', '', '', '', '可以控制一个机械目标，持续一小段时间。这个设备并不稳定，可能会令目标瘫痪或者变得非常非常生气。这是侏儒工程学尖端技术的体现。', '', '', '', '', '', '', '', '', '');
