INSERT INTO `locales_spell` VALUES (8363, 'Parasite', '', '', '', '寄生', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s2 to an enemy, then an additional $s1 Nature damage every $t1 sec. for $d.', '', '', '', '对敌人造成普通伤害再加上$s2点额外伤害，并继续对其造成每$t1秒$s1点额外的自然伤害，持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8364, 'Blizzard', '', '', '', '暴风雪', '', '', '', '', '', '', '', '', '', 'Calls down a blizzard that lasts $d., inflicting $s1 Frost damage every $t1 sec. to all enemies in a selected area.', '', '', '', '召唤持续$d的暴风雪，对指定区域内的所有敌人每$t1秒造成$s1点冰霜伤害。', '', '', '', '', '', '', '', '', '');
