INSERT INTO `locales_spell` VALUES (8512, 'Windfury Totem', '', '', '', '风怒图腾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Summons a Windfury Totem with $s1 health at the feet of the caster.  The totem enchants all party members main-hand weapons with wind, if they are within $8514a1 yards.  Each hit has a 20% chance of granting the attacker $8516s2 extra $lattack:attacks; with $8516s1 extra melee attack power.  Lasts $d.', '', '', '', '在施法者身边召唤一个生命值为$s1点的风怒图腾，持续$d。它可以使半径$8514a1码范围内的所有小队成员的主手武器附带风怒效果，每次击中敌人都有20%的几率令攻击者获得额外的$8516s2次近战攻击机会，并且在这几次攻击中的攻击强度提高$8516s1点。', '', '', '', '', '', '', '', '', '');
