INSERT INTO `locales_spell` VALUES (8623, 'Eviscerate', '', '', '', '剔骨', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Finishing move that causes damage per combo point, increased by Attack Power:\n   1 point  : 60-90 damage\n   2 points: 105-135 damage\n   3 points: 150-180 damage\n   4 points: 195-225 damage\n   5 points: 240-270 damage', '', '', '', '终结技，根据连击点数决定造成的伤害，该伤害会受到攻击强度的加成影响：\n   1点：60-90 伤害\n  2点：105-135 伤害\n  3点：150-180 伤害\n  4点：195-225 伤害\n  5点：240-270 伤害', '', '', '', '', '', '', '', '', '');
