INSERT INTO `locales_spell` VALUES (8629, 'Gouge', '', '', '', '凿击', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Causes $s1 damage, incapacitating the opponent for $d, and turns off your attack.  Target must be facing you.  Any damage caused will revive the target.  Awards $s2 combo $lpoint:points;.', '', '', '', '对目标造成$s1点伤害，令其瘫痪$d，并使你不再攻击这个目标。这个技能必须在目标面对着你的时候发动，任何后继的伤害都会令目标醒来。奖励$s2个连击点数。', '', '', 'Incapacitated.', '', '', '', '瘫痪。', '', '');
