INSERT INTO `locales_spell` VALUES (8639, 'Rupture', '', '', '', '割裂', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\n   1 point  : 60 damage over 8 secs\n   2 points: 90 damage over 10 secs\n   3 points: 126 damage over 12 secs\n   4 points: 168 damage over 14 secs\n   5 points: 216 damage over 16 secs', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间，该伤害会受到攻击强度的加成影响：\n   1点：60伤害，持续8秒\n   2点：90伤害，持续10秒\n   3点：126伤害，持续12秒\n   4点：168伤害，持续14秒\n   5点：216伤害，持续16秒', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8640, 'Rupture', '', '', '', '割裂', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\n   1 point  : 88 damage over 8 secs\n   2 points: 130 damage over 10 secs\n   3 points: 180 damage over 12 secs\n   4 points: 238 damage over 14 secs\n   5 points: 304 damage over 16 secs', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间，该伤害会受到攻击强度的加成影响：\n   1点：88伤害，持续8秒\n   2点：130伤害，持续10秒\n   3点：180伤害，持续12秒\n   4点：238伤害，持续14秒\n   5点：304伤害，持续16秒', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
