INSERT INTO `locales_spell` VALUES (8989, 'Whirlwind', '', '', '', '旋风斩', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Attacks nearby enemies in a whirlwind of steel that lasts $d., inflicting weapon damage plus $3231s1 every $t1 sec. Grants the caster temporary magic immunity.', '', '', '', '像旋风一般挥舞手中的武器，攻击周围的所有敌人，每$t1秒对它们造成武器伤害再加上$3231s1点额外伤害，持续$d。', '', '', 'Immune to magic.\nInflicting normal damage plus $3231s1 every $t1 sec to nearby enemies.', '', '', '', '免疫魔法。\n每$t1秒对附近的所有敌人造成武器伤害外加$3231s1点伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8990, 'Retribution Aura', '', '', '', '惩罚光环', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.', '', '', '', '对任何使用近战武器攻击附近小队成员的生物造成$s1点神圣伤害。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', '$s1 Holy damage inflicted to melee attackers.', '', '', '', '对攻击者造成$s1点神圣伤害。', '', '');
INSERT INTO `locales_spell` VALUES (8992, 'Shred', '', '', '', '撕碎', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Shred the target, causing $s2% damage plus 99 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.', '', '', '', '撕扯目标，对其造成武器伤害的$s2%再加上99点伤害，必须在目标背后发动。奖励$s3个连击点数。', '', '', '', '', '', '', '', '', '');
