INSERT INTO `locales_spell` VALUES (8994, 'Banish', '', '', '', '放逐术', '', '', '', '', '', '', '', '', '', 'Banishes an enemy, preventing all action but making it invulnerable for up to $d. Only one target can be banished at a time.', '', '', '', '放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续$d。在同一时间内只能放逐一个目标。', '', '', 'Immune to all attacks and spells, but unable to act.', '', '', '', '不会受到任何伤害，但也无法做出任何动作。', '', '');
