INSERT INTO `locales_spell` VALUES (9492, 'Rip', '', '', '', '撕扯', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\n   1 point  : 66 damage over $d.\n   2 points: 108 damage over $d.\n   3 points: 150 damage over $d.\n   4 points: 192 damage over $d.\n   5 points: 234 damage over $d.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定伤害总量，该伤害会受到攻击强度的加成影响：\n   1点：$d内66伤害\n   2点：$d内108伤害\n   3点：$d内150伤害\n   4点：$d内192伤害\n   5点：$d内234伤害', '', '', 'Bleed damage every $t1 seconds.', '', '', '', '每$t1秒因流血受到一次伤害。', '', '');
INSERT INTO `locales_spell` VALUES (9493, 'Rip', '', '', '', '撕扯', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\n   1 point  : 90 damage over $d.\n   2 points: 144 damage over $d.\n   3 points: 198 damage over $d.\n   4 points: 252 damage over $d.\n   5 points: 306 damage over $d.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定伤害总量，该伤害会受到攻击强度的加成影响：\n   1点：$d内90伤害\n   2点：$d内144伤害\n   3点：$d内198伤害\n   4点：$d内252伤害\n   5点：$d内306伤害', '', '', 'Bleed damage every $t1 seconds.', '', '', '', '每$t1秒因流血受到一次伤害。', '', '');
