INSERT INTO `locales_spell` VALUES (9612, 'Ink Spray', '', '', '', '墨汁喷射', '', '', '', '', '', '', '', '', '', 'Reduces an enemy\'s chance to hit by $s1% for $d.', '', '', '', '使敌人攻击时的命中几率降低$s1%，持续$d。', '', '', 'Chance to hit reduced by $s1%.', '', '', '', '击中目标的几率降低$s1%。', '', '');
