INSERT INTO `locales_spell` VALUES (9614, 'Rift Beacon', '', '', '', '裂隙标记', '', '', '', '', '', '', '', '', '', 'Marks an enemy with a tracking device. After $d., $9615s1 Lost One Rift Travelers will find and attack the enemy. Lost One Rift Travelers are unstable at the subatomic level and so cannot maintain physical form past $9615d.', '', '', '', '使用追踪设备标记目标，$d之后，$9615s1个失落裂隙行者会找到并攻击该目标。失落裂隙行者无法在这种状态下长时间维持实体形态，因此会在$9615d后消失。', '', '', 'Rift Travelers are locking onto your position. They will find you after $d.', '', '', '', '裂隙行者正在对你进行定位。$d之后，裂隙行者就会找到你。', '', '');
INSERT INTO `locales_spell` VALUES (9615, 'Summon Rift Traveler', '', '', '', '召唤裂隙行者', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
