INSERT INTO `locales_spell` VALUES (9894, 'Rip', '', '', '', '撕扯', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\n   1 point  : 192 damage over $d.\n   2 points: 312 damage over $d.\n   3 points: 432 damage over $d.\n   4 points: 552 damage over $d.\n   5 points: 672 damage over $d.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定伤害总量，该伤害会受到攻击强度的加成影响：\n   1点：$d内192伤害\n   2点：$d内312伤害\n   3点：$d内432伤害\n   4点：$d内552伤害\n   5点：$d内672伤害', '', '', 'Bleed damage every $t1 seconds.', '', '', '', '每$t1秒因流血受到一次伤害。', '', '');
