INSERT INTO `locales_spell` VALUES (10605, 'Chain Lightning', '', '', '', '闪电链', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies.  Each jump reduces the damage by 30%.  Affects $x1 total targets.', '', '', '', '向敌人射出一支闪电箭，对其造成$s1点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少30%，最多可攻击$x1个目标。', '', '', '', '', '', '', '', '', '');
