INSERT INTO `locales_spell` VALUES (10613, 'Windfury Totem', '', '', '', '风怒图腾', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Summons a Windfury Totem with $s1 health at the feet of the caster.  The totem enchants all party members main-hand weapons with wind, if they are within $10607a1 yards.  Each hit has a 20% chance of granting the attacker $10608s2 extra $lattack:attacks; with $10608s1 extra melee attack power.  Lasts $d.', '', '', '', '在施法者身边召唤一个生命值为$s1点的风怒图腾，持续$d。它可以使半径$10607a1码范围内的所有小队成员的主手武器附带风怒效果，每次击中敌人都有20%的几率令攻击者获得额外的$10607s2次近战攻击机会，并且在这几次攻击中的攻击强度提高$10607s1点。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10614, 'Windfury Totem', '', '', '', '风怒图腾', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Summons a Windfury Totem with $s1 health at the feet of the caster.  The totem enchants all party members main-hand weapons with wind, if they are within $10611a1 yards.  Each hit has a 20% chance of granting the attacker $10610s2 extra $lattack:attacks; with $10610s1 extra melee attack power.  Lasts $d.', '', '', '', '在施法者身边召唤一个生命值为$s1点的风怒图腾，持续$d。它可以使半径$10611a1码范围内的所有小队成员的主手武器附带风怒效果，每次击中敌人都有20%的几率令攻击者获得额外的$10610s2次近战攻击机会，并且在这几次攻击中的攻击强度提高$10610s1点。', '', '', '', '', '', '', '', '', '');
