INSERT INTO `locales_spell` VALUES (10667, 'Rage of Ages', '', '', '', '远古之怒', '', '', '', '', '', '', '', '', '', 'Increases Strength by $s1 when consumed. Effect lasts for 60 minutes.', '', '', '', '使用后力量提高$s1点，效果持续60分钟。', '', '', 'Increases Strength by $s1.', '', '', '', '力量提高$s1点。', '', '');
