INSERT INTO `locales_spell` VALUES (10673, 'Bombay', '', '', '', '灰猫', '', '', '', '', '', '', '', '', '', 'Donni Anthania plans to have a bombay buried with her when she dies. A wise adventurer can put its talents to much better use.', '', '', '', '唐尼·安塔尼亚 (Donni Anthania) 计划在她去世后将一座孟买墓与她合葬。聪明的冒险家可以更好地利用自己的才能。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10674, 'Cornish Rex', '', '', '', '黄猫', '', '', '', '', '', '', '', '', '', 'Donni Anthania invites these cats to her tea parties. But she doesn\'t serve their favorite drink: the tears of their enemies.', '', '', '', '唐尼·安塔尼亚邀请这些猫参加她的茶会。但她不提供他们最喜欢的饮料：敌人的眼泪。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10675, 'Maine Coon', '', '', '', '黑纹灰猫', '', '', '', '', '', '', '', '', '', 'Old Alterac saying: \'A cat has nine lives, but needs only one.\'', '', '', '', '老奥特兰克说过：“猫有九条命，但只需要一条。”', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10676, 'Orange Tabby', '', '', '', '虎皮猫', '', '', '', '', '', '', '', '', '', 'The last person who tried to housebreak this cat quickly learned that a soiled rug is better than a shredded everything-else.', '', '', '', '最后一个试图入室盗窃这只猫的人很快就意识到，脏地毯比撕碎的其他东西要好。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10677, 'Siamese', '', '', '', '黑尾白猫', '', '', '', '', '', '', '', '', '', 'Known for its blue eyes. Also considered a delicacy by giant murlocs.', '', '', '', '以其蓝眼睛而闻名。也被巨型鱼人视为美味佳肴。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10678, 'Silver Tabby', '', '', '', '黑斑白猫', '', '', '', '', '', '', '', '', '', 'Sleeping is this cat\'s second favorite activity. The first is yawning.', '', '', '', '睡觉是这只猫第二喜欢的活动。第一个是打哈欠。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10679, 'White Kitten', '', '', '', '白猫', '', '', '', '', '', '', '', '', '', 'The queen had three kittens. The first gave her a juicy rat. The second, a tasty hare. And the white, her favorite, presented the head of her rival.', '', '', '', '女王养了三只小猫。第一个给了她一只多汁的老鼠。第二个，美味的野兔。而她最喜欢的白色，则是她对手的头。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10680, 'Cockatiel', '', '', '', '红尾鹦鹉', '', '', '', '', '', '', '', '', '', 'Some say this clever bird can be taught to speak--but it\'s smart enough to keep its beak shut.', '', '', '', '有人说这种聪明的鸟可以被教说话——但它足够聪明，可以闭上嘴。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10681, 'Cockatoo', '', '', '', '美冠鹦鹉', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your bird.', '', '', '', '右键点击以召唤或解散你的鹦鹉。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10682, 'Hyacinth Macaw', '', '', '', '花羽鹦鹉', '', '', '', '', '', '', '', '', '', 'The jungle trolls train these birds to mimic calls for help in order to lure unsuspecting travelers into traps.', '', '', '', '丛林巨魔训练这些鸟类模仿呼救声，以引诱毫无戒心的旅行者落入陷阱。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10683, 'Green Wing Macaw', '', '', '', '绿翼鹦鹉', '', '', '', '', '', '', '', '', '', 'Favored pet of the Defias pirates, this colorful bird is handy for remembering passwords, grocery lists, and cracker recipes.', '', '', '', '这只色彩缤纷的鸟是迪菲亚海盗最喜爱的宠物，它可以方便地记住密码、购物清单和饼干食谱。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10684, 'Senegal', '', '', '', '金翼鹦鹉', '', '', '', '', '', '', '', '', '', 'Favored pet of the goblins of Booty Bay, this colorful bird is renowned for its ability to count coins, tally budgets, and lie about contracts.', '', '', '', '这只色彩斑斓的鸟是藏宝海湾妖精们最喜爱的宠物，它以数金币、计算预算和谎报合同的能力而闻名。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10685, 'Ancona', '', '', '', '灰色小鸡', '', '', '', '', '', '', '', '', '', 'It thinks you taste like chicken too.', '', '', '', '它认为你的味道也像鸡肉。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10686, 'Prairie Chicken', '', '', '', '农场小鸡', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your chicken.', '', '', '', '右键点击以召唤或解散你的小鸡。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10687, 'White Plymouth Rock', '', '', '', '白色小鸡', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your chicken.', '', '', '', '右键点击以召唤或解散你的小鸡。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10688, 'Cockroach', '', '', '', '蟑螂', '', '', '', '', '', '', '', '', '', 'The cockroach is usually an impulse buy. Its owners have a hard time parting with it even after numerous attempts.', '', '', '', '蟑螂通常是冲动购买。即使经过多次尝试，它的主人也很难摆脱它。', '', '', '', '', '', '', '', '', '');
