INSERT INTO `locales_spell` VALUES (10690, 'Infallible Mind', '', '', '', '坚定信念', '', '', '', '', '', '', '', '', '', 'Increases Intellect by $s1 when consumed.', '', '', '', '使用后智力提高$s1点。', '', '', 'Increases Intellect by $s1.', '', '', '', '智力提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (10691, 'Spiritual Domination', '', '', '', '精神矍铄', '', '', '', '', '', '', '', '', '', 'Increases Spirit by $s1 when consumed.', '', '', '', '使用后精神提高$s1点。', '', '', 'Increases Spirit by $s1.', '', '', '', '精神提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (10692, 'Infallible Mind', '', '', '', '坚定信念', '', '', '', '', '', '', '', '', '', 'Increases Intellect by $s1 when consumed. Effect lasts for 60 minutes.', '', '', '', '使用后智力提高$s1点，效果持续60分钟。', '', '', 'Increases Intellect by $s1.', '', '', '', '智力提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (10693, 'Spiritual Domination', '', '', '', '精神矍铄', '', '', '', '', '', '', '', '', '', 'Increases Spirit by $s1 when consumed. Effect lasts for 60 minutes.', '', '', '', '使用后精神提高$s1点，效果持续60分钟。', '', '', 'Increases Spirit by $s1.', '', '', '', '精神提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (10694, 'Disenchant (PT)', '', '', '', 'Disenchant (PT)', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10695, 'Dark Whelpling', '', '', '', '黑龙宝宝', '', '', '', '', '', '', '', '', '', 'Hopes that someday it can grow up to destroy villages, just like mommy.', '', '', '', '希望有一天它长大后能像妈妈一样摧毁村庄。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10696, 'Azure Whelpling', '', '', '', '蓝龙宝宝', '', '', '', '', '', '', '', '', '', 'Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic.', '', '', '', '与蓝龙军团的其他成员一样，这些异想天开的小动物对奥术魔法表现出浓厚的兴趣。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10697, 'Crimson Whelpling', '', '', '', '红龙宝宝', '', '', '', '', '', '', '', '', '', 'Hailing from the Wetlands, this young dragon is just learning how to hunt, breathe fire, and go on cute destructive rampages.', '', '', '', '这条来自湿地的年轻龙刚刚学习如何狩猎、喷火以及进行可爱的破坏性横冲直撞。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10698, 'Emerald Whelpling', '', '', '', '绿龙宝宝', '', '', '', '', '', '', '', '', '', 'Once bred and raised by the green dragon Itharius, this unique breed of dragon has settled in the jungles of Feralas.', '', '', '', '这种独特的龙由绿龙伊萨留斯 (Itharius) 培育和饲养，现已定居在菲拉斯的丛林中。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10699, 'Bronze Whelpling', '', '', '', '青铜龙宝宝', '', '', '', '', '', '', '', '', '', 'The Bronze Whelpling was lost in time until an unusual event allowed her to escape.', '', '', '', '青铜龙龙迷失了时间，直到一次不寻常的事件让她逃脱了。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10700, 'Radiant Faeling', '', '', '', '精灵龙宝宝', '', '', '', '', '', '', '', '', '', 'Hello, friend! Brightwing likes it when you visit!', '', '', '', '朋友你好！当您访问时，Brightwing 会喜欢它！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10701, 'Dart Frog', '', '', '', '蓝蛙', '', '', '', '', '', '', '', '', '', 'Toads and frogs are fast friends of trolls, perfect for poisons.', '', '', '', '蟾蜍和青蛙是巨魔的好朋友，非常适合毒药。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10702, 'Island Frog', '', '', '', '岛蛙', '', '', '', '', '', '', '', '', '', 'This little friend snuck into your boot to join you on your travels.', '', '', '', '这位小朋友溜进了你的靴子，和你一起旅行。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10703, 'Wood Frog', '', '', '', '林蛙', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your frog.', '', '', '', '右键点击以召唤或解散你的青蛙。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10704, 'Tree Frog', '', '', '', '树蛙', '', '', '', '', '', '', '', '', '', 'Known for their powerful legs and keen eyesight.', '', '', '', '以其有力的双腿和敏锐的视力而闻名。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10705, 'Eagle Owl', '', '', '', '黄色猫头鹰', '', '', '', '', '', '', '', '', '', 'Many owls nest high in the stone structures of Darnassus, hunting any pests that enter the night elves\' city.', '', '', '', '许多猫头鹰在达纳苏斯的石结构高处筑巢，捕猎进入暗夜精灵城市的害虫。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10706, 'Hawk Owl', '', '', '', '黑色猫头鹰', '', '', '', '', '', '', '', '', '', 'This dark-feathered bird of prey is often seen as a harbinger of doom amongst the druids of Teldrassil.', '', '', '', '这种深色羽毛的猛禽经常被泰达希尔的德鲁伊视为厄运的预兆。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10707, 'Great Horned Owl', '', '', '', '棕色猫头鹰', '', '', '', '', '', '', '', '', '', 'Night elf children are given an owl feather on their first birthday as a token of good luck.', '', '', '', '暗夜精灵的孩子在一岁生日时会收到一根猫头鹰羽毛作为好运的象征。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10708, 'Snowy Owl', '', '', '', '白色猫头鹰', '', '', '', '', '', '', '', '', '', 'Winterspring\'s furbolg prize the brilliant white feathers of these majestic creatures for ritual purposes.', '', '', '', '冬泉谷的熊怪会出于仪式目的而珍视这些雄伟生物的亮白色羽毛。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10709, 'Prairie Dog', '', '', '', '土拨鼠', '', '', '', '', '', '', '', '', '', 'A complex system of burrows protects the prairie dog from its neighbors\' massive hooves.', '', '', '', '复杂的洞穴系统可以保护土拨鼠免受邻居巨大蹄子的侵害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10710, 'Cottontail Rabbit', '', '', '', '黄毛兔', '', '', '', '', '', '', '', '', '', 'Mountain cottontails can leap up a steep incline with speed you would not believe.', '', '', '', '山棉尾兔可以以令人难以置信的速度跃上陡峭的斜坡。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10711, 'Snowshoe Rabbit', '', '', '', '黄纹兔', '', '', '', '', '', '', '', '', '', 'If you go chasing snowshoe rabbits, you know you\'re going to fall.', '', '', '', '如果你去追雪鞋兔，你就知道你会摔倒。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10712, 'Spotted Rabbit', '', '', '', '斑点兔', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your rabbit.', '', '', '', '右键点击以召唤或解散你的兔子。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10713, 'Albino Snake', '', '', '', '白鳞蛇', '', '', '', '', '', '', '', '', '', 'A favored companion of Kirin Tor magi, this reptile makes one wonder whether it\'s truly a snake or something else altogether.', '', '', '', '作为肯瑞托法师最喜爱的伙伴，这种爬行动物让人怀疑它到底是蛇还是其他什么东西。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10714, 'Black Kingsnake', '', '', '', '黑色王蛇', '', '', '', '', '', '', '', '', '', 'Xan\'tish fearlessly tracks, captures, and trains these noble snakes so they will aid their comrades in battle.', '', '', '', 'Xan\\\'tish 无畏地追踪、捕获并训练这些高贵的蛇，以便它们在战斗中帮助战友。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10715, 'Blue Racer', '', '', '', '蓝鳞蛇', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your snake.', '', '', '', '右键点击以召唤或解散你的蛇。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10716, 'Brown Snake', '', '', '', '棕色蟒蛇', '', '', '', '', '', '', '', '', '', 'The brown snake is native to Horde-controlled territories. It seems unremarkable until its victims are within range.', '', '', '', '棕蛇原产于部落控制的领土。在受害者进入攻击范围之前，它看起来并不引人注目。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10717, 'Crimson Snake', '', '', '', '赤练蛇', '', '', '', '', '', '', '', '', '', 'The crimson snake is favored among the Darkspear trolls for not only its vicious nature, but also its steadfast loyalty.', '', '', '', '深红蛇深受暗矛巨魔的青睐，不仅因为它的邪恶本性，还因为它坚定的忠诚。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10718, 'Water Snake', '', '', '', '绿色水蛇', '', '', '', '', '', '', '', '', '', 'Brought to Sparkwater Port aboard merchant ships, these short-lived reptiles are considered pests by the port\'s residents.', '', '', '', '这些短命的爬行动物被商船带到斯帕克沃特港，被港口居民视为害虫。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10719, 'Ribbon Snake', '', '', '', '赤环蛇', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your snake.', '', '', '', '右键点击以召唤或解散你的蛇。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10720, 'Scarlet Snake', '', '', '', '血纹蛇', '', '', '', '', '', '', '', '', '', 'Brave assassins sometimes capture these critters to use their highly toxic venom to poison weapons.', '', '', '', '勇敢的刺客有时会捕获这些生物，用它们的剧毒毒液来毒害武器。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10721, 'Elven Wisp', '', '', '', '小精灵', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your wisp.', '', '', '', '右键点击以召唤或解散你的小精灵。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10722, 'Silithid Swarm', '', '', '', '异种蝎群', '', '', '', '', '', '', '', '', '', 'Summons $s1 $lSilithid Swarm:Silithid Swarms; to accompany the caster until dismissed.', '', '', '', '召唤$s1个异种蝎群为施法者作战，直到被解散。', '', '', '', '', '', '', '', '', '');
