INSERT INTO `locales_spell` VALUES (10730, 'Pacify', '', '', '', '抚慰', '', '', '', '', '', '', '', '', '', 'Pacifies an enemy, rendering it unable to attack for $d.', '', '', '', '使一个敌人不能攻击，持续$d。', '', '', 'Unable to attack.', '', '', '', '不能进行攻击。', '', '');
