INSERT INTO `locales_spell` VALUES (10732, 'Supercharge', '', '', '', '增压', '', '', '', '', '', '', '', '', '', 'Speeds the attack of nearby mechanical allies by $s2% and increases the Physical damage they deal by $s1 for $d.', '', '', '', '使附近的友方机械单位的攻击速度提高$s2%，物理伤害提高$s1点，持续$d。', '', '', 'Physical damage dealt is increased by $s1.\nAttack speed increased by $s2%.', '', '', '', '对敌人造成的物理伤害提高$s1点。\n攻击速度提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (10733, 'Flame Spray', '', '', '', '烈焰喷射', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to enemies in a cone in front of the caster.', '', '', '', '对施法者面前一个锥形区域中的敌人造成$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10734, 'Hail Storm', '', '', '', '冰雹', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Movement speed reduced by $s1%.', '', '', '', '移动速度降低$s1%。', '', '');
