INSERT INTO `locales_spell` VALUES (10767, 'Rising Spirit', '', '', '', '高涨士气', '', '', '', '', '', '', '', '', '', 'Increases Spirit by $s1.', '', '', '', '精神提高$s1点。', '', '', 'Increases Spirit by $s1.', '', '', '', '精神提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (10768, 'Skinning', '', '', '', '剥皮', '', '', 'Artisan', '', '', '', '大师级', '', '', 'Artisan skill in skinning the hides from beasts for use in Leatherworking.  Gives a potential skinning skill of 300.  Requires a Skinning Knife.', '', '', '', '大师级的剥皮技能，让你可以从动物身上获取皮革和毛皮以用于制皮业。使你获得300点的剥皮技能上限。需要一把剥皮小刀。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10769, 'Artisan Skinning', '', '', '', '大师级剥皮', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10770, 'Create Weegli\'s Barrel', '', '', '', '制造维格利的酒桶', '', '', '', '', '', '', '', '', '', 'Creates Weegli\'s Barrel.', '', '', '', '制造维格利的酒桶。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10771, 'Soul Shatter', '', '', '', '灵魂破碎', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10772, 'Create Weegli\'s Barrel', '', '', '', '制造维格利的酒桶', '', '', '', '', '', '', '', '', '', 'Place near the Troll Door.', '', '', '', '放置在巨魔大门附近。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10787, 'Panther', '', '', '', '黑豹', '', '', '', '', '', '', '', '', '', 'The jungle trolls have long coveted panther fangs, using them for rituals or as ingredients in mojos.', '', '', '', '丛林巨魔拥有一直觊觎已久的豹牙，用它们进行仪式或作为魔精的成分。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10788, 'Leopard', '', '', '', '黑斑黄豹', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Sabre Cat.', '', '', '', '召唤或解散一头可供骑乘的夜刃豹。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10789, 'Spotted Frostsaber', '', '', '', '斑点霜刃豹', '', '', '', '', '', '', '', '', '', 'This hearty mount\'s ferocious appetite earned it the nickname \"Dragon Belly\" in the Night Elf language.', '', '', '', '这种丰盛的坐骑凶猛的食欲使它在暗夜精灵语中赢得了“龙腹”的绰号。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10790, 'Tiger', '', '', '', '黑纹虎', '', '', '', '', '', '', '', '', '', 'The wonderful thing about tigers is tigers are wonderful things!', '', '', '', '老虎的奇妙之处在于老虎是奇妙的东西！', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10792, 'Spotted Panther', '', '', '', '白斑黑豹', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Sabre Cat.', '', '', '', '召唤或解散一头可供骑乘的夜刃豹。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10793, 'Striped Nightsaber', '', '', '', '条纹夜刃豹', '', '', '', '', '', '', '', '', '', 'Considered one of Azeroth\'s perfect predators, these agile beasts can sprint through dense forests without making a sound.', '', '', '', '这些敏捷的野兽被认为是艾泽拉斯完美的掠食者之一，它们可以在茂密的森林中冲刺而不会发出任何声音。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10794, 'Spirit Shock', '', '', '', '灵魂震击', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (10795, 'Ivory Raptor', '', '', '', '白色迅猛龙', '', '', '', '', '', '', '', '', '', 'A fearsome predator with ivory-colored scales, ready to strike at any moment.', '', '', '', '有着象牙色鳞片的可怕掠食者，随时准备发起攻击。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10796, 'Turquoise Raptor', '', '', '', '青色迅猛龙', '', '', '', '', '', '', '', '', '', 'Bred from the fiercest stock anywhere and guaranteed not to bite (much).', '', '', '', '由世界上最凶猛的种群培育而成，保证不会咬人（太多）。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10797, 'Starshards', '', '', '', '星辰碎片', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Rains starshards down on the enemy target\'s head, causing $o1 Arcane damage over $d.', '', '', '', '召唤群星的碎片攻击敌人，在$d内对其造成$o1点奥术伤害。', '', '', '$o1 Arcane damage over $d.', '', '', '', '在$d内造成$o1点奥术伤害。', '', '');
INSERT INTO `locales_spell` VALUES (10798, 'Obsidian Raptor', '', '', '', '黑色迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10799, 'Violet Raptor', '', '', '', '紫色迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10800, 'Brown Tallstrider', '', '', '', '棕色陆行鸟', '', '', '', '', '', '', '', '', '', 'A tall and curious bird, blending perfectly with its natural surroundings.', '', '', '', '一种高大而好奇的鸟，与周围的自然环境完美融合。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10801, 'Gray Tallstrider', '', '', '', '灰色陆行鸟', '', '', '', '', '', '', '', '', '', 'A stoic and observant creature, adapting to any environment it encounters.', '', '', '', '一种坚忍而善于观察的生物，能够适应遇到的任何环境。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10802, 'Pink Tallstrider', '', '', '', '粉色陆行鸟', '', '', '', '', '', '', '', '', '', 'A vibrant and playful bird, spreading joy wherever it goes.', '', '', '', '一只充满活力和顽皮的鸟，无论走到哪里都会传播欢乐。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (10803, 'Purple Tallstrider', '', '', '', '紫色陆行鸟', '', '', '', '', '', '', '', '', '', 'Accidentally released by the Darkmoon Faire — makes for a surprisingly sturdy steed.', '', '', '', '暗月马戏团意外释放的战马——造就了一匹异常坚固的战马。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
