INSERT INTO `locales_spell` VALUES (11213, 'Arcane Concentration', '', '', '', '奥术专注', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives you a $h% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.', '', '', '', '使你有$h%的几率在施放任何一种伤害性法术之后进入节能施法状态。节能施法状态可以使你的下一个伤害性法术所消耗的法力值减少$/10;12536s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11222, 'Arcane Focus', '', '', '', '奥术集中', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces the chance that the opponent can resist your Arcane spells by $s1%.', '', '', '', '使你的敌人抵抗你的奥术魔法的几率降低$s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11232, 'Arcane Mind', '', '', '', '奥术心智', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases your maximum Mana by $s1%.', '', '', '', '使你的法力值上限提高$s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11237, 'Improved Arcane Missiles', '', '', '', '强化奥术飞弹', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives you a $s1% chance to avoid interruption caused by damage while channeling Arcane Missiles.', '', '', '', '使你有$s1%的几率在施放奥术飞弹时不会因为受到伤害而中断施法。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11242, 'Arcane Impact', '', '', '', '奥术冲击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the critical strike chance of your Arcane Explosion and Arcane Missiles spells by an additional $s1%.', '', '', '', '使你的魔爆术和奥术飞弹造成致命一击效果的几率提高$s1%。', '', '', '', '', '', '', '', '', '');
