INSERT INTO `locales_spell` VALUES (11273, 'Rupture', '', '', '', '割裂', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\n   1 point  : 128 damage over 8 secs\n   2 points: 185 damage over 10 secs\n   3 points: 252 damage over 12 secs\n   4 points: 329 damage over 14 secs\n   5 points: 416 damage over 16 secs', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间，该伤害会受到攻击强度的加成影响：\n   1点：128伤害，持续8秒\n   2点：185伤害，持续10秒\n   3点：252伤害，持续12秒\n   4点：329伤害，持续14秒\n   5点：416伤害，持续16秒', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
INSERT INTO `locales_spell` VALUES (11274, 'Rupture', '', '', '', '割裂', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\n   1 point  : 176 damage over 8 secs\n   2 points: 255 damage over 10 secs\n   3 points: 348 damage over 12 secs\n   4 points: 455 damage over 14 secs\n   5 points: 576 damage over 16 secs', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间，该伤害会受到攻击强度的加成影响：\n   1点：176伤害，持续8秒\n   2点：255伤害，持续10秒\n   3点：348伤害，持续12秒\n   4点：455伤害，持续14秒\n   5点：576伤害，持续16秒', '', '', '$s1 damage every $t1 seconds.', '', '', '', '每$t1秒$s1点伤害。', '', '');
