INSERT INTO `locales_spell` VALUES (11426, 'Ice Barrier', '', '', '', '寒冰护体', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Instantly shields you, absorbing $s1 damage.  Lasts $d.  While the shield holds, spells will not be interrupted.\n', '', '', '', '立即为你加上魔法护盾，可吸收$s1点伤害，持续$d。只要护盾存在，受保护者的施法就不会被打断。', '', '', 'Absorbs damage.', '', '', '', '吸收伤害。', '', '');
INSERT INTO `locales_spell` VALUES (11427, 'Cleave', '', '', '', '顺劈斩', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to an enemy and its nearest allies, affecting up to $x1 targets.', '', '', '', '对目标和它身边最近的敌人造成你的武器伤害再加$s1点伤害，最多可影响$x1个目标。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11428, 'Knockdown', '', '', '', '击倒', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 damage to an enemy, stunning it for $d.', '', '', '', '对敌人造成$s2点伤害，并使其昏迷$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (11430, 'Slam', '', '', '', '猛击', '', '', '', '', '', '', '', '', '', 'Slams an enemy to the ground, inflicting Physical damage and stunning it for $d.', '', '', '', '击倒目标，对其造成物理伤害，并使其昏迷$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
