INSERT INTO `locales_spell` VALUES (11433, 'Death & Decay', '', '', '', '死亡凋零', '', '', '', '', '', '', '', '', '', 'Invokes the malignant power of death and decay, inflicting Shadow damage to all enemies in a selected area for $d.', '', '', '', '以死亡凋零的力量攻击指定区域内的所有敌人，对它们造成暗影伤害，持续$d。', '', '', '', '', '', '', '', '', '');
