INSERT INTO `locales_spell` VALUES (11436, 'Slow', '', '', '', '减速术', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s1% and slows its movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
