INSERT INTO `locales_spell` VALUES (11442, 'Withered Touch', '', '', '', '枯萎之触', '', '', '', '', '', '', '', '', '', 'Diseases an enemy, inflicting $s1 Shadow damage every $t1 sec. and draining $s2 mana every $t2 sec., transferring it to the caster. Lasts $d.', '', '', '', '使一个敌人感染疾病，每$t1秒对其造成$s1点暗影伤害，每$t2秒吸取$s2点法力值并将其转移给施法者。持续$d。', '', '', '$s1 Shadow damage inflicted every $t1 sec.\n$s2 mana leeched every $t2 sec.', '', '', '', '每$t1秒受到$s1点暗影伤害。\n每$t2秒吸取$s2点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (11443, 'Cripple', '', '', '', '残废术', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s2% and its movement by $s1%, in addition to reducing its Strength by $s3%. Lasts $d.', '', '', '', '使敌人的攻击间隔延长$s2%，移动速度降低$s1%，力量降低$s3%。持续$d。', '', '', 'Movement speed reduced by $s1%.\nTime between attacks increased by $s2%.\nStrength reduced by $s3%.', '', '', '', '攻击间隔延长$s2%。\n移动速度降低$s1%。\n力量降低$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (11444, 'Shackle Undead', '', '', '', '束缚亡灵', '', '', '', '', '', '', '', '', '', 'Shackles an undead enemy for up to $d., preventing it from casting spells, attacking, or moving. Any damage caused will release the target. Only one target can be shackled at a time.', '', '', '', '束缚敌对亡灵单位，最多持续$d。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (11445, 'Bone Armor', '', '', '', '骨甲术', '', '', '', '', '', '', '', '', '', 'Encases the caster in bone armor, absorbing $s1 damage for $d. While the armor holds, spellcasting cannot be interrupted by Physical attacks.', '', '', '', '白骨护甲环绕着施法者，可在$d内吸收最多$s1点伤害。只要骨甲仍然存在，施法就不会被物理攻击打断。', '', '', 'Damage is absorbed by bone armor.', '', '', '', '伤害被骨甲吸收。', '', '');
INSERT INTO `locales_spell` VALUES (11446, 'Mind Control', '', '', '', '精神控制', '', '', '', '', '', '', '', '', '', 'Controls a humanoid mind up to level $s1.  Lasts $d, but the target gets a chance to break free every 5 seconds.', '', '', '', '控制一个最高等级为$s1的人型目标，持续$d，被控制的目标每5秒都有一定的几率逃脱。', '', '', 'Charmed.', '', '', '', '被魅惑。', '', '');
