INSERT INTO `locales_spell` VALUES (11657, 'Jang\'thraze', '', '', '', '迦萨斯', '', '', '', '', '', '', '', '', '', 'Shields the wielder from physical damage, absorbing $s1 damage. Lasts $d1.', '', '', '', '吸收$s1点物理伤害，持续$d1。', '', '', 'Absorbs physical damage.', '', '', '', '吸收物理伤害。', '', '');
