INSERT INTO `locales_spell` VALUES (11711, 'Curse of Agony', '', '', '', '痛苦诅咒', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Curses the target with agony, causing $o1 Shadow damage over $d.  This damage is dealt slowly at first, and builds up as the Curse reaches its full duration.  Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加痛苦的诅咒，使其在$d内受到$o1点伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', '$o1 Shadow damage over $d.', '', '', '', '在$d内造成总计$o1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (11712, 'Curse of Agony', '', '', '', '痛苦诅咒', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Curses the target with agony, causing $o1 Shadow damage over $d.  This damage is dealt slowly at first, and builds up as the Curse reaches its full duration.  Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加痛苦的诅咒，使其在$d内受到$o1点伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', '$o1 Shadow damage over $d.', '', '', '', '在$d内造成总计$o1点暗影伤害。', '', '');
