INSERT INTO `locales_spell` VALUES (11719, 'Curse of Tongues', '', '', '', '语言诅咒', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Forces the target to speak in Demonic, slowing the casting time of all spells by $s1%.  Only one Curse per Warlock can be active on any one target.  Lasts $d.', '', '', '', '强迫目标使用恶魔语，使其所有法术的施放时间延长$s1%，持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Speaking Demonic increasing casting time by $s1%.', '', '', '', '以恶魔语念出咒语，使施法时间延长$s1%。', '', '');
