INSERT INTO `locales_spell` VALUES (11721, 'Curse of the Elements', '', '', '', '元素诅咒', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Curses the target for $d, reducing Fire and Frost resistances by $s1 and increasing Fire and Frost damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.', '', '', '', '对目标施放诅咒，使其火焰和冰霜抗性降低$s1点，受到火焰和冰霜系攻击时所承受的伤害提高$s2%，效果持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Reduces Fire and Frost resistances by $s1.  Increases Fire and Frost damage taken by $s2%.', '', '', '', '火焰和冰霜抗性降低$s1点。受到火焰和冰霜系攻击时所承受的伤害提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (11722, 'Curse of the Elements', '', '', '', '元素诅咒', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Curses the target for $d, reducing Fire and Frost resistances by $s1 and increasing Fire and Frost damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.', '', '', '', '对目标施放诅咒，使其火焰和冰霜抗性降低$s1点，受到火焰和冰霜系攻击时所承受的伤害提高$s2%，效果持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Reduces Fire and Frost resistances by $s1.  Increases Fire and Frost damage taken by $s2%.', '', '', '', '火焰和冰霜抗性降低$s1点。受到火焰和冰霜系攻击时所承受的伤害提高$s2%。', '', '');
