INSERT INTO `locales_spell` VALUES (11835, 'Power Word: Shield', '', '', '', '真言术：盾', '', '', '', '', '', '', '', '', '', 'Wraps an ally in a shield that lasts up to $d., absorbing fixed amount of Physical or magical damage. While the shield holds, spells will not be interrupted by Physical attacks.', '', '', '', '立即为目标加上魔法护盾，可吸收$s1点伤害，持续$d。只要护盾存在，受保护者的施法就不会被物理攻击打断。', '', '', 'Shielded against Physical and magical damage.', '', '', '', '吸收物理和魔法伤害。', '', '');
