INSERT INTO `locales_spell` VALUES (11922, 'Entangling Roots', '', '', '', '纠缠根须', '', '', '', '', '', '', '', '', '', 'Entangles an enemy in roots, inflicting Nature damage every $t2 sec. and immobilizing it for up to $d.', '', '', '', '用根须将敌人缠住，每$t2秒对其造成一次自然伤害，并使其无法移动，最多持续$d。', '', '', 'Immobilized.\nNature damage inflicted every $t2 sec.', '', '', '', '无法移动。\n每$t2秒受到一次自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (11923, 'Repair the Blade of Heroes', '', '', '', '修理英雄之剑', '', '', '', '', '', '', '', '', '', 'The sword must be reforged before it can be used. Reforging the sword requires 4 Steel Bars, 4 Strong Flux, 2 Elemental Fire and 2 Heavy Grinding Stones.', '', '', '', '剑必须经过重铸才能使用。重铸剑需要 4 根钢棒、4 颗强力助熔剂、2 颗元素之火和 2 颗重磨石。', '', '', '', '', '', '', '', '', '');
