INSERT INTO `locales_spell` VALUES (11958, 'Ice Block', '', '', '', '寒冰屏障', '', '', '', '', '', '', '', '', '', 'You become encased in a block of ice, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move or cast spells.', '', '', '', '你被一道寒冰屏障所笼罩，在$d内不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。', '', '', 'Immune to all attacks and spells.  Cannot attack, move or use spells.', '', '', '', '对所有攻击和法术免疫。无法攻击、移动或施法。', '', '');
