INSERT INTO `locales_spell` VALUES (11971, 'Sunder Armor', '', '', '', '破甲攻击', '', '', '', '', '', '', '', '', '', 'Hacks at an enemy\'s armor, reducing it by $s1 per Sunder Armor. Can be applied up to 5 times. Lasts $d.', '', '', '', '击破目标的护甲，每次破甲攻击都会使其护甲值降低$s1点，最多可累加5次，持续$d。', '', '', 'Reduced armor.', '', '', '', '护甲值降低。', '', '');
INSERT INTO `locales_spell` VALUES (11972, 'Shield Bash', '', '', '', '盾击', '', '', '', '', '', '', '', '', '', 'Bashes an enemy with the caster\'s shield, inflicting Physical damage and interrupting the spell being cast for $d.', '', '', '', '使用你的盾牌重击目标，对其造成物理伤害，并使该法术无法被施放，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11974, 'Power Word: Shield', '', '', '', '真言术：盾', '', '', '', '', '', '', '', '', '', 'Wraps an ally in a shield that lasts up to $d., absorbing a maximum of $s1 Physical or magical damage. While the shield holds, spells will not be interrupted by Physical attacks.', '', '', '', '立即为目标加上魔法护盾，可吸收$s1点物理或魔法伤害，最多持续$d。只要护盾存在，受保护者的施法就不会被物理攻击打断。', '', '', 'Shielded against Physical and magical damage.', '', '', '', '吸收物理和魔法伤害。', '', '');
INSERT INTO `locales_spell` VALUES (11975, 'Arcane Explosion', '', '', '', '魔爆术', '', '', '', '', '', '', '', '', '', 'Sends out a blast wave of magic, inflicting Arcane damage to nearby enemies.', '', '', '', '制造一次以施法者为中心的魔法爆炸，对附近的敌人造成奥术伤害。', '', '', '', '', '', '', '', '', '');
