INSERT INTO `locales_spell` VALUES (11978, 'Kick', '', '', '', '脚踢', '', '', '', '', '', '', '', '', '', 'Kicks an enemy for $s1 damage, interrupting the spell being cast for $d.', '', '', '', '用脚快速踢敌人，对其造成$s1点伤害，并使其在$d内无法施法。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (11980, 'Curse of Weakness', '', '', '', '虚弱诅咒', '', '', '', '', '', '', '', '', '', 'Reduces the Physical damage dealt by an enemy by $s1 for $d. Only one curse per warlock can be active on any one target.', '', '', '', '目标所能造成的伤害降低$s1点，持续$d。每个术士只能对一个目标施加一种诅咒。', '', '', 'Physical damage dealt is reduced by $s1.', '', '', '', '对目标造成的物理伤害降低$s1点。', '', '');
