INSERT INTO `locales_spell` VALUES (12021, 'Fixate', '', '', '', '凝视', '', '', '', '', '', '', '', '', '', 'Causes an enemy to fixate upon the caster and increases the caster\'s attack speed by $s2% for $d. While the target is fixated upon the caster, the target is very reluctant to attack anything else.', '', '', '', '使一个敌人的注意力集中在施法者身上，并使施法者的攻击速度提高$s2%，持续$d。在这段时间里，该敌人很难转而攻击其它目标。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (12022, 'Admiral\'s Hat', '', '', '', '将军之帽', '', '', '', '', '', '', '', '', '', 'Gives $M1 additional stamina to party members within $a1 yards.', '', '', '', '使半径$a1码范围内的小队成员的耐力提高$s1点。', '', '', 'Stamina increased by $s1.', '', '', '', '耐力提高$s1点。', '', '');
