INSERT INTO `locales_spell` VALUES (12040, 'Shadow Shield', '', '', '', '暗影之盾', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with a shield woven of Shadow magic. The shield lasts $d., absorbs up to $s1 Physical or magical damage, and inflicts $s2 damage to melee attackers.', '', '', '', '以暗影魔法能量保护施法者，持续$d。吸收最多$s1点物理或魔法伤害，对近战攻击者造成$s2点伤害。', '', '', 'Shielded against Physical and magical damage.\n$s2 Shadow damage inflicted to melee attackers.', '', '', '', '吸收物理和魔法伤害。\n对近战攻击者造成$s2点伤害。', '', '');
INSERT INTO `locales_spell` VALUES (12042, 'Arcane Power', '', '', '', '奥术强化', '', '', '', '', '', '', '', '', '', 'When activated, your spells deal $s1% more damage while costing $s2% more mana to cast.  This effect lasts $D.', '', '', '', '激活之后，你的法术会造成$s1%的额外伤害，但同时也要消耗$s2%的额外法力才能施放。这个效果可以持续$D。', '', '', 'Increased damage and mana cost for your spells.', '', '', '', '你的法术可以造成更高伤害，但是需要消耗更多法力值才能施放。', '', '');
