INSERT INTO `locales_spell` VALUES (12540, 'Gouge', '', '', '', '凿击', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 damage to an enemy and stuns it for up to $d. You will automatically stop attacking. Target must be facing you. Any damage received by the stunned target will revive it.', '', '', '', '对目标造成$s1点伤害，令其昏迷$d，并使你不再攻击这个目标。这个技能必须在目标面对着你的时候发动，任何后继的伤害都会令目标醒来。奖励$s2个连击点数。', '', '', 'Incapacitated.', '', '', '', '瘫痪。', '', '');
INSERT INTO `locales_spell` VALUES (12541, 'Ghoul Rot', '', '', '', '食尸鬼腐气', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Chance to hit reduced by $s1%.', '', '', '', '击中目标的几率降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (12542, 'Fear', '', '', '', '恐惧术', '', '', '', '', '', '', '', '', '', 'Strikes fear in an enemy, causing it to flee in terror for $d. Only 1 target can be feared at a time.', '', '', '', '使敌人因为极度的恐惧而奔逃，最多持续$d。在同一时间内，只有1个敌人会被你的恐惧术影响。', '', '', 'Fleeing in fear.', '', '', '', '因恐惧而逃跑。', '', '');
INSERT INTO `locales_spell` VALUES (12543, 'Hi-Explosive Bomb', '', '', '', '高爆炸弹', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage and stuns targets in a 3 yard radius for $d.  Any damage will break the effect.', '', '', '', '对半径3码范围内的所有敌人造成$s1点火焰伤害，并使它们昏迷$d。任何伤害都会打断这个效果。', '', '', 'Stunned.  Any damage will break the effect.', '', '', '', '昏迷。任何伤害都会打断这个效果。', '', '');
INSERT INTO `locales_spell` VALUES (12544, 'Frost Armor', '', '', '', '霜甲术', '', '', '', '', '', '', '', '', '', 'Encases the caster in a layer of frost that lasts $d. The thick ice increases armor by $s1, slows melee attackers\' movement to $6136s2%, and increases the time between their attacks by $6136s1%.', '', '', '', '使护甲提高$s1点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能降低$6136s2%，攻击间隔延长$6136s1%，持续$d。', '', '', 'Armor increased by $s1.\nSlowing melee attackers\' movement and attacks.', '', '', '', '护甲提高$s1点。\n降低近战攻击者的移动和攻击速度。', '', '');
INSERT INTO `locales_spell` VALUES (12545, 'Spitelash', '', '', '', '恶鞭', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Physical damage taken is increased by $s1.', '', '', '', '受到物理攻击时所承受的伤害提高$s1点。', '', '');
