INSERT INTO `locales_spell` VALUES (12553, 'Shock', '', '', '', '震击', '', '', '', '', '', '', '', '', '', 'Instantly throws a bolt of lightning at an enemy, inflicting Nature damage.', '', '', '', '立即向目标射出一支闪电箭，对其造成自然伤害。', '', '', '', '', '', '', '', '', '');
