INSERT INTO `locales_spell` VALUES (12733, 'Fearless', '', '', '', '无畏', '', '', '', '', '', '', '', '', '', 'Increases armor by $s2, all resistances by $s3 and grants immunity to Fear for $d.', '', '', '', '护甲值提高$s2点，所有抗性提高$s3点，免疫恐惧，持续$d。', '', '', 'Increased armor, increased resistances and immune to Fear.', '', '', '', '护甲值提高，增强抗性，免疫恐惧。', '', '');
