INSERT INTO `locales_spell` VALUES (12824, 'Polymorph', '', '', '', '变形术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (12825, 'Polymorph', '', '', '', '变形术', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
