INSERT INTO `locales_spell` VALUES (12884, 'Acid Breath', '', '', '', '酸息术', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 Nature damage and an additional $s1 damage every $t1 sec. to enemies in a cone in front of the caster. Lasts $d.', '', '', '', '对施法者面前一个锥形区域中的敌人造成$s2点自然伤害，并在$t1秒内造成$s1点额外伤害。持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。', '', '');
