INSERT INTO `locales_spell` VALUES (12887, 'Sweeping Slam', '', '', '', '横扫猛击', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to enemies in a cone in front of the caster, knocking them back.', '', '', '', '对施法者面前一个锥形区域中的敌人造成普通武器伤害再加上$s1点额外伤害，并将它们击退。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (12888, 'Cause Insanity', '', '', '', '导致疯狂', '', '', '', '', '', '', '', '', '', 'Drives an enemy target temporarily insane, speeding its attacks by $s2% and its movement by $s3%, as well as causing it to attack its own allies for $d.', '', '', '', '使敌人暂时发疯，攻击速度提高$s2%，移动速度提高$s3%，并会攻击自己的盟友，持续$d。', '', '', 'Charmed.\nAttack speed increased by $s2%.\nMovement speed increased by $s3%.', '', '', '', '被魅惑。\n攻击速度提高$s2%。\n移动速度提高$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (12889, 'Curse of Tongues', '', '', '', '语言诅咒', '', '', '', '', '', '', '', '', '', 'Forces nearby enemies to speak in Demonic, reducing their casting speed by $s1% for $d. Only one curse per warlock can be active on any one target.', '', '', '', '强迫目标使用恶魔语，使其所有法术的施放时间延长$s1%，持续$d。每个术士只能对一个目标施加一种诅咒。', '', '', 'Casting speed reduced by $s1%.', '', '', '', '施法速度降低$s1%。', '', '');
