INSERT INTO `locales_spell` VALUES (13006, 'Shrink Ray', '', '', '', '缩小射线', '', '', '', '', '', '', '', '', '', 'Shrinks the target reducing their attack power by $13003s1.  Thats what it usually does anyway.....', '', '', '', '缩小目标的体型，使它所能造成的伤害降低$13003s1%，耐力降低$13003s2%。当然，通常来说是这样的效果……', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13007, 'Divine Protection', '', '', '', '圣佑术', '', '', '', '', '', '', '', '', '', 'Protects the caster from all attacks and spells for $d., but during that time the caster also cannot attack or use spells.', '', '', '', '使施法者免受一切物理和法术攻击伤害，持续$d。但是在这段时间内施法者不能攻击或者使用非法术类的能力。', '', '', 'Immune to all attacks and spells.\nCannot attack or use spells.', '', '', '', '对所有攻击和法术免疫。\n无法攻击或施法。', '', '');
INSERT INTO `locales_spell` VALUES (13008, 'Retribution Aura', '', '', '', '惩罚光环', '', '', '', '', '', '', '', '', '', 'Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.', '', '', '', '对任何使用近战武器攻击附近小队成员的生物造成$s1点神圣伤害。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', '$s1 Holy damage inflicted to melee attackers.', '', '', '', '对攻击者造成$s1点神圣伤害。', '', '');
