INSERT INTO `locales_spell` VALUES (13159, 'Aspect of the Pack', '', '', '', '豹群守护', '', '', '', '', '', '', '', '', '', 'The hunter and group members within $a1 yards take on the aspects of a pack of cheetahs, increasing movement speed by $s1%.  If a pack member takes damage, they will be dazed for $15571d.  Only one Aspect can be active at a time.', '', '', '', '猎人和$g他:她;周围半径$a1码范围内的队友均获得豹群守护的效果，使移动速度提高$s1%。如果任何一个队友受到伤害，则全队都会眩晕$15571d。一个猎人在同一时间内只能激活一种守护。', '', '', '$s1% increased movement speed.  Dazed if damage is taken.', '', '', '', '移动速度提高$s1%。如果受到伤害则会眩晕。', '', '');
INSERT INTO `locales_spell` VALUES (13160, 'Aspect of the Pack', '', '', '', '豹群守护', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13161, 'Aspect of the Beast', '', '', '', '野兽守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a beast, becoming untrackable.  Only one Aspect can be active at a time.', '', '', '', '猎人获得野兽守护，变得无法追踪。一个猎人在同一时间内只能激活一种守护。', '', '', 'Untrackable.', '', '', '', '无法被追踪。', '', '');
