INSERT INTO `locales_spell` VALUES (13163, 'Aspect of the Monkey', '', '', '', '灵猴守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a monkey, increasing chance to dodge by $s1%.  Only one Aspect can be active at a time.', '', '', '', '猎人获得灵猴守护，使躲闪几率提高$s1%。一个猎人在同一时间内只能激活一种守护。', '', '', 'Increases chance to dodge by $s1%.', '', '', '', '躲闪几率提高$s1%。', '', '');
