INSERT INTO `locales_spell` VALUES (13166, 'Battle Chicken', '', '', '', '作战小鸡', '', '', '', '', '', '', '', '', '', 'Creates a Battle Chicken that will fight for you for $d or until it is destroyed.', '', '', '', '制造一只机械小鸡为你作战。持续$d或者直到小鸡被摧毁。', '', '', '', '', '', '', '', '', '');
