INSERT INTO `locales_spell` VALUES (13168, 'Chicken Fury', '', '', '', '小鸡之怒', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by the chicken by $s1% and speeds the chicken\'s attack by $s2% for $d.', '', '', '', '使小鸡造成的物理伤害提高$s1%，攻击速度提高$s2%，持续$d。', '', '', 'Physical damage dealt is increased by $s1%.\nAttack speed increased by $s2%.', '', '', '', '物理伤害能力提高$s1%。\n攻击速度提高$s2%。', '', '');
