INSERT INTO `locales_spell` VALUES (13180, 'Gnomish Mind Control Cap', '', '', '', '侏儒洗脑帽', '', '', '', '', '', '', '', '', '', 'Engage in mental combat with a humanoid target to try and control their mind.  If all works well, you will control the mind of the target for $13181d .....', '', '', '', '接触目标的思想并尝试控制它。如果一切正常，你就可以控制目标的思想，持续$13181d……', '', '', '', '', '', '', '', '', '');
