INSERT INTO `locales_spell` VALUES (13183, 'Goblin Dragon Gun', '', '', '', '地精龙枪', '', '', '', '', '', '', '', '', '', 'Deals $13184s1 fire damage for $d to all targets in a cone in front of the engineer using the weapon.   That is unless it explodes.....', '', '', '', '对所有身处使用者面前的一个锥形区域中的敌人造成$13184s1点火焰伤害，持续$d。当然，前提是它没有突然爆炸……', '', '', 'Dealing $13184s1 fire damage per second.', '', '', '', '每秒造成$13184s1点火焰伤害。', '', '');
