INSERT INTO `locales_spell` VALUES (13234, 'Harm Prevention Belt', '', '', '', '防护腰带', '', '', '', '', '', '', '', '', '', 'A shield of force protects you from the next $s1 damage done over the next $d1. WARNING:  Force Field may overload when struck temporarily removing the wearer from this dimension.', '', '', '', '制造一个力场，替你在接下来的$d1内吸收$s1点伤害。警告：力场有可能因受到冲击而过载，并暂时将佩戴者转移到另一个维度。', '', '', 'Absorbs damage.  Effectiveness not guaranteed.', '', '', '', '吸收伤害，不保证总是有效。', '', '');
