INSERT INTO `locales_spell` VALUES (13238, 'Goblin Mortar', '', '', '', '地精迫击炮', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage and causes $o2 damage over $d to targets in a 10 yard radius.', '', '', '', '对半径10码范围内的所有敌人造成$s1点火焰伤害，并在接下来的$d内对其造成总计$o2点额外伤害。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
