INSERT INTO `locales_spell` VALUES (13241, 'Goblin Sapper Charge', '', '', '', '地精工兵炸药', '', '', '', '', '', '', '', '', '', 'Explodes when triggered dealing $s1 Fire damage to all enemies nearby and $s2 damage to you.', '', '', '', '触发之后发生爆炸，对附近的所有敌人造成$s1点火焰伤害，对你造成$s2点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13258, 'Summon Goblin Bomb', '', '', '', '召唤地精炸弹', '', '', '', '', '', '', '', '', '', 'Creates a mobile bomb that charges the nearest enemy and explodes for $13259s1 fire damage.', '', '', '', '制造一颗自走炸弹，它会冲向最近的敌人并自爆，对其造成$13259s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
