INSERT INTO `locales_spell` VALUES (13262, 'Disenchant', '', '', '', '分解', '', '', '', '', '', '', '', '', '', 'Extracts the magical element(s) from good quality (Green) or better weapons or armor.  The targeted item will be DESTROYED and will not be retrievable.', '', '', '', '从优质（绿色）或更好的武器或护甲中提炼出其中的魔法元素，在这个过程中该武器或护甲会被摧毁。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13278, 'Gnomish Death Ray', '', '', '', '侏儒死亡射线', '', '', '', '', '', '', '', '', '', 'The devices charges over time using your life force and then directs a burst of energy at your opponent.', '', '', '', '这件设备可以将你的生命能量以强力冲击波的形式发射出去，攻击你的敌人。', '', '', 'Charging death ray using your life force.', '', '', '', '使用你的生命能量为死亡射线充能。', '', '');
