INSERT INTO `locales_spell` VALUES (13298, 'Poison', '', '', '', '毒药', '', '', '', '', '', '', '', '', '', 'Inflicts Nature damage to an enemy every $t1 sec. for $d.', '', '', '', '每$t1秒对目标造成一次自然伤害，持续$d。', '', '', 'Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒受到一次自然伤害。', '', '');
