INSERT INTO `locales_spell` VALUES (13321, 'Mana Burn', '', '', '', '法力燃烧', '', '', '', '', '', '', '', '', '', 'Hits an enemy with an anti-mana bolt. For each point of mana consumed by the bolt, the target takes $e1 damage.', '', '', '', '向敌人射出一支可抽取法力值的箭，每抽取1点法力值，目标就受到$e1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13322, 'Frostbolt', '', '', '', '寒冰箭', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to an enemy and reduces its movement speed for $d.', '', '', '', '对敌人造成冰霜伤害，并使其移动速度降低，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (13323, 'Polymorph', '', '', '', '变形术', '', '', '', '', '', '', '', '', '', 'Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物或小动物施放。', '', '', 'Cannot attack or cast spells.\nHealth regeneration increased.', '', '', '', '不能攻击或施法。\n生命值回复速度提高。', '', '');
