INSERT INTO `locales_spell` VALUES (13326, 'Arcane Intellect', '', '', '', '奥术智慧', '', '', '', '', '', '', '', '', '', 'Increases an ally\'s Intellect by $s1 for $d.', '', '', '', '使目标的智力提高$s1点，持续$d。', '', '', 'Intellect increased by $s1.', '', '', '', '智力提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (13327, 'Reckless Charge', '', '', '', '无畏冲锋', '', '', '', '', '', '', '', '', '', 'Charge an enemy, knocking it silly for $d. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target.', '', '', '', '向目标冲锋，将其打傻$d秒。这个技能也会使你被击倒并在短时间内昏迷。任何伤害都会唤醒目标。', '', '', 'Incapacitated.', '', '', '', '瘫痪。', '', '');
INSERT INTO `locales_spell` VALUES (13338, 'Curse of Tongues', '', '', '', '语言诅咒', '', '', '', '', '', '', '', '', '', 'Forces an enemy to speak in Demonic, reducing its casting speed by $s1% for $d. Only one curse per warlock can be active on any one target.', '', '', '', '强迫目标使用恶魔语，使其所有法术的施放时间延长$s1%，持续$d。每个术士只能对一个目标施加一种诅咒。', '', '', 'Casting speed reduced by $s1%.', '', '', '', '施法速度降低$s1%。', '', '');
