INSERT INTO `locales_spell` VALUES (13578, 'Jadefire', '', '', '', '碧火', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with searing magic for $d. The flames increase armor by $s2% and inflict $s1 damage to melee attackers.', '', '', '', '灼热的魔法环绕着施法者，使其护甲提高$s2%，并对使用近战武器击中施法者的敌人造成$s1点伤害。持续$d。', '', '', 'Armor increased by $s2%.\n$s1 Fire damage inflicted to melee attackers.', '', '', '', '护甲值提高$s2%。\n对近战攻击者造成$s1点火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (13579, 'Gouge', '', '', '', '凿击', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 damage to an enemy and stuns it for up to $d. You will automatically stop attacking. Target must be facing you. Any damage received by the stunned target will revive it.', '', '', '', '对目标造成$s1点伤害，令其昏迷$d，并使你不再攻击这个目标。这个技能必须在目标面对着你的时候发动，任何后继的伤害都会令目标醒来。奖励$s2个连击点数。', '', '', 'Incapacitated.', '', '', '', '瘫痪。', '', '');
INSERT INTO `locales_spell` VALUES (13582, 'Deadly Poison', '', '', '', '致命毒药', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Nature damage to nearby enemies every $t1 sec. for $d.', '', '', '', '每$t1秒对附近的敌人造成$s1点自然伤害，持续$d。', '', '', '$s1 Nature damage inflicted every $t1 sec.', '', '', '', '每$t1秒造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (13583, 'Curse of the Deadwood', '', '', '', '死木诅咒', '', '', '', '', '', '', '', '', '', 'Reduces healing effects for an enemy by $s1% for $d.', '', '', '', '使目标在受到治疗时的治疗效果降低$s1%，持续$d。', '', '', 'Healing effects reduced by $s1%.', '', '', '', '治疗效果降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (13584, 'Strike', '', '', '', '打击', '', '', '', '', '', '', '', '', '', 'Strikes at an enemy, inflicting normal damage plus $s1.', '', '', '', '对敌人造成普通伤害再加上$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (13585, 'Lightning Shield', '', '', '', '闪电之盾', '', '', '', '', '', '', '', '', '', 'Surrounds an ally with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.', '', '', '', '施法者被3个闪电球环绕，如果敌人用近身或远程攻击打中施法者，就有一定的几率被闪电球反击并受到$s1点伤害，每次反击消耗一个闪电球。持续$d。', '', '', '$h% chance of inflicting $s1 Nature damage on hit.', '', '', '', '有$h%的几率在击中敌人时对其造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (13586, 'Aqua Jet', '', '', '', '水流喷射', '', '', '', '', '', '', '', '', '', 'Sprays water in all directions, inflicting Frost damage to nearby enemies and knocking them back.', '', '', '', '向各个方向射出水流，对附近的敌人造成冰霜伤害，并将它们击退。', '', '', '', '', '', '', '', '', '');
