INSERT INTO `locales_spell` VALUES (13589, 'Haste Aura', '', '', '', '加速光环', '', '', '', '', '', '', '', '', '', 'Increases the attack speed of all nearby party members by $s1%. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.', '', '', '', '使附近小队成员的攻击速度提高$s1%。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Attack speed increased by $s1%.', '', '', '', '攻击速度提高$s1%。', '', '');
