INSERT INTO `locales_spell` VALUES (13813, 'Explosive Trap', '', '', '', '爆炸陷阱', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Place a fire trap that explodes when an enemy approaches, causing $13812s1 Fire damage and $13812o2 additional Fire damage over $13812d to all within $13812a1 yards.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.', '', '', '', '在地面上放置一个陷阱，当敌人接近时会爆炸，对半径$13812a1码范围内的所有敌人造成$13812s1点火焰伤害，并在接下来的$13812d内继续对其造成$13812o2点额外的火焰伤害。陷阱可存在$d。只能在非战斗状态中安置陷阱，每个猎人在同一时间内只能布置一个陷阱。', '', '', '', '', '', '', '', '', '');
