INSERT INTO `locales_spell` VALUES (13896, 'Feedback', '', '', '', '回馈', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $6347s1 of the attacker\'s Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.', '', '', '', '牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失$6347s1点法力值，并对其造成等量的暗影伤害。效果持续$d。', '', '', 'Anti-magic energy will burn $6347s1 of the attacker\'s Mana, causing 1 Shadow damage for each point of Mana burned.', '', '', '', '任何对牧师成功施放的敌对法术都会令施法者损失$6347s1点法力值，并对其造成等量的暗影伤害。', '', '');
