INSERT INTO `locales_spell` VALUES (14316, 'Explosive Trap', '', '', '', '爆炸陷阱', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Place a fire trap that explodes when an enemy approaches, causing $14314s1 Fire damage and $14314o2 additional Fire damage over $14314d to all within $14314a1 yards.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.', '', '', '', '在地面上放置一个陷阱，当敌人接近时会爆炸，对半径$14314a1码范围内的所有敌人造成$14314s1点火焰伤害，并在接下来的$14314d内继续对其造成$14314o2点额外的火焰伤害。陷阱可存在$d。只能在非战斗状态中安置陷阱，每个猎人在同一时间内只能布置一个陷阱。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14317, 'Explosive Trap', '', '', '', '爆炸陷阱', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Place a fire trap that explodes when an enemy approaches, causing $14315s1 Fire damage and $14315o2 additional Fire damage over $14315d to all within $14315a1 yards.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.', '', '', '', '在地面上放置一个陷阱，当敌人接近时会爆炸，对半径$14315a1码范围内的所有敌人造成$14315s1点火焰伤害，并在接下来的$14315d内继续对其造成$14315o2点额外的火焰伤害。陷阱可存在$d。只能在非战斗状态中安置陷阱，每个猎人在同一时间内只能布置一个陷阱。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14318, 'Aspect of the Hawk', '', '', '', '雄鹰守护', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'The hunter takes on the aspects of a hawk, increasing Ranged Attack Power by $s1.  Only one Aspect can be active at a time.', '', '', '', '猎人获得雄鹰守护，使远程攻击强度提高$s1点。一个猎人在同一时间内只能激活一种守护。', '', '', 'Increases Ranged Attack Power by $s1.', '', '', '', '远程攻击强度提高$s1点。', '', '');
