INSERT INTO `locales_spell` VALUES (14323, 'Hunter\'s Mark', '', '', '', '猎人印记', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Places the Hunter\'s Mark on the target, increasing the Ranged Attack Power of all attackers against that target by $s2.  In addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible.  The target also appears on the mini-map.  Lasts for $d.', '', '', '', '给目标加上猎人印记，使任何攻击者的远程武器对该目标的攻击强度提高$s2点。另外，被施加了这项技能的目标总是可以被猎人看见，无论是隐形还是潜行都无法摆脱。目标的位置也会在微缩地图上显示出来，持续$d。', '', '', 'All attackers gain $s2 Ranged Attack Power against this target.', '', '', '', '对此目标进行的所有远程攻击均有额外的$s2点远程攻击强度加成。', '', '');
INSERT INTO `locales_spell` VALUES (14324, 'Hunter\'s Mark', '', '', '', '猎人印记', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Places the Hunter\'s Mark on the target, increasing the Ranged Attack Power of all attackers against that target by $s2.  In addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible.  The target also appears on the mini-map.  Lasts for $d.', '', '', '', '给目标加上猎人印记，使任何攻击者的远程武器对该目标的攻击强度提高$s2点。另外，被施加了这项技能的目标总是可以被猎人看见，无论是隐形还是潜行都无法摆脱。目标的位置也会在微缩地图上显示出来，持续$d。', '', '', 'All attackers gain $s2 Ranged Attack Power against this target.', '', '', '', '对此目标进行的所有远程攻击均有额外的$s2点远程攻击强度加成。', '', '');
INSERT INTO `locales_spell` VALUES (14325, 'Hunter\'s Mark', '', '', '', '猎人印记', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Places the Hunter\'s Mark on the target, increasing the Ranged Attack Power of all attackers against that target by $s2.  In addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible.  The target also appears on the mini-map.  Lasts for $d.', '', '', '', '给目标加上猎人印记，使任何攻击者的远程武器对该目标的攻击强度提高$s2点。另外，被施加了这项技能的目标总是可以被猎人看见，无论是隐形还是潜行都无法摆脱。目标的位置也会在微缩地图上显示出来，持续$d。', '', '', 'All attackers gain $s2 Ranged Attack Power against this target.', '', '', '', '对此目标进行的所有远程攻击均有额外的$s2点远程攻击强度加成。', '', '');
INSERT INTO `locales_spell` VALUES (14326, 'Scare Beast', '', '', '', '恐吓野兽', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Scares a beast, causing it to run in fear for up to $d.  Damage caused may interrupt the effect.  Only one beast can be feared at a time.', '', '', '', '恐吓一头野兽，使其因恐慌而逃跑，最多持续$d。任何伤害都有可能打断这个效果。每个猎人在同一时间内只能恐吓一头野兽。', '', '', 'Feared.', '', '', '', '恐惧。', '', '');
