INSERT INTO `locales_spell` VALUES (14529, 'Focused Casting', '', '', '', 'zzOLDFocused Casting', '', '', '', '', '', '', '', '', '', 'While active, you no longer lose casting time from taking damage.  Lasts $d.', '', '', '', '激活之后，你不会因受到伤害而损失施法时间。持续$d。', '', '', 'Cannot lose casting time from taking damage.', '', '', '', '不会因受到伤害而损失施法时间。', '', '');
