INSERT INTO `locales_spell` VALUES (14531, 'Martyrdom', '', '', '', '殉难', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives you a $h% chance to gain the Focused Casting effect that lasts for $14743d after being the victim of a melee or ranged critical strike.  The Focused Casting effect prevents you from losing casting time when taking damage and increases resistance to Interrupt effects by $14743s2%.', '', '', '', '使你有$h%的几率在受到敌人的近战或远程致命一击后得到专注施法效果，持续$14743d。专注施法效果可以让你在施法时不会因为受到伤害而延长施法时间，且令你抵抗打断效果的几率提高$14743s2%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14532, 'Creeper Venom', '', '', '', '慢性毒药', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage taken by nearby enemies by $s1% for $d.', '', '', '', '受到物理攻击时所承受的伤害提高$s1%，$d。', '', '', 'Physical damage taken is increased by $s1%.', '', '', '', '受到物理攻击时所承受的伤害提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (14533, 'Disjunction', '', '', '', '分离', '', '', '', '', '', '', '', '', '', 'Increases the Fire, Frost, and Arcane damage that nearby enemies take by $s1% for $d.', '', '', '', '使附近的敌人在受到火焰、冰霜或奥术攻击时承受的伤害提高$s1%，持续$d。', '', '', 'Fire, Frost, and Arcane damage taken is increased by $s1%.', '', '', '', '在受到火焰、冰霜或奥术攻击时承受的伤害提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (14534, 'Barbed Sting', '', '', '', '倒钩之刺', '', '', '', '', '', '', '', '', '', 'Increases the time between nearby enemies\' attacks by $s1% for $d.', '', '', '', '使附近敌人的攻击间隔延长$s1%，持续$d。', '', '', 'Time between attacks increased by $s1%.', '', '', '', '攻击间隔延长$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (14535, 'Dredge Sickness', '', '', '', '病弱', '', '', '', '', '', '', '', '', '', 'Reduces all attributes of nearby enemies by $s1% for $d.', '', '', '', '使附近敌人的所有属性降低$s1%，持续$d。', '', '', 'All attributes reduced by $s1%.', '', '', '', '所有属性降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (14537, 'Six Demon Bag', '', '', '', '六魔包', '', '', '', '', '', '', '', '', '', 'Blasts enemies in front of you with the power of wind, fire, all that kind of thing!', '', '', '', '以风与火、雷与电，乃至万物的力量攻击敌人！', '', '', '', '', '', '', '', '', '');
