INSERT INTO `locales_spell` VALUES (14539, 'Putrid Enzyme', '', '', '', '腐烂蛋白', '', '', '', '', '', '', '', '', '', 'Increases the Nature damage taken by nearby enemies by $s1% and increases the Shadow damage they take by $s2%. Lasts $d.', '', '', '', '使附近敌人在受到自然系攻击时承受的伤害提高$s1%，在受到暗影系攻击时承受的伤害提高$s2%。持续$d。', '', '', 'Nature damage taken is increased by $s1%.\nShadow damage taken is increased by $s2%.', '', '', '', '受到自然系攻击时承受的伤害提高$s1%。\n受到暗影系攻击时承受的伤害提高$s2%。', '', '');
