INSERT INTO `locales_spell` VALUES (14621, 'Polymorph', '', '', '', '变形术', '', '', '', '', '', '', '', '', '', 'Transforms you into a sheep, forcing you to wander around for up to $d.  While wandering, you cannot attack or cast spells and any damage will transform you back into your normal form.', '', '', '', '将你变成绵羊，使你在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。', '', '', 'Cannot attack or cast spells.', '', '', '', '不能攻击或施法。', '', '');
