INSERT INTO `locales_spell` VALUES (14891, 'Smelt Dark Iron', '', '', '', '熔炼黑铁', '', '', '', '', '', '', '', '', '', 'Allows the miner to smelt chunks of dark iron ore into a dark iron bar.  Smelting Dark Iron can only be done at the Black Forge in Blackrock Depths.', '', '', '', '使矿工可以将黑铁矿石熔炼成黑铁锭。必须在黑石深渊中的黑铁熔炉中进行。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14892, 'Inspiration', '', '', '', '灵感', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases your target\'s armor by $14893s1% for $14893d after getting a critical effect from your Flash Heal, Heal, Greater Heal, or Prayer of Healing spell.', '', '', '', '在你的快速治疗、治疗术、强效治疗术或治疗祷言对目标造成极效治疗效果后，使目标的护甲值提高$14893s1%，持续$14893d。', '', '', '', '', '', '', '', '', '');
