INSERT INTO `locales_spell` VALUES (14895, 'Overpower', '', '', '', '压制', '', '', '', '', '', '', '', '', '', 'Instantly overpowers an enemy, causing weapon damage plus $s1. Can only be used after the target dodges. Overpower cannot be blocked, dodged, or parried.', '', '', '', '立刻压制敌人，对其造成武器伤害外加$s1点伤害。只能在目标躲闪之后使用。压制无法被格档、躲闪或招架。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14897, 'Slowing Poison', '', '', '', '减速毒药', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s1% and slows its movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
