INSERT INTO `locales_spell` VALUES (14900, 'Chain Heal', '', '', '', '治疗链', '', '', '', '', '', '', '', '', '', 'Infuses a wounded ally with healing energy that spreads to another nearby ally. The spell affects up to $x1 targets, but the healing energy is diminished by 50% for each successive target.', '', '', '', '运用治疗的能量为一个受伤的盟友恢复生命值，这股能量会继续治疗附近的其它盟友，最多影响$x1个目标，但每次治疗的效果都降低50%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14901, 'Spiritual Guidance', '', '', '', '精神指引', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases spell damage and healing by up to $s1% of your total Spirit.', '', '', '', '使你的法术的治疗和伤害效果提高，数值最多相当于你的精神值的$s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (14902, 'Cheap Shot', '', '', '', '偷袭', '', '', '', '', '', '', '', '', '', 'Stuns an enemy for $d. Must be stealthed. Awards $s2 combo $lpoint:points;.', '', '', '', '使目标昏迷$d，必须在潜行状态下使用。奖励$s2点连击点数。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (14903, 'Rupture', '', '', '', '割裂', '', '', '', '', '', '', '', '', '', 'Inflicts Physical damage to an enemy every $t1 sec. Additional combo points increase the periodic damage inflicted and the total duration.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定持续时间：\n   1点：45伤害，持续6秒\n   2点：75伤害，持续10秒\n   3点：105伤害，持续14秒\n   4点：135伤害，持续18秒\n   5点：165伤害，持续22秒', '', '', 'Physical damage inflicted every $t1 sec.', '', '', '', '每$t1秒因流血受到一次伤害。', '', '');
INSERT INTO `locales_spell` VALUES (14904, 'Master Healer', '', '', '', '治疗大师', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces the casting time of your Heal and Greater Heal spells by $/1000;S1 sec.', '', '', '', '使你的治疗术和强力治疗术的施法时间减少$/1000;S1秒。', '', '', '', '', '', '', '', '', '');
