INSERT INTO `locales_spell` VALUES (15470, 'Curse of Tongues', '', '', '', '语言诅咒', '', '', '', '', '', '', '', '', '', 'Forces nearby enemies to speak in Demonic, reducing their casting speed by $s1% for $d. Only one curse per warlock can be active on any one target.', '', '', '', '强迫目标使用恶魔语，使其所有法术的施放时间延长$s1%，持续$d。每个术士只能对一个目标施加一种诅咒。', '', '', 'Casting speed reduced by $s1%.', '', '', '', '施法速度降低$s1%。', '', '');
