INSERT INTO `locales_spell` VALUES (15473, 'Shadowform', '', '', '', '暗影形态', '', '', '', '', '', '', '', '', '', 'Assume a Shadowform, increasing your Shadow damage by $s2% and reducing Physical damage done to you by $s3%.  However, you may not cast Holy spells while in this form.', '', '', '', '进入暗影形态，使你能造成的暗影伤害提高$s2%，受到物理攻击时承受的伤害降低$s3%。但是在这个形态下，你不能施放神圣系的法术。', '', '', 'Shadow damage you deal increased by $s2%.  Physical damage you take reduced by $s3%.  You may not cast Holy spells.', '', '', '', '使你能造成的暗影伤害提高$s2%，受到物理攻击时承受的伤害降低$s3%。不能施放神圣系的法术。', '', '');
