INSERT INTO `locales_spell` VALUES (15507, 'Lightning Shield', '', '', '', '闪电之盾', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.', '', '', '', '$n颗闪电球环绕着施法者，有$h%的几率对近战或远程攻击者造成$s1点伤害。每次闪电之盾发动反击都会消耗一颗闪电球。因此，闪电之盾最多可维持$d，或者在反击$n次后消失。', '', '', '$h% chance of inflicting $s1 Nature damage on hit.', '', '', '', '有$h%的几率在击中敌人时对其造成$s1点自然伤害。', '', '');
