INSERT INTO `locales_spell` VALUES (15534, 'Polymorph', '', '', '', '变形术', '', '', '', '', '', '', '', '', '', 'Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物或小动物施放。', '', '', 'Cannot attack or cast spells.\nHealth regeneration increased.', '', '', '', '不能攻击或施法。\n生命值回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (15535, 'Enveloping Winds', '', '', '', '包围之风', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Surrounds an enemy with a cyclone for up to $d. If the target takes any damage, it will break free of the imprisoning winds.', '', '', '', '一阵旋风包围着敌人，最多持续$d。如果目标受到伤害，则该效果消失。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
