INSERT INTO `locales_spell` VALUES (15779, 'White Mechanostrider', '', '', '', '白色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'Forced to recall the model after numerous complaints of an \"uncontrollable throttle\", Gnomish engineers now refer to a proto-type blunder as a \"model B\".', '', '', '', '在多次抱怨“油门失控”后，侏儒工程师被迫召回该模型，现在将原型错误称为“模型 B”。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (15780, 'Green Mechanostrider', '', '', '', '绿色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable mechanical tallstrider.', '', '', '', '召唤或解散一只可供骑乘的机械陆行鸟。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (15781, 'Steel Mechanostrider', '', '', '', '钢质机械陆行鸟', '', '', '', '', '', '', '', '', '', 'A mechanical marvel, built to withstand the toughest of battles.', '', '', '', '机械奇迹，专为承受最艰难的战斗而打造。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
