INSERT INTO `locales_spell` VALUES (15783, 'Blizzard', '', '', '', '暴风雪', '', '', '', '', '', '', '', '', '', 'Calls down a blizzard that lasts $d., inflicting $s1 Frost damage every $t1 sec. to all enemies in a selected area.', '', '', '', '召唤持续$d的暴风雪，对指定区域内的所有敌人每$t1秒造成$s1点冰霜伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (15784, 'Frost Armor', '', '', '', '霜甲术', '', '', '', '', '', '', '', '', '', 'Encases an ally in a layer of frost that lasts $d. The thick ice increases armor by $s1, slows melee attackers\' movement to $6136s2%, and increases the time between their attacks by $6136s1%.', '', '', '', '使一个盟友被冰霜包围，持续$d。厚重的冰霜使护甲值提高$s1点，令使用近战武器击中被保护者的敌人的移动速度降低$6136s2%，并使它们的攻击间隔延长$6136s1%。', '', '', 'Armor increased by $s1.\nSlowing melee attackers\' movement and attacks.', '', '', '', '护甲提高$s1点。\n降低近战攻击者的移动和攻击速度。', '', '');
INSERT INTO `locales_spell` VALUES (15785, 'Mana Burn', '', '', '', '法力燃烧', '', '', '', '', '', '', '', '', '', 'Hits an enemy with an anti-mana bolt. For each point of mana consumed by the bolt, the target takes $e1 damage.', '', '', '', '向敌人射出一支可抽取法力值的箭，每抽取1点法力值，目标就受到$e1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (15786, 'Earthbind Totem', '', '', '', '地缚图腾', '', '', '', '', '', '', '', '', '', 'Summons an Earthbind Totem that lasts $d. and periodically reduces the movement speed of nearby enemies to $3600s1% of normal.', '', '', '', '召唤一个地缚图腾，持续$d。周期性地使附近敌人的移动速度降低到普通速度的$3600s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (15787, 'Moonflare Totem', '', '', '', '月焰图腾', '', '', '', '', '', '', '', '', '', 'Summons a Moonflare Totem at the caster\'s feet. Totem lasts $d. and inflicts Arcane damage to nearby enemies every $15789t1 sec.', '', '', '', '在施法者身边召唤一个月焰图腾，每$15789t1秒对附近的敌人造成一次奥术伤害。持续$d。', '', '', '', '', '', '', '', '', '');
