INSERT INTO `locales_spell` VALUES (15799, 'Chain Heal', '', '', '', '治疗链', '', '', '', '', '', '', '', '', '', 'Infuses a wounded ally with healing energy that spreads to another nearby ally. The spell affects up to $x1 targets, but the healing energy is diminished by 50% for each successive target.', '', '', '', '运用治疗的能量为一个受伤的盟友恢复生命值，这股能量会继续治疗附近的其它盟友，最多影响$x1个目标，但每次治疗的效果都降低50%。', '', '', '', '', '', '', '', '', '');
