INSERT INTO `locales_spell` VALUES (16031, 'Releasing Corrupt Ooze', '', '', '', '释放腐化软泥怪', '', '', '', '', '', '', '', '', '', 'Releases a captured Felwood ooze so it can interact with a primal ooze in Un\'Goro Crater.', '', '', '', '释放一个被捕获的腐化软泥怪，使它与安戈洛的原始软泥怪发生互动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16032, 'Merging Oozes', '', '', '', '融合软泥怪', '', '', '', '', '', '', '', '', '', 'A captured Felwood ooze merges with a primal ooze of Un\'Goro Crater.', '', '', '', '费伍德软泥怪和安戈洛软泥怪的融合体。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16033, 'Chain Lightning', '', '', '', '闪电链', '', '', '', '', '', '', '', '', '', 'Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.', '', '', '', '向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，最多可攻击$x1个目标，每次击中都会造成更高的自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16034, 'Shock', '', '', '', '震击', '', '', '', '', '', '', '', '', '', 'Instantly throws a bolt of lightning at an enemy, inflicting Nature damage.', '', '', '', '立即向目标射出一支闪电箭，对其造成自然伤害。', '', '', '', '', '', '', '', '', '');
