INSERT INTO `locales_spell` VALUES (16081, 'Arctic Wolf', '', '', '', '极地冰狼', '', '', '', '', '', '', '', '', '', 'Ancient furbolg legends claim that wolves born with a white coat are blessed by Azeroth\'s two moons.', '', '', '', '古老的熊怪传说声称，生来就有白毛的狼受到了艾泽拉斯两颗卫星的祝福。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
