INSERT INTO `locales_spell` VALUES (16164, 'Elemental Focus', '', '', '', '元素集中', '', '', '', '', '', '', '', '', '', 'Gives you a $h% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell.  The Clearcasting state reduces the mana cost of your next damage spell by $16246s1%.', '', '', '', '使你有$h1%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。这个状态可以使你的下一个伤害性法术所消耗的法力值减少$16246s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16166, 'Elemental Mastery', '', '', '', '元素掌握', '', '', '', '', '', '', '', '', '', 'When activated, this spell gives your next Fire, Frost, or Nature damage spell a $s1% critical strike chance and reduces the mana cost by $s2%.', '', '', '', '激活之后，你的下一个火焰、冰霜或自然法术有$s1%的几率造成致命一击，且法力值消耗降低$s2%。', '', '', 'Your next Fire, Frost, or Nature damage spell has it\'s mana cost reduced by $s2% and is guaranteed a critical strike.', '', '', '', '你的下一个火焰、冰霜或自然法术必定造成致命一击，且法力值消耗降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (16167, 'Rend Blackhand Mounts', '', '', '', '雷德·黑手坐骑', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16168, 'Flame Buffet', '', '', '', '烈焰打击', '', '', '', '', '', '', '', '', '', 'Inflicts Fire damage to an enemy and increases the Fire damage it takes for $d.', '', '', '', '对敌人造成火焰伤害，并使其在受到火焰攻击时承受更多伤害，持续$d。', '', '', 'Increased Fire damage taken.', '', '', '', '在受到火焰攻击时承受更多伤害。', '', '');
INSERT INTO `locales_spell` VALUES (16169, 'Arcing Smash', '', '', '', '圆弧斩', '', '', '', '', '', '', '', '', '', 'Lashes out in a vicious arc, inflicting normal damage plus $s1 to enemies in a cone in front of the caster.', '', '', '', '对施法者面前一个锥形区域内的所有敌人造成普通伤害外加$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16170, 'Bloodlust', '', '', '', '嗜血术', '', '', '', '', '', '', '', '', '', 'Increases an ally\'s attack speed by $s1% for $d.', '', '', '', '使一个友方玩家的攻击速度提高$s1%，持续$d。', '', '', 'Attack speed increased by $s1%.', '', '', '', '攻击速度提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (16171, 'Empower Will', '', '', '', '强化意志', '', '', '', '', '', '', '', '', '', 'Dispels $s1 polymorph, charm, or knockout $leffect:effects; from nearby allies.', '', '', '', '驱散附近盟友身上的$s1个变形、魅惑或击昏效果。', '', '', '', '', '', '', '', '', '');
