INSERT INTO `locales_spell` VALUES (16339, 'Flametongue Weapon', '', '', '', '火舌武器', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Imbue the Shaman\'s weapon with fire.  Each hit causes $/77;10445m1 to $/25;10445M1 additional Fire damage, based on the speed of the weapon.  Slower weapons cause more fire damage per swing.  Lasts for 5 minutes.', '', '', '', '给萨满祭司的武器附加火焰的力量。每次击中敌人都会对其造成$/77;10445m1到$/25;10445M1点额外的火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。持续5分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (16340, 'Frost Breath', '', '', '', '冰息术', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to enemies in a cone in front of the caster, stealing their mana and reducing their movement speed for $d.', '', '', '', '对施法者面前一个锥形区域中的敌人造成冰霜伤害，偷取它们的法力值，并降低它们的移动速度，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
