INSERT INTO `locales_spell` VALUES (16430, 'Soul Tap', '', '', '', '灵魂分流', '', '', '', '', '', '', '', '', '', 'Taps into an enemy\'s soul. Steals $s1 health every $t1 sec. and $s2 mana every $t2 sec., transferring them to the caster. Lasts $d.', '', '', '', '每$t1秒偷取$s1点生命值，每$t2秒偷取$s2点法力值，并将它们转移给施法者，持续$d。', '', '', '$s1 health leeched every $t1 sec.\n$s2 mana leeched every $t2 sec.', '', '', '', '每$t1秒偷取$s1点生命值，\n每$t2秒偷取$s2点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (16431, 'Bone Armor', '', '', '', '骨甲术', '', '', '', '', '', '', '', '', '', 'Encases the caster in bone armor, absorbing $s1 damage for $d. While the armor holds, spellcasting cannot be interrupted by Physical attacks.', '', '', '', '白骨护甲环绕着施法者，可在$d内吸收最多$s1点伤害。只要骨甲仍然存在，施法就不会被物理攻击打断。', '', '', 'Damage is absorbed by bone armor.', '', '', '', '伤害被骨甲吸收。', '', '');
