INSERT INTO `locales_spell` VALUES (16449, 'Maggot Slime', '', '', '', '蛆虫粘液', '', '', '', '', '', '', '', '', '', 'Reduces an enemy\'s melee attack power by $s1 and its ranged attack power by $s2 for $d.', '', '', '', '使敌人的近战攻击强度降低$s1点，远程攻击强度降低$s2点，持续$d。', '', '', 'Melee attack power reduced by $s1.\nRanged attack power reduced by $s2.', '', '', '', '近战攻击强度降低$s1点。\n远程攻击强度降低$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (16450, 'Smolderweb Hatchling', '', '', '', '烟网蜘蛛', '', '', '', '', '', '', '', '', '', 'These spiders are immensily cunning yet loyal to their brood. Handle with care and no pest will ever disturb your sound sleep.', '', '', '', '这些蜘蛛非常狡猾，但对它们的巢穴忠诚。小心处理，任何害虫都不会打扰您的睡眠。', '', '', '', '', '', '', '', '', '');
