INSERT INTO `locales_spell` VALUES (17196, 'Seeping Willow', '', '', '', '横扫重锤', '', '', '', '', '', '', '', '', '', 'Lowers all stats by $s2 and deals $s1 Nature damage every $t1 sec to all enemies within an $a1 yard radius of the caster for $d.', '', '', '', '使施法者身边半径$a1码范围内的敌人的所有属性降低$s2点，每$t1秒对它们造成$s1点自然伤害，持续$d。', '', '', 'All stats lowered by $s2 and periodic Nature damage.', '', '', '', '所有属性降低$s2点，受到周期性自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (17197, 'Maggot Goo', '', '', '', '蛆虫腐液', '', '', '', '', '', '', '', '', '', 'Poisons nearby enemies for $s1 damage, then inflicts an additional $s2 Nature damage every $t2 sec. for $d.', '', '', '', '使附近的敌人中毒，受到$s1点伤害，并在接下来的$d内每$t2秒受到$s2点额外的自然伤害。', '', '', '$s2 Nature damage inflicted every $t2 sec.', '', '', '', '每$t2秒$s2点自然伤害。', '', '');
