INSERT INTO `locales_spell` VALUES (17227, 'Curse of Weakness', '', '', '', '虚弱诅咒', '', '', '', '', '', '', '', '', '', 'Reduces the Physical damage dealt by an enemy by $s1 for $d. Only one curse per warlock can be active on any one target.', '', '', '', '目标所能造成的伤害降低$s1点，持续$d。每个术士只能对一个目标施加一种诅咒。', '', '', 'Physical damage dealt is reduced by $s1.', '', '', '', '对目标造成的物理伤害降低$s1点。', '', '');
