INSERT INTO `locales_spell` VALUES (17229, 'Winterspring Frostsaber', '', '', '', '冬泉霜刃豹', '', '', '', '', '', '', '', '', '', 'Taming this savage breed requires patience, strength, and a large supply of fake mice and twine.', '', '', '', '驯服这种野蛮品种需要耐心、力量以及大量的假老鼠和麻线。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
