INSERT INTO `locales_spell` VALUES (17445, 'Bone Smelt', '', '', '', '白骨熔化', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to an enemy and reduces its armor by $s2% for $d.', '', '', '', '对一个敌人造成$s1点火焰伤害，并使其护甲值降低$s2%，持续$d。', '', '', 'Armor reduced by $s2%.', '', '', '', '护甲降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (17446, 'The Black Sleep', '', '', '', '黑暗睡眠', '', '', '', '', '', '', '', '', '', 'Bewitches enemies in a cone in front of the caster so that they fall asleep, rendering them unable to attack or cast spells for $d.', '', '', '', '催眠施法者面前一个锥形区域中的敌人，使它们陷入睡眠状态，无法攻击或施法，持续$d。', '', '', 'Cannot attack or cast spells.', '', '', '', '不能攻击或施法。', '', '');
