INSERT INTO `locales_spell` VALUES (17448, 'Testament of Hope', '', '', '', '希望的证明', '', '', '', '', '', '', '', '', '', 'Restores $s1 health. Can only be used at 10% health.', '', '', '', '回复$s1点生命值。只能在生命值不高于10%时使用。', '', '', '', '', '', '', '', '', '');
