INSERT INTO `locales_spell` VALUES (17450, 'Ivory Raptor', '', '', '', '白色迅猛龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Raptor. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一只可供骑乘的猛禽。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
