INSERT INTO `locales_spell` VALUES (17453, 'Green Mechanostrider', '', '', '', '绿色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'The terradynamic exo-plotters are conjoined by hydraulic imaging to the equilibrium enhancers...', '', '', '', '地形动力外绘图仪通过液压成像与平衡增强器相连......', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17454, 'Unpainted Mechanostrider', '', '', '', '未涂色的机械陆行鸟', '', '', '', '', '', '', '', '', '', 'A work in progress, waiting for its true colors to be revealed.', '', '', '', '一部正在进行中的作品，等待其真实面目被揭晓。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17455, 'Purple Mechanostrider', '', '', '', '紫色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'A sleek and stylish machine, perfect for those with a taste for the extraordinary.', '', '', '', '一款时尚的机器，非常适合那些追求非凡品味的人。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17456, 'Red & Blue Mechanostrider', '', '', '', '红蓝两色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'A striking combination of fiery red and cool blue, showcasing the power of opposites.', '', '', '', '火红色和冷蓝色的惊人组合，展现了对立的力量。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17457, 'Undead Slayer 75', '', '', '', 'Undead Slayer 75', '', '', '', '', '', '', '', '', '', '+$s1 Attack Power when fighting Undead.', '', '', '', '对亡灵的攻击强度提高$s1点。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17458, 'Fluorescent Green Mechanostrider', '', '', '', '绿色荧光机械陆行鸟', '', '', '', '', '', '', '', '', '', 'The trusted mechanical steed of Engineer Figgles, made by accident trying to make improved models of his mechanical whelps.', '', '', '', '菲格尔斯工程师值得信赖的机械战马，是为了改进他的机械幼崽的模型而偶然制造的。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17459, 'Icy Blue Mechanostrider', '', '', '', '冰蓝色机械陆行鸟', '', '', '', '', '', '', '', '', '', 'This historic piece of gnomish engineering was forced into retirement due to its extremely \"touchy\" gyroscometer.', '', '', '', '这个具有历史意义的侏儒工程由于其极其“敏感”的陀螺仪而被迫退役。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17460, 'Frost Ram', '', '', '', '霜山羊', '', '', '', '', '', '', '', '', '', 'Male rams will often smash their thick skulls against each other for hours to impress a female. In that way, they\'re very similar to dwarves.', '', '', '', '雄性公羊经常会用厚厚的头骨互相撞击几个小时，以给雌性留下深刻印象。从这一点来说，他们与矮人非常相似。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17461, 'Black Ram', '', '', '', '黑山羊', '', '', '', '', '', '', '', '', '', 'I\'ve not seen this breed in ages, but when they\'re ram tough they stick around. - Veron Amberstill.', '', '', '', '我已经很久没见过这个品种了，但当它们很顽强时，它们就会留下来。 - 贝隆·安伯斯蒂尔。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17462, 'Red Skeletal Horse', '', '', '', '红色骸骨军马', '', '', '', '', '', '', '', '', '', 'The Forsaken believe that without a purpose, even beasts of burden suffer in undeath.', '', '', '', '被遗忘者相信，如果没有目标，即使是驮兽也会遭受不死之苦。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17463, 'Blue Skeletal Horse', '', '', '', '蓝色骸骨军马', '', '', '', '', '', '', '', '', '', 'The Forsaken believe that without a purpose, even beasts of burden suffer in undeath.', '', '', '', '被遗忘者相信，如果没有目标，即使是驮兽也会遭受不死之苦。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17464, 'Brown Skeletal Horse', '', '', '', '棕色骸骨军马', '', '', '', '', '', '', '', '', '', 'The Forsaken believe that without a purpose, even beasts of burden suffer in undeath.', '', '', '', '被遗忘者相信，如果没有目标，即使是驮兽也会遭受不死之苦。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (17465, 'Green Skeletal Warhorse', '', '', '', '绿色骸骨战马', '', '', '', '', '', '', '', '', '', 'When fallen heroes are raised into undeath, so too are their horses.', '', '', '', '当阵亡的英雄被复活为不死之身时，他们的马匹也会复活。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
