INSERT INTO `locales_spell` VALUES (17616, 'Corpse Explosion', '', '', '', '尸爆', '', '', '', '', '', '', '', '', '', 'Causes a corpse to explode, inflicting $s1 Shadow damage on enemies near the corpse.', '', '', '', '使一具尸体爆炸，对尸体附近的所有敌人造成$s1点暗影伤害。', '', '', '', '', '', '', '', '', '');
