INSERT INTO `locales_spell` VALUES (17619, 'Alchemists Stone', '', '', '', '炼金石', '', '', '', '', '', '', '', '', '', 'Increases the effects that healing and mana potions have on the wearer by 33%.', '', '', '', '使你在饮用治疗药水和法力药水时获得的效果提高33%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17620, 'Drain Life', '', '', '', '吸取生命', '', '', '', '', '', '', '', '', '', 'Drains $o1 health from an enemy over $d., transferring it to the caster.', '', '', '', '在$d内从敌人身上吸取总计$o1点生命值，并将其转移给施法者。', '', '', '$o1 health leeched over $d.', '', '', '', '在$d内吸取总计$o1点生命值。', '', '');
