INSERT INTO `locales_spell` VALUES (17623, 'Visions of the Past', '', '', '', '往日的幻象', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Allows wielder to see the spirits of Caer Darrow. Only works on Caer Darrow.', '', '', '', '使佩戴者可以看到凯尔达隆的幽灵。只在凯尔达隆有效。', '', '');
INSERT INTO `locales_spell` VALUES (17624, 'Petrification', '', '', '', '石化', '', '', '', '', '', '', '', '', '', 'You turn to stone, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move or cast spells.  You can only have the effect of one flask at a time.', '', '', '', '你进入石头形态，免受一切物理和法术攻击的伤害，持续$d。但是在这段时间里，你无法攻击、移动或施法。你每次只能使用一瓶此类药水。', '', '', 'Immune to all attacks and spells.  Cannot attack, move or use spells.', '', '', '', '对所有攻击和法术免疫。无法攻击、移动或施法。', '', '');
INSERT INTO `locales_spell` VALUES (17625, 'Unholy Aura', '', '', '', '邪恶光环', '', '', '', '', '', '', '', '', '', 'Increases movement speed and life regeneration rate.', '', '', '', '移动速度和生命值回复速度提高。', '', '', 'Increased movement speed and life regeneration.', '', '', '', '移动速度和生命值回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (17626, 'Flask of the Titans', '', '', '', '泰坦合剂', '', '', '', '', '', '', '', '', '', 'Increases the player\'s maximum health by $s1 for $d.  You can only have the effect of one flask at a time.  This effect persists through death.', '', '', '', '使玩家的生命值上限提高$s1点，持续$d。你在同一时间内只能保有一种合剂的效果，这种效果在死亡后仍可继续存在。', '', '', 'Health increased by $s1.', '', '', '', '生命值上限提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (17627, 'Distilled Wisdom', '', '', '', '萃取智慧', '', '', '', '', '', '', '', '', '', 'Increases the player\'s maximum mana by $s1 for $d.  You can only have the effect of one flask at a time.  This effect persists through death.', '', '', '', '使玩家的法力值上限提高$s1点，持续$d。你在同一时间内只能保有一种合剂的效果，这种效果在死亡后仍可继续存在。', '', '', 'Mana increased by $s1.', '', '', '', '法力值上限提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (17628, 'Supreme Power', '', '', '', '至高能量', '', '', '', '', '', '', '', '', '', 'Increases damage done by magical spells and effects by up to $s1 for $d.  You can only have the effect of one flask at a time.  This effect persists through death.', '', '', '', '使法术和魔法效果所造成的伤害提高最多$s1点，持续$d。你在同一时间内只能保有一种合剂的效果，这种效果在死亡后仍可继续存在。', '', '', 'Spell damage increased by up to $s1.', '', '', '', '法术伤害提高最多$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (17629, 'Chromatic Resistance', '', '', '', '多彩抗性', '', '', '', '', '', '', '', '', '', 'Increases your resistance to all schools of magic by $s1 for $d.  You can only have the effect of one flask at a time.  This effect persists through death and stacks with all other resistance spells and items.', '', '', '', '使你对所有魔法的抗性提高$s1点，持续$d。你在同一时间内只能保有一种合剂的效果，但该效果可以和任何提高抗性的法术和物品所提供的效果共存，且在死亡后仍可继续存在。', '', '', 'All magic schools resistance increased by $s1. ', '', '', '', '所有魔法抗性提高$s1点。', '', '');
