INSERT INTO `locales_spell` VALUES (17651, 'Image Projection', '', '', '', '影像投射', '', '', '', '', '', '', '', '', '', 'Summons $17653s1 $lSpectral Projection:Spectral Projections; to fight in the place of the caster, who becomes invisible and invulnerable, though unable to act. After $d., these apparitions sacrifice their lives to heal the caster, who resumes the battle.', '', '', '', '召唤$17653s1个鬼灵幻象为施法者作战，同时施法者将隐形并不会受到任何伤害，但也无法行动。$d之后，这些幻象会牺牲自己为施法者治疗，然后施法者将重返战斗。', '', '', 'Invisible, but unable to act.\nImmune to all attacks and spells.', '', '', '', '隐形但无法行动。\n免疫一切攻击和法术。', '', '');
