INSERT INTO `locales_spell` VALUES (17695, 'Defiling Aura', '', '', '', '污染光环', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with an aura that periodically reduces the Shadow resistance of nearby enemies by $17697s1. The aura lasts until cancelled.', '', '', '', '施法者被光环包围，周期性地使附近敌方的暗影抗性降低$17697s1点。光环一直持续，直到主动取消。', '', '', 'Periodically reducing the Shadow resistance of nearby enemies.', '', '', '', '周期性地使附近敌方的暗影抗性降低。', '', '');
