INSERT INTO `locales_spell` VALUES (17707, 'Panda', '', '', '', '熊猫', '', '', '', '', '', '', '', '', '', 'This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature.', '', '', '', '尽管这只小型熊猫幼崽患有嗜睡症，但它仍受到艾泽拉斯各地冒险家的热烈追捧。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17708, 'Diablo', '', '', '', '迷你破坏神', '', '', '', '', '', '', '', '', '', 'AND THE HEAVENS SHALL TREMBLE, AND MAN SHALL WEEP, AND THE END OF DAYS SHALL--wait, why are you so tall?', '', '', '', '天将颤抖，人将哭泣，末日将——等等，你为什么这么高？', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17709, 'Zergling', '', '', '', '跳跳虫', '', '', '', '', '', '', '', '', '', 'A small, fierce member of the Zerg swarm, the zergling is not to be trifled with. Very dangerous in high numbers.', '', '', '', '小狗是虫族中体型小而凶猛的一员，不容小觑。数量多时非常危险。', '', '', '', '', '', '', '', '', '');
