INSERT INTO `locales_spell` VALUES (17715, 'Consuming Shadows', '', '', '', '吞噬暗影', '', '', '', '', '', '', '', '', '', 'Causes the caster to periodically inflict $17716s1 Shadow damage to all enemies in a selected area, slowing their movement to $17716s2%. Lasts $d.', '', '', '', '使施法者周期性地对指定区域中的敌人造成$17716s1点暗影伤害，并使其移动速度降低到普通速度的$17716s2%。持续$d。', '', '', 'Periodically damaging and slowing enemies in a selected area.', '', '', '', '周期性地对指定区域中的敌人造成暗影伤害，并使其移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (17716, 'Consuming Shadows', '', '', '', '吞噬暗影', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Movement speed slowed by $s2%.', '', '', '', '移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (17727, 'Create Spellstone (Greater)', '', '', '', '制造强效法术石', '', '', '', '', '', '', '', '', '', 'Creates a Greater Spellstone for the caster.  When equipped and used, the Greater Spellstone removes harmful magic effects from the caster and will absorb $17729s2 magic damage for $17729d.  In addition, equipping the Greater Spellstone improves your chance to get a critical strike with spells by $18384s1%.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块强效法术石以供施法者使用，装备并使用后可以移除施法者身上的所有魔法效果，并可在$17729d内吸收总计$17729s2点魔法伤害。另外，装备强效法术石后，你的法术造成致命一击的几率也会提高$18384s1%。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17728, 'Create Spellstone (Major)', '', '', '', '制造特效法术石', '', '', '', '', '', '', '', '', '', 'Creates a Major Spellstone for the caster.  When equipped and used, the Major Spellstone removes harmful magic effects from the caster and will absorb $17730s2 magic damage for $17730d.  In addition, equipping the Major Spellstone improves your chance to get a critical strike with spells by $18384s1%.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块特效法术石以供施法者使用，装备并使用后可以移除施法者身上的所有魔法效果，并可在$17730d内吸收总计$17730s2点魔法伤害。另外，装备特效法术石后，你的法术造成致命一击的几率也会提高$18384s1%。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17729, 'Greater Spellstone', '', '', '', '强效法术石', '', '', '', '', '', '', '', '', '', 'Removes all magic effects from the caster and will absorb $s2 magic damage for $d.', '', '', '', '移除附加在施法者身上的所有魔法效果，在接下来的$d内可吸收最多$s2点魔法伤害。', '', '', 'Absorbs magic damage.', '', '', '', '吸收魔法伤害。', '', '');
INSERT INTO `locales_spell` VALUES (17730, 'Major Spellstone', '', '', '', '特效法术石', '', '', '', '', '', '', '', '', '', 'Removes all magic effects from the caster and will absorb $s2 magic damage for $d.', '', '', '', '移除附加在施法者身上的所有魔法效果，在接下来的$d内可吸收最多$s2点魔法伤害。', '', '', 'Absorbs magic damage.', '', '', '', '吸收魔法伤害。', '', '');
