INSERT INTO `locales_spell` VALUES (17768, 'Wolfshead Helm', '', '', '', '狼头之盔', '', '', '', '', '', '', '', '', '', 'When shapeshifting into Cat form the Druid gains 20 energy, when shapeshifting into Bear form the Druid gains 5 rage.', '', '', '', '变形成为猎豹形态之后，德鲁伊可以获得20点能量值；变形成为熊形态之后，德鲁伊可以获得5点怒气值。', '', '', '', '', '', '', '', '', '');
