INSERT INTO `locales_spell` VALUES (17937, 'Curse of Shadow', '', '', '', '暗影诅咒', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Curses the target for $d, reducing Shadow and Arcane resistances by $s1 and increasing Shadow and Arcane damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.', '', '', '', '对目标施放诅咒，使其暗影和奥术抗性降低$s1点，受到暗影和奥术系攻击时所承受的伤害提高$s2%，效果持续$d。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。', '', '', 'Shadow and Arcane resistances reduced by $s1.  Shadow and Arcane damage taken increased by $s2%.', '', '', '', '暗影和奥术抗性降低$s1点。受到暗影和奥术系攻击时所承受的伤害提高$s2%。', '', '');
