INSERT INTO `locales_spell` VALUES (17962, 'Conflagrate', '', '', '', '燃烧', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Ignites a target that is already afflicted by Immolate, dealing $s1 Fire damage and consuming the Immolate spell.', '', '', '', '点燃一个已经受到献祭效果影响的目标，对其造成$s1点火焰伤害，并吞噬献祭法术的效果。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (17963, 'Sundering Cleave', '', '', '', '破甲顺劈', '', '', '', '', '', '', '', '', '', 'Hacks at the armor of an enemy and its nearby allies, affecting up to $x1 targets. A target\'s armor is reduced by $s1 per Sunder Armor. Can be applied up to 5 times. Lasts $d.', '', '', '', '使一个敌人和它附近盟友的护甲值降低，可最多影响$x1个目标。每次破甲都会令所有目标的护甲降低$s1点，可叠加5次。持续$d。', '', '', 'Reduced armor.', '', '', '', '护甲值降低。', '', '');
