INSERT INTO `locales_spell` VALUES (18288, 'Amplify Curse', '', '', '', '诅咒增幅', '', '', '', '', '', '', '', '', '', 'Increases the effect of your next Curse of Weakness or Curse of Agony by $s1%, or your next Curse of Exhaustion by $s2%.  Lasts $d.', '', '', '', '使你的下一个虚弱诅咒或痛苦诅咒的效果提高$s1%，或使你的下一个疲劳诅咒的效果提高$s2%。', '', '', 'Increases effect for your next Curse of Weakness or Curse of Agony by $s1%, or your next Curse of Exhaustion by $s2%.', '', '', '', '使你的下一个虚弱诅咒或痛苦诅咒的效果提高$s1%，或使你的下一个疲劳诅咒的效果提高$s2%。', '', '');
