INSERT INTO `locales_spell` VALUES (18309, 'Bear Form', '', '', '', '熊形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Shapeshifts into a bear, increasing armor and hit points, as well as allowing the use of various bear abilities. Lasts until cancelled.', '', '', '', '变成一头熊，持续$d。提高护甲和生命值，并可使用多种熊形态下专有的技能。变身效果一直持续，直到被主动取消。', '', '', 'Shapeshifted into bear.\nArmor and hit points increased.', '', '', '', '变形成为熊。\n护甲值和生命值提高。', '', '');
