INSERT INTO `locales_spell` VALUES (18499, 'Berserker Rage', '', '', '', '狂暴之怒', '', '', '', '', '', '', '', '', '', 'The warrior enters a berserker rage, becoming immune to Fear and Incapacitate effects and generating extra rage when taking damage.  Lasts $d.', '', '', '', '战士进入狂暴状态，对恐惧和击昏效果免疫，在受到伤害时产生额外的怒气值，持续$d。', '', '', 'Immune to Fear and Incapacitate effects.  Generating extra rage when taking damage.', '', '', '', '对恐惧和击昏效果免疫，在受到伤害时产生额外的怒气值。', '', '');
INSERT INTO `locales_spell` VALUES (18500, 'Wing Buffet', '', '', '', '龙翼攻击', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 damage to enemies in a cone in front of the caster, knocking them back.', '', '', '', '对施法者面前一个锥形区域中的敌人造成$s2点伤害，并击退它们。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (18501, 'Enrage', '', '', '', '狂怒', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by the caster by $s1 and speeds its attacks by $s2% for $d.', '', '', '', '使施法者对敌人造成的物理伤害提高$s1点，攻击速度提高$s2%，持续$d。', '', '', 'Physical damage dealt is increased by $s1.\nAttack speed increased by $s2%.', '', '', '', '对敌人造成的物理伤害提高$s1点。\n攻击速度提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (18502, 'Curse of Hakkar', '', '', '', '哈卡的诅咒', '', '', '', '', '', '', '', '', '', 'Drains $s1 mana from an enemy every $t1 sec., transferring it to the caster over $d.', '', '', '', '每$t1秒从敌人身上吸取$s1点法力值，将它转移给施法者。持续$d。', '', '', '$s1 mana leeched every $t1 sec.', '', '', '', '每$t1秒吸收$s1点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (18503, 'Hex', '', '', '', '妖术', '', '', '', '', '', '', '', '', '', 'Transforms an enemy into a chicken, rendering it unable to attack or cast spells for $d.', '', '', '', '将敌人变成一只小鸡，使其无法攻击或施法，持续$d。', '', '', 'Hexed.', '', '', '', '被妖术变形。', '', '');
