INSERT INTO `locales_spell` VALUES (18543, 'Flame Lash', '', '', '', '烈焰鞭笞', '', '', '', '', '', '', '', '', '', 'Burns an enemy, then inflicts additional Fire damage every $t1 sec. for $d.', '', '', '', '灼烧敌人，并对其每$t1秒造成一次额外火焰伤害，持续$d。', '', '', 'Fire damage inflicted every $t1 sec.', '', '', '', '每$t1秒受到一次火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (18544, 'Force of Will', '', '', '', '意志之力', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases your spell damage by $s2% and the critical strike chance of your offensive spells by $s1%.', '', '', '', '使你的法术伤害提高$s1%，攻击性法术的致命一击几率提高$s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (18545, 'Scorpid Sting', '', '', '', '毒蝎钉刺', '', '', '', '', '', '', '', '', '', 'Stings an enemy, reducing its Strength and Agility by $s1 for $d.', '', '', '', '钉刺敌人，使其力量和敏捷降低$s1点，持续$d。', '', '', 'Strength and Agility reduced by $s1.', '', '', '', '力量和敏捷降低$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (18546, 'Overdrive', '', '', '', '过载', '', '', '', '', '', '', '', '', '', 'Immobilizes the caster, but increases its attack speed by $s2% for $d.', '', '', '', '使施法者不能移动，但使其攻击速度提高$s2%，持续$d。', '', '', 'Immobilized.\nAttack speed increased by $s2%.', '', '', '', '不能移动。\n攻击速度提高$s2%。', '', '');
