INSERT INTO `locales_spell` VALUES (18560, 'Mooncloth', '', '', '', '月布', '', '', '', '', '', '', '', '', '', 'The purification of tainted Felcloth into Mooncloth can only be done at a moonwell, and only ocassionally will the waters permit themselves to be used in such a way.', '', '', '', '将被玷污的恶魔布净化为月布的过程只能在月亮井中进行。', '', '', '', '', '', '', '', '', '');
