INSERT INTO `locales_spell` VALUES (18562, 'Swiftmend', '', '', '', '迅捷治愈', '', '', '', '', '', '', '', '', '', 'Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to 12 sec. of Rejuvenation or 18 sec. of Regrowth.', '', '', '', '吞噬友方目标身上的一个回春术或愈合的持续效果，并立即为其回复生命值，其数值等于12秒的回春效果或18秒的愈合效果。', '', '', '', '', '', '', '', '', '');
