INSERT INTO `locales_spell` VALUES (18633, 'Weakening Disease', '', '', '', '虚弱疾病', '', '', '', '', '', '', '', '', '', 'Deals $s1 Shadow damage every $t1 sec for $d and lowers their Strength for the duration of the disease.', '', '', '', '每$t1秒对敌人造成$s1点暗影伤害，并在疾病生效期间降低它们的力量值，持续$d。', '', '', 'Diseased and weakened.', '', '', '', '感染疾病，力量降低。', '', '');
INSERT INTO `locales_spell` VALUES (18634, 'Target Dummy - Event 001', '', '', '', 'Target Dummy - Event 001', '', '', '', '', '', '', '', '', '', 'Drops a target dummy on the ground that attracts nearby monsters to attack it.  Lasts for 3 min.', '', '', '', '在地上放置一个假人，吸引附近的怪物攻击它。持续3分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (18647, 'Banish', '', '', '', '放逐术', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Banishes the enemy target, preventing all action but making it invulnerable for up to $d.  Only one target can be banished at a time.  Only works on Demons and Elementals.', '', '', '', '放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续$d。每个术士在同一时间内只能放逐一个目标，只能对恶魔和元素生物使用。', '', '', 'Invulnerable, but unable to act.', '', '', '', '不会受到任何伤害，但也无法做出任何动作。', '', '');
