INSERT INTO `locales_spell` VALUES (18976, 'Self Resurrection', '', '', '', '自我复活', '', '', '', '', '', '', '', '', '', 'A Soulstone is used automatically upon death, restoring its owner to life at $s1% health and mana.', '', '', '', '玩家被杀死之后，灵魂石会自动令其复活，并恢复$s1%的生命值和法力值。', '', '', '', '', '', '', '', '', '');
