INSERT INTO `locales_spell` VALUES (18989, 'Gray Kodo', '', '', '', '灰色科多兽', '', '', '', '', '', '', '', '', '', 'The kodo is the backbone of our people. Wherever the Horde goes - in trade, settlement, or war - there you will find the mighty kodo.', '', '', '', '科多兽是我们人民的支柱。无论部落走到哪里——贸易、定居点或战争——你都会发现强大的科多兽。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (18990, 'Brown Kodo', '', '', '', '棕色科多兽', '', '', '', '', '', '', '', '', '', 'The kodo is the backbone of our people. Wherever the Horde goes - in trade, settlement, or war - there you will find the mighty kodo.', '', '', '', '科多兽是我们人民的支柱。无论部落走到哪里——贸易、定居点或战争——你都会发现强大的科多兽。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (18991, 'Green Kodo', '', '', '', '绿色科多兽', '', '', '', '', '', '', '', '', '', 'An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through Desolace.', '', '', '', '这只科多兽是科多兽群中的头号成员，是席卷凄凉之地的强大生物的典型代表。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (18992, 'Teal Kodo', '', '', '', '蓝色科多兽', '', '', '', '', '', '', '', '', '', 'The kodo is the backbone of our people. Wherever the Horde goes - in trade, settlement, or war - there you will find the mighty kodo.', '', '', '', '科多兽是我们人民的支柱。无论部落走到哪里——贸易、定居点或战争——你都会发现强大的科多兽。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
