INSERT INTO `locales_spell` VALUES (19028, 'Soul Link', '', '', '', '灵魂链接', '', '', '', '', '', '', '', '', '', 'When active, $18814s1% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, or Felhunter, or enslaved demon instead.  In addition, both the demon and master will inflict $25228s1% more damage.  Lasts as long as the demon is active and controlled.', '', '', '', '激活之后，施法者所承受的伤害有$18814s1%被$g他:她;的恶魔分担。另外，恶魔和其主人的任何攻击所造成的伤害都提高$25228s1%。只要恶魔保持激活状态，该效果就一直持续。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19029, 'Create Coagulated Rot', '', '', '', '制造凝固腐质', '', '', '', '', '', '', '', '', '', 'Combine 7 pieces of Living Rot inside the mortar and grind away with the pestle. Leave standing to allow coagulation.', '', '', '', '将7块生命腐质装入臼中并研磨，然后等待其凝固。', '', '', '', '', '', '', '', '', '');
