INSERT INTO `locales_spell` VALUES (19128, 'Knockdown', '', '', '', '击倒', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 damage to an enemy and its nearest allies, stunning them for $d. Affects up to $x1 targets.', '', '', '', '对目标和它身边的敌人造成$s2点伤害，并使它们昏迷$d。最多可影响$x1个目标。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (19129, 'Massive Tremor', '', '', '', '剧烈震颤', '', '', '', '', '', '', '', '', '', 'Causes a massive ground tremor, inflicting $s1 damage to nearby enemies and interrupts any spell being cast for $d..', '', '', '', '制造一场大地震，对附近的敌人造成$s1点伤害，并打断所有法术的施放，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19130, 'Revenge', '', '', '', '复仇', '', '', '', '', '', '', '', '', '', 'Instantly counterattack an enemy for $s1 damage. Revenge must follow a block, dodge, or parry.', '', '', '', '立即反击敌人，对其造成$s1点伤害。复仇只有在成功格挡、躲闪或招架之后才能使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19131, 'Shield Charge', '', '', '', '盾牌冲锋', '', '', '', '', '', '', '', '', '', 'Charges an enemy, knocking it back and inflicting normal damage plus $s3.', '', '', '', '对敌人发起冲锋，将其击退并造成普通伤害外加$s3点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19132, 'Mighty Blow', '', '', '', '全力一击', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to an enemy, knocking it back.', '', '', '', '对敌人造成普通武器伤害再加上$s1点额外伤害，并将其击退。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19133, 'Frost Shock', '', '', '', '冰霜震击', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to an enemy and reduces its movement speed for $d.', '', '', '', '对敌人造成冰霜伤害，并使其移动速度降低，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (19134, 'Intimidating Shout', '', '', '', '破胆怒吼', '', '', '', '', '', '', '', '', '', 'Shouts at an enemy, paralyzing it with terror for $d. and causing all other nearby enemies to flee in fear.', '', '', '', '向目标发出怒吼，使其因恐惧而被麻痹，并使附近的其它敌人逃跑，持续$d。', '', '', 'Intimidated.', '', '', '', '被恐吓。', '', '');
INSERT INTO `locales_spell` VALUES (19135, 'Avatar', '', '', '', '天神下凡', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by the caster by $s1% and enhances its armor by $s2% for $d.', '', '', '', '使施法者对敌人造成的物理伤害提高$s1%，护甲值提高$s2%，持续$d。', '', '', 'Physical damage dealt is increased by $s1%.\nArmor increased by $s2%.', '', '', '', '对敌人造成的物理伤害提高$s1%。\n护甲值提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (19136, 'Stormbolt', '', '', '', '风暴之锤', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 damage to an enemy, stunning it for $d.', '', '', '', '对一个敌人造成$s1点伤害，并使其昏迷。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (19137, 'Slow', '', '', '', '减速术', '', '', '', '', '', '', '', '', '', 'Increases the time between nearby enemies\' attacks by $s1% and slows their movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
