INSERT INTO `locales_spell` VALUES (19261, 'Touch of Weakness', '', '', '', '虚弱之触', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'The next melee attack against the caster will cause $19249s1 Shadow damage and reduce the damage caused by the attacker by $19249s2 for $19249d.', '', '', '', '对施法者进行的下一次近战攻击会令攻击者承受$19249s1点暗影伤害，并使其所能造成的伤害减少$19249s2点，持续$19249d。', '', '', 'The next damaging melee attack against you will damage and weaken the target.', '', '', '', '下一次对你造成伤害的近战攻击可以削弱攻击者。', '', '');
INSERT INTO `locales_spell` VALUES (19262, 'Touch of Weakness', '', '', '', '虚弱之触', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'The next melee attack against the caster will cause $19251s1 Shadow damage and reduce the damage caused by the attacker by $19251s2 for $19251d.', '', '', '', '对施法者进行的下一次近战攻击会令攻击者承受$19251s1点暗影伤害，并使其所能造成的伤害减少$19251s2点，持续$19251d。', '', '', 'The next damaging melee attack against you will damage and weaken the target.', '', '', '', '下一次对你造成伤害的近战攻击可以削弱攻击者。', '', '');
