INSERT INTO `locales_spell` VALUES (19306, 'Counterattack', '', '', '', '反击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A strike that becomes active after parrying an opponent\'s attack.  This attack deals $s1 damage and immobilizes the target for $d.  Counterattack cannot be blocked, dodged, or parried.', '', '', '', '在招架敌人的攻击之后可以使用的技能，对敌人造成$s1点伤害，并使其无法行动，持续$d。反击无法被格挡、躲闪或招架。', '', '', 'Immobile.', '', '', '', '无法行动。', '', '');
INSERT INTO `locales_spell` VALUES (19307, 'Crystal of Zin-Malor', '', '', '', '辛玛洛水晶', '', '', '', '', '', '', '', '', '', 'Deals damage and drains $s1 mana every second if you are not worthy.', '', '', '', '如果你没有价值，则每秒吸取$s1点法力值并造成伤害。', '', '', 'Periodic health and mana loss.', '', '', '', '周期性地损失生命值和法力值。', '', '');
INSERT INTO `locales_spell` VALUES (19308, 'Shadowguard', '', '', '', '暗影守卫', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28378s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.', '', '', '', '施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到$28378s1点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用$n次，持续$d。', '', '', 'Causes $s1 Shadow damage to attacker on hit.  This damage causes no threat.  $n charges.', '', '', '', '在被击中后对攻击者造成$s1点暗影伤害，这种伤害不会造成威胁值。可使用$n次。', '', '');
