INSERT INTO `locales_spell` VALUES (19505, 'Devour Magic', '', '', '', '吞噬魔法', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Purges $s1 harmful magic $leffect:effects; from a friend or $s1 beneficial magic $leffect:effects; from an enemy.  If an effect is devoured, the Felhunter will be healed for $19658s1.', '', '', '', '从一个友方目标身上消除$s1个有害魔法效果，或者从一个敌方目标身上消除$s1个有益魔法效果。每吞噬一个魔法效果，地狱猎犬就可回复$19658s1点生命值。', '', '', '', '', '', '', '', '', '');
