INSERT INTO `locales_spell` VALUES (19574, 'Bestial Wrath', '', '', '', '狂野怒火', '', '', '', '', '', '', '', '', '', 'Send your pet into a rage causing $s2% additional damage for $d.  While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.', '', '', '', '使宠物进入疯狂状态，对目标造成的伤害提高$s2%，持续$d。在这种状态下，宠物不会有任何恐惧或怜悯，也无法停止下来，除非被杀死。', '', '', 'Enraged.', '', '', '', '狂怒。', '', '');
INSERT INTO `locales_spell` VALUES (19575, 'Improved Revive Pet', '', '', '', '强化复活宠物', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Revive Pet\'s casting time is reduced by $/1000;s1 sec, mana cost is reduced by $s2%, and increases the health your pet returns with by an additional $s3%.', '', '', '', '使你的复活宠物法术的施法时间减少$/1000;s1秒，法力值消耗降低$s2%，宠物复活后的生命值提高$s3%。', '', '', '', '', '', '', '', '', '');
