INSERT INTO `locales_spell` VALUES (19644, 'Strike', '', '', '', '打击', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to an enemy.', '', '', '', '对敌人造成普通武器伤害再加上$s1点额外伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19645, 'Anti-Magic Shield', '', '', '', '反魔法盾', '', '', '', '', '', '', '', '', '', 'Creates an anti-magic shell around the caster, giving it magic immunity for $d.', '', '', '', '反魔法的护罩包围施法者，使其对魔法免疫，持续$d。', '', '', 'Immune to magic.', '', '', '', '免疫魔法。', '', '');
