INSERT INTO `locales_spell` VALUES (19647, 'Spell Lock', '', '', '', '法术封锁', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Silences the enemy for $24259d.  If used on a casting target, it will counter the enemy\'s spellcast, preventing any spell from that school of magic from being cast for $d.', '', '', '', '使敌人沉默$24259d。如果目标正在施法，则反制该目标的施法意图，使其在$d内无法施放任何与该法术属于同一类别的法术。', '', '', '', '', '', '', '', '', '');
