INSERT INTO `locales_spell` VALUES (19740, 'Blessing of Might', '', '', '', '力量祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Places a Blessing on the friendly target, increasing melee attack power by $s1 for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其近战攻击强度提高$s1，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Increases melee attack power by $s1.', '', '', '', '近战攻击强度提高$s1点。', '', '');
