INSERT INTO `locales_spell` VALUES (19742, 'Blessing of Wisdom', '', '', '', '智慧祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Places a Blessing on the friendly target, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，每$t1秒回复$s1点法力值，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Restores $s1 mana every $t1 seconds.', '', '', '', '每$t1秒恢复$s1点法力值。', '', '');
