INSERT INTO `locales_spell` VALUES (19748, 'Charismatic Aura', '', '', '', '魅力光环', '', '', '', '', '', '', '', '', '', 'Decreases range at which monsters will attack party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使半径$a1码范围内的怪物攻击队友的几率降低。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Decreases range at which monsters will attack.', '', '', '', '降低敌人的警戒范围。', '', '');
