INSERT INTO `locales_spell` VALUES (19752, 'Divine Intervention', '', '', '', '神圣干涉', '', '', '', '', '', '', '', '', '', 'The paladin sacrifices $ghimself:herself; to remove the targeted party member from harms way.  Enemies will stop attacking the protected party member, who will be immune to all harmful attacks but cannot take any action for $19753d.', '', '', '', '圣骑士牺牲自己，保护目标队友免受任何伤害。敌人会停止攻击被保护的队友，但该队友在$19753d内无法进行任何行动。', '', '', 'Complete immunity but unable to move.', '', '', '', '完全免疫伤害，但无法行动。', '', '');
