INSERT INTO `locales_spell` VALUES (19776, 'Shadow Word: Pain', '', '', '', '暗言术：痛', '', '', '', '', '', '', '', '', '', 'Utters a word of darkness, inflicting Shadow damage to an enemy every $t1 sec. for $d.', '', '', '', '黑暗的咒语，每$t1秒对敌人造成一次暗影伤害，持续$d。', '', '', 'Shadow damage inflicted every $t1 sec.', '', '', '', '每$t1秒受到一次暗影伤害。', '', '');
