INSERT INTO `locales_spell` VALUES (19779, 'Inspire', '', '', '', '灵感', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by an ally by $s2% and speeds its attacks by $s1% for $d.', '', '', '', '使一个盟友对敌人造成的物理伤害提高$s2%，攻击速度提高$s1%，持续$d。', '', '', 'Attack speed increased by $s1%.\nPhysical damage dealt is increased by $s2%.', '', '', '', '对敌人造成的物理伤害提高$s2%。\n攻击速度提高$s1%。', '', '');
