INSERT INTO `locales_spell` VALUES (19875, 'Shield Discipline', '', '', '', 'zzOLDShield Discipline', '', '', '', '', '', '', '', '', '', 'A passive ability that grants a $s1% chance to reflect spells while a shield is equipped.  In addition, increases the damage done by your Shield Bash ability by $s2% and the threat it causes by $s3%.', '', '', '', '被动技能，使你有$s1%的几率在装备了盾牌的情况下反射法术。另外还使你的盾击技能所造成的伤害提高$s2%，威胁值增加$s3%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (19876, 'Shadow Resistance Aura', '', '', '', '暗影抗性光环', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives $s1 additional Shadow resistance to all party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使附近半径$a1码范围内的所有队友的暗影抗性提高$s1点。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Increases Shadow resistance by $s1.', '', '', '', '暗影抗性提高$s1点。', '', '');
