INSERT INTO `locales_spell` VALUES (19976, 'Seal of Light', '', '', '', '光明圣印', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Places a Seal on the friendly target, increasing the effects of Holy Light spells used on the target by $s1 and the effect Flash of Light spells used on the target by $s2.  Lasts $d.  Players may only have one Seal on them per Paladin at any one time.', '', '', '', '为友方目标施加圣印，使对目标施放的圣光术效果提高$s1点，对目标施放的圣光闪现效果提高$s2点。持续$d。每个圣骑士在同一时间内只能给目标施加一个圣印，且同类型的圣印在同一个目标身上只能存在一个。', '', '', 'Receives $s1 extra healing from Holy Light spells, and $s2 extra healing from Flash of Light spells.', '', '', '', '从圣光术中获得$s1点额外治疗，从圣光闪现中获得$s2点额外治疗。', '', '');
INSERT INTO `locales_spell` VALUES (19977, 'Blessing of Light', '', '', '', '光明祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Places a Blessing on the friendly target, increasing the effects of Holy Light spells used on the target by up to $s1 and the effect Flash of Light spells used on the target by up to $s2.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使圣光术为其恢复的生命值提高$s1点，圣光闪现为其恢复的生命值提高$s2点，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Receives up to $s1 extra healing from Holy Light spells, and up to $s2 extra healing from Flash of Light spells.', '', '', '', '因圣光术恢复的生命值提高$s1点，因圣光闪现恢复的生命值提高$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (19978, 'Blessing of Light', '', '', '', '光明祝福', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Places a Blessing on the friendly target, increasing the effects of Holy Light spells used on the target by up to $s1 and the effect Flash of Light spells used on the target by up to $s2.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使圣光术为其恢复的生命值提高$s1点，圣光闪现为其恢复的生命值提高$s2点，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Receives up to $s1 extra healing from Holy Light spells, and up to $s2 extra healing from Flash of Light spells.', '', '', '', '因圣光术恢复的生命值提高$s1点，因圣光闪现恢复的生命值提高$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (19979, 'Blessing of Light', '', '', '', '光明祝福', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Places a Blessing on the friendly target, increasing the effects of Holy Light spells used on the target by up to $s1 and the effect Flash of Light spells used on the target by up to $s2.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使圣光术为其恢复的生命值提高$s1点，圣光闪现为其恢复的生命值提高$s2点，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Receives up to $s1 extra healing from Holy Light spells, and up to $s2 extra healing from Flash of Light spells.', '', '', '', '因圣光术恢复的生命值提高$s1点，因圣光闪现恢复的生命值提高$s2点。', '', '');
