INSERT INTO `locales_spell` VALUES (20018, 'Create Healthstone (Major)', '', '', '', '制造特效治疗石', '', '', '', '', '', '', '', '', '', 'Creates a Major Healthstone that can be used to instantly restore $11732s1 health.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块特效治疗石，使用后可以立刻恢复$11732s1点生命值。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20019, 'Engulfing Flames', '', '', '', '吞噬之焰', '', '', '', '', '', '', '', '', '', 'Sets an enemy aflame, inflicting $o1 Fire damage over $d. and sending it into a state of panic. While the target is affected, the flames periodically scorch its nearby allies for $20021s1 damage as well.', '', '', '', '使一个敌人着火，在$d内造成总计$o1点火焰伤害，并使其进入恐慌状态。在这段时间里，火焰会周期性地灼烧该目标身边的盟友，对它们造成$20021s1点伤害。', '', '', 'You\'re burning!', '', '', '', '你在燃烧！', '', '');
INSERT INTO `locales_spell` VALUES (20020, 'Enchant Boots - Greater Stamina', '', '', '', '附魔靴子 - 强效耐力', '', '', '', '', '', '', '', '', '', 'Permanently enchant boots to give +7 Stamina.', '', '', '', '永久性地为一双靴子附魔，使它们获得耐力+7的效果。', '', '', '', '', '', '', '', '', '');
