INSERT INTO `locales_spell` VALUES (20022, 'Create Soulstone', '', '', '', '制造灵魂石', '', '', '', '', '', '', '', '', '', 'Creates a Soulstone that is automatically used upon death, restoring its owner to life at $3026s1% health and mana.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一个灵魂石，在死亡时自动生效，使其复生，并恢复$3026s1%生命值和魔法值。\n\n如果注销超过15分钟，魔法物品将消失。', '', '', '', '', '', '', '', '', '');
