INSERT INTO `locales_spell` VALUES (20029, 'Enchant Weapon - Icy Chill', '', '', '', '附魔武器 - 冰寒', '', '', '', '', '', '', '', '', '', 'Permanently enchant a melee weapon to often chill the target reducing their movement and attack speed.', '', '', '', '永久性地为一把近战武器附魔，使它能释放冰寒，使目标的移动和攻击速度减慢。', '', '', '', '', '', '', '', '', '');
