INSERT INTO `locales_spell` VALUES (20148, 'Shield Specialization', '', '', '', '盾牌专精', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the amount of damage absorbed by your shield by $s1% and has a $h% chance to restore 2% of maximum mana when a block occurs. This effect cannot occur more than once every second.', '', '', '', '使你的盾牌所能吸收的伤害提高$s1%。并有$h%的几率在发生格挡时恢复2%的法力值。这种效果每秒生效不超过一次。', '', '', '', '', '', '', '', '', '');
