INSERT INTO `locales_spell` VALUES (20154, 'Seal of Righteousness', '', '', '', '正义圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fills the Paladin with holy spirit for $d, granting each melee attack an additional $/87;s1 to $/25;s1 Holy damage.  Slower weapons cause more Holy damage per swing.  Only one Seal can be active on the Paladin at any one time.', '', '', '', '神圣的灵魂充满圣骑士的体内，持续$d，令其近战攻击有一定几率造成$/87;s1到$/25;s1点额外的神圣伤害。攻击速度越慢的武器每击造成的伤害越高。圣骑士在同一时间内只能激活一种圣印。', '', '', 'Melee attacks cause an additional $/87;20187s3 to $/25;20187s3 Holy damage.', '', '', '', '近战攻击有一定几率造成$/87;20187s3到$/25;20187s3点额外的神圣伤害。', '', '');
