INSERT INTO `locales_spell` VALUES (20162, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 10 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有10倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
INSERT INTO `locales_spell` VALUES (20163, 'Seal of Fury', '', '', '', 'zzOLDSeal of Fury', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fills the Paladin with divine fury for $d, allowing melee attacks to cause additional threat.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20183d, causing Holy damage spells cast on that enemy to generate additional threat.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣的愤怒充满圣骑士的体内，持续$d，令其在攻击时对敌人造成更多的威胁值。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20183d。神圣系的伤害性法术会对被审判的目标造成更高的威胁值。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks cause additional threat.', '', '', '', '近战攻击造成额外威胁值。', '', '');
INSERT INTO `locales_spell` VALUES (20164, 'Seal of Justice', '', '', '', '公正圣印', '', '', '', '', '', '', '', '', '', 'Fills the Paladin with the spirit of justice for $d, giving each melee attack a chance to stun for $20170d.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20184d, preventing them from fleeing.  Your melee strikes will refresh the spell\'s duration.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '公正之魂充满圣骑士的体内，持续$d，使其每次近战攻击都有一定几率令目标昏迷$20170d。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20184d。被审判的目标无法逃跑。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks have a chance to stun for $20170d.', '', '', '', '近战攻击有一定几率令目标昏迷$20170d。', '', '');
INSERT INTO `locales_spell` VALUES (20165, 'Seal of Light', '', '', '', '光明圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20167s1.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20185d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20267s1.  Your melee strikes will refresh the spell\'s duration.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣之光充满圣骑士的体内，持续$d，使其每次近战攻击都有一定几率回复$20167s1点生命值。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20185d。使用近战武器击中被审判的目标就有一定几率令攻击者回复$20267s1点生命值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks have a chance to heal you for $20167s1.', '', '', '', '近战攻击有一定几率为你回复$20167s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (20166, 'Seal of Wisdom', '', '', '', '智慧圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fills the Paladin with divine wisdom for $d, giving each melee attack a chance to restore $20168s1 of the Paladin\'s mana.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20186d, granting attacks and spells used against the judged enemy a chance to restore $20268s1 mana to the attacker.  Your melee strikes will refresh the spell\'s duration.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣的智慧充满圣骑士的体内，持续$d，令其每次使用近战武器击中敌人时都有一定几率恢复$20168s1点法力值。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20186d。如果被审判的目标受到了武器和法术攻击，攻击者就有一定几率恢复$20268s1点法力值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks have a chance to restore $20168s1 mana.', '', '', '', '近战攻击有一定几率回复$20168s1点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (20167, 'Seal of Light', '', '', '', '光明圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20168, 'Seal of Wisdom', '', '', '', '智慧圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20169, 'Holy Shield', '', '', '', 'zzOLDHoly Shield', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases chance to block by $s1% for $d, and deals $s2 Holy damage for each attack blocked while active.  Each block expends a charge.  $n charges.', '', '', '', '使你的格挡几率提高$s1%，持续$d。在此期间每次成功格挡都会对攻击者造成$s2点神圣伤害，每次成功格挡会消耗掉一次格挡机会，最多可格挡$n次。', '', '', 'Block chance increased by $s1%.  $s2 Holy damage dealt to attacker when blocked.  $n charges.', '', '', '', '格挡几率提高$s1%。格挡成功后对攻击者造成$s2点神圣伤害。可使用$n次。', '', '');
