INSERT INTO `locales_spell` VALUES (20213, 'Illumination', '', '', '', '启发', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'After getting a critical effect from your Flash of Light, Holy Light, or Holy Shock heal spell, gives you a $h% chance to gain Mana equal to the base cost of the spell.', '', '', '', '在你的圣光闪现、圣光术或神圣震击造成极效治疗或致命一击效果后，使你有$h%的几率回复施法所消耗的法力值。', '', '', '', '', '', '', '', '', '');
