INSERT INTO `locales_spell` VALUES (20216, 'Divine Favor', '', '', '', '神恩术', '', '', '', '', '', '', '', '', '', 'When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a $s1% critical effect chance.', '', '', '', '激活之后，使你的下一个圣光闪现、圣光术或神圣震击有$s1%的几率造成极效治疗效果。', '', '', 'Critical effect chance of next Flash of Light, Holy Light, or Holy Shock spell increased by $s1%.', '', '', '', '你的下一个圣光闪现、圣光术或神圣震击造成极效治疗效果的几率提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (20217, 'Blessing of Kings', '', '', '', '王者祝福', '', '', '', '', '', '', '', '', '', 'Places a Blessing on the friendly target, increasing total stats by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其所有属性提高$s1%，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Increases stats by $s1%.', '', '', '', '所有属性提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (20218, 'Sanctity Aura', '', '', '', '圣洁光环', '', '', '', '', '', '', '', '', '', 'Increases Holy damage done by party members within $a1 yards by $s1%.  Players may only have one Aura on them per Paladin at any one time.', '', '', '', '使半径$a1码范围内的队友的神圣系攻击对敌人造成的伤害提高$s1%。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。', '', '', 'Increases Holy damage done by $s1%.', '', '', '', '神圣伤害提高$s1%。', '', '');
