INSERT INTO `locales_spell` VALUES (20229, 'Blast Wave', '', '', '', '冲击波', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to nearby enemies and reduces their movement speed by $s2% for $d.', '', '', '', '对附近的敌人造成$s1点火焰伤害，并使它们的移动速度降低$s2%，持续$d。', '', '', 'Movement speed reduced by $s2%.', '', '', '', '移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (20230, 'Retaliation', '', '', '', '反击风暴', '', '', '', '', '', '', '', '', '', 'Instantly counterattack any enemy that strikes you in melee for $d.  Melee attacks made from behind cannot be counterattacked.  A maximum of $n attacks will cause retaliation.', '', '', '', '在任何敌人以近战武器击中你之后可以立刻对其进行反击，持续$d。从你背后发动的近战攻击无法被反击。最多可反击$n次攻击。', '', '', 'Counterattacking all melee attacks.', '', '', '', '反击所有近战伤害。', '', '');
