INSERT INTO `locales_spell` VALUES (20294, 'Immolate', '', '', '', '献祭', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 Fire damage to an enemy and scorches it for an additional $s1 damage every $t1 sec. for $d.', '', '', '', '对敌人造成$s2点火焰伤害，并在接下来的$d内每$t1秒造成$s1点额外伤害。', '', '', '$s1 Fire damage inflicted every $t1 sec.', '', '', '', '每$t1秒$s1点火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20295, 'Lightning Bolt', '', '', '', '闪电箭', '', '', '', '', '', '', '', '', '', 'Blasts an enemy with lightning, inflicting Nature damage.', '', '', '', '用闪电攻击目标，对其造成自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20296, 'Flamestrike', '', '', '', '烈焰风暴', '', '', '', '', '', '', '', '', '', 'Calls down a pillar of flame, burning all enemies in a selected area and inflicting additional damage every $t2 sec. for $d.', '', '', '', '召唤一根火柱，灼烧指定区域内的所有敌人，并对它们每$t2秒造成一次额外伤害，持续$d。', '', '', 'Fire damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到一次火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20297, 'Frostbolt', '', '', '', '寒冰箭', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to an enemy and reduces its movement speed for $d.', '', '', '', '对敌人造成冰霜伤害，并使其移动速度降低，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (20298, 'Shadow Bolt', '', '', '', '暗影箭', '', '', '', '', '', '', '', '', '', 'Hurls a bolt of dark magic at an enemy, inflicting Shadow damage.', '', '', '', '向目标射出一支暗影箭，对其造成暗影伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20299, 'Forked Lightning', '', '', '', '叉状闪电', '', '', '', '', '', '', '', '', '', 'Inflicts Nature damage to enemies in a cone in front of the caster.', '', '', '', '对施法者面前一个锥形区域中的敌人造成自然伤害。', '', '', '', '', '', '', '', '', '');
