INSERT INTO `locales_spell` VALUES (20305, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 15 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有15倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
INSERT INTO `locales_spell` VALUES (20306, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 20 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有20倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
INSERT INTO `locales_spell` VALUES (20307, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 25 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有25倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
INSERT INTO `locales_spell` VALUES (20308, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 6', '', '', '', '等级 6', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 30 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有30倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
INSERT INTO `locales_spell` VALUES (20309, 'Seal of the Crusader', '', '', '', 'zzOLDSeal of the Crusader', '', '', 'Rank 6', '', '', '', '等级 6', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20304d, increasing Holy damage taken by up to $20304s1.  Only one Judgement per Paladin can be active at any one time.', '', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\\\'s energy will judge an enemy for $20304d, increasing Holy damage taken by up to $20304s1.  Only one Judgement per Paladin can be active at any one time.', '', '', 'Attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', 'Attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '');
