INSERT INTO `locales_spell` VALUES (20344, 'Judgement of Light', '', '', '', '圣光审判', '', '', 'Rank 2', '', '', '', '等级 2', '', '', '', '', '', '', '', '', '', 'Melee attacks made against you have a chance of causing the attacker to be healed for $20341s1.', '', '', '', '使用近战武器击中你之后，攻击者有一定几率恢复$20341s1点生命值。', '', '');
