INSERT INTO `locales_spell` VALUES (20347, 'Seal of Light', '', '', '', '光明圣印', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20333s1.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20344d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20341s1.  Your melee strikes will refresh the spell\'s duration.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣之光充满圣骑士的体内，持续$d，使其每次近战攻击都有一定几率回复$20333s1点生命值。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20344d。使用近战武器击中被审判的目标就有一定几率令攻击者回复$20341s1点生命值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks have a chance to heal you for $20333s1.', '', '', '', '近战攻击有一定几率为你回复$20333s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (20348, 'Seal of Light', '', '', '', '光明圣印', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20334s1.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy will judge an enemy for $20345d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20342s1.  Your melee strikes will refresh the spell\'s duration.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣之光充满圣骑士的体内，持续$d，使其每次近战攻击都有一定几率回复$20334s1点生命值。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20345d。使用近战武器击中被审判的目标就有一定几率令攻击者回复$20342s1点生命值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks have a chance to heal you for $20334s1.', '', '', '', '近战攻击有一定几率为你回复$20334s1点生命值。', '', '');
