INSERT INTO `locales_spell` VALUES (20419, 'Seal of Fury', '', '', '', 'zzOLDSeal of Fury', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Fills the Paladin with divine fury for $d, allowing melee attacks to cause additional threat.  Only one Seal can be active on the Paladin at any one time.  More effective than Seal of Fury (Rank 1).\n\nUnleashing this Seal\'s energy will judge an enemy for $20411d, causing Holy damage spells cast on that enemy to generate additional threat.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣的愤怒充满圣骑士的体内，持续$d，令其在攻击时对敌人造成更多的威胁值。圣骑士在同一时间内只能激活一种圣印。比愤怒圣印（等级 1）更有效。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20411d。神圣系的伤害性法术会对被审判的目标造成更高的威胁值。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks cause additional threat.', '', '', '', '近战攻击造成额外威胁值。', '', '');
INSERT INTO `locales_spell` VALUES (20420, 'Fireball', '', '', '', '火球术', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to an enemy.', '', '', '', '对敌人造成$s1点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20421, 'Seal of Fury', '', '', '', 'zzOLDSeal of Fury', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Fills the Paladin with divine fury for $d, allowing melee attacks to cause additional threat.  Only one Seal can be active on the Paladin at any one time.  More effective than Seal of Fury (Rank 2).\n\nUnleashing this Seal\'s energy will judge an enemy for $20412d, causing Holy damage spells cast on that enemy to generate additional threat.  Only one Judgement per Paladin can be active at any one time.', '', '', '', '神圣的愤怒充满圣骑士的体内，持续$d，令其在攻击时对敌人造成更多的威胁值。圣骑士在同一时间内只能激活一种圣印。比愤怒圣印（等级 2）更有效。\n\n释放这种圣印的能量将对目标造成审判效果，持续$20412d。神圣系的伤害性法术会对被审判的目标造成更高的威胁值。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attacks cause additional threat.', '', '', '', '近战攻击造成额外威胁值。', '', '');
