INSERT INTO `locales_spell` VALUES (20654, 'Entangling Roots', '', '', '', '纠缠根须', '', '', '', '', '', '', '', '', '', 'Entangles nearby enemies in roots, inflicting Nature damage every $t2 sec. and immobilizing them for up to $d.', '', '', '', '使附近的敌人被根须纠缠，每$t2秒受到一次自然伤害，并且无法移动。最多持续$d。', '', '', 'Immobilized.\nNature damage inflicted every $t2 sec.', '', '', '', '无法移动。\n每$t2秒受到一次自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20655, 'Barkskin', '', '', '', '树皮术', '', '', '', '', '', '', '', '', '', 'Heals an ally for $s2 damage every $t2 sec. and increases its armor by $s1 for $d.', '', '', '', '每$t2秒为一个盟友治疗$s2点伤害，并令其护甲值提高$s1点，持续$d。', '', '', 'Armor increased by $s1.\n$s2 damage healed every $t2 sec.', '', '', '', '每$t2秒回复$s2点生命值。\n护甲值提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (20656, 'Faerie Fire', '', '', '', '精灵之火', '', '', '', '', '', '', '', '', '', 'Reduces an enemy\'s armor by $s1 for $d. While affected, the target cannot use stealth or invisibility.', '', '', '', '使敌人的护甲降低$s1点，持续$d。在效果持续期间，目标无法潜行或隐形。', '', '', 'Armor reduced by $s1.\nCannot use stealth or invisibility.', '', '', '', '护甲降低$s1点。\n无法潜行或隐形。', '', '');
