INSERT INTO `locales_spell` VALUES (20658, 'Execute', '', '', '', '斩杀', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Attempt to finish off a wounded foe, causing $s1 damage and converting each extra point of rage into $*10;F1 additional damage.  Only usable on enemies that have 20% or less health.', '', '', '', '尝试杀死一个受伤的敌人，对其造成$s1点基础伤害，并将每一个额外的怒气点数转化为$*10;F1点额外伤害。只对生命值少于20%的敌人有效。', '', '', '', '', '', '', '', '', '');
