INSERT INTO `locales_spell` VALUES (20663, 'Sleep', '', '', '', '催眠术', '', '', '', '', '', '', '', '', '', 'Puts an enemy to sleep for up to $d. Any damage caused will awaken the target. Only one target can be asleep at a time.', '', '', '', '使敌人进入睡眠状态，最多持续$d。任何对目标造成伤害的行为都会唤醒它。同一时间内只能有一个目标被催眠。', '', '', 'Asleep.', '', '', '', '沉睡。', '', '');
