INSERT INTO `locales_spell` VALUES (20665, 'Regrowth', '', '', '', '愈合', '', '', '', '', '', '', '', '', '', 'Heals an ally for a fixed amount, then heals additional damage every $t2 sec. for $d.', '', '', '', '为一个盟友恢复一定的生命值，并在接下来的$d内每$t2秒恢复一些生命值。', '', '', 'Damage healed every $t2 sec.', '', '', '', '每$t2秒治疗一定伤害。', '', '');
