INSERT INTO `locales_spell` VALUES (20668, 'Sleepwalk', '', '', '', '梦游', '', '', '', '', '', '', '', '', '', 'Takes control of a humanoid enemy up to level $s1 for $d, increases the magical damage it deals by $s2, and increases the Physical damage it deals by $s3.', '', '', '', '控制一个等级不高于$s1级的敌对人型生物，持续$d。使其所能造成的魔法伤害提高$s2点，并使其所能造成的物理伤害提高$s3点。', '', '', 'Charmed.\nMagical damage dealt is increased by $s2.\nPhysical damage dealt is increased by $s3.', '', '', '', '被魅惑。\n所能造成的魔法伤害提高$s2点。\n所能造成的物理伤害提高$s3点。', '', '');
