INSERT INTO `locales_spell` VALUES (20694, 'Holy Nova', '', '', '', '神圣新星', '', '', '', '', '', '', '', '', '', 'Causes an explosion of divine light, inflicting $s1 Holy damage to nearby enemies and reducing the caster\'s threat level for $d.', '', '', '', '制造一次以施法者为中心的神圣能量爆炸，对半径$a1码范围内的所有目标造成$s1点神圣伤害，并降低施法者的威胁级别，持续$d。', '', '', '', '', '', '', '', '', '');
