INSERT INTO `locales_spell` VALUES (20702, 'Summon Treant Allies', '', '', '', '召唤树人', '', '', '', '', '', '', '', '', '', 'Summons $s1 $lTreant Ally:Treant Allies; to accompany the caster until dismissed.', '', '', '', '召唤$s1个树人为施法者作战，直到被解散。', '', '', '', '', '', '', '', '', '');
