INSERT INTO `locales_spell` VALUES (20709, 'Arcanite Skeleton Key', '', '', '', '奥金万能钥匙', '', '', '', '', '', '', '', '', '', 'Allows opening of hard locks.  The skeleton key is consumed in the process.', '', '', '', '可以打开复杂的锁，需消耗万能钥匙。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20710, 'Inner Courage 20', '', '', '', 'Inner Courage 20', '', '', '', '', '', '', '', '', '', '+$s1% chance to resist Fear spells and effects.', '', '', '', '抵抗恐惧法术和效果的几率提高$s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20711, 'Spirit of Redemption', '', '', '', '救赎之魂', '', '', '', '', '', '', '', '', '', 'Upon death, the priest becomes the Spirit of Redemption for $27827d.  The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects.  While in this form the priest can cast any healing spell free of cost.  When the effect ends, the priest dies.', '', '', '', '在死亡时，牧师变成一个救赎之魂，持续$27827d。救赎之魂无法移动、攻击，也不会受到任何法术或效果的影响。在这个形态下，牧师可以施放任何治疗法术，不需消耗任何法力值。当救赎之魂效果结束时，牧师死亡。', '', '', '', '', '', '', '', '', '');
