INSERT INTO `locales_spell` VALUES (20752, 'Create Soulstone (Lesser)', '', '', '', '制造次级灵魂石', '', '', '', '', '', '', '', '', '', 'Creates a Lesser Soulstone.  The Soulstone can be used to store one target\'s soul.  If the target dies while his soul is stored, he will be able to resurrect with $20758s1 health and $20758q1 mana.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块次级灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复$20758s1点生命值和$20758q1点法力值。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (20753, 'Demoralizing Roar', '', '', '', '挫志咆哮', '', '', '', '', '', '', '', '', '', 'Reduces the melee attack power of nearby enemies by $s1 for $d.', '', '', '', '使附近敌人的攻击强度降低$s1点，持续$d。', '', '', 'Melee attack power reduced by $s1.', '', '', '', '近战攻击强度降低$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (20754, 'Rain of Fire', '', '', '', '火焰之雨', '', '', '', '', '', '', '', '', '', 'Calls down a molten rain, burning all enemies in a selected area for $s1 Fire damage every $t1 sec. for $d.', '', '', '', '召唤火焰之雨，对指定区域中的敌人每$t1秒造成$s1点伤害，持续$d。', '', '', '$s1 Fire damage inflicted every $t1 sec.', '', '', '', '每$t1秒$s1点火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20755, 'Create Soulstone', '', '', '', '制造灵魂石', '', '', '', '', '', '', '', '', '', 'Creates a Soulstone.  The Soulstone can be used to store one target\'s soul.  If the target dies while his soul is stored, he will be able to resurrect with $20759s1 health and $20759q1 mana.\n\nConjured items disappear if logged out for more than 15 minutes.', '', '', '', '制造一块灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复$20759s1点生命值和$20759q1点法力值。\n\n如果持有该物品的玩家退出游戏超过15分钟，则该物品就会消失。', '', '', '', '', '', '', '', '', '');
