INSERT INTO `locales_spell` VALUES (20882, 'Enslave Demon', '', '', '', '奴役恶魔', '', '', '', '', '', '', '', '', '', 'Enslaves the target demon, up to level $m1, forcing it to do your bidding.  While enslaved, the time between the demon\'s attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.', '', '', '', '奴役等级不高于$m1级的恶魔，强制它听从你的命令。在被奴役的状态下，恶魔的攻击间隔延长$s2%，施法速度降低$s3%。奴役效果最多持续$d。', '', '', 'Enslaved.', '', '', '', '被奴役。', '', '');
