INSERT INTO `locales_spell` VALUES (20907, 'Lacerate', '', '', '', 'zzOLDLacerate', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Wounds the target causing them to bleed for $o1 damage over $d.', '', '', '', '使目标的伤口不断流血，在$d内造成累计$o1点伤害。', '', '', 'Bleeding for $s1 damage every $t1 seconds.', '', '', '', '因流血受到每$t1秒$s1点伤害。', '', '');
