INSERT INTO `locales_spell` VALUES (20909, 'Counterattack', '', '', '', '反击', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'A strike that becomes active after parrying an opponent\'s attack.  This attack deals $s1 damage and immobilizes the target for $d.  Counterattack cannot be blocked, dodged, or parried.', '', '', '', '在招架敌人的攻击之后可以使用的技能，对敌人造成$s1点伤害，并使其无法行动，持续$d。反击无法被格挡、躲闪或招架。', '', '', 'Immobile.', '', '', '', '无法行动。', '', '');
