INSERT INTO `locales_spell` VALUES (20911, 'Blessing of Sanctuary', '', '', '', '庇护祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Places a Blessing on the friendly target, reducing damage dealt from all sources by up to $s1 for $d.  In addition, when the target blocks a melee attack the attacker will take $s2 Holy damage.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多$s1点，持续$d。另外，当目标格挡一次近战攻击时，攻击者会受到$s2点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Damage taken reduced by up to $s1 and blocked melee attacks cause $s2 Holy damage to the attacker.', '', '', '', '受到攻击时所承受的伤害减少最多$s1点，格挡近战攻击会对攻击者造成$s2点神圣伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20912, 'Blessing of Sanctuary', '', '', '', '庇护祝福', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Places a Blessing on the friendly target, reducing damage dealt from all sources by up to $s1 for $d.  In addition, when the target blocks a melee attack the attacker will take $s2 Holy damage.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多$s1点，持续$d。另外，当目标格挡一次近战攻击时，攻击者会受到$s2点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Damage taken reduced by up to $s1 and blocked melee attacks cause $s2 Holy damage to the attacker.', '', '', '', '受到攻击时所承受的伤害减少最多$s1点，格挡近战攻击会对攻击者造成$s2点神圣伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20913, 'Blessing of Sanctuary', '', '', '', '庇护祝福', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Places a Blessing on the friendly target, reducing damage dealt from all sources by up to $s1 for $d.  In addition, when the target blocks a melee attack the attacker will take $s2 Holy damage.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多$s1点，持续$d。另外，当目标格挡一次近战攻击时，攻击者会受到$s2点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Damage taken reduced by up to $s1 and blocked melee attacks cause $s2 Holy damage to the attacker.', '', '', '', '受到攻击时所承受的伤害减少最多$s1点，格挡近战攻击会对攻击者造成$s2点神圣伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20914, 'Blessing of Sanctuary', '', '', '', '庇护祝福', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Places a Blessing on the friendly target, reducing damage dealt from all sources by up to $s1 for $d.  In addition, when the target blocks a melee attack the attacker will take $s2 Holy damage.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多$s1点，持续$d。另外，当目标格挡一次近战攻击时，攻击者会受到$s2点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Damage taken reduced by up to $s1 and blocked melee attacks cause $s2 Holy damage to the attacker.', '', '', '', '受到攻击时所承受的伤害减少最多$s1点，格挡近战攻击会对攻击者造成$s2点神圣伤害。', '', '');
INSERT INTO `locales_spell` VALUES (20915, 'Seal of Command', '', '', '', '命令圣印', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Gives the Paladin a chance to deal additional Holy damage equal to $20424s1% of normal weapon damage.  Only one Seal can be active on the Paladin at any one time.  Lasts $d.\n\nUnleashing this Seal\'s energy will judge an enemy, instantly causing $/2;20963s1 Holy damage, $20963s1 if the target is stunned or incapacitated.', '', '', '', '使圣骑士在攻击时有一定几率对目标造成与攻击伤害的$20424s1%等量的神圣伤害。圣骑士在同一时间内只能激活一种圣印。持续$d。\n\n释放这种圣印的能量将对目标造成审判效果，对其立刻造成$/2;20963s1点神圣伤害，若目标昏迷或瘫痪则造成$20963s1点神圣伤害。', '', '', 'Melee attacks have a chance to deal additional Holy damage.', '', '', '', '近战攻击有一定几率造成额外的神圣伤害。', '', '');
