INSERT INTO `locales_spell` VALUES (21080, 'Putrid Breath', '', '', '', '腐烂气息', '', '', '', '', '', '', '', '', '', 'Adds a chance to cast Putrid Breath on enemy when hit by a melee attack.', '', '', '', '有一定几率在被近战武器击中时对攻击者施放腐烂气息。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (21081, 'Sunder Armor', '', '', '', '破甲攻击', '', '', '', '', '', '', '', '', '', 'Hacks at an enemy\'s armor, reducing it by $s1 per Sunder Armor. Can be applied up to 5 times. Lasts $d.', '', '', '', '击破目标的护甲，每次破甲攻击都会使其护甲值降低$s1点，最多可累加5次，持续$d。', '', '', 'Reduced armor.', '', '', '', '护甲值降低。', '', '');
INSERT INTO `locales_spell` VALUES (21082, 'Seal of the Crusader', '', '', '', '十字军圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal\'s energy has a 5 times higher chance to trigger all proc effects on your weapon.', '', '', '', '十字军的灵魂充满圣骑士的体内，持续$d，使其近战攻击强度提高$s1点。圣骑士的攻击速度也提高$s2%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量有5倍几率触发武器上的所有可触发效果。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。', '', '', 'Melee attack power increased by $s1.  Melee attacks are $s2% faster, but deal less damage.', '', '', '', '近战攻击强度提高$s1点。近战攻击速度提高$s2%，但是所造成的伤害减少。', '', '');
