INSERT INTO `locales_spell` VALUES (21750, 'Freezing Trap (TEST)', '', '', '', 'zzOLDFreezing Trap (TEST)', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Place a frost trap that freezes the first enemy that approaches, preventing all action for up to $3355d.  Any damage caused will break the ice.  Trap will exist for $d.  Only one trap can be active at a time.', '', '', '', '在地面上放置一个陷阱，它会冻结第一个接近它的敌人，使其在最多$3355d内无法行动，任何伤害都会取消冰冻效果。陷阱可存在$d。只能在非战斗状态中安置陷阱，每个猎人在同一时间内只能布置一个陷阱。', '', '', '', '', '', '', '', '', '');
