INSERT INTO `locales_spell` VALUES (21791, 'Tranquility', '', '', '', '宁静', '', '', '', '', '', '', '', '', '', 'Regenerates all nearby group members for $s1 every $t1 seconds for $d.  Druid must channel to maintain the spell.', '', '', '', '使附近所有小队成员每$t1秒钟恢复$s1点生命值，持续$d。德鲁伊必须不断引导能量以维持法术。', '', '', 'Heals nearby party members for $s1 every $t1 seconds.', '', '', '', '每$t1秒为附近的小队成员恢复$s1点生命值。', '', '');
