INSERT INTO `locales_spell` VALUES (21793, 'Twisted Tranquility', '', '', '', '扭曲宁静', '', '', '', '', '', '', '', '', '', 'Deals nature damage to enemies in an area over $d, slowing their movement by $s2% and increasing the time between their attacks by $s3%.', '', '', '', '对指定区域内的敌人造成自然伤害，使它们的移动速度降低$s2%，攻击间隔延长$s3%，持续$d。', '', '', 'Deals nature damage every $t sec.\nReduces movement speed by $s2%.\nTime between attacks increased by $s3%.', '', '', '', '每$t秒受到一次自然伤害。\n移动速度降低$s2%。\n攻击间隔延长$s3%。', '', '');
