INSERT INTO `locales_spell` VALUES (22168, 'Renew', '', '', '', '恢复', '', '', '', '', '', '', '', '', '', 'Heals an ally for $s1 damage every $t1 sec. for $d.', '', '', '', '治疗目标，在$d内恢复总计$o1点生命值。', '', '', '$s1 damage healed every $t1 sec.', '', '', '', '每$t1秒回复$s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (22187, 'Power Word: Shield', '', '', '', '真言术：盾', '', '', '', '', '', '', '', '', '', 'Wraps an ally in a shield that lasts up to $d., absorbing a maximum of $s1 Physical or magical damage. While the shield holds, spells will not be interrupted by Physical attacks.', '', '', '', '立即为目标加上魔法护盾，可吸收$s1点物理或魔法伤害，最多持续$d。只要护盾存在，受保护者的施法就不会被物理攻击打断。', '', '', 'Shielded against Physical and magical damage.', '', '', '', '吸收物理和魔法伤害。', '', '');
