INSERT INTO `locales_spell` VALUES (22274, 'Greater Polymorph', '', '', '', '强效变形术', '', '', '', '', '', '', '', '', '', 'Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.', '', '', '', '将敌人变成一只绵羊，强迫它在附近游荡，最多持续$d。在此期间，绵羊不能攻击或施法，但会以高速回复。一个施法者在同一时间内只能变形一个目标，只能对野兽、龙类、巨人、人型生物和小动物使用。', '', '', 'Cannot attack or cast spells.\nHealth regeneration increased.', '', '', '', '不能攻击或施法。\n生命值回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (22275, 'Flamestrike', '', '', '', '烈焰风暴', '', '', '', '', '', '', '', '', '', 'Calls down a pillar of flame, burning all enemies in a selected area and inflicting additional damage every $t2 sec. for $d.', '', '', '', '召唤一根火柱，灼烧指定区域内的所有敌人，并对它们每$t2秒造成一次额外伤害，持续$d。', '', '', 'Fire damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到一次火焰伤害。', '', '');
