INSERT INTO `locales_spell` VALUES (22355, 'Chain Lightning', '', '', '', '闪电链', '', '', '', '', '', '', '', '', '', 'Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, causing Nature damage to each.', '', '', '', '向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，对每个目标都造成自然伤害，最多可攻击$x1个目标。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (22356, 'Slow', '', '', '', '减速术', '', '', '', '', '', '', '', '', '', 'Increases the time between nearby enemies\' attacks by $s1% and slows their movement by $s2% for $d.', '', '', '', '使敌人的攻击间隔延长$s1%，移动速度降低$s2%，持续$d。', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.', '', '', '', '攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
