INSERT INTO `locales_spell` VALUES (22415, 'Entangling Roots', '', '', '', '纠缠根须', '', '', '', '', '', '', '', '', '', 'Entangles an enemy in roots, inflicting Nature damage every $t2 sec. and immobilizing it for up to $d.', '', '', '', '用根须将敌人缠住，每$t2秒对其造成一次自然伤害，并使其无法移动，最多持续$d。', '', '', 'Immobilized.\nNature damage inflicted every $t2 sec.', '', '', '', '无法移动。\n每$t2秒受到一次自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (22416, 'Backstab', '', '', '', '背刺', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to an enemy, but only if attacking from behind. ', '', '', '', '对目标造成武器伤害再加$s1点伤害，必须从目标背后发动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (22417, 'Shadow Shield', '', '', '', '暗影之盾', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with a shield woven of Shadow magic. The shield lasts $d., absorbs up to $s1 Physical or magical damage, and inflicts $s2 damage to melee attackers.', '', '', '', '以暗影魔法能量保护施法者，持续$d。吸收最多$s1点物理或魔法伤害，对近战攻击者造成$s2点伤害。', '', '', 'Shielded against Physical and magical damage.\n$s2 Shadow damage inflicted to melee attackers.', '', '', '', '吸收物理和魔法伤害。\n对近战攻击者造成$s2点伤害。', '', '');
