INSERT INTO `locales_spell` VALUES (22639, 'Eskhandar\'s Rake', '', '', '', '伊森哈德扫击', '', '', '', '', '', '', '', '', '', 'Slows enemy\'s movement by $s2% and causes them to bleed for $o1 damage over $d.', '', '', '', '使敌人的移动速度降低$s2%，并在接下来的$d内不断流血，承受总计$o1点伤害。', '', '', 'Movement slowed by $s2% and bleeding for $s1 damage every $t1 sec.', '', '', '', '移动速度降低$s2%，每$t1秒因流血而承受$s1点伤害。', '', '');
