INSERT INTO `locales_spell` VALUES (22641, 'Reckless Charge', '', '', '', '无畏冲锋', '', '', '', '', '', '', '', '', '', 'Charge an enemy, knocking it silly for 30 seconds. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target.', '', '', '', '向目标冲锋，将其打傻30秒。这个技能也会使你被击倒并在短时间内昏迷。任何伤害都会唤醒目标。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (22642, 'Brood Power: Bronze', '', '', '', '雏龙之语：青铜', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Casting speed reduced by $s2%.\nTime between attacks increased by $s3%.', '', '', '', '施法速度降低$s2%。\n攻击间隔延长$s3%。', '', '');
