INSERT INTO `locales_spell` VALUES (22715, 'Hydrojet', '', '', '', '喷液', '', '', '', '', '', '', '', '', '', 'Knocks nearby enemies back and reduces their movement speed to $s1% of normal for $d.', '', '', '', '击退附近的敌人，并使它们的移动速度降低到普通速度的$s1%。', '', '', 'Movement speed reduced to $s1% of normal.', '', '', '', '移动速度降低到正常速度的$s1%。', '', '');
