INSERT INTO `locales_spell` VALUES (22717, 'Black War Steed', '', '', '', '黑色战驹', '', '', '', '', '', '', '', '', '', 'Trained to withstand brutal hand-to-hand combat in the fiercest battlefields.', '', '', '', '经过训练可以在最激烈的战场上承受残酷的肉搏战。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22718, 'Black War Kodo', '', '', '', '黑色作战科多兽', '', '', '', '', '', '', '', '', '', 'Bred for their aggressive, unpredictable demeanor by the Kor\'kron stablemasters, the Black War Kodos\' trumpeting call signifies that blood will soon be shed.', '', '', '', '库卡隆马厩长培育出具有侵略性、不可预测的性格，黑色战科多兽的号角声预示着鲜血即将流淌。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22719, 'Black Battlestrider', '', '', '', '黑色作战机械陆行鸟', '', '', '', '', '', '', '', '', '', 'A formidable mount, instilling fear in the hearts of enemies.', '', '', '', '令人畏惧的坐骑，让敌人心生恐惧。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22720, 'Black War Ram', '', '', '', '黑色战羊', '', '', '', '', '', '', '', '', '', 'A sturdy and resilient mount, bred for battle in the mountains.', '', '', '', '坚固而有弹性的坐骑，专为山地战斗而培育。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22721, 'Black War Raptor', '', '', '', '黑色作战迅猛龙', '', '', '', '', '', '', '', '', '', 'Bred from the same vicious line of raptors which sired Ohgan and brought victory to the Gurubashi Empire.', '', '', '', '与奥根的后代相同的凶猛猛禽血统为古拉巴什帝国带来了胜利。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22722, 'Red Skeletal Warhorse', '', '', '', '红色骷髅战马', '', '', '', '', '', '', '', '', '', 'When fallen heroes are raised into undeath, so too are their horses.', '', '', '', '当阵亡的英雄被复活为不死之身时，他们的马匹也会复活。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22723, 'Black War Tiger', '', '', '', '黑色战豹', '', '', '', '', '', '', '', '', '', 'A sleek and deadly predator, ready to pounce on its foes.', '', '', '', '一只光滑而致命的掠食者，随时准备扑向敌人。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22724, 'Black War Wolf', '', '', '', '黑色战狼', '', '', '', '', '', '', '', '', '', 'Prized by Orgrimmar guards for their keen sense of smell.', '', '', '', '因其敏锐的嗅觉而受到奥格瑞玛守卫的赞赏。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (22725, 'Defense +5', '', '', '', '防御 +3', '', '', '', '', '', '', '', '', '', 'Permanently increase the defense value of an item worn on the chest, legs, hands or feet by 5. Only usable on items level 45 and above.', '', '', '', '永久增加佩戴在胸部、腿部、手部或脚部的物品的防御值 5 点。仅适用于 45 级及以上的物品。', '', '', '', '', '', '', '', '', '');
