INSERT INTO `locales_spell` VALUES (22888, 'Rallying Cry of the Dragonslayer', '', '', '', '屠龙者的咆哮', '', '', '', '', '', '', '', '', '', 'Increases critical chance of spells by 10%, melee and ranged by 5% and grants 140 attack power. 120 minute duration.', '', '', '', '使法术的致命一击几率提高10%，近战和远程攻击的致命一击几率提高5%，攻击强度提高140点。持续120分钟。', '', '', 'Increases critical chance of spells by 10%, melee and ranged by 5% and grants 140 attack power. 120 minute duration.', '', '', '', '使法术的致命一击几率提高10%，近战和远程攻击的致命一击几率提高5%，攻击强度提高140点。持续120分钟。', '', '');
