INSERT INTO `locales_spell` VALUES (23218, 'Feral Move Speed Increase', '', '', '', 'Feral Move Speed Increase', '', '', '', '', '', '', '', '', '', 'Increases your movement speed by $s1% while in Bear, Cat, or Travel Form.  Only active outdoors.', '', '', '', '使你在熊形态、猎豹形态或旅行形态下的移动速度提高$s1%，只能在户外使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (23219, 'Swift Mistsaber', '', '', '', '迅捷雾刃豹', '', '', '', '', '', '', '', '', '', 'Some historians claim that this breed\'s misty grey coat is the result of ancient Highborne experiments conducted on nightsabers.', '', '', '', '一些历史学家声称，这个品种的雾灰色皮毛是古代上层精灵对夜刃豹进行实验的结果。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (23220, 'Swift Dawnsaber', '', '', '', '迅捷晨刃豹', '', '', '', '', '', '', '', '', '', 'Night elves once believed that seeing this light colored saber breed in the wild was an ill omen.', '', '', '', '暗夜精灵曾经相信，在野外看到这种浅色的剑品种是一种不祥的预兆。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
