INSERT INTO `locales_spell` VALUES (23419, 'Corrupted Fire Nova Totem', '', '', '', '堕落火焰新星图腾', '', '', '', '', '', '', '', '', '', 'Summons a Fire Nova Totem that has $s1 health and lasts $d.  Unless it is destroyed within $11311t1 sec., the totem inflicts $11307s1 fire damage to enemies within $11307a1 yd.', '', '', '', '在施法者身边召唤一个生命值为$s1的火焰新星图腾，在被召唤出来$11311t1秒钟之后，它会对半径$11307s1码范围内的敌人造成$11307s1点火焰伤害，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (23420, 'Corrupted Stoneskin Totem', '', '', '', '堕落石肤图腾', '', '', '', '', '', '', '', '', '', 'Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $10405a1 yards, reducing melee damage taken by $10405s1.  Lasts $d.', '', '', '', '在施法者身边召唤出一个生命值为$s1的石肤图腾。这个图腾可以使半径$10405a1码范围内的小队成员所受到的物理伤害减少$10405s1，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (23422, 'Corrupted Healing Stream Totem', '', '', '', '堕落治疗之泉图腾', '', '', 'Rank 5', '', '', '', '等级 5', '', '', 'Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $10461a1 yards for $10461s1 every $10461t1 seconds.', '', '', '', '在施法者身边召唤出一个生命值为$s1点的治疗之泉图腾，每$10461t1秒对半径$10461a1码范围内的所有小队成员恢复$10461s1点生命值，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (23423, 'Corrupted Windfury Totem', '', '', '', '堕落风怒图腾', '', '', '', '', '', '', '', '', '', 'Summons a Windfury Totem with $s1 health at the feet of the caster.  The totem enchants all party members weapons with wind, if they are within $10611a1 yards.  Each hit has a 20% chance of granting the attacker $10610s2 extra $lattack:attacks; with $10610s1 extra attack power.  Lasts $d.', '', '', '', '在施法者身边召唤一个生命值为$s1点的风怒图腾，持续$d。它可以使半径$10611a1码范围内的所有小队成员的主手武器附带风怒效果，每次击中敌人都有20%的几率令攻击者获得额外的$10610s2次攻击机会，并且在这几次攻击中的攻击强度提高$10610s1点。', '', '', '', '', '', '', '', '', '');
