INSERT INTO `locales_spell` VALUES (23537, 'Enrage', '', '', '', '暴怒', '', '', '', '', '', '', '', '', '', 'Increases the caster\'s attack speed by $s2% and the Physical damage it deals by $s1 for $d.', '', '', '', '使施法者的攻击速度提高$s2%，所能造成的物理伤害提高$s1点，持续$d。', '', '', 'Physical damage dealt is increased by $s1.\nAttack speed increased by $s2%.', '', '', '', '物理伤害提高$s1点。\n攻击速度提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (23538, 'Battle Standard', '', '', '', '军旗', '', '', '', '', '', '', '', '', '', 'Place a Battle Standard with $s1 health that increases the maximum damage of all party members that stay within $23576a1 yards of the Battle Standard by $23576s1%.  Lasts $d. May only be used in Alterac Valley.', '', '', '', '在地面上放置一面生命值为$s1点的军旗，它可以使附近半径$23576a1码范围内的所有小队成员所能造成的最大伤害提高$23576s1%。持续$d。只能在奥特兰克山谷中使用。', '', '', '', '', '', '', '', '', '');
