INSERT INTO `locales_spell` VALUES (23720, 'Blessing of the Black Book', '', '', '', '黑龙之书的祝福', '', '', '', '', '', '', '', '', '', 'Empowers your pet, increasing pet damage by $s1% and increasing pet armor by $s2% for $d. This spell will only affect an Imp, Succubus, Voidwalker, Felhunter, Infernal and Doomguard.', '', '', '', '增强你的宠物的能力，将宠物伤害提高 $s1%，将宠物护甲提高 $s2%，花费 $d。该法术只会影响小鬼、魅魔、虚空行者、地狱猎手、地狱火和末日守卫。', '', '', 'Damage dealt is increased by $s1%.\nArmor is increased by $s2%.', '', '', '', '对敌人造成的伤害提高$s1%。\n护甲值提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (23721, 'Arcane Infused', '', '', '', '奥术灌输', '', '', '', '', '', '', '', '', '', 'Infuses you with Arcane energy, causing your next Arcane Shot fired within $d to detonate at the target. The Arcane Detonation will deal $23722s1 damage to enemies near the target.', '', '', '', '向你灌输奥术能量，使你在$d内施放的下一次奥术射击在目标身上爆炸，对其身边的敌人造成$23722s1点伤害。', '', '', 'Your next Arcane Shot will create an Arcane Detonation.', '', '', '', '你的下一次奥术射击在目标身上爆炸。', '', '');
