INSERT INTO `locales_spell` VALUES (24160, 'Syncretist\'s Sigil', '', '', '', '调和的徽记', '', '', '', '', '', '', '', '', '', 'Permanently adds 10 Stamina, 7 Defense, and increases healing by up to 24 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供耐力10，防御+10，所有治疗法术的效果效果提高最多24的属性。无法与其它同位置的附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24161, 'Death\'s Embrace', '', '', '', '死亡的拥抱', '', '', '', '', '', '', '', '', '', 'Permanently adds 28 Attack Power and 1% Dodge to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供+28点攻击强度和躲闪几率+1%的属性。无法与其它附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24162, 'Falcon\'s Call', '', '', '', '猎鹰的召唤', '', '', '', '', '', '', '', '', '', 'Permanently adds 24 Ranged Attack Power, 10 Stamina, and 1% Chance to Hit to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供远程攻击强度+24，耐力+10，命中几率+1%的属性。无法与其它附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24163, 'Vodouisant\'s Vigilant Embrace', '', '', '', '巫毒的警觉', '', '', '', '', '', '', '', '', '', 'Permanently adds 15 Intellect and increases all healing and spell damage by up to 13 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供所有魔法造成的治疗或伤害效果提高最多13点并提高智力15点的属性。无法与其它同位置的附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24164, 'Presence of Sight', '', '', '', '魔法的视域', '', '', '', '', '', '', '', '', '', 'Permanently adds 18 to all healing and damage spells and 1% chance to hit with spells to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供所有治疗和伤害法术的效果+18，法术命中率+1%的属性。无法与其它附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24165, 'Hoodoo Hex', '', '', '', '不祥的妖术', '', '', '', '', '', '', '', '', '', 'Permanently adds 10 Stamina and increases spell damage and healing by up to 18 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供耐力+10，所有治疗和伤害法术的效果效果提高最多18的属性。无法与其它同位置的附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24167, 'Prophetic Aura', '', '', '', '预言的光环', '', '', '', '', '', '', '', '', '', 'Permanently adds 10 Stamina, 4 mana per 5 sec., and increases healing by up to 24 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供耐力+10，每5秒回复4点法力值，所有治疗法术的效果效果提高最多24的属性。无法与其它同位置的附魔共存。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24168, 'Animist\'s Caress', '', '', '', '灵魂的安抚', '', '', '', '', '', '', '', '', '', 'Permanently adds 10 Stamina, 10 Intellect, and increases healing by up to 24 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '永久性地为一件头部或腿部装备提供耐力+10，智力+10，所有治疗法术的效果效果提高最多24的属性。无法与其它同位置的附魔共存。', '', '', '', '', '', '', '', '', '');
