INSERT INTO `locales_spell` VALUES (24236, 'Whirlwind', '', '', '', '旋风斩', '', '', '', '', '', '', '', '', '', 'Attacks nearby enemies in a whirlwind of steel that lasts $d. and inflicts normal damage plus $15589s1.', '', '', '', '像旋风一般挥舞手中的武器，攻击周围的所有敌人，对它们造成普通伤害再加上$15589s1点伤害，持续$d。', '', '', 'Attacking all nearby enemies for normal damage plus $15589s1.', '', '', '', '对附近的所有敌人造成武器伤害外加$15589s1点伤害。', '', '');
