INSERT INTO `locales_spell` VALUES (24238, 'Test Rip', '', '', '', 'Test Rip', '', '', 'Rank 6', '', '', '', '等级 6', '', '', 'Finishing move that causes damage over time.  Damage increases per combo point:\n   1 point  : 228 damage over $d.\n   2 points: 354 damage over $d.\n   3 points: 480 damage over $d.\n   4 points: 606 damage over $d.\n   5 points: 732 damage over $d.', '', '', '', '终结技，使目标在一段时间内受到持续的伤害。根据连击点数决定伤害总量：\n   1点：$d内300伤害\n   2点：$d内498伤害\n   3点：$d内696伤害\n   4点：$d内894伤害\n   5点：$d内1092伤害', '', '', 'Bleed damage every $t1 seconds.', '', '', '', '每$t1秒受到一次流血伤害。', '', '');
INSERT INTO `locales_spell` VALUES (24239, 'Hammer of Wrath', '', '', '', '愤怒之锤', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Hurls a hammer that strikes an enemy for $s1 Holy damage.  Only usable on enemies that have 20% or less health.', '', '', '', '投掷一柄战锤，对敌人造成$s1点神圣伤害。只能对生命值低于20%的目标使用。', '', '', '', '', '', '', '', '', '');
