INSERT INTO `locales_spell` VALUES (24242, 'Swift Razzashi Raptor', '', '', '', '拉扎什迅猛龙', '', '', '', '', '', '', '', '', '', 'The only known Razzashi Raptors were said to have been in the custody of Bloodlord Mandokir in Zul\'Gurub. This species of raptor has not been seen in many years.', '', '', '', '据说唯一已知的拉扎什猛禽被祖尔格拉布的血领主曼多基尔看管。这种猛禽已经很多年没有见过了。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (24243, 'Increase Spell Dam 840', '', '', '', '提高法术伤害840', '', '', '', '', '', '', '', '', '', 'Increases damage and healing done by magical spells and effects by up to $s1.', '', '', '', '提高所有法术和魔法效果所造成的伤害和治疗效果，最多$s1点。', '', '', '', '', '', '', '', '', '');
