INSERT INTO `locales_spell` VALUES (24248, 'Copy of Ferocious Bite', '', '', '', 'Copy of Ferocious Bite', '', '', 'Rank 4', '', '', '', '等级 4', '', '', 'Finishing move that causes damage per combo point and converts each extra point of energy into $f1 additional damage:\n   1 point  : 170-220 damage\n   2 points: 295-345 damage\n   3 points: 420-470 damage\n   4 points: 545-595 damage\n   5 points: 670-720 damage', '', '', '', '终结技，根据连击点数决定所造成的伤害，并将每一点额外的能量点数转化为$f1点额外伤害：\n   1点：190-240 伤害\n   2点：335-385 伤害\n   3点：480-530 伤害\n   4点：625-675 伤害\n   5点：770-820 伤害', '', '', '', '', '', '', '', '', '');
