INSERT INTO `locales_spell` VALUES (24255, 'Primal Blessing', '', '', '', '原始祝福', '', '', '', '', '', '', '', '', '', 'Infuses the caster with a blessing from the Primal Gods. Ranged and melee attack power increased by $s1 for $d.', '', '', '', '使施法者获得远古神灵的祝福，远程和近战攻击强度提高$s1点，持续$d秒。', '', '', 'Melee attack power increased by $s1.\nRanged attack power increased by $s2.', '', '', '', '近战攻击强度提高$s1点。\n远程攻击强度提高$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (24256, 'Primal Blessing Trigger DND', '', '', '', 'Primal Blessing Trigger DND', '', '', '', '', '', '', '', '', '', 'Grants a small chance when ranged or melee damage is dealt to infuse the wielder with a blessing from the Primal Gods. Ranged and melee attack power increased by 300 for 12 seconds.', '', '', '', '使施法者有较小的几率获得远古神灵的祝福，在对敌人造成伤害时远程和近战攻击强度提高300点，持续12秒。', '', '', '', '', '', '', '', '', '');
