INSERT INTO `locales_spell` VALUES (24658, 'Unstable Power', '', '', '', '能量无常', '', '', '', '', '', '', '', '', '', 'Increases your spell damage by up to 204 and your healing by up to 408 for $d. Every time you cast a spell, the bonus is reduced by 17 spell damage and 34 healing.', '', '', '', '使你的法术伤害效果提高最多204点，法术治疗效果提高最多408点，持续$d。你每施放一次法术，此增益的效果就降低17点伤害和34点治疗效果。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24659, 'Unstable Power', '', '', '', '能量无常', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Spell damage increased by up to $s1.\nHealing increased by up to $s2.', '', '', '', '法术伤害效果提高最多$s1点。\n法术治疗效果提高最多$s2点。', '', '');
