INSERT INTO `locales_spell` VALUES (24661, 'Restless Strength', '', '', '', '充沛之力', '', '', '', '', '', '', '', '', '', 'Increases your melee and ranged damage by 40 for $d. Every time you hit a target, this bonus is reduced by 2.', '', '', '', '使你所能造成的近战和远程伤害提高40点，持续$d。你每击中一次目标，这个数字就减少2点。', '', '', '', '', '', '', '', '', '');
