INSERT INTO `locales_spell` VALUES (24664, 'Sleep', '', '', '', '睡眠', '', '', '', '', '', '', '', '', '', 'Puts nearby enemies to sleep for up to $d. Any damage caused will awaken them.', '', '', '', '使敌人进入睡眠状态，最多持续$d。任何对目标造成伤害的行为都会唤醒它。', '', '', 'Asleep.', '', '', '', '沉睡。', '', '');
