INSERT INTO `locales_spell` VALUES (24668, 'Shadow Bolt', '', '', '', '暗影箭', '', '', '', '', '', '', '', '', '', 'Hurls a bolt of dark magic at an enemy, inflicting Shadow damage.', '', '', '', '向目标射出一支暗影箭，对其造成暗影伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24669, 'Rain of Fire', '', '', '', '火焰之雨', '', '', '', '', '', '', '', '', '', 'Calls down a molten rain, burning all enemies in a selected area for $s1 Fire damage every $t1 sec. for $d.', '', '', '', '召唤火焰之雨，对指定区域中的敌人每$t1秒造成$s1点伤害，持续$d。', '', '', '$s1 Fire damage inflicted every $t1 sec.', '', '', '', '每$t1秒$s1点火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (24670, 'Inferno', '', '', '', '地狱火', '', '', '', '', '', '', '', '', '', 'Summons a meteor from the Twisting Nether, causing $22699s1 Fire damage and stunning all enemy targets in the area for $20310d.  An Infernal rises from the crater, under the command of the caster for $20882d.  Once control is lost, the Infernal must be Enslaved to maintain control.  Can only be used outdoors.', '', '', '', '从扭曲虚空中召来一颗流星，对其着陆区域的所有敌人造成$22699s1点火焰伤害，并使它们昏迷$20310d。一个巨大的地狱火恶魔将从着陆点出现，并被施法者控制$20882d。如果控制失效，则施法者必须奴役地狱火才能继续指挥它。只能在户外使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24671, 'Snap Kick', '', '', '', '蹬踏', '', '', '', '', '', '', '', '', '', 'Inflicts $s2 damage to an enemy, stunning it for $d.', '', '', '', '对敌人造成$s2点伤害，并使其昏迷$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (24672, 'Unholy Frenzy', '', '', '', '邪恶狂热', '', '', '', '', '', '', '', '', '', 'Increases an ally\'s attack speed by $s1% for $d., but also inflicts $s2 Nature damage to that ally every $t2 sec.', '', '', '', '使一个盟友的攻击速度提高$s1%，持续$d。同时该盟友每$t2秒受到$s2点自然伤害。', '', '', 'Attack speed increased by $s1%.\n$s2 Nature damage inflicted every $t2 sec.', '', '', '', '攻击速度提高$s1%。\n每$t2秒受到$s2点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (24673, 'Curse of Blood', '', '', '', '血之诅咒', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage taken by an enemy by $s1 for $d.', '', '', '', '在受到物理攻击时所承受的伤害提高$s1点，持续$d。', '', '', 'Physical damage taken is increased by $s1.', '', '', '', '受到物理攻击时所承受的伤害提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (24674, 'Veil of Shadow', '', '', '', '暗影之雾', '', '', '', '', '', '', '', '', '', 'Reduces healing effects for an enemy by $s1% for $d.', '', '', '', '使一个敌人在受到治疗时的治疗效果降低$s1%，持续$d。', '', '', 'Healing effects reduced by $s1%.', '', '', '', '治疗效果降低$s1%。', '', '');
