INSERT INTO `locales_spell` VALUES (24680, 'Chain Lightning', '', '', '', '闪电链', '', '', '', '', '', '', '', '', '', 'Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.', '', '', '', '向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，最多可攻击$x1个目标，每次击中都会造成更高的自然伤害。', '', '', '', '', '', '', '', '', '');
