INSERT INTO `locales_spell` VALUES (24682, 'Forked Lightning', '', '', '', '叉状闪电', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Inflicts $s1 Nature damage to enemies in a cone in front of the caster.', '', '', '', '对施法者面前的一个锥形区域中的所有敌人造成$s1点自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24683, 'Lightning Cloud', '', '', '', '闪电之云', '', '', '', '', '', '', '', '', '', 'Creates a cloud of lightning that lasts $d., blasting all enemies in a selected area for $s1 Nature damage and inflicting $s2 additional damage every $t2 sec.', '', '', '', '召唤一朵持续$d的雷云，对指定区域中的所有敌人造成$s1点自然伤害，并每$t2秒造成$s2点额外伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24684, 'Chain Burn', '', '', '', '链式燃烧', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Hits an enemy with an anti-mana bolt that arcs to another nearby enemy. For each point of mana consumed by the bolt, the target takes $e1 damage. The spell affects up to $x1 targets.', '', '', '', '从目标身上吸取$s1点法力值，每吸取1点法力值，目标就受到$e1点伤害，可影响到最多$x1个额外的目标。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24685, 'Earth Shock', '', '', '', '地震', '', '', '', '', '', '', '', '', '', 'Shocks an enemy with concussive force, inflicting Nature damage and interrupting the spell being cast for $d.', '', '', '', '以震撼性的力量攻击目标，对其造成自然伤害，并使其在$d内不能施法。', '', '', '', '', '', '', '', '', '');
