INSERT INTO `locales_spell` VALUES (24687, 'Aspect of Jeklik', '', '', '', '耶克里克的守护', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 on nearby enemies, preventing them from spellcasting for $d.', '', '', '', '对附近的敌人造成普通伤害再加$s1点伤害，并使它们不能施法，持续$d。', '', '', 'Cannot cast spells.', '', '', '', '不能施法。', '', '');
INSERT INTO `locales_spell` VALUES (24688, 'Aspect of Venoxis', '', '', '', '温诺希斯的守护', '', '', '', '', '', '', '', '', '', 'Spits poison at nearby enemies, inflicting Nature damage, then additional damage every $t2 sec. for $d.', '', '', '', '对附近的敌人射出毒液，造成自然伤害，并在接下来的$d内每$t2秒造成一次额外伤害。', '', '', 'Nature damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到一次自然伤害。', '', '');
