INSERT INTO `locales_spell` VALUES (24726, 'Deputize Agent of Nozdormu', '', '', '', '诺兹多姆的代言人', '', '', '', '', '', '', '', '', '', 'Target a friendly player to deputize them as an Agent of Nozdormu. As an Agent of Nozdormu, only you and your deputies may take the Silithid Carapace Fragments from the corpses of the silithid. Keep your badge in your pack at all times.', '', '', '', '对一个友方玩家使用，任命他们为诺兹多姆的代言人。作为诺兹多姆的代言人，只有你和你的副官可以从异种虫类的尸体上收集它们的甲壳碎片。请保持你的背包中有足够的空间。', '', '', '', '', '', '', '', '', '');
