INSERT INTO `locales_spell` VALUES (24854, 'Mana Spring Totem', '', '', '', '法力之泉图腾', '', '', '', '', '', '', '', '', '', 'Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $24853s1 mana every $24853t1 seconds to group members within $24853a1 yards.', '', '', '', '在施法者身边召唤一个生命值为$s1点的法力之泉图腾，持续$d。它可以为半径$24853a1码范围内的小队成员每$24853t1秒回复$24853s1点法力值。', '', '', '', '', '', '', '', '', '');
