INSERT INTO `locales_spell` VALUES (24857, 'Arcane Blast', '', '', '', '奥术冲击', '', '', '', '', '', '', '', '', '', 'Blasts an enemy with Arcane magic, inflicting normal damage plus $s2 and knocking the enemy back.', '', '', '', '以奥术魔法冲击敌人，将其击退并造成普通伤害外加$s2点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (24858, 'Moonkin Form', '', '', '', '枭兽形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Transforms the Druid into Moonkin Form. While in this form the armor contribution from items is increased by 360%, the Mana cost of your Balance spells is reduced by 20%, and all party members within 30 yards have their spell critical chance increased by 3%. The Moonkin can only cast Balance spells, Innervate, and Remove Curse while shapeshifted. The act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.', '', '', '', '将德鲁伊转变为枭兽形态。在这种形式下，物品的护甲贡献增加了$24905s1%，平衡法术的法力消耗减少了$24905s3%，$24907a1码内的所有小队成员的法术暴击几率增加了$24907s1%。枭兽在变形时只能施展平衡法术、激活和解除诅咒。变形行为可以使施法者摆脱变形和运动障碍效果。', '', '', 'Immune to Polymorph effects.  Armor contribution from items is increased by $24905s1%.', '', '', '', '免疫变形效果。护甲值提高$24905s1%。', '', '');
