INSERT INTO `locales_spell` VALUES (25019, 'Blizzard', '', '', '', '暴风雪', '', '', '', '', '', '', '', '', '', 'Calls down a blizzard that lasts $d., inflicting $s1 Frost damage every $t1 sec. to all enemies in a selected area.', '', '', '', '召唤持续$d的暴风雪，对指定区域内的所有敌人每$t1秒造成$s1点冰霜伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25020, 'Lightning Shield', '', '', '', '闪电之盾', '', '', '', '', '', '', '', '', '', 'Surrounds the caster with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.', '', '', '', '$n颗闪电球环绕着施法者，有$h%的几率对近战或远程攻击者造成$s1点伤害。每次闪电之盾发动反击都会消耗一颗闪电球。因此，闪电之盾最多可维持$d，或者在反击$n次后消失。', '', '', '$h% chance of inflicting $s1 Nature damage on hit.', '', '', '', '有$h%的几率对近战或远程攻击者造成$s1点自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (25021, 'Chain Lightning', '', '', '', '闪电链', '', '', '', '', '', '', '', '', '', 'Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.', '', '', '', '向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，最多可攻击$x1个目标，每次击中都会造成更高的自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25022, 'Hallow\'s End Fright', '', '', '', '复活节惊骇', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Spooked!\nTime between attacks increased by $s1%.\nMovement speed reduced by $s2%.\n', '', '', '', '鬼啊！\n攻击间隔延长$s1%。\n移动速度降低$s2%。', '', '');
