INSERT INTO `locales_spell` VALUES (25024, 'Drop Mine', '', '', '', '布雷', '', '', '', '', '', '', '', '', '', 'Deploys a land mine. Mines take 3 seconds to arm and deal $25099s1 damage to all tonks in a $25099a1 yard radius once triggered.', '', '', '', '放置一颗地雷。地雷需要3秒钟才能安装完毕，一旦触发，会对半径$25099a1码范围内的所有蒸汽车造成$25099s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25025, 'Earth Shock', '', '', '', '地震', '', '', '', '', '', '', '', '', '', 'Shocks an enemy with concussive force, inflicting Nature damage and interrupting the spell being cast for $d.', '', '', '', '以震撼性的力量攻击目标，对其造成$s1点自然伤害，并使其在$d内不能施法。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25026, 'Activate MG Turret', '', '', '', '速射炮台', '', '', '', '', '', '', '', '', '', '10 mana per second.\nAutomatically fires a shot at the nearest enemy tonk within $25032a1 yards every $t1 sec, dealing $25032s1 damage per shot.\n', '', '', '', '每秒钟10点法力值。\n每$t1秒自动对你面前半径$25032a1码范围内的最近的蒸汽车发射炮弹，每发造成$25032s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25027, 'Flamethrower', '', '', '', '火焰喷射器', '', '', '', '', '', '', '', '', '', '10 mana per second.\nDeals $25029s1 damage every $t1 sec to all tonks in front of you within $25029a1 yards. Also slows movement to $25029s2% and deals $25029s3 damage per second for $25029d.', '', '', '', '每秒钟10点法力值。\n每$t1秒对你面前半径$25029a1码范围内的所有蒸汽车造成$25029s1点伤害。同时也会使它们的移动速度降低到普通速度的$25029s3%，并每$s25029t2秒造成$25029s2点伤害，持续$25029d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25028, 'Fire Blast', '', '', '', '火焰冲击', '', '', '', '', '', '', '', '', '', 'Inflicts Fire damage to an enemy.', '', '', '', '对敌人造成火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25029, 'Flamethrower', '', '', '', '火焰喷射器', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Deals $s3 damage every $t3 sec.\nMovement speed slowed by $s2%.', '', '', '', '每$t3秒造成$s3点伤害。\n移动速度降低$s2%。', '', '');
