INSERT INTO `locales_spell` VALUES (25117, 'Minor Wizard Oil', '', '', '', '初级巫师之油', '', '', '', '', '', '', '', '', '', 'While applied to target weapon it increases spell damage by up to 8.  Lasts for 30 minutes.', '', '', '', '涂抹在目标武器上之后，使持有者的法术所能造成的伤害提高最多8点，持续30分钟。', '', '', '', '', '', '', '', '', '');
