INSERT INTO `locales_spell` VALUES (25503, 'Enrage', '', '', '', '狂怒', '', '', '', '', '', '', '', '', '', 'Generates 20 rage over $d, but reduces base armor by 27% in Bear Form and 16% in Dire Bear Form.  The druid is considered in combat for the duration.', '', '', '', '在$d内增加20点怒气值，但在熊形态下基础护甲值降低27%，巨熊状态下基础护甲值降低16%。在此期间德鲁伊处于战斗状态中。', '', '', 'Gain $/10;s1 rage per second.  Armor reduced.', '', '', '', '每秒获得$/10;s1点怒气值。护甲值降低。', '', '');
