INSERT INTO `locales_spell` VALUES (25779, 'Mana Burn', '', '', '', '法力燃烧', '', '', '', '', '', '', '', '', '', 'Hits an enemy with an anti-mana bolt. For each point of mana consumed by the bolt, the target takes $e1 damage.', '', '', '', '向附近的敌人射出可抽取法力值的箭，每抽取1点法力值，目标就受到$e1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25780, 'Righteous Fury', '', '', '', '正义之怒', '', '', '', '', '', '', '', '', '', 'Increases the threat generated by your Holy attacks by $s1%.  Lasts until cancelled.', '', '', '', '使你的神圣攻击产生的威胁增加 $s1%。持续到取消为止。', '', '', 'Increases the threat generated by your Holy attacks by $s1%.', '', '', '', '使你的神圣系攻击所造成的威胁值提高$s1%。', '', '');
