INSERT INTO `locales_spell` VALUES (25782, 'Greater Blessing of Might', '', '', '', '强效力量祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Might, increasing melee attack power by $s1 for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效力量祝福的效果，使其近战攻击强度提高$s1，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Increases melee attack power by $s1.', '', '', '', '近战攻击强度提高$s1点。', '', '');
