INSERT INTO `locales_spell` VALUES (25890, 'Greater Blessing of Light', '', '', '', '强效光明祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Light, increasing the effects of Holy Light spells used on the target by up to $s1 and the effect Flash of Light spells used on the target by up to $s2.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效光明祝福的效果，使圣光术为其恢复的生命值提高$s1点，圣光闪现为其恢复的生命值提高$s2点，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Receives up to $s1 extra healing from Holy Light spells, and up to $s2 extra healing from Flash of Light spells.', '', '', '', '因圣光术恢复的生命值提高最多$s1点，因圣光闪现恢复的生命值提高最多$s2点。', '', '');
INSERT INTO `locales_spell` VALUES (25891, 'Earthstrike', '', '', '', '大地之击', '', '', '', '', '', '', '', '', '', 'Increases your melee and ranged attack power by $s1.  Effect lasts for $d.', '', '', '', '使你的远程和近战攻击强度提高$s1点，持续$d。', '', '', 'Increases melee and ranged attack power by $s1.', '', '', '', '远程和近战攻击强度提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (25892, 'Grace of Earth', '', '', '', '大地之优雅', '', '', '', '', '', '', '', '', '', 'Reduces your threat to enemy targets within $a1 yards, making them less likely to attack you.', '', '', '', '降低你对半径$a1码范围内的目标的威胁值，降低它们攻击你的几率。', '', '', '', '', '', '', '', '', '');
