INSERT INTO `locales_spell` VALUES (25894, 'Greater Blessing of Wisdom', '', '', '', '强效智慧祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Wisdom, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效智慧祝福的效果，每$t1秒回复$s1点法力值，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Restores $s1 mana every $t1 seconds.', '', '', '', '每$t1秒回复$s1点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (25895, 'Greater Blessing of Salvation', '', '', '', '强效拯救祝福', '', '', '', '', '', '', '', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Salvation, reducing the amount of all threat generated by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效拯救祝福的效果，令其对怪物造成的威胁降低$s1%，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Reduces threat generated by $s1%.', '', '', '', '威胁值降低$s1%。', '', '');
