INSERT INTO `locales_spell` VALUES (25898, 'Greater Blessing of Kings', '', '', '', '强效王者祝福', '', '', '', '', '', '', '', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Kings, increasing total stats by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高$s1%，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Increases stats by $s1%.', '', '', '', '所有属性提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (25899, 'Greater Blessing of Sanctuary', '', '', '', '强效庇护祝福', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Sanctuary, reducing damage dealt from all sources by up to $s1 for $d.  In addition, when the target blocks a melee attack the attacker will take $s2 Holy damage.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效庇护祝福的效果，使其所受到的所有类型的伤害都减少最多$s1点，持续$d。另外，当目标格挡了近战攻击之后，攻击者会受到$s2点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Damage taken reduced by up to $s1 and blocked melee attacks cause $s2 Holy damage to the attacker.', '', '', '', '受到攻击时所承受的伤害减少最多$s1点，格挡之后对攻击者造成$s2点神圣伤害。', '', '');
