INSERT INTO `locales_spell` VALUES (25918, 'Greater Blessing of Wisdom', '', '', '', '强效智慧祝福', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Gives all members of the raid or group that share the same class with the target the Greater Blessing of Wisdom, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.', '', '', '', '使团队或小队中所有与目标职业相同的玩家都获得强效智慧祝福的效果，每$t1秒回复$s1点法力值，持续$d。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。', '', '', 'Restores $s1 mana every $t1 seconds.', '', '', '', '每$t1秒回复$s1点法力值。', '', '');
