INSERT INTO `locales_spell` VALUES (25988, 'Eye for an Eye', '', '', '', '以眼还眼', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'All spell criticals against you cause $s1% of the damage taken to the caster as well.  The damage caused by Eye for an Eye will not exceed 50% of the Paladin\'s total health.', '', '', '', '所有对你造成致命一击的法术都会对其施法者造成$s1%的伤害，但最大数值不会超过圣骑士生命值总量的50%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (25989, 'Toxin', '', '', '', '剧毒', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Deals $s1 damage every $t1 sec.\nSlows movement by $s2%.', '', '', '', '每$t1秒造成$s1点伤害。\n移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (25990, 'Graccu\'s Mince Meat Fruitcake', '', '', '', '格拉库的肉松蛋糕', '', '', '', '', '', '', '', '', '', 'Restores $s1% of your health and mana per second for $d.  Must remain seated while eating.  You should also probably like the taste of fruitcake.', '', '', '', '每秒恢复总生命值和法力值的$s1%，持续$d。进食时必须保持坐姿。另外，你也应该会很喜欢它的味道！', '', '', 'Restores $s1% of your health and mana per second.  Mmmm... fruitcake...', '', '', '', '每$t1秒回复$s1%的生命值和法力值。嗯……好香啊……', '', '');
INSERT INTO `locales_spell` VALUES (25991, 'Poison Bolt Volley', '', '', '', '毒箭之雨', '', '', '', '', '', '', '', '', '', 'Shoots poison at an enemy, inflicting Nature damage, then additional damage every $t2 sec. for $d.', '', '', '', '向敌人射出毒箭，对其造成自然伤害，并每$t2秒造成一次额外的自然伤害。持续$d。', '', '', '$s2 nature damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到$s2点自然伤害。', '', '');
