INSERT INTO `locales_spell` VALUES (26463, 'Mercurial Shield', '', '', '', '水银护盾', '', '', '', '', '', '', '', '', '', 'Increases your spell resistances by 100 for $d. Every time a hostile spell lands on you, this bonus is reduced by 10 resistance.', '', '', '', '使你的法术抗性提高100点，持续$d。每当你受到一次敌对魔法的影响，这个加成效果就降低10点。', '', '', '', '', '', '', '', '', '');
