INSERT INTO `locales_spell` VALUES (26467, 'Persistent Shield', '', '', '', '持续护盾', '', '', '', '', '', '', '', '', '', 'Your magical heals provide the target with a shield that absorbs damage equal to 15% of the amount healed for $d.', '', '', '', '你的魔法类治疗技能可以令目标获得一层魔法护盾，这层护盾可以吸收相当于总治疗量15%的伤害，护盾效果持续$d。', '', '', 'Provides damage absorption on heal.', '', '', '', '治疗时提供伤害吸收效果。', '', '');
INSERT INTO `locales_spell` VALUES (26468, 'Snowman', '', '', '', '雪人', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your snowman.', '', '', '', '右键点击以召唤或解散你的雪人。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (26469, 'Summon Snowman', '', '', '', '召唤雪人', '', '', '', '', '', '', '', '', '', 'He loves to dance and wave and play with you! He melts after Winter Veil, but don\'t worry; he\'ll be back again someday!', '', '', '', '他喜欢和你跳舞、挥手、玩耍！冬幕节过后他就会融化，但别担心；他总有一天会回来的！', '', '', '', '', '', '', '', '', '');
