INSERT INTO `locales_spell` VALUES (26527, 'Enrage', '', '', '', '激怒', '', '', '', '', '', '', '', '', '', 'Increases the caster\'s attack speed by $s2% and the Physical damage it deals by $s1 for $d.', '', '', '', '使施法者的攻击速度提高$s2%，物理伤害提高$s1点，持续$d。', '', '', 'Physical damage dealt is increased by $s1.\nAttack speed increased by $s2%.', '', '', '', '攻击速度提高$s2%。\n物理伤害提高$s1点。', '', '');
