INSERT INTO `locales_spell` VALUES (27609, 'Dispel Magic', '', '', '', '驱散魔法', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Dispels magic on the target, removing $s1 harmful $lspell:spells; from a friend or $s1 beneficial $lspell:spells; from an enemy.', '', '', '', '驱散目标身上的魔法效果，从友方身上移除$s1个有害法术，或是从敌人身上移除$s1个有益法术。', '', '', '', '', '', '', '', '', '');
