INSERT INTO `locales_spell` VALUES (27617, 'Vanish', '', '', '', '消失', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Allows the rogue to vanish from sight, entering an improved stealth mode for $11329d.  Also breaks movement impairing effects.  More effective than Vanish (Rank 1).', '', '', '', '使盗贼消失并进入强化的潜行模式，持续$11329d。同时也可解除一切移动限制效果。比消失（等级 1）更有效。', '', '', 'Improved stealth.', '', '', '', '强化潜行。', '', '');
INSERT INTO `locales_spell` VALUES (27618, 'Blizzard', '', '', '', '暴风雪', '', '', 'Rank 6', '', '', '', '等级 6', '', '', 'Ice shards pelt the target area doing $o1 Frost damage over $d.', '', '', '', '破碎的冰块从天而降，在$d内对目标造成$o1点冰霜伤害。', '', '', '$s1 Frost damage every $t1 $lsecond:seconds;.', '', '', '', '每$t1秒造成$s1点冰霜伤害。', '', '');
INSERT INTO `locales_spell` VALUES (27619, 'Ice Block', '', '', '', '寒冰屏障', '', '', '', '', '', '', '', '', '', 'You become encased in a block of ice, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move or cast spells.', '', '', '', '你被一道寒冰屏障所笼罩，在$d内不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。', '', '', 'Immune to all attacks and spells.  Cannot attack, move or use spells.', '', '', '', '对所有攻击和法术免疫。无法攻击、移动或施法。', '', '');
