INSERT INTO `locales_spell` VALUES (27986, 'Levitate', '', '', '', '漂浮', '', '', '', '', '', '', '', '', '', 'Allows the caster to levitate, floating a few feet above the ground.  While levitating, you will fall at a reduced speed and travel over water-like surfaces.  ', '', '', '', '让施法者可以漂浮在地面上，移动速度降低，但是能越过水体表面行走。任何伤害都会中断漂浮效果。', '', '', 'Levitating.', '', '', '', '漂浮。', '', '');
INSERT INTO `locales_spell` VALUES (27987, 'Unholy Aura', '', '', '', '邪恶光环', '', '', '', '', '', '', '', '', '', 'Causes the caster to automatically inflict $17466s1 Shadow damage every $t1 sec. to nearby enemies. The aura lasts until cancelled.', '', '', '', '使施法者自动对周围的敌人每$t1秒造成$17466s1点暗影伤害。该光环的效果一直持续到主动取消。', '', '', 'Automatically inflicting $27988s1 Shadow damage every $t1 sec. to nearby enemies.', '', '', '', '自动对周围的敌人每$t1秒造成$27988s1点暗影伤害。', '', '');
