INSERT INTO `locales_spell` VALUES (27989, 'Arcane Explosion', '', '', '', '魔爆术', '', '', '', '', '', '', '', '', '', 'Sends out a blast wave of magic, inflicting Arcane damage to nearby enemies.', '', '', '', '制造一次以施法者为中心的魔法爆炸，对附近的敌人造成奥术伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (27990, 'Fear', '', '', '', '恐惧', '', '', '', '', '', '', '', '', '', 'Strikes fear in an enemy, causing it to flee in terror for $d. Only 1 target can be feared at a time.', '', '', '', '使敌人因为极度的恐惧而奔逃，最多持续$d。在同一时间内，只有1个敌人会被你的恐惧术影响。', '', '', 'Fleeing in fear.', '', '', '', '因恐惧而逃跑。', '', '');
INSERT INTO `locales_spell` VALUES (27991, 'Sunder Armor', '', '', '', '破甲', '', '', '', '', '', '', '', '', '', 'Hacks at an enemy\'s armor, reducing it by $s1 per Sunder Armor. Can be applied up to 5 times. Lasts $d.', '', '', '', '击破敌人的护甲，每次破甲可以使其护甲值降低$s1点。可叠加最多5次。持续$d。', '', '', 'Reduced armor.', '', '', '', '护甲值降低。', '', '');
INSERT INTO `locales_spell` VALUES (27992, 'Mana Burn', '', '', '', '法力燃烧', '', '', '', '', '', '', '', '', '', 'Hits an enemy with an anti-mana bolt. For each point of mana consumed by the bolt, the target takes $e1 damage.', '', '', '', '向敌人射出一支可抽取法力值的箭，每抽取1点法力值，目标就受到$e1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (27993, 'Stomp', '', '', '', '践踏', '', '', '', '', '', '', '', '', '', 'Inflicts normal damage plus $s1 to nearby enemies, reducing movement speed for $d.', '', '', '', '对附近的敌人造成普通伤害再加上$s1点伤害，并使它们的移动速度降低，效果持续$d。', '', '', 'Movement speed reduced by $s2%.', '', '', '', '移动速度降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (27994, 'Drain Life', '', '', '', '吸取生命', '', '', '', '', '', '', '', '', '', 'Drains $o1 health from an enemy over $d., transferring it to the caster.', '', '', '', '在$d内从敌人身上吸取总计$o1点生命值，并将其转移给施法者。', '', '', '$o1 health leeched over $d.', '', '', '', '在$d内吸取总计$o1点生命值。', '', '');
