INSERT INTO `locales_spell` VALUES (28264, 'Increase Spell Dam 46', '', '', '', '提高法术伤害46', '', '', '', '', '', '', '', '', '', 'Increases damage and healing done by magical spells and effects by up to $s1.', '', '', '', '提高所有法术和魔法效果所造成的伤害和治疗效果，最多$s1点。', '', '', '', '', '', '', '', '', '');
