INSERT INTO `locales_spell` VALUES (28270, 'Polymorph: Cow', '', '', '', '变形术：奶牛', '', '', '', '', '', '', '', '', '', 'Transforms the enemy into a cow, forcing it to wander around for up to $d.  While wandering, the cow cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成一头牛，使其在周围到处闲逛，最多持续$d。在这个过程中，牛无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让牛恢复正常状态。每个法师在同一时间内只能将一个目标变形，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (28271, 'Polymorph: Turtle', '', '', '', '变形术：龟', '', '', '', '', '', '', '等级 1', '', '', 'Transforms the enemy into a turtle, forcing it to wander around for up to $d.  While wandering, the turtle cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成一只乌龟，使其在周围到处闲逛，最多持续$d。在这个过程中，乌龟无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让乌龟恢复正常状态。每个法师在同一时间内只能将一个目标变形，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (28272, 'Polymorph: Pig', '', '', '', '变形术：猪', '', '', '', '', '', '', '等级 1', '', '', 'Transforms the enemy into a pig, forcing it to wander around for up to $d.  While wandering, the pig cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成一只猪，使其在周围到处闲逛，最多持续$d。在这个过程中，猪无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让猪恢复正常状态。每个法师在同一时间内只能将一个目标变形，只能对野兽、人型生物和小动物施放。', '', '', 'Cannot attack or cast spells.  Increased regeneration.', '', '', '', '不能攻击或施法。回复速度提高。', '', '');
