INSERT INTO `locales_spell` VALUES (28293, 'Chain Lightning', '', '', '', '闪电链', '', '', '', '', '', '', '', '', '', 'Strikes nearby enemies with a lightning bolt that arcs to another nearby enemies. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.', '', '', '', '向附近的敌人发射闪电箭，并在击中目标后跳跃到邻近的敌人身上。这个法术可以伤害最多$x1个目标，每次跳跃都造成更高的自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (28294, 'Lightning Totem', '', '', '', '闪电图腾', '', '', '', '', '', '', '', '', '', 'Summons an Lightning Totem that lasts $d. and periodically damages nearby enemies.', '', '', '', '召唤一个持续$d的闪电图腾，对周围的敌人造成持续伤害。', '', '', '', '', '', '', '', '', '');
