INSERT INTO `locales_spell` VALUES (28310, 'Mind Flay', '', '', '', '精神鞭笞', '', '', '', '', '', '', '', '', '', 'Inflicts Shadow damage to an enemy and reduces its movement speed for $d.', '', '', '', '对敌人造成暗影伤害，并降低其移动速度，持续$d。', '', '', '$s1 Shadow damage inflicted every second for $d.\nReduced movement speed.', '', '', '', '每秒受到$s1点暗影伤害，持续$d。\n移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (28311, 'Slime Bolt', '', '', '', '软泥之箭', '', '', '', '', '', '', '', '', '', 'Shoots poison at an enemy, inflicting Nature damage, then additional damage every $t2 sec. for $d.', '', '', '', '对敌人射出毒液，造成自然伤害，并在接下来的$d内每$t2秒造成一次额外伤害。', '', '', 'Nature damage inflicted every $t2 sec.', '', '', '', '每$t2秒造成一次自然伤害。', '', '');
