INSERT INTO `locales_spell` VALUES (28332, 'Frost Warding', '', '', '', '冰霜障壁', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Increases the armor and resistances given by your Frost Armor and Ice Armor spells by $s1%.  In addition, gives your Frost Ward a $s2% chance to reflect Frost spells and effects while active.', '', '', '', '使你的霜甲术和冰甲术所提供的护甲值和抗性提高$s1%。另外，你的防护冰霜结界有$s2%的几率将冰霜系法术和魔法效果反射给施法者。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (28333, 'Whirlwind Primer', '', '', '', '旋风斩', '', '', '', '', '', '', '', '', '', 'Attacks nearby enemies in a whirlwind of steel that lasts $d. and inflicts normal damage plus $15576s1.', '', '', '', '像旋风一般挥舞手中的武器，攻击周围的所有敌人，对它们造成普通伤害再加上$15576s1点伤害，持续$d。', '', '', 'Attacking all nearby enemies for normal damage plus $15576s1.', '', '', '', '对附近的所有敌人造成武器伤害外加$15576s1点伤害。', '', '');
