INSERT INTO `locales_spell` VALUES (29055, 'Refreshing Red Apple', '', '', '', '甜美的红苹果', '', '', '', '', '', '', '', '', '', 'Restores $s1% of your health and mana per second for $d.  Must remain seated while eating.', '', '', '', '每秒恢复总生命值和法力值的$s1%，持续$d。进食时必须保持坐姿。', '', '', 'Restores $s1% of your health and mana per second.', '', '', '', '每秒为你回复$s1%的生命值和法力值。', '', '');
