INSERT INTO `locales_spell` VALUES (29061, 'Shield Wall', '', '', '', '盾墙', '', '', '', '', '', '', '', '', '', 'Reduces the Physical and magical damage taken by the caster by $s1% for $d.', '', '', '', '使你在遭到物理和法术攻击时所承受的伤害值降低$s1%，持续$d。', '', '', 'Physical and magical damage taken is reduced by $s1%.', '', '', '', '受到物理和魔法攻击时承受的伤害降低$s1%。', '', '');
