INSERT INTO `locales_spell` VALUES (29212, 'Cripple', '', '', '', '残废术', '', '', '', '', '', '', '', '', '', 'Increases the time between an enemy\'s attacks by $s2% and its movement by $s1%, in addition to reducing its Strength by $s3%. Lasts $d.', '', '', '', '使敌人的攻击间隔延长$s2%，移动速度降低$s1%，力量降低$s3%。持续$d。', '', '', 'Movement speed reduced by $s1%.\nTime between attacks increased by $s2%.\nStrength reduced by $s3%.', '', '', '', '攻击间隔延长$s2%。\n移动速度降低$s1%。\n力量降低$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (29213, 'Curse of the Plaguebringer', '', '', '', '瘟疫使者的诅咒', '', '', '', '', '', '', '', '', '', 'Curses the target with the Curse of the Plaguebringer. If the target is not dispelled of the curse, the target will become infected along with all nearby allies in a selected area with the Wrath of the Plaguebringer.', '', '', '', '使目标受到瘟疫使者的诅咒。如果目标未被驱散诅咒，则周围的玩家都会受到瘟疫使者之怒的影响。', '', '', 'The Plague awaits you....', '', '', '', '瘟疫在等着你……', '', '');
