INSERT INTO `locales_spell` VALUES (29848, 'Polymorph', '', '', '', '变形术', '', '', '', '', '', '', '', '', '', 'Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.', '', '', '', '将敌人变成绵羊，使其在周围到处闲逛，最多持续$d。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物或小动物施放。', '', '', 'Cannot attack or cast spells.\nHealth regeneration increased.', '', '', '', '不能攻击或施法。\n生命值回复速度提高。', '', '');
INSERT INTO `locales_spell` VALUES (29849, 'Frost Nova', '', '', '', '冰霜新星', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to nearby enemies, immobilizing them for up to $d.', '', '', '', '对附近的敌人造成冰霜伤害，使他们无法移动，持续最多$d。', '', '', 'Immobilized.', '', '', '', '不能移动。', '', '');
INSERT INTO `locales_spell` VALUES (29851, 'Whirlwind', '', '', '', '旋风斩', '', '', '', '', '', '', '', '', '', 'Attacks nearby enemies in a whirlwind of steel that lasts $d. and inflicts normal damage plus $15589s1.', '', '', '', '像旋风一般挥舞手中的武器，攻击周围的所有敌人，对它们造成普通伤害再加上$15589s1点伤害，持续$d。', '', '', 'Attacking all nearby enemies for normal damage plus $15589s1.', '', '', '', '对附近的所有敌人造成武器伤害外加$15589s1点伤害。', '', '');
