INSERT INTO `locales_spell` VALUES (30081, 'Retching Plague', '', '', '', '作呕瘟疫', '', '', '', '', '', '', '', '', '', 'Diseases an enemy for $d., increasing the Physical damage it takes by $s1 and reducing its Stamina by $s2. The diseased target has $h% chance of spreading its illness to one of its nearby allies when struck in combat.', '', '', '', '使目标感染疾病，在受到物理攻击时承受的伤害提高$s1点，耐力降低$s2点，持续$d。感染疾病的目标有$h%的几率在被击中时将疾病传染给附近的盟友。', '', '', 'Physical damage taken is increased by $s1.\nStamina reduced by $s2.\n$h% chance to spread Retching Plague on hit.', '', '', '', '受到物理攻击时承受的伤害提高$s1点。\n耐力降低$s2点。\n有$h%的几率在被击中时传播作呕瘟疫。', '', '');
