INSERT INTO `locales_spell` VALUES (30091, 'Flamestrike', '', '', '', '烈焰冲击', '', '', '', '', '', '', '', '', '', 'Calls down a pillar of flame, burning all enemies in a selected area and inflicting additional damage every $t2 sec. for $d.', '', '', '', '召唤一根火柱，灼烧指定区域内的所有敌人，并对它们每$t2秒造成一次额外伤害，持续$d。', '', '', 'Fire damage inflicted every $t2 sec.', '', '', '', '每$t2秒受到一次火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (30092, 'Blast Wave', '', '', '', '冲击波', '', '', '', '', '', '', '', '', '', 'Unleashes a wave of flame, inflicting Fire damage to nearby enemies and reducing their movement speed for $d.', '', '', '', '施法者放出一道火焰冲击波，所有被冲击波触及的敌人都会受到火焰伤害，同时降低移动速度，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
INSERT INTO `locales_spell` VALUES (30093, 'Blizzard', '', '', '', '暴风雪', '', '', '', '', '', '', '', '', '', 'Calls down a blizzard that lasts $d., inflicting $s1 Frost damage every $t1 sec. to all enemies in a selected area.', '', '', '', '召唤持续$d的暴风雪，对指定区域内的所有敌人每$t1秒造成$s1点冰霜伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (30094, 'Frost Nova', '', '', '', '冰霜新星', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to nearby enemies, immobilizing them for up to $d.', '', '', '', '对附近的敌人造成冰霜伤害并将其冻结在原地，冻结效果最多可持续$d。', '', '', 'Immobilized.', '', '', '', '被定身。', '', '');
INSERT INTO `locales_spell` VALUES (30095, 'Cone of Cold', '', '', '', '寒冷之锥', '', '', '', '', '', '', '', '', '', 'Inflicts Frost damage to enemies in a cone in front of the caster, reducing their movement speed for $d.', '', '', '', '对施法者面前一个锥形区域内的敌人造成冰霜伤害，并降低他们的移动速度，持续$d。', '', '', 'Reduced movement speed.', '', '', '', '移动速度降低。', '', '');
