INSERT INTO `locales_spell` VALUES (30156, 'Hippogryph Hatchling', '', '', '', '角鹰兽宝宝', '', '', '', '', '', '', '', '', '', 'After a harpy incursion in Feralas, several hippogryph nesting grounds were attacked. Hundreds of hatchlings were orphaned, and they have been entrusted to the care of the druids on Sardor Isle.', '', '', '', '鹰身女妖入侵菲拉斯后，数个角鹰兽筑巢地遭到袭击。数百只幼龟成为孤儿，它们被托付给萨多岛上的德鲁伊照顾。', '', '', '', '', '', '', '', '', '');
