INSERT INTO `locales_spell` VALUES (44026, 'Compounding Flame', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Increases the Fire damage taken by $s1% for $d.', '', '', '', '', '', '', 'Fire damage taken is increased by $s1%.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44027, 'Curse of Ember', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Curses the target for $d, reducing Fire resistances by $s1 and increasing Fire damage taken by $s2%.', '', '', '', '', '', '', 'Reduces Fire resistance by $s1.  Increases Fire damage taken by $s2%.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44028, 'Embernova', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Causes an explosion of fire magic around the caster, causing $s2 Fire damage to all targets within $a2 yards.', '', '', '', '', '', '', '$s1 Fire damage inflicted every $t1 sec.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44029, 'Draconic Eruption Rune', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Causes an explosion of fire magic around the caster, causing $s1 Fire damage to friendly targets within $a1 yards.', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44030, 'Draconic Eruption Rune', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Silenced.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44031, 'Draconic Binding Rune', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Increases the time between nearby enemies\' attacks by $s1%, slows their movement by $s2%, and slow casting speed by $s3% for $d.', '', '', '', '', '', '', 'Time between attacks increased by $s1%.\nMovement speed reduced by $s2%.\nCasting speed reduced by $s3%.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44032, 'Draconic Burning Rune', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Sets the target aflame, causing $o1 Fire damage over $d.', '', '', '', '', '', '', '$s1 Fire damage every $t1 seconds.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (44033, 'Draconic Gaze', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Stuns the target for $d.', '', '', '', '', '', '', 'Stunned.', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45000, 'Fox Kit', '', '', '', '狐狸幼崽', '', '', '', '', '', '', '', '', '', 'During frigid nights, these critters use their fluffy tails as a blanket to stay warm.', '', '', '', '在寒冷的夜晚，这些小动物用毛茸茸的尾巴作为毯子来保暖。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45001, 'Swift Spectral Tiger', '', '', '', '迅捷幽灵虎', '', '', '', '', '', '', '', '', '', 'Historians claim that these incorporeal beasts were created when Draenor exploded, unleashing energies that warped the world\'s flora and fauna.', '', '', '', '历史学家声称，这些无形的野兽是在德拉诺爆炸时创造的，释放出的能量扭曲了世界上的动植物群。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45002, 'Dryad Form', '', '', '', '树妖形态', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '\"What is nature\'s call?\"', '', '', '', '“大自然的召唤是什么？“', '', '');
