INSERT INTO `locales_spell` VALUES (45005, 'Recipe: Delicious Pizza', '', '', '', '食谱：美味披萨', '', '', '', '', '', '', '', '', '', 'Teaches you how to cook Delicious Pizza .', '', '', '', '教你学会烹制美味披萨。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45006, 'Delicious Pizza', '', '', '', '美味披萨', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45007, 'Swift Magic Rooster', '', '', '', '迅捷魔法公鸡', '', '', '', '', '', '', '', '', '', 'Magic in the hands of a genius can do wonderful, miraculous things. Magic in the hands of an idiot can make a giant rooster.', '', '', '', '天才手中的魔法可以创造奇妙的事情。白痴手中的魔法可以变成一只巨大的公鸡。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45008, 'White Riding Bear', '', '', '', '白色战熊', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Bear. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的熊。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45009, 'Black Riding Bear', '', '', '', '黑色战熊', '', '', '', '', '', '', '', '', '', 'He\'s big, he\'s ready for battle, and he\'s a bear. What more could you want in a mount?', '', '', '', '他很大，他已经做好了战斗的准备，而且他是一只熊。您还想要什么？', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
