INSERT INTO `locales_spell` VALUES (45014, 'Enchanted Broom', '', '', '', '魔法扫帚', '', '', '', '', '', '', '', '', '', 'Created by a high elf apprentice, this broom would be extremely useful if anyone could figure out how to make it stop.', '', '', '', '这把扫帚是由一名高等精灵学徒创造的，如果有人能弄清楚如何让它停下来的话，它将非常有用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45015, 'Thalassian Tender', '', '', '', '萨拉塔斯树苗', '', '', '', '', '', '', '', '', '', 'It always wakes up dancing. What a happy little tree!', '', '', '', '它总是在跳舞中醒来。多么幸福的小树呀！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45016, 'Dryad Fawn', '', '', '', '树妖小鹿', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your Dryad Fawn.', '', '', '', '右键点击以召唤或解散你的树妖小鹿。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45017, 'Summon Thalassian Warhorse', '', '', '', '召唤萨拉斯军马', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a warhorse, which serves as a mount. Speed is increased based on your Riding skill.', '', '', '', '召唤一匹战马，作为坐骑。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
