INSERT INTO `locales_spell` VALUES (45019, 'Summon Thalassian Charger', '', '', '', '召唤萨拉斯战马', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a Charger, which serves as a mount. Speed is increased based on your Riding skill.', '', '', '', '召唤一个充电器，用作坐骑。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45020, 'Summon Argent Charger', '', '', '', '召唤银色战马', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a Charger, which serves as a mount. Speed is increased based on your Riding skill.', '', '', '', '召唤一个充电器，用作坐骑。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45021, 'Dragonhawk Hatchling', '', '', '', '龙鹰幼崽', '', '', '', '', '', '', '', '', '', 'Once prized by dragonhawk breeders in Silvermoon. Stands out at night to predators, making it necessary to gain awareness at an early age.', '', '', '', '曾被银月城的龙鹰饲养者所珍视。在夜间对掠食者来说很显眼，因此有必要在很小的时候就获得认识。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45022, 'Thalassian Orphan', '', '', '', '萨拉斯孤儿', '', '', '', '', '', '', '', '', '', 'Summon and dismiss the orphan you\'ve agreed to look after.', '', '', '', '召唤并解散你同意照顾的孤儿。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45023, 'Cheeky Monkey', '', '', '', '顽皮猴子', '', '', '', '', '', '', '', '', '', 'The monkeys of Azeroth are infamous tricksters, and these beloved companions of the Darkmoon Faire have taken that innate cunning to a whole new level.', '', '', '', '艾泽拉斯的猴子是臭名昭著的骗子，这些暗月马戏团心爱的伙伴将它们与生俱来的狡猾提升到了一个全新的水平。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45024, 'Food', '', '', '', '进食', '', '', '', '', '', '', '', '', '', 'Restores $o1 health over $d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain 25 Stamina for $24799d.', '', '', '', '在$d内恢复总计$o1点生命值，进食时必须保持坐姿。如果你花费至少10秒钟来进食，你的耐力将提高25点，持续$24799d。', '', '', 'Restores $/5;s1 health per second.', '', '', '', '每秒恢复$/5;s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (45025, 'Female Elven Mage Form', '', '', '', '女性精灵法师形态', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
