INSERT INTO `locales_spell` VALUES (45028, 'Summon Scarlet Warhorse', '', '', '', '召唤血色军马', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a warhorse, which serves as a mount. Speed is increased based on your Riding skill.', '', '', '', '召唤一匹战马，作为坐骑。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45029, 'Summon Scarlet Charger', '', '', '', '召唤血色战马', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a Charger, which serves as a mount. Speed is increased based on your Riding skill.', '', '', '', '召唤一个充电器，用作坐骑。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45030, 'Summon Spectral Fox', '', '', '', '召唤幽灵狐', '', '', '', '', '', '', '', '', '', 'Summons a Fox to fight for you for $d.', '', '', '', '召唤一只幽灵狐为你战斗，持续时间$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45031, 'Summon Arcane Elemental', '', '', '', '召唤奥术元素', '', '', '', '', '', '', '', '', '', 'In case of darkness, this little elemental is an infinite source of a soothing blue glow.', '', '', '', '在黑暗的情况下，这个小元素是舒缓蓝色光芒的无限来源。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45032, 'Swift Red Ram', '', '', '', '迅捷红色战羊', '', '', '', '', '', '', '', '', '', 'Wildhammer Fact Checker claims that this specific breed was the first type of ram domesticated by the dwarves when they settled in Dun Morogh.', '', '', '', '蛮锤事实核查者声称，这种特定品种是矮人定居丹莫罗时驯化的第一种公羊。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45033, 'Swift Brewfest Ram', '', '', '', '迅捷美酒节战羊', '', '', '', '', '', '', '', '', '', 'Dwarves attribute this breed\'s even temperament to rigorous training, but other races argue that a daily diet of strong ale has something to do with it.', '', '', '', '矮人将这个品种的均匀性情归因于严格的训练，但其他种族则认为这与每天喝烈性啤酒有关。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45034, 'Brewfest Ram', '', '', '', '美酒节战羊', '', '', '', '', '', '', '', '', '', 'Brewers retired this mount from active advertising service after complaints that the beasts were \"too temperamental\" to control in major cities.', '', '', '', '在抱怨这些野兽“脾气太暴躁”而无法在大城市中控制后，酿酒商从积极的广告服务中退役了这匹坐骑。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45035, 'Flaxen Riding Saber', '', '', '', '亚麻色利刃豹', '', '', '', '', '', '', '', '', '', 'Night elves once believed that seeing this light colored saber breed in the wild was an ill omen.', '', '', '', '暗夜精灵曾经相信，在野外看到这种浅色的剑品种是一种不祥的预兆。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45036, 'Swift Darnassian Nightsaber', '', '', '', '迅捷达纳苏斯夜刃豹', '', '', '', '', '', '', '', '', '', 'When a night elf\'s mount perishes, it is custom for the rider to keep one of the saber\'s great fangs as a token of remembrance.', '', '', '', '当暗夜精灵的坐骑死去时，骑手会按照惯例保留其中一根军刀的巨大尖牙作为纪念。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45037, 'Swift Horde Worg', '', '', '', '迅捷部落座狼', '', '', '', '', '', '', '', '', '', 'If asked to fetch, will most likely bring you back the head of a small mammal or humanoid.', '', '', '', '如果被要求去取，很可能会带回小型哺乳动物或人形生物的头部。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45038, 'Swift Gray Worg', '', '', '', '迅捷灰色座狼', '', '', '', '', '', '', '', '', '', 'The wolves of the Horde are befriended, not domesticated.', '', '', '', '部落的狼是被友善对待的，而不是被驯化的。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45039, 'Swift Alliance Steed', '', '', '', '迅捷联盟战马', '', '', '', '', '', '', '', '', '', 'Armored to withstand collisions in battle.', '', '', '', '装甲可以承受战斗中的碰撞。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45040, 'Swift Gray Steed', '', '', '', '迅捷灰色战马', '', '', '', '', '', '', '', '', '', 'A veteran of some of the toughest battles fought by the Alliance.', '', '', '', '一位参加过联盟最艰苦战斗的老兵。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45041, 'Swift Blue Riding Raptor', '', '', '', '迅捷蓝色迅猛龙', '', '', '', '', '', '', '', '', '', 'Speed, cunning, and ferocity are the things trolls and raptors admire about each other.', '', '', '', '速度、狡猾和凶猛是巨魔和猛禽相互钦佩的地方。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45042, 'Swift Crimson Skeletal Steed', '', '', '', '迅捷深红骷髅战马', '', '', '', '', '', '', '', '', '', 'Some horses merely adopt the dark. This horse was born in it.', '', '', '', '有些马只喜欢黑暗。这匹马就诞生在其中。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45043, 'Swift Forsaken Skeletal Steed', '', '', '', '迅捷被遗忘者骷髅战马', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Skeletal Steed. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一匹可供骑乘的骷髅战马。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45044, 'Swift Blood Kodo', '', '', '', '迅捷血色科多兽', '', '', '', '', '', '', '', '', '', 'An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through Mulgore.', '', '', '', '这只科多兽是科多兽群中的头号成员，是席卷莫高雷的强大生物的典型代表。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45045, 'Armored Brewfest Kodo', '', '', '', '迅捷美酒节科多兽', '', '', '', '', '', '', '', '', '', 'A festive mount, celebrating the joyous spirit of Brewfest.', '', '', '', '喜庆的坐骑，庆祝美酒节的欢乐精神。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45046, 'Swift Gnomeregan Mechastrider', '', '', '', '迅捷诺莫瑞根机甲陆行鸟', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Mechastrider. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的机械陆行者。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45047, 'Swift Armored Unicorn', '', '', '', '迅捷装甲独角兽', '', '', '', '', '', '', '', '', '', 'A mythical creature, protected by enchanted armor, embodying grace and power.', '', '', '', '一种神话生物，受到魔法盔甲的保护，体现了优雅和力量。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45048, 'Swift Thalassian Unicorn', '', '', '', '迅捷萨拉斯独角兽', '', '', '', '', '', '', '', '', '', 'A majestic mount, hailing from the enchanted forests of Quel\'Thalas.', '', '', '', '一匹雄伟的坐骑，来自奎尔萨拉斯的魔法森林。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45049, 'Thalassian Unicorn', '', '', '', '萨拉斯独角兽', '', '', '', '', '', '', '', '', '', 'A rare and magical creature, sought after by those who appreciate beauty and elegance.', '', '', '', '一种稀有而神奇的生物，受到那些欣赏美丽和优雅的人的追捧。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45050, 'Swift Red Rocket Car', '', '', '', '迅捷红色火箭车', '', '', '', '', '', '', '', '', '', 'Always go twenty over the speed limit.', '', '', '', '始终超过速度限制二十。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (45051, 'Swift Blue Rocket Car', '', '', '', '迅捷蓝色火箭车', '', '', '', '', '', '', '', '', '', 'Airbags not included.', '', '', '', '不包括安全气囊。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
