INSERT INTO `locales_spell` VALUES (45300, 'Venomhide Poison', '', '', '', '毒皮毒药', '', '', '', '', '', '', '', '', '', 'Coats a weapon with poison that lasts for 5 minutes.\nEach strike has a $h% chance of poisoning the enemy for $14795o1 Nature damage over $14795d.  Stacks up to 5 times on a single target.  15 charges.', '', '', '', '给一件武器浸毒，效果持续5分钟。\n每次攻击都有$h%的几率令敌人中毒，在$14795d内对其造成$14795o1点自然伤害。对单一目标最多可以叠加5次。可使用15次。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45301, 'Venomhide Poison', '', '', '', '毒皮毒药', '', '', '', '', '', '', '', '', '', 'Teaches Venhomide Poison.', '', '', '', '教你学会施放毒皮毒药。', '', '', '', '', '', '', '', '', '');
