INSERT INTO `locales_spell` VALUES (45400, 'Frostfire Bolt', '', '', '', '霜火箭', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Launches a bolt of frostfire at the enemy, causing $s1 frost and fire damage, slowing movement speed by $s3% and causing an additional $s2 fire damage over $d sec. This spell will be checked against the lower of the target\'s Frost and Fire resists.', '', '', '', '向目标释放霜火箭，造成$s1点伤害，使目标减速$s3%，并在$d内造成额外$s2点火焰伤害。此法术将检测目标的冰霜抗性和火焰抗性，依据较低的一项造成伤害。', '', '', '$s2 Fire damage every $t2 seconds.', '', '', '', '每$t2秒造成$s2点火焰伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45401, 'Water Elemental', '', '', '', '召唤水元素', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summon a Water Elemental to fight for the caster for $d.', '', '', '', '召唤一个水元素为你战斗，持续时间$d。', '', '', '', '', '', '', '', '', '');
