INSERT INTO `locales_spell` VALUES (45406, 'Brilliance Aura', '', '', '', '辉煌光环', '', '', '', '', '', '', '', '', '', 'Allows $s1% Mana regeneration to continue while casting for party members within $a1 yards. Lasts until cancelled.', '', '', '', '在为 $a1 码内的小队成员施法时，允许继续恢复 $s1% 法力。持续到取消为止。', '', '', 'Mana regeneration while casting increased by $s1%.', '', '', '', '施法时法力回复增加$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45407, 'Ritual of Refreshment', '', '', '', '召唤餐桌', '', '', '', '', '', '', '', '', '', 'Begins a ritual that creates a refreshment table.  Raid members can click the table to acquire Conjured Manna Biscuits.  The tables lasts for 3 min.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must right-click the refreshment portal and not move until the ritual is complete.', '', '', '', '开启一个召唤餐桌的仪式。团队成员可以点击餐桌获取魔法点心。餐桌存在3分钟。需要施法者和2个团队成员共同完成仪式。参与者必须右键点击召唤餐桌的传送门，并且在仪式结束之前不得移动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45408, 'Brilliance Aura', '', '', '', '辉煌光环', '', '', '', '', '', '', '', '', '', 'Gives additional Mana regeneration to the Mage and his Party Members equal to $s1% of the Caster\'s mana regeneration within $a1 yards. Lasts until cancelled.', '', '', '', '为法师及其队友提供额外的法力回复，相当于 $a1 码内施法者法力回复的 $s1%。持续到取消为止。', '', '', 'Mana regeneration while casting increased by a portion of the Mage\'s.', '', '', '', '施法时法力回复根据法师法力回复能力的百分比增加。', '', '');
INSERT INTO `locales_spell` VALUES (45409, 'Crusader Strike', '', '', '', '十字军打击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A strike that causes $s2 damage and increases the holy damage taken by the target by up to $s1 per Crusader Strike.  Can be applied up to 5 times.  Lasts $d.', '', '', '', '对目标造成$s2点伤害，每次十字军打击都可使目标在受到神圣伤害时多承受$s1点额外神圣伤害，共可累加5次。持续$d。', '', '', 'Increases Holy damage taken by up to $s1.', '', '', '', '受到的神圣伤害增加$s1点。', '', '');
