INSERT INTO `locales_spell` VALUES (45414, 'Runic Shield', '', '', '', '符文盾', '', '', '', '', '', '', '', '', '', 'A protective ward surrounds the caster absorbing $s1 magical damage. While the shield holds, gain 600 armor. Lasts $d.', '', '', '', '施法者周围有一个保护结界，可吸收 s1 美元的魔法伤害。当盾牌持有时，获得 600 点护甲值。持续$d。', '', '', 'Absorbs damage.', '', '', '', '吸收伤害。', '', '');
