INSERT INTO `locales_spell` VALUES (45417, 'Potent Venom', '', '', '', '烈性毒液', '', '', '', '', '', '', '', '', '', 'Your direct melee and ranged attacks have a chance to inject poison into your target that deals 100 Nature damage over 12 sec. Stacks up to 5 times.', '', '', '', '你的近战和远程攻击有几率向你的目标注入毒液，在 8 秒内造成 100 点自然伤害。最多可叠加 5 次。', '', '', 'Your direct melee and ranged attacks have a chance to inject poison into your target that deals 100 Nature damage over 12 sec. Stacks up to 5 times.', '', '', '', '你的近战和远程攻击有几率向你的目标注入毒液，在 8 秒内造成 100 点自然伤害。最多可叠加 5 次。', '', '');
