INSERT INTO `locales_spell` VALUES (45498, 'Blood Tiger\'s Blessing', '', '', '', '血虎的祝福', '', '', '', '', '', '', '', '', '', 'Your damaging spells and melee attacks have a 3% chance to steal $45497s1 life from the target enemy.', '', '', '', '你的伤害性法术和近战攻击有 3% 的几率从目标敌人身上窃取 $45497s1 生命。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45499, 'Blood Plague', '', '', '', '血瘟疫', '', '', '', '', '', '', '', '', '', 'Deals $s1 Shadow damage every $t1 sec for $d. All damage done is then transferred to the caster.', '', '', '', '每 $t1 秒造成 $s1 暗影伤害，持续 $d。所有造成的伤害都会转移到施法者身上。', '', '', 'Deals $s1 Shadow damage every $t1 sec.', '', '', '', '每 $t1 秒造成 $s1 暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45500, 'Spirit Link', '', '', '', '灵魂链接', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Links the spirit of an ally to that of other group members within 15 yards. When the target takes damage, $s1% is distributed among nearby allies. Lasts $d.', '', '', '', '将一个盟友的灵魂与15码内其他团队成员的灵魂联系起来。目标所受伤害的$s1%会分摊给附近的成员。持续$d。', '', '', 'Splitting $s1% of all damage taken with group members.', '', '', '', '与团队成员分摊所有受到的伤害的 $s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45501, 'Blood Plague', '', '', '', '血瘟疫', '', '', '', '', '', '', '', '', '', 'Your damaging spells have a 4% chance to inflict the target with a disease that causes 120 Shadow damage over 6 sec. Damage caused by the disease heals you.', '', '', '', '你的伤害性法术有 4% 的几率使目标罹患疾病，在 6 秒内造成 120 点暗影伤害。疾病造成的伤害可以治愈你。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45502, 'Ethereal Form', '', '', '', '灵体形态', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Makes the Shaman take $s1% less physical damage, but unable to cast spells for $d.', '', '', '', '使萨满祭司受到的物理伤害减少$s1%，期间无法施法，持续$d。', '', '', 'Walking with the spirits.', '', '', '', '与灵魂同行。', '', '');
INSERT INTO `locales_spell` VALUES (45503, 'Big Bad Voodoo', '', '', '', '终极巫毒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Channels the power of the spirits, rendering nearby party members immune to all damage and effects for $d. Does not affect the caster.', '', '', '', '引导灵魂的力量，使附近除施法者以外的团队成员免疫所有伤害和效果，持续$d。', '', '', 'We be jammin\'!', '', '', '', '我们被干扰了！', '', '');
INSERT INTO `locales_spell` VALUES (45504, 'Hex', '', '', '', '妖术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Transforms the enemy into a frog that cannot cast, and does $s3% less damage for up to $d. Only works on Beasts, Humanoids and Critters.', '', '', '', '将敌人变成一只青蛙，使其无法施法，并减少$s3%的伤害，最多持续$d。只能对野兽、人型生物和小动物使用。', '', '', 'Cannot cast spells and damage reduced by $s3%.', '', '', '', '沉默，伤害降低$s3%。', '', '');
INSERT INTO `locales_spell` VALUES (45505, 'Feral Spirit', '', '', '', '野性狼魂', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Summons two Spirit Wolves under the command of the Shaman for $d.', '', '', '', '召唤两只幽灵狼为萨满祭司作战，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45506, 'Earthquake', '', '', '', '地震术', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Creates a violent earthquake in the target area causing $s1 Physical damage to enemies every $t1 sec, and reducing their speed by $s2% in an 8 yard radius.  Lasts $d.  Shaman must channel to maintain the spell.', '', '', '', '在目标区域制造强烈地震，每$t1秒对8码半径内的敌人造成$s1点物理伤害，并使敌人速度降低$s2%。持续$d。萨满必须引导才能维持法术。', '', '', '$s1 damage every $t1 seconds, and reducing speed by $s2%.', '', '', '', '每$t1秒造成$s1点伤害，并降低$s2%的速度。', '', '');
INSERT INTO `locales_spell` VALUES (45508, 'Thunderhead', '', '', '', '雷暴', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows your Lightning Shield to be cast on allies and reduces its mana cost by 20%. Only usable on one ally at a time.', '', '', '', '使你的闪电之盾可以对盟友使用，并减少20%的法力消耗。只能对一个盟友使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45509, 'Bloodlust', '', '', '', '嗜血', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases melee, ranged, and spell casting speed by $s1% for a target party member within $r yards.  Lasts $d.', '', '', '', '使$r码内一名目标队员的近战、远程和施法速度提高$s1%。持续$d。', '', '', 'Melee, ranged, and spell casting speed increased by $s1%.', '', '', '', '近战、远程和施法速度提高$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45510, 'Bloodlust', '', '', '', '嗜血', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Teaches Bloodlust (Rank 1).', '', '', '', '教你学会施放嗜血（等级 1）。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45511, 'Bloodlust', '', '', '', '嗜血', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Increases melee, ranged, and spell casting speed by $s1% for a target party member within $r yards.  Lasts $d.', '', '', '', '使$r码内一名目标队员的近战、远程和施法速度提高$s1%。持续$d。', '', '', 'Melee, ranged, and spell casting speed increased by $s1%.', '', '', '', '近战、远程和施法速度提高$s1%。', '', '');
