INSERT INTO `locales_spell` VALUES (45521, 'Stormstrike', '', '', '', '风暴打击', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Gives you an extra attack.  In addition, the next 2 sources of Nature damage dealt to the target are increased by $s2%.  Lasts $d.', '', '', '', '使你获得一次额外的攻击机会，另外，你的下2次攻击对敌人造成的自然伤害提高$s2%，持续$d。', '', '', 'Increases Nature damage taken by $s2%.', '', '', '', '自然伤害提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (45522, 'Poison Bolt', '', '', '', '毒箭', '', '', '', '', '', '', '', '', '', 'Shoots poison at an enemy, inflicting $s1 Nature damage.', '', '', '', '向敌人发射毒药，造成 $s1 自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45523, 'Poisonous Strikes', '', '', '', '毒击', '', '', '', '', '', '', '', '', '', 'Your finishing moves have a $b1% chance per combo point to deal $45522s1 Nature damage.', '', '', '', '你的终结技每连击点有 $b1% 的几率造成 $45522s1 自然伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45524, 'Sated', '', '', '', '疲倦', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Cannot benefit from Bloodlust or other similar effects. ', '', '', '', '无法从嗜血或其他类似效果中获得增益。', '', '');
INSERT INTO `locales_spell` VALUES (45525, 'Earth Shield', '', '', '', '大地之盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The caster is surrounded with an earthen shield, giving a $s2% chance of ignoring spell interruption when damaged and causing attacks to heal the Shaman for $45526s1. This effect can only occur once every few seconds. $n charges. Lasts 10 min. Only one elemental shield can be active on the Shaman at any one time.', '', '', '', '施法者被土盾包围，施法时有$s2%的几率不会延长施法时间，受到攻击时恢复$45526s1点生命值。间隔数秒触发一次，最多生效$n次，持续$d。同时只能存在一个元素护盾。', '', '', '$s2% chance to ignore spell interruption when damaged and attacks heal the Shaman for $45526s1.', '', '', '', '施法时有$s2%的几率忽视打断，受到攻击有几率恢复$45526s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (45526, 'Earth Shield', '', '', '', '大地之盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45527, 'Water Shield', '', '', '', '水之护盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The caster is surrounded by $n globes of water. When a spell, melee or ranged attack hits the caster, 130 mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts $d. Only one elemental shield can be active on the Shaman at any one time.', '', '', '', '施法者被 $n 个水球包围。当法术、近战或远程攻击击中施法者时，施法者会恢复 130 点法力。这会消耗一个水球。每隔几秒只有一个地球仪会激活。持续$d。萨满祭司在同一时间只能激活一个元素护盾。', '', '', 'Attacks and spells used against you restore 130 mana. $n charges.', '', '', '', '受到攻击有几率恢复$45528s1点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (45528, 'Water Shield', '', '', '', '水之护盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45529, 'Calm Elements', '', '', '', '安抚元素', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Calms the target, reducing the range at which it will attack you by $s1 yards.  Only affects Elemental targets level $v or lower.  Lasts $d.', '', '', '', '安抚目标，使它的警戒范围减少$s1码。只对$v级及以下等级的目标有效。持续$d。', '', '', 'Reduced distance at which target will attack.', '', '', '', '减小目标的警戒范围。', '', '');
INSERT INTO `locales_spell` VALUES (45530, 'Reduce Crit 1', '', '', '', '减少暴击1', '', '', '', '', '', '', '', '', '', 'Reduces your chance to get critically hit by $s1%.', '', '', '', '减少你受到重击的几率 $s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45531, 'Reduce Crit 2', '', '', '', '减少暴击2', '', '', '', '', '', '', '', '', '', 'Reduces your chance to get critically hit by $s1%.', '', '', '', '减少你受到重击的几率 $s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45532, 'Reduce Crit 3', '', '', '', '减少暴击3', '', '', '', '', '', '', '', '', '', 'Reduces your chance to get critically hit by $s1%.', '', '', '', '减少你受到重击的几率 $s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45534, 'Lava Lash', '', '', '', '熔岩猛击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Charge your weapon with lava, instantly dealing $s1% Weapon Damage as fire damage. Damage is increased by $s2% if your weapon is enchanted with Flametongue.', '', '', '', '以熔岩附着你的武器,立即造成武器伤害$s1%的火焰伤害。如果你的武器被火舌武器附魔，伤害增加$s2%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45535, 'Arcane Vulnerability', '', '', '', '奥术漏洞', '', '', '', '', '', '', '', '', '', 'Blasts a target for $s1 Arcane damage and increases Arcane damage taken by $s2 for $d.', '', '', '', '爆炸目标造成 $s1 奥术伤害，并增加 $s2 受到的奥术伤害 $d。', '', '', 'Increases damage taken from Arcane spells by up to $s2.', '', '', '', '使奥术法术造成的伤害最多增加 $s2。', '', '');
INSERT INTO `locales_spell` VALUES (45536, 'Healing Rain', '', '', '', '治疗之雨', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Blanket the target area in healing rains, restoring $o1 health to party members over $d.', '', '', '', '在目标区域降下治疗之雨,在$d内为团队成员恢复$o1点生命值。', '', '', '$s1 healing every $t1 seconds.', '', '', '', '每$t1秒恢复$s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (45537, '[PH] Fire Nova', '', '', '', '火焰新星', '', '', '', '', '', '', '', '', '', 'Causes the shaman\'s active Fire totem to emit a wave of flames after 4 seconds, inflicting 893 to 997 Fire damage to enemies within 10 yards of the totem.', '', '', '', '火焰图腾在4秒后对10码内的敌人造成893到997点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45538, '[PH] Mana Tide', '', '', '', '法力潮汐', '', '', '', '', '', '', '', '', '', 'Causes the shaman\'s active Water totem to emit a tide of water, restoreing 290 mana every 3 seconds to group members within 20 yards.', '', '', '', '潮汐图腾每3秒为20码内的团队成员恢复290点法力。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45539, '[PH] Earthgrab', '', '', '', '陷地', '', '', '', '', '', '', '', '', '', 'Causes the shaman\'s active Earth totem to emit a pulse of earth, ensnaring enemies with vines within 10 yards for $d.', '', '', '', '大地图腾束缚10码内的敌人，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45540, '[PH] Harsh Wind', '', '', '', '狂风', '', '', '', '', '', '', '', '', '', 'Causes the shaman\'s active Wind totem to emit a gust of wind, ', '', '', '', '风怒图腾使敌人无法施法并减速。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45541, 'Elemental Focus', '', '', '', '元素集中', '', '', '', '', '', '', '', '', '', 'After landing a critical strike with a Fire, Frost, or Nature damage spell or melee attack, you enter a Clearcasting state.  The Clearcasting state reduces the mana cost of your next 2 damage spells by 40%.', '', '', '', '在你的火焰、冰霜、自然伤害性法术或近战攻击造成致命一击后进入节能施法状态。这个状态可以使你接下来2个伤害性法术所消耗的法力值减少40%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45542, 'Clearcasting', '', '', '', '节能施法', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Your next elemental damage spell has its mana cost reduced by $s1%.', '', '', '', '你的下一个元素伤害法术所消耗的法力值减少$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45543, 'Arcane Vulnerability', '', '', '', '奥术漏洞', '', '', '', '', '', '', '', '', '', 'Chance on landing a damaging spell to deal 75-85 Arcane damage and increase the target\'s Arcane damage taken by 10 for 15 sec. This stacks up to 3 times.', '', '', '', '有几率施展伤害性法术，造成 75-85 点奥术伤害，并使目标受到的奥术伤害增加 10 点，持续 15 秒。最多可叠加 3 次。', '', '', '', '', '', '', '', '', '');
