INSERT INTO `locales_spell` VALUES (45550, 'Improved Divine Spirit', '', '', '', '强化神圣之灵', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Your Divine Spirit and Prayer of Spirit spells also increase the target\'s spell damage and healing by an amount equal to 5% of their total Spirit.', '', '', '', '你的神圣之灵和精神祷言还会增加目标的法术伤害和治疗效果，增加量相当于其精神的5%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45551, 'Prayer of Spirit', '', '', '', '精神祷言', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Power infuses the target\'s party, increasing their Spirit by $s1 for $d.', '', '', '', '使目标队伍成员的精神值增加$s1，持续$d。', '', '', 'Increases Spirit by $s1.', '', '', '', '精神值增加$s1。', '', '');
