INSERT INTO `locales_spell` VALUES (45554, 'Shadow Mend', '', '', '', '暗影治疗', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Heal the friendly target $s1. This spell generates reduced threat.', '', '', '', '治疗友方目标$s1。这个法术产生较低的威胁值。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45555, 'Pain Spike', '', '', '', '痛苦尖刺', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Causes $s1 Shadow damage instantly, but the damage caused will begin healing itself after landing.', '', '', '', '立即造成$s1点暗影伤害，但造成的伤害会在之后自行愈合。', '', '', 'Healing temporary damage.', '', '', '', '恢复暂时损失的生命值。', '', '');
INSERT INTO `locales_spell` VALUES (45556, 'Pain Spike', '', '', '', '痛苦尖刺', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', 'Healing temporary damage.', '', '', '', '恢复暂时损失的生命值。', '', '');
INSERT INTO `locales_spell` VALUES (45557, 'Vampiric Touch', '', '', '', '吸血鬼之触', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the percentage healed by Vampiric Embrace by an additional $s1% and your Vampiric Embrace now causes all party members to also gain mana equal to $s2% of any Shadow spell damage you deal.', '', '', '', '吸血鬼的拥抱的治疗量额外提高$s1%，同时也会为队友恢复法力值，数值相当于你对目标造成的暗影伤害的$s2%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45558, 'Vampiric Touch', '', '', '', '吸血鬼之触', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Increases the percentage healed by Vampiric Embrace by an additional $s1% and your Vampiric Embrace now causes all party members to also gain mana equal to $s2% of any Shadow spell damage you deal.', '', '', '', '吸血鬼的拥抱的治疗量额外提高$s1%，同时也会为队友恢复法力值，数值相当于你对目标造成的暗影伤害的$s2%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45559, 'Shadow Nova', '', '', '', '暗影新星', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Causes an explosion of cursed shadow around the caster, causing $s1 Shadow damage to all enemy targets within $a1 yards. This effect causes increased threat.', '', '', '', '在施法者周围引发诅咒暗影爆炸，对$a1码内所有敌人造成$s1点暗影伤害。这种效果会产生大量威胁。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45560, 'Reflective Shields', '', '', '', '反射护盾', '', '', '', '', '', '', '', '', '', 'Causes $s1% of the damage absorbed by your Power Word: Shield to reflect back at the attacker.  This damage causes no threat.', '', '', '', '将你的真言术：盾吸收伤害的$s1%反射回攻击者。这种伤害不会产生威胁。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45561, 'Reflective Shield', '', '', '', '反射护盾', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45562, 'Proclaim Champion', '', '', '', '勇士誓约', '', '', '', '', '', '', '', '', '', 'Proclaim the friendly target as your champion for 2 hours. Increases armor by 230, all resistances by 10 and allows the use of various Champion spells on that target. Only one Champion can be proclaimed at a time.', '', '', '', '宣布友方目标为你的冠军，持续 2 小时。护甲增加 230，所有抗性增加 10，并允许对该目标使用各种冠军法术。一次只能宣布一名冠军。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45563, 'Champion\'s Grace', '', '', '', '勇士之赐', '', '', '', '', '', '', '', '', '', 'Bestow the target Champion with grace, increasing all healing done by the priest by $s2%. Lasts $d.', '', '', '', '为勇士赐福，提高对勇士$s2%的治疗效果。持续$d。', '', '', 'Healing taken from the priest increased by $s2%.', '', '', '', '牧师对你的治疗效果提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (45564, 'Champion\'s Bond', '', '', '', '勇士之义', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Creates a bond between priest and Champion. When the priest takes damage up to $45570s2 will be taken by the Champion instead. Lasts $d.', '', '', '', '在牧师和勇士之间建立联系。当牧师受到攻击时，勇士会分担最多$45570s2点伤害。持续$d。', '', '', 'Up to $45570s2 damage taken by the priest is taken by the Champion instead. ', '', '', '', '牧师受到的最多$45570s2点伤害由勇士承担。', '', '');
INSERT INTO `locales_spell` VALUES (45565, 'Empower Champion', '', '', '', '赋能勇士', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Empower the target Champion, increasing spell damage done by up to $s2 and attack power by $s3. Lasts $d.', '', '', '', '为勇士赋予力量，法术强度提高$s2点，攻击强度提高$s3点。持续$d。', '', '', 'All healing and spell damage done increased by up to $s2 and attack power by $s3.', '', '', '', '治疗效果和法术伤害提高$s2点，攻击强度提高$s3点。', '', '');
INSERT INTO `locales_spell` VALUES (45566, 'Summon Champion', '', '', '', '召唤勇士', '', '', '', '', '', '', '', '', '', 'Summon the priest\'s Champion from anywhere in the world.', '', '', '', '从世界各地召唤勇士。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45567, 'Revive Champion', '', '', '', '复活勇士', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Return the priest\'s Champion to life with $s2 health and 2800 mana. Cannot be cast when in combat.', '', '', '', '复活勇士并恢复$s2点生命值和2800点法力值。无法在战斗中施放。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45568, 'Holy Champion', '', '', '', '神圣勇士', '', '', '', '', '', '', '', '', '', 'Arise, my champion!', '', '', '', '起来吧，我的勇士！', '', '', 'Proclaimed champion by a priest. Increases armor by $s2 and all resistances by $s3.', '', '', '', '成为牧师的勇士。护甲值提高$s2点，所有抗性提高$s3点。', '', '');
INSERT INTO `locales_spell` VALUES (45569, 'Champion\'s Resolve', '', '', '', '勇士意志', '', '', '', '', '', '', '', '', '', 'Wards the champion against Fear.  The next Fear effect used against the target will fail, using up the ward. Lasts $d.', '', '', '', '提高勇士的意志力，使下一个针对勇士的恐惧效果失效,持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45570, 'Champion\'s Bond', '', '', '', '勇士之义', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'This spell should be automatically casted by the Priest\'s champion onto the Priest.', '', '', '', '这个法术会自动施加到牧师身上。', '', '', 'Up to $s2 damage taken by the priest is taken by the Champion instead. ', '', '', '', '牧师受到的最多$s2点伤害由勇士承担。', '', '');
INSERT INTO `locales_spell` VALUES (45575, 'Improved Shield Block', '', '', '', '强化盾牌格挡', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Allows your Shield Block ability to block an additional attack and increases the duration by $/1000;s2 second.', '', '', '', '使你的盾牌格档技能可以额外格档一次攻击，并使其有效时间延长$/1000;S2秒。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45576, 'Improved Disciplines', '', '', '', '强化戒律', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces the cooldown of your Retaliation, Recklessness and Shield Wall abilities by $/60000;s1 min.', '', '', '', '使你的反击风暴、鲁莽和盾墙技能的冷却时间减少$/60000;s1分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45577, 'Improved Disciplines', '', '', '', '强化戒律', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Reduces the cooldown of your Retaliation, Recklessness and Shield Wall abilities by $/60000;s1 min.', '', '', '', '使你的反击风暴、鲁莽和盾墙技能的冷却时间减少$/60000;s1分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45578, 'Improved Disciplines', '', '', '', '强化戒律', '', '', 'Rank 3', '', '', '', '等级 3', '', '', 'Reduces the cooldown of your Retaliation, Recklessness and Shield Wall abilities by $/60000;s1 min.', '', '', '', '使你的反击风暴、鲁莽和盾墙技能的冷却时间减少$/60000;s1分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45579, 'Devastate', '', '', '', '毁灭打击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'An instant weapon attack that causes $s1% of weapon damage plus $s2 and additional threat for each application of Sunder Armor on the target. In addition, this attack will renew the duration of the Sunder Armor effect.', '', '', '', '立即用武器攻击，造成$s1%武器伤害并附加$s2点伤害，目标身上的每层破甲效果都会增加此次攻击的威胁值。此外，这次攻击会刷新破甲效果的持续时间。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45580, 'Commanding Shout', '', '', '', '命令怒吼', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'The warrior shouts, maximum health of all party members within within $a1 yards by $s1.  Lasts $d.', '', '', '', '战士怒吼，使$a1码范围内所有队员的最大生命值提高$s1点。持续$d。', '', '', 'Increases your maximum health by $s1.', '', '', '', '你的最大生命值提高$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (45581, 'Concussion Blow', '', '', '', '震荡猛击', '', '', 'Enhanced', '', '', '', '增强', '', '', 'A brutal strike that deals weapon damage and stuns the opponent for $d.', '', '', '', '一次残忍的打击，造成武器伤害并击晕对手$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (45582, 'Shield Guard', '', '', '', '持盾护卫', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Guard the friendly target with your shield, causing $s1% of all melee and ranged attacks to attack you instead. Target must remain within $a1 yards of the warrior. A unit can only be guarded by one Shield Guard at a time. The warrior can only Shield Guard one target at a time.', '', '', '', '护卫友方目标，为其分担$s1%近战和远程伤害。目标必须在战士$a1码范围内。战士同一时间只能护卫一个目标，且这个效果不能叠加。', '', '', 'Guarded.', '', '', '', '护卫。', '', '');
INSERT INTO `locales_spell` VALUES (45583, 'Death Scream', '', '', '', '死亡尖啸', '', '', '', '', '', '', '', '', '', 'Let out a terrifying scream that affects 4 nearby enemies for $45585d, causing them to damage their nearby allies for $45585s1 damage upon death.', '', '', '', '发出可怕的尖啸，对周围4个敌人造成$45585d点伤害，若敌人死亡，则对其附近的盟友造成$45585s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45584, 'Die by the Sword', '', '', '', '剑下亡魂', '', '', 'Passive', '', '', '', '被动', '', '', 'Increases your chance to parry attacks by $45589s1% while under the effects of Retaliation.', '', '', '', '在反击风暴状态下你的招架几率提高$45589s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45585, 'Death Scream', '', '', '', '死亡尖啸', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Damages nearby allies upon death.', '', '', '', '死亡时对附近的盟友造成伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45586, 'Stormbolt', '', '', '', '风暴之锤', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Inflicts $s1 damage to an enemy, stunning it for $d.', '', '', '', '对一个敌人造成$s1点伤害，并使其昏迷$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (45587, 'Bladestorm', '', '', '', '剑刃风暴', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'You attack all nearby enemies for $d causing weapon damage plus an additional $9633s1 every $t1 sec.  While under the effects of Bladestorm, you cannot move or perform any other abilities but you do not feel pity or remorse or fear and you cannot be stopped unless killed.', '', '', '', '攻击周围所有敌人，每$t1秒对它们造成武器伤害再加上$9633s1点额外伤害，持续$d。在此状态下你无法移动或使用技能，但你不会感到怜悯、悔恨或恐惧，除非被杀死，否则无法被阻止。', '', '', 'Attacking all nearby enemies in a whirlwind of steel.', '', '', '', '用钢铁般的旋风攻击附近的所有敌人。', '', '');
INSERT INTO `locales_spell` VALUES (45588, 'Bladestorm', '', '', '', '剑刃风暴', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'You attack all nearby enemies for $d causing weapon damage plus an additional $9633s1 every $t1 sec. While under the effects of Bladestorm, you move $s3% slower than normal, but cannot perform any other abilities but you do not feel pity or remorse or fear and you cannot be stopped unless killed.', '', '', '', '攻击周围所有敌人，每$t1秒对它们造成武器伤害再加上$9633s1点额外伤害，持续$d。在此状态下你无法移动或使用技能，但你不会感到怜悯、悔恨或恐惧，除非被杀死，否则无法被阻止。', '', '', 'Attacking all nearby enemies in a whirlwind of steel.', '', '', '', '用钢铁般的旋风攻击附近的所有敌人。', '', '');
INSERT INTO `locales_spell` VALUES (45589, 'Die by the Sword', '', '', '', '剑下亡魂', '', '', '', '', '', '', '', '', '', 'Increases your chance to parry attacks by $s1% while under the effects of Retaliation.', '', '', '', '在反击风暴状态下你的招架几率提高$s1%。', '', '', 'Increased chance to parry by $s1%.', '', '', '', '招架几率增加$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45590, 'Avatar', '', '', '', '天神下凡', '', '', '', '', '', '', '', '', '', 'Increases the Physical damage dealt by the caster by $s1% and enhances its armor by $s2% for $d.', '', '', '', '使施法者造成的物理伤害提高$s1%，护甲值提高$s2%，持续$d。', '', '', 'Physical damage dealt is increased by $s1%.\nArmor increased by $s2%.', '', '', '', '对敌人造成的物理伤害提高$s1%。\n护甲值提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (45591, 'Dagger Mastery', '', '', '', '匕首掌握', '', '', 'Passive', '', '', '', '被动', '', '', 'Increases the normalized weapon speed to calculate damage of Daggers to 2.3 seconds.', '', '', '', '将计算匕首伤害的标准化武器速度提高到2.3秒。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45592, 'Pulverize', '', '', '', '粉碎', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Causes your melee attacks to have a 35% chance to deal $45593s1 damage to nearby enemies for 30 seconds.', '', '', '', '使你的近战攻击有35%的几率对附近的敌人造成$45593s1点伤害，持续30秒。', '', '', 'Chance to deal physical damage in an area around melee attack targets.', '', '', '', '近战攻击有几率对周围目标造成物理伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45593, 'Pulverize', '', '', '', '粉碎', '', '', '', '', '', '', '', '', '', 'Causes $s1 damage to nearby enemies.', '', '', '', '对附近的敌人造成$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45594, 'Rallying Cry', '', '', '', '振奋咆哮', '', '', '', '', '', '', '', '', '', 'A rallying cry that removes all Stun and Fear effects from party members within $a1 yards.', '', '', '', '消除$a1码范围内队伍成员的昏迷和恐惧效果。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45595, 'Intervene', '', '', '', '援护', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Run at high speed towards a party member, intercepting the next melee or ranged attack made against them.', '', '', '', '高速奔向队友，拦截下一次针对他们的近战或远程攻击。', '', '', 'The next melee or ranged attack made against you will be made against the intervening warrior instead.', '', '', '', '下一次对你的近战或远程攻击将由战士承担。', '', '');
INSERT INTO `locales_spell` VALUES (45596, 'Spellsteal', '', '', '', '法术窃取', '', '', '', '', '', '', '', '', '', 'Steals a beneficial magic effect from the target. This effect lasts a maximum of 2 min.', '', '', '', '从目标身上窃取一个增益魔法效果。这个效果最多持续 2 分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45597, 'Gladiator Stance', '', '', '', '角斗士姿态', '', '', '', '', '', '', '', '', '', 'A dauntless combat stance.\n\nIncreases your damage by $45598s1%.', '', '', '', '无畏的战斗姿态。\n\n使你的伤害增加$45598s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45598, 'Gladiator Stance Passive', '', '', '', '角斗士姿态被动', '', '', '', '', '', '', '', '', '', 'Increase physical damage done by $s1%.\nDecreases threat generated by $s3%.', '', '', '', '伤害增加$s1%。\n威胁减少$s3%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45599, 'Decisive Strike', '', '', '', '果断一击', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Decisively strikes the opponent with the power of Slam (Rank 4), causing weapon damage plus $11605s1.', '', '', '', '用猛击（等级 4）的力量打击对手，造成的伤害增加$11605s1点。', '', '', 'Full credit for this ability\'s design goes to Wall of Wallcraft.', '', '', '', '这种能力的设计完全归功于Wallcraft之墙。', '', '');
INSERT INTO `locales_spell` VALUES (45600, 'Shadow Strikes', '', '', '', '暗影打击', '', '', '', '', '', '', '', '', '', 'All melee attacks against Poisoned targets cause additional Shadow damage equal to $45601s1% of weapon damage.', '', '', '', '所有对中毒目标的近战攻击都会造成额外的暗影伤害，数值相当于$45601s1%的武器伤害。', '', '', 'Melee attacks against Poisoned or Dazed targets cause additional Shadow damage equal to $45601s1% of weapon damage.', '', '', '', '对中毒或眩晕目标的近战攻击造成额外的暗影伤害，数值相当于$45601s1%的武器伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45601, 'Shadow Strikes', '', '', '', '暗影打击', '', '', '', '', '', '', '', '', '', 'Deals $s1% of weapon damage as shadow damage.', '', '', '', '造成相当于武器伤害$s1%的暗影伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45602, 'Fan of Knives', '', '', '', '刀扇', '', '', '', '', '', '', '', '', '', 'Sprays knives at up to 5 targets within 8 yards, dealing ranged weapon damage.', '', '', '', '向8码内最多5个目标发射飞刀，造成远程武器伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45603, 'Surprise Attack', '', '', '', '突袭', '', '', '', '', '', '', '', '', '', 'A strike that deals $s1% weapon damage. This attack cannot be blocked, dodged or parried. Awards $s2 combo $lpoint:points;.', '', '', '', '造成$s1%武器伤害。此攻击无法被格挡、躲闪或招架。奖励$s2个连击点数。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45604, 'Flourish', '', '', '', '兴奋', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Finishing move that increases your chance to parry by an additional 20%. Lasts longer per combo point: \n1 point: 8 seconds \n2 points: 10 seconds \n3 points: 12 seconds \n4 points: 14 seconds \n5 points: 16 seconds', '', '', '', '终结技，使你的招架几率提高20%。根据连击点数的数量决定效果持续时间：\n1点：8秒 \n2点：10秒 \n3点：12秒 \n4点：14秒\n5点：16秒', '', '', 'Chance to parry increased by $s2%.', '', '', '', '招架几率提高$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (45605, 'Deadly Throw', '', '', '', '致命投掷', '', '', '', '', '', '', '等级 1', '', '', 'Finishing move that causes thrown weapon damage plus additional damage per combo point: \n1 point : 132-228 damage \n2 points: 216-312 damage \n3 points: 300-396 damage \n4 points: 384-480 damage \n5 points: 468-564 damage', '', '', '', '终结技，造成投掷武器伤害，并跟据连击点数的数量造成额外伤害：\n1点：132-228点伤害\n2点：216-312点伤害 \n3点：300-396点伤害\n4点：384-480点伤害\n5点：468-564点伤害', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45606, 'Shadow Dance', '', '', '', '暗影之舞', '', '', '', '', '', '', '', '', '', 'Enter the Shadow Dance for 6 sec, allowing the use of Sap, Garrote, Ambush, Cheap Shot, Premeditation, Pickpocket and Disarm Trap regardless of being stealthed.', '', '', '', '立即进入暗影之舞状态，持续6秒。无论是否潜行都可以使用闷棍、锁喉、伏击、偷袭、预谋、搜索和解除陷阱技能。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45607, 'Flashbang', '', '', '', '闪光弹', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Ignites Flash Powder in a burst that interrupts all enemy casting nearby for $d.', '', '', '', '点燃闪光粉，打断附近所有敌人的施法并沉默，持续$d。', '', '', 'Interrupted.', '', '', '', '沉默。', '', '');
INSERT INTO `locales_spell` VALUES (45608, 'Detection', '', '', '', '侦测陷阱', '', '', '', '', '', '', '', '', '', 'Hidden traps will become easier to spot for $d.', '', '', '', '隐藏的陷阱将变得更容易发现，持续$d。', '', '', 'Detecting traps.', '', '', '', '侦测陷阱。', '', '');
INSERT INTO `locales_spell` VALUES (45609, 'Shiv', '', '', '', '毒刃', '', '', '', '', '', '', '', '', '', 'Performs an instant off-hand weapon attack that automatically applies the poison from your off-hand weapon to the target.  Slower weapons require more Energy.  Awards 1 combo point.', '', '', '', '立即使用副手武器攻击目标，并使其受到你的副手武器所带毒药效果的影响。慢速武器需要更多能量值。奖励1个连击点数。', '', '', '', '', '', '', '', '', '');
