INSERT INTO `locales_spell` VALUES (45611, 'Agitating Poison', '', '', '', '激怒毒药I', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Coats a weapon with poison that lasts for 30 minutes.\nEach strike has a 20% chance of poisoning the enemy which instantly inflicts $45613s1 Nature damage, and causes additional threat.  115 charges.', '', '', '', '给一件武器浸毒，效果持续30分钟。\n每次攻击都有20%的几率令敌人中毒，立即造成$45613s1点自然伤害，并产生额外的威胁值。可使用115次。', '', '', '', '', '', '', '', '', '');
