INSERT INTO `locales_spell` VALUES (45619, 'Conviction', '', '', '', '定罪', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Strikes the enemy with holy conviction that causes $s1 Holy damage and infuses the paladin with holy power, increasing critical strike chance for melee and spells by 2% for 30 seconds. Has a chance to activate any seal effects.', '', '', '', '以神圣信念打击敌人，造成 s1 点神圣伤害，并使圣骑士注入神圣力量，使近战和法术暴击率提高 2%，持续 30 秒。有几率激活任何封印效果。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45620, 'Conviction', '', '', '', '定罪', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Strikes the enemy with holy conviction that causes $s1 Holy damage and infuses the paladin with holy power, increasing critical strike chance for melee and spells by 3% for 30 seconds. Has a chance to activate any seal effects.', '', '', '', '以神圣信念打击敌人，造成 s1 点神圣伤害，并使圣骑士注入神圣力量，使近战和法术暴击率提高 3%，持续 30 秒。有几率激活任何封印效果。', '', '', '', '', '', '', '', '', '');
