INSERT INTO `locales_spell` VALUES (45624, 'Food', '', '', '', '食物', '', '', '', '', '', '', '', '', '', 'Restores $o1 health over $d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $45623s1% dodge and $45623s2 defense for $45623d.', '', '', '', '在 $d 内恢复 $o1 生命值。吃饭时必须保持坐姿。如果你花至少 10 秒吃东西，你就会吃饱，并获得 $45623s1% 闪避和 $45623s2 防御，花费 $45623d。', '', '', 'Restores $/5;s1 health per second.', '', '', '', '每秒恢复 $/5;s1 生命值。', '', '');
