INSERT INTO `locales_spell` VALUES (45649, 'Aspect of the Turtle', '', '', '', '乌龟守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a turtle, reducing all damage they take by 20%, but increases their time between attacks by 30%, and reduces their movement speed by 30%.  Lasts $d.', '', '', '', '猎人获得乌龟守护，受到的伤害减少20%，攻击间隔和移动速度减少30%。持续$d。', '', '', 'Damage taken reduced by 20% but movement speed and time between attacks increased by 30%.', '', '', '', '受到的伤害减少20%，攻击速度和移动速度减少30%。', '', '');
INSERT INTO `locales_spell` VALUES (45650, 'Aspect of the Wolf', '', '', '', '孤狼守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a wolf, increasing melee attack power by $s and disabling the use of ranged weapons and abilities.  Only one Aspect can be active at a time.', '', '', '', '猎人获得孤狼守护，增加$s1点近战攻击力，但禁止使用远程武器和技能。一个猎人在同一时间内只能激活一种守护。', '', '', 'Increases melee attack power by $s1.', '', '', '', '增加$s1点近战攻击力。', '', '');
INSERT INTO `locales_spell` VALUES (45651, 'Aspect of the Fox', '', '', '', '狐狸守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a fox, allowing for casting of stationary ranged attacks while moving, but reducing damage done by $s1%.  Only one Aspect can be active at a time.', '', '', '', '猎人获得狐狸守护，可以进行移动射击，但伤害减少$s1%。一个猎人在同一时间内只能激活一种守护。', '', '', 'Able to cast while moving. Ranged damage reduced by $s1%.', '', '', '', '可以进行移动射击，但伤害减少$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45652, 'Aspect of the Snake', '', '', '', '蝰蛇守护', '', '', '', '', '', '', '', '', '', 'The hunter takes on the aspects of a snake, causing most melee attacks and ranged auto attacks to have a chance to restore $45664s1 mana.  Only one Aspect can be active at a time.', '', '', '', '猎人获得蝰蛇守护，使近战和远程攻击有几率回复$45664s1点法力值。一个猎人在同一时间内只能激活一种守护。', '', '', 'Restoring mana from most attacks.', '', '', '', '攻击时有几率回复法力。', '', '');
