INSERT INTO `locales_spell` VALUES (45702, 'Mana Flare', '', '', '', '法力爆燃', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Channel negative magical energies into an area that deals $s1 arcane damage to nearby enemies when they cast spells.', '', '', '', '创建一个负魔区域，区域内的敌人施法时受到$s1点奥术伤害。', '', '', '', '', '', '', '', '', '');
