INSERT INTO `locales_spell` VALUES (45705, 'Tree of Life Form', '', '', '', '生命之树形态', '', '', 'Shapeshift', '', '', '', '变形', '', '', 'Shapeshift into the Tree of Life.  While in this form the healing power of nearby party members is increased by an amount equal to $45707s1% of your spirit, your movement speed is reduced by $45706s2%, and you cannot cast damaging spells or Healing Touch, but the mana cost of heal over time spells is reduced by 20%.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.', '', '', '', '变形为生命之树。在这种形态下，附近队友的治疗能力会增加相当于你精神值$45707s1%的量，你的移动速度会降低$45706s2%，并且你不能施放伤害性法术或治疗之触，但随着时间的推移治疗法术减少 20%。变形行为可以使施法者摆脱变形和运动障碍效果。', '', '', 'Immune to Polymorph effects. ', '', '', '', '免疫变形效果。', '', '');
INSERT INTO `locales_spell` VALUES (45706, 'Tree of Life Form (Passive)', '', '', '', '生命之树形态（被动）', '', '', 'Passive', '', '', '', '被动', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45707, 'Tree of Life Aura', '', '', '', '生命之树光环', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Increases healing done.', '', '', '', '增加治疗效果。', '', '');
INSERT INTO `locales_spell` VALUES (45708, 'Berserk', '', '', '', '狂暴', '', '', '', '', '', '', '', '', '', 'Removes all Fear effects and increases your energy regeneration rate by 100% while in Cat form, and increases your total health by 20% while in Bear form. After the effect ends, the health is lost. Effect lasts 20 seconds.', '', '', '', '猎豹形态下移除所有恐惧效果并提高100%能量回复。熊形态下提高20%生命值上限，效果结束扣除生命值。持续时间20秒。', '', '', '', '', '', '', '', '', '');
