INSERT INTO `locales_spell` VALUES (45715, 'Natural Weapons', '', '', '', '武器平衡', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the damage you deal with physical attacks in all forms by $s1%. Also increases chance to hit with melee attacks and spells by $s2%.', '', '', '', '使你在所有形态下的物理攻击所能造成的伤害提高$s1%。同时近战攻击和法术命中几率提高$s2%。', '', '', '', '', '', '', '', '', '');
