INSERT INTO `locales_spell` VALUES (45732, 'Mana Tree', '', '', '', '法力树', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Creates a blessed Mana Tree near the caster.  Members of your raid or party can click the Mana Tree to restore $45733o1 mana over $45733d.  Being attacked cancels the effect.  Mana Tree lasts for $d or 5 charges.', '', '', '', '在施法者附近创造一棵受祝福的法力树。你的团队或小队的成员可以通过点击法力树，在$45733d内恢复$45733o1点法力值，被攻击会取消该效果。法力树持续$d或使用5次后消失。', '', '', '', '', '', '', '', '', '');
