INSERT INTO `locales_spell` VALUES (45734, 'Owlkin Frenzy', '', '', '', '枭兽狂怒', '', '', 'Passive', '', '', '', '被动', '', '', 'Attacks done to you while in Moonkin Form have a $h% chance to cause you to go into a Frenzy, causing you to be immune to pushback while casting. Lasts $45735d.', '', '', '', '在枭兽形态下受到攻击有$h%的几率进入狂怒状态，使你在施法时不会被干扰。持续$45735d。', '', '', '', '', '', '', '', '', '');
