INSERT INTO `locales_spell` VALUES (45739, 'Wolfsheart', '', '', '', '狼心', '', '', '', '', '', '', '', '', '', 'Permanently adds the effect of when shapeshifting into Cat form the Druid gains 20 energy, when shapeshifting into Bear form the Druid gains 5 rage to a head slot item. Does not stack with other enchantments for the selected equipment slot.', '', '', '', '为头部附魔，进入猎豹形态时获得20能量，进入熊形态时获得5点怒气，不与其他附魔效果叠加。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45740, 'Storm Crow Form', '', '', '', '风暴乌鸦形态', '', '', 'Shapeshift', '', '', '', 'Shapeshift', '', '', 'Transforms the Druid into Storm Crow Form. The Storm Crow can only cast Balance spells while shapeshifted.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.', '', '', '', '变成一只风暴乌鸦。风暴乌鸦只能施放平衡系法术。\n\n变身可以解除施法者身上的所有变形和移动限制效果。', '', '', 'Immune to Polymorph effects.', '', '', '', '免疫变形效果。', '', '');
