INSERT INTO `locales_spell` VALUES (45742, 'Cyclone', '', '', '', '飓风术', '', '', '', '', '', '', '', '', '', 'Tosses the enemy target into the air, preventing all action but making them invulnerable for up to $d.  Only one target can be affected by your Cyclone at a time.', '', '', '', '将敌人吹上天空，使其无法动作，但也无法被攻击，持续最多$d秒。德鲁伊在同一时间内只能对一个目标使用旋风。', '', '', '', '', '', '', '', '', '');
