INSERT INTO `locales_spell` VALUES (45800, 'Ardent Defender', '', '', '', '炽热防御者', '', '', 'Passive', '', '', '', '被动', '', '', 'When you have less than 35% health, all damage taken is reduced by 25%.', '', '', '', '当你的生命值低于35%时，你承受的所有伤害降低25%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45801, 'Greater Blessing of Sacrifice', '', '', '', '强效牺牲祝福', '', '', '', '', '', '', '', '', '', 'Places a seal on a party member, causing the caster to split $s1% of all damage taken by that party member. Damage cannot be mitigated. Lasts $d.', '', '', '', '对一名小队成员施加祝福，该成员受到的所有伤害的$s1%由施法者承担。伤害无法减免。持续$d。', '', '', 'Splitting $s1% of all damage taken by a party member.', '', '', '', '承担一名小队成员受到的所有伤害的$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45802, 'Seal of the Martyr', '', '', '', '殉难圣印', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'All melee attacks deal additional Holy damage equal to $s1% of normal weapon damage, but the Paladin loses health equal to $s2% of the total damage inflicted. \n\nUnleashing this Seal\'s energy will judge an enemy, instantly causing $45816s1 Holy damage at the cost of health equal to 33% of the damage caused.', '', '', '', '所有近战攻击都可以造成额外的神圣伤害，数值相当于普通武器伤害的$s1%，但是圣骑士也会损失相当于造成伤害$s2%的生命值。 \n\n释放这种圣印的能量将对目标立即造成$45816s1点神圣伤害，但圣骑士也会损失造成的伤害33%的生命值。', '', '', 'Melee attacks deal additional Holy damage at the cost of health.', '', '', '', '近战攻击造成额外的神圣伤害，自身受到伤害反噬。', '', '');
