INSERT INTO `locales_spell` VALUES (45842, 'Bonus Healing', '', '', '', '额外治疗', '', '', '', '', '', '', '', '', '', 'If your target is below 50% health, your direct healing spells will cause your target to be healed for an additional 80 to 100 health.', '', '', '', '如果你的目标生命值低于 50%，你的直接治疗法术将使你的目标获得额外 80 到 100 点生命值的治疗。', '', '', '', '', '', '', '', '', '');
