INSERT INTO `locales_spell` VALUES (45900, 'Improved Enslave Demon', '', '', '', '强化奴役恶魔', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces the Attack Speed and Casting Speed penalty of your Enslave Demon spell by $s1% and reduces the resist chance by $s3%.', '', '', '', '使你的奴役恶魔的攻击速度和施法速度惩罚降低$s1%，并使其被抵抗的几率降低$s3%。', '', '', '', '', '', '', '', '', '');
