INSERT INTO `locales_spell` VALUES (45902, 'Master Conjuror', '', '', '', '魔石大师', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the amount of Health restored by your Healthstone by $18692s1% and increases the bonuses and effects of your Firestones and Spellstones by $18774s1%.', '', '', '', '治疗石的恢复量提高$18692s1%，火焰石和法术石的效果提高$18774s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45903, 'Master Conjuror', '', '', '', '魔石大师', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Increases the amount of Health restored by your Healthstone by $18693s1% and increases the bonuses and effects of your Firestones and Spellstones by $18775s1%.', '', '', '', '治疗石的恢复量提高$18693s1%，火焰石和法术石的效果提高$18775s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45904, 'Atrocity', '', '', '', '残暴', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'You devastate the area around your target, inflicting Corruption (Rank 7) on all enemies around it within 15 yards.', '', '', '', '摧毁目标区域，使半径15码范围内的所有目标受到腐蚀术（等级 7）的影响。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45905, 'Doombringer', '', '', '', '厄运使者', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Reduces the cooldown of your Inferno spell by $/60000;s1 min and your Ritual of Doom spell by $/60000;s2 min.', '', '', '', '地狱火冷却时间减少$/60000;s1分钟，末日仪式冷却时间减少$/60000;s2分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45906, 'Doombringer', '', '', '', '厄运使者', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Reduces the cooldown of your Inferno spell by $/60000;s1 min and your Ritual of Doom spell by $/60000;s2 min.', '', '', '', '地狱火冷却时间减少$/60000;s1分钟，末日仪式冷却时间减少$/60000;s2分钟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45907, 'Rain of Chaos', '', '', '', '混乱之雨', '', '', 'Summon', '', '', '', '召唤', '', '', 'Summons a meteor from the Twisting Nether, causing $22699s1 Fire damage and stunning all enemy targets in the area for $20310d.  An Infernal rises from the crater, under the command of the Warlock.', '', '', '', '从扭曲虚空中召唤一颗陨星，对区域内所有敌方目标造成$22699s1点火焰伤害，并使其昏迷$20310d。陨星会化作地狱火从陨坑中爬出为术士作战。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45908, 'Demon Portal', '', '', '', '恶魔之门', '', '', '', '', '', '', '', '', '', 'Opens a portal into the Twisting Nether that summons a Felguard under the command of the caster for 5 min. Once control is lost, the Felguard must be Enslaved to maintain control. Requires the caster and 2 additional party members to complete the ritual. In order to participate, all players must right-click the portal and not move until the ritual is complete.', '', '', '', '打开一个通往扭曲虚空的传送门，召唤一个受施法者控制的恶魔守卫，持续5分钟。若持续时间结束，可以使用奴役恶魔重新控制恶魔守卫。需要施法者和另外2名队成员来完成仪式。所有参与的玩家必须右键单击传送门，并且在仪式完成之前不能移动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45909, 'Demonic Empowerment', '', '', '', '恶魔强化', '', '', '', '', '', '', '', '', '', 'Grants the Warlock\'s summoned demon Empowerment.\n\nImp - Increases the Imp\'s spell critical strike chance by 20% for 30 sec.\n\nVoidwalker - Increases the Voidwalker\'s health by 20%, and its threat generated from spells and attacks by 20% for 20 sec.\n\nSuccubus -  Instantly vanishes, causing the Succubus to go into an improved Invisibility state.\n\nFelhunter - Dispels all magical effects from the Felhunter.', '', '', '', '强化术士所召唤的恶魔。\n\n小鬼 - 使小鬼的法术暴击几率提高20%，持续30秒。\n\n虚空行者 - 使虚空行者的生命值提高20%，其法术和攻击产生的威胁值提高20%，持续20秒。\n\n魅魔 - 立即消失，使魅魔进入强化的隐身状态。\n\n地狱犬 - 驱散地狱犬的所有魔法效果。', '', '', 'Empowered.', '', '', '', '授权。', '', '');
INSERT INTO `locales_spell` VALUES (45910, 'Mana Funnel', '', '', '', '法力通道', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Transfers $s1 mana from the caster to $ghis:her; pet every second as long as the caster channels.', '', '', '', '只要施法者保持着引导法术的状态，就会每秒钟将$s1点法力值转移给$g他:她;的宠物。', '', '', 'Transferring Mana.', '', '', '', '转移法力。', '', '');
INSERT INTO `locales_spell` VALUES (45911, 'Mana Funnel', '', '', '', '法力通道', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Transfers $s1 mana from the caster to $ghis:her; pet every second as long as the caster channels.', '', '', '', '只要施法者保持着引导法术的状态，就会每秒钟将$s1点法力值转移给$g他:她;的宠物。', '', '', 'Transferring Mana.', '', '', '', '转移法力。', '', '');
INSERT INTO `locales_spell` VALUES (45912, 'Demon Portal Effect', '', '', '', '恶魔之门效果', '', '', '', '', '', '', '', '', '', 'Summons a Felguard.', '', '', '', '召唤一个恶魔守卫。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45913, 'Soul Siphon', '', '', '', '灵魂虹吸', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the Health drained by your Drain Life spell by $s1% and causes 15% of the Mana drained by your Drain Mana spell to damage the opponent.', '', '', '', '使吸取生命的吸取量提高$s1%，使吸取法力对目标造成吸取量15%的伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45914, 'Soul Siphon', '', '', '', '灵魂虹吸', '', '', 'Rank 2', '', '', '', '等级 2', '', '', 'Increases the Health drained by your Drain Life spell by $s1% and causes 30% of the Mana drained by your Drain Mana spell to damage the opponent.', '', '', '', '使吸取生命的吸取量提高$s1%，使吸取法力对目标造成吸取量15%的伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45915, 'Carrion Swarm', '', '', '', '腐臭虫群', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'A wave of demonic bats and chaotic magic releases over enemies in a cone infront of the caster, dealing $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec. for $d.', '', '', '', '对前方扇形区域的敌人造成$s1点暗影伤害，并每$t2秒造成额外$s2点暗影伤害，持续$d。', '', '', 'Suffering $s2 Shadow damage every $t2 sec.', '', '', '', '每$t2秒造成$s2点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45916, 'Curse of Archimonde [PH]', '', '', '', '阿克蒙德的诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'An arcane curse that decreases the target\'s Intellect by $s1 and drains $s2 mana every $t2 seconds for $d. Only one Curse per Warlock can be active on any one target.', '', '', '', '给目标施加阿克蒙德的诅咒，使其智力降低$s1点，并每$t2秒消耗$s2点法力值，持续$d。每个术士只能对任何一个目标施放一个诅咒，且同类诅咒不能叠加。', '', '', 'Intellect reduced by $s1.\nDrains $s2 mana every $t2 seconds to the caster.', '', '', '', '智力降低$s1点。\n每$t2秒消耗$s2点法力值。', '', '');
INSERT INTO `locales_spell` VALUES (45917, 'Curse of Mannoroth [PH]', '', '', '', '玛诺洛斯的诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Slows the target\'s attack speed by $s1% for $d.  Only one Curse per Warlock can be active on any one target.', '', '', '', '使目标的攻击速度降低$s1%，持续$d。每个术士只能对任何一个目标施放一个诅咒，且同类诅咒不能叠加。', '', '', 'Attack speed slowed by $s1%.', '', '', '', '攻击速度降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (45918, 'Curse of Sargeras [PH]', '', '', '', '萨格拉斯的诅咒', '', '', 'Rank 1', '', '', '', '等级 1', '', '', '[PH].  Only one Curse per Warlock can be active on any one target.', '', '', '', '[PH]。  Only one Curse per Warlock can be active on any one target。', '', '', '[PH] $o1 Shadow damage over $d.', '', '', '', '$d内造成$o1点暗影伤害。', '', '');
INSERT INTO `locales_spell` VALUES (45919, 'Demonic Servitude', '', '', '', '恶魔奴役', '', '', '', '', '', '', '', '', '', 'You are now able to maintain your control over even greater demons indefinitely, allowing you to summon Doomguards, Infernals, and Felguards as permanent pets.', '', '', '', '你现在可以无限期地控制更大的恶魔，允许你召唤末日守卫、地狱火和恶魔守卫作为永久宠物。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45920, 'Ritual of Souls', '', '', '', '灵魂仪式', '', '', '', '', '', '', '', '', '', 'Begins a ritual that creates a Soulwell.  Raid members can click the Soulwell to acquire a Major Healthstone.  The Soulwell lasts for 3 min.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must right-click the soul portal and not move until the ritual is complete.', '', '', '', '开始进行一个制造灵魂之井的仪式。团队成员可以点击灵魂之井以获得一枚特效治疗石。灵魂之井持续3分钟。需要施法者和2名队友共同完成仪式。所有参与召唤的队友都必须使用右键点击灵魂之门，并且在召唤完成之前不得移动。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (45921, 'Demonic Aegis', '', '', '', '恶魔庇护', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Increases the effectiveness of your Demon Skin and Demon Armor spells by $s1%.', '', '', '', '使你的恶魔皮肤和魔甲术的效果提高$s1%。', '', '', '', '', '', '', '', '', '');
