INSERT INTO `locales_spell` VALUES (45954, 'Sanctified Command', '', '', '', '神圣命令', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Gives your Seal of Command a $s1% chance to resist dispel effects and your Judgement of Command will restore mana equal to $s2% of the base mana cost of the Seal of Command to you and nearby party members.', '', '', '', '使你的命令圣印有$s1%的几率抵抗驱散效果，你的命令审判将为你和附近的小队成员恢复相当于命令圣印基础法力消耗的$s2%的法力值。', '', '', '', '', '', '', '', '', '');
