INSERT INTO `locales_spell` VALUES (45958, 'Shield Mastery', '', '', '', '盾牌精通', '', '', '', '', '', '', '', '', '', 'When using Shield Block, your first block within $45959d aborbs $45959s1% more damage and causes your next Revenge to deal $45962s1% more damage.', '', '', '', '使用盾牌格挡时，你在$45959d内的第一次格挡会减少$45959s1%的伤害，并使你的下一次复仇造成$45962s1%的额外伤害。', '', '', '', '', '', '', '', '', '');
