INSERT INTO `locales_spell` VALUES (46202, 'Armored Frostmane Riding Bear', '', '', '', '装甲霜鬃战熊', '', '', '', '', '', '', '', '', '', 'This ursine mount\'s swiftness is enhanced by its heavy armor.', '', '', '', '这头熊坐骑的重甲增强了它的敏捷性。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46203, 'Blizzcon Riding Bear', '', '', '', '暴雪嘉年华战熊', '', '', '', '', '', '', '', '', '', 'Just remember to have your special little passenger straped in tightly before running off at top speed on an adventure.', '', '', '', '请记住，在全速出发冒险之前，将您特别的小乘客绑紧。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46204, 'Armored Amani Riding Bear', '', '', '', '装甲阿曼尼战熊', '', '', '', '', '', '', '', '', '', 'The Amani trolls decorate these ferocious mounts in magic amulets and ceremonial masks as a way to venerate the bear god Nalorakk.', '', '', '', '阿曼尼巨魔用魔法护身符和仪式面具装饰这些凶猛的坐骑，以表达对熊神纳洛拉克的崇敬。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46205, 'Quel\'dorei Dragonhawk', '', '', '', '奎尔多雷龙鹰', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Dragonhawk. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的龙鹰。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46206, 'Riding Dragonhawk', '', '', '', '龙鹰', '', '', '', '', '', '', '', '', '', 'Dragonhawks are among the deadliest known predators. They are able to spot prey from great distances, rush in, and rend with both talon and beak.', '', '', '', '龙鹰是已知最致命的掠食者之一。它们能够从很远的距离发现猎物，然后冲进去，用爪子和喙撕碎猎物。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46207, 'Riding Ice Saber', '', '', '', '霜刃豹', '', '', '', '', '', '', '', '', '', 'The lack of spots or stripes marks this beast as a descendant of the most ancient frostsaber line.', '', '', '', '缺乏斑点或条纹标志着这种野兽是最古老的霜刃豹血统的后裔。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46208, 'Riding Aqua Saber', '', '', '', '水纹豹', '', '', '', '', '', '', '', '', '', 'Taming this savage breed requires patience, strength, and a large supply of fake mice and twine.', '', '', '', '驯服这种野蛮品种需要耐心、力量以及大量的假老鼠和麻线。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46209, 'Riding Chromatic Drake', '', '', '', '彩色幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46210, 'Riding Black Drake', '', '', '', '黑色幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46211, 'Immortal Champion\'s Drake', '', '', '', '不朽勇士的幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46212, 'Riding Bronze Drake', '', '', '', '青铜幼龙', '', '', '', '', '', '', '', '', '', 'Lost time is never found again.', '', '', '', '失去的时间就再也找不回来了。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46213, 'Riding Green Drake', '', '', '', '绿色幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46214, 'Riding Red Drake', '', '', '', '红色幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46215, 'Mysterious Warp Stalker', '', '', '', '神秘的迁跃追猎者', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Warp Stalker. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一个可供骑乘的亚空间追猎者。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46216, 'Immortal Champion\'s Charger', '', '', '', '不朽勇士的战马', '', '', '', '', '', '', '', '', '', 'But the most important rule, the rule you can never forget, no matter how much he cries, no matter how much he begs, never feed him after midnight.', '', '', '', '但最重要的规则，你永远不能忘记的规则，无论他如何哭泣，无论他如何乞求，午夜之后永远不要给他喂食。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46217, 'Riding Void Drake', '', '', '', '虚空幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Drake. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一条可供骑乘的幼龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46218, 'Riding Infinite Drake', '', '', '', '无限幼龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Draker. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一个可供骑乘的德雷克。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46219, 'Riding Gryphon', '', '', '', '狮鹫', '', '', '', '', '', '', '', '', '', 'Gryphons\' keen eyesight allows them to see over vast distances and warn their riders of any dangers that lie ahead.', '', '', '', '狮鹫敏锐的视力使它们能够看到很远的距离，并警告它们的骑手前方有任何危险。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46220, 'Riding Armored Gryphon', '', '', '', '装甲狮鹫', '', '', '', '', '', '', '', '', '', 'This noble gryphon is as staunch a battle companion as any a member of the Alliance could ask for.', '', '', '', '这头高贵的狮鹫是联盟任何成员所要求的坚定的战斗伙伴。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46221, 'Riding Cenarion Hippogryph', '', '', '', '塞纳里奥角鹰兽', '', '', '', '', '', '', '', '', '', 'Members of the Cenarion Circle have shared a long and prosperous partnership with their hippogryph allies. When conflict is unavoidable, the Cenarion War Hippogryph is called into service.', '', '', '', '塞纳里奥议会的成员与他们的角鹰兽盟友有着长期而繁荣的伙伴关系。当冲突不可避免时，塞纳里奥战争角鹰兽就会投入使用。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46222, 'Riding Wyvern', '', '', '', '双足飞龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Wyvern. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一只可供骑乘的双足飞龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46223, 'Riding Armored Wyvern', '', '', '', '装甲双足飞龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Wyvern. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一只可供骑乘的双足飞龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46224, 'Dark Rider\'s Steed', '', '', '', '黑暗骑士的战马', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Steed. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一匹可供骑乘的战马。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46225, 'Turbo-Charged Flying Machine', '', '', '', '涡轮增压飞行器', '', '', '', '', '', '', '', '', '', 'Only the most talented engineers have the courage and the mental stamina to create a flying machine that boasts stability and safety. Turbo-charging one is just crazy!', '', '', '', '只有最有才华的工程师才有勇气和毅力创造出具有稳定性和安全性的飞行器。涡轮增压简直太疯狂了！', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46226, 'Black Bear Cub', '', '', '', '黑熊幼崽', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your bear cub.', '', '', '', '右键单击以召唤或解散你的黑熊幼崽。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46227, 'Wally', '', '', '', '沃利', '', '', '', '', '', '', '', '', '', 'The squirming cub refused to leave the tree. We had to chuck it from the treetops.', '', '', '', '蠕动的幼崽拒绝离开树。我们不得不把它从树顶上扔下来。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46228, 'White Bear Cub', '', '', '', '白熊幼崽', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your bear cub.', '', '', '', '右键单击以召唤或解散你的白熊幼崽。', '', '', '', '', '', '', '', '', '');
