INSERT INTO `locales_spell` VALUES (46315, 'Cleave', '', '', '', '顺劈斩', '', '', 'Felgaurd', '', '', '', '恶魔卫士', '', '', 'A sweeping attack that does your weapon damage plus $s1 to the target and his nearest ally.', '', '', '', '横扫攻击，对目标和附近的敌人造成武器伤害附加$s1点伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46316, 'Intercept', '', '', '', '拦截', '', '', 'Felguard', '', '', '', '恶魔卫士', '', '', 'Charge an enemy, causing $20615s2 damage and stunning it for $20615d.', '', '', '', '向敌人冲锋，造成$20615s2点伤害，并使其昏迷$20615d秒。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46317, 'Torment', '', '', '', '折磨', '', '', 'Felguard', '', '', '', '恶魔卫士', '', '', 'Taunts the creature, increasing the chance that it will attack the Felguard.', '', '', '', '嘲讽目标，增加它攻击恶魔守卫的几率。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46318, 'Demoralize', '', '', '', '挫败', '', '', '', '', '', '', '', '', '', 'Reduces the melee attack power of an enemy by $s1 for $d.', '', '', '', '使敌人的近战攻击力降低$s1点，持续$d。', '', '', 'Melee attack power reduced by $s1.', '', '', '', '近战攻击力降低$s1点。', '', '');
INSERT INTO `locales_spell` VALUES (46319, 'Summon Horde Defender', '', '', '', '召唤部落防御者', '', '', '', '', '', '', '', '', '', 'Summons a Horde Defender that will protect the area from enemies of the Horde.', '', '', '', '召唤一名部落防御者来保护该地区免受部落敌人的侵害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46432, 'Tied Up', '', '', '', '绑起来', '', '', '', '', '', '', '', '', '', 'Tie a beast and drag it with you. Only works on injured taurens.', '', '', '', '绑住一只野兽并拖着它。只对受伤的牛头人有效。', '', '', 'You are being dragged away by an enemy. Fight your way out of bondage before it\'s too late.', '', '', '', '你正被敌人拖走。快点摆脱束缚。', '', '');
INSERT INTO `locales_spell` VALUES (46433, 'Tied Up', '', '', '', '绑起来', '', '', '', '', '', '', '', '', '', 'Tie up a live meal and drag it with you. Only works on injured gnomes.', '', '', '', '把活的食物绑起来背在身上。只对受伤的侏儒有效。', '', '', 'You are being dragged away by an enemy. Fight your way out of bondage before it\'s too late.', '', '', '', '你正被敌人拖走。快点摆脱束缚。', '', '');
INSERT INTO `locales_spell` VALUES (46434, 'Burning Blood Visual', '', '', '', '燃血视觉', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46435, 'Burning Blood', '', '', '', '燃血', '', '', '', '', '', '', '', '', '', 'Increases the caster\'s movement speed by $s2% and the Physical damage it deals by $s1 for $d.', '', '', '', '使施法者的移动速度提高$s2%，造成的物理伤害提高$s1点，持续$d。', '', '', 'The ritual sacrifice of an ally has ignited the cursed blood in which you were covered, causing you to go berserk. You die when this expires.', '', '', '', '你身上淋满了队友献祭自己引燃的诅咒之血，你狂暴了。效果结束你将死亡。', '', '');
INSERT INTO `locales_spell` VALUES (46436, 'Winterax Ritual Suicide', '', '', '', '冰斧牺牲仪式', '', '', '', '', '', '', '', '', '', 'Sacrifice your life to invoke a dark ritual practiced by trolls of the Winterax tribe. The consequences may be unpredictable!', '', '', '', '牺牲你的生命来唤起冰斧巨魔所实行的黑暗仪式。后果可能无法预料！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46437, 'Bathed in Blood', '', '', '', '沐浴在鲜血中', '', '', '', '', '', '', '', '', '', 'Mark nearby enemies as having participated in killing Korrak.', '', '', '', '将附近的敌人标记参与了杀害Korrak的行动', '', '', 'You have Korrak\'s blood on your hands, allowing you to partake in the twisted voodoo rituals of the Winterax tribe.', '', '', '', '你手上沾满了科尔拉克的鲜血，你可以参加冰斧部落扭曲的巫毒仪式。', '', '');
INSERT INTO `locales_spell` VALUES (46438, 'Blitz', '', '', '', '闪电战', '', '', '', '', '', '', '', '', '', 'Grants immunity to movement impairing effects, and increases mount speed by $s1%.', '', '', '', '免疫移动限制效果，并将坐骑速度提高 $s1%。', '', '', 'You are outnumbered, but not outmatched. Immune to movement impairing effects. Mounted speed increased by $s1%.', '', '', '', '对面人多势重，但优势在你。免疫移动限制效果。骑乘速度提高 $s1%。', '', '');
INSERT INTO `locales_spell` VALUES (46439, 'Winterax Disguise', '', '', '', '冰斧伪装', '', '', '', '', '', '', '', '', '', 'Use to disguise yourself as a member of the Winterax tribe.', '', '', '', '用来伪装成冰斧部落的一员。', '', '', 'Disguised as a member of the Winterax tribe.', '', '', '', '伪装成冰斧部落的一员。', '', '');
INSERT INTO `locales_spell` VALUES (46440, 'Winterax Champion', '', '', '', '冰斧勇士', '', '', '', '', '', '', '', '', '', 'Imbued with the power of the Winterax tribe. Chance to crit increased by 50% while in Alterac Valley.', '', '', '', '灌注了冰斧部落的力量。在奥特兰克山谷时暴击率提高50%。', '', '', 'Imbued with the power of the Winterax tribe. Chance to crit increased by 50% while in Alterac Valley.', '', '', '', '灌注了冰斧部落的力量。暴击率在奥特兰克山谷时提高50%。', '', '');
INSERT INTO `locales_spell` VALUES (46441, 'Dalaran Warhorse', '', '', '', '达拉然战马', '', '', '', '', '', '', '', '', '', 'The powerful and unyielding white stallion.', '', '', '', '强大而不屈的白色种马。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46442, 'Knight\'s Warhorse', '', '', '', '骑士战马', '', '', '', '', '', '', '', '', '', 'Trained to withstand brutal hand-to-hand combat in the fiercest battlefields.', '', '', '', '经过训练可以在最激烈的战场上承受残酷的肉搏战。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46443, 'Raven Lord', '', '', '', '乌鸦之神', '', '', '', '', '', '', '', '', '', 'The rest be forgotten to walk upon the ground, clipped wings and shame.', '', '', '', '其余的则被遗忘在地面上行走，折断翅膀并感到羞耻。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46444, 'Darkmoon Dancing Bear', '', '', '', '暗月跳舞熊', '', '', '', '', '', '', '', '', '', 'These fearsome mounts have a habit of suddenly breaking out into dance amid battle, much to the annoyance of their riders.', '', '', '', '这些可怕的坐骑有在战斗中突然跳舞的习惯，这让骑手们非常恼火。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46445, 'Quel\'dorei Steed', '', '', '', '奎尔多雷战马', '', '', '', '', '', '', '', '', '', 'Comes from a lineage of fine horses that once grazed near the shores of the Well of Eternity.', '', '', '', '来自曾经在永恒之井岸边吃草的优良马的血统。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46446, 'Riding Zhevra', '', '', '', '斑马', '', '', '', '', '', '', '', '', '', 'It has stripes!', '', '', '', '它有条纹！', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46447, 'Ivory War Raptor', '', '', '', '白色迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46448, 'Spectral Gryphon', '', '', '', '幽灵狮鹫', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Spectral Gryphon. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的光谱狮鹫。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46449, 'Shadowhorn Stag', '', '', '', '黑角鹿', '', '', '', '', '', '', '', '', '', 'A powerful, beautiful being.', '', '', '', '一个强大而美丽的存在。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46450, 'Nightmare Dreamrunner', '', '', '', '梦魇追梦者', '', '', '', '', '', '', '', '', '', 'A nightmarish steed of hardened steel and vengeful spirits, this companion will follow you to the depths of the Molten Core and back without complaint.', '', '', '', '这匹伙伴是一匹由坚硬的钢铁和复仇之魂组成的噩梦般的战马，将毫无怨言地跟随你前往熔火之心的深处并返回。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46451, 'Riding Frayfeather Hippogryph', '', '', '', '乱羽角鹰兽', '', '', '', '', '', '', '', '', '', 'Ancient mounts of the Highborne, now left to run wild, they can rarely be found due to their latent magical powers.', '', '', '', '上层精灵的古老坐骑，现在已被放任不管，由于其潜在的魔法力量，它们很少被发现。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46452, 'Snowball', '', '', '', '雪球', '', '', '', '', '', '', '', '', '', 'Happy New Year!', '', '', '', '新年快乐！', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46453, 'Riding Zhevra', '', '', '', '斑马', '', '', '', '', '', '', '', '', '', 'Zhevras are rarely used as mounts in Azeroth due to their stubborn nature and tendency to bite.', '', '', '', '热弗拉斯由于其顽固的本性和咬人的倾向，在艾泽拉斯很少被用作坐骑。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46454, 'Riding Ravasaur Hunter', '', '', '', '狩猎暴掠龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Ravasaur Hunter. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一名可供骑乘的掠掠龙猎人。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46455, 'Riding Ravasaur Runner', '', '', '', '疾奔暴掠龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Ravasaur Runner. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的掠掠龙奔跑者。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46456, 'Riding Venomide Ravasaur', '', '', '', '毒皮暴掠龙', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable Venomide Ravasaur. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一头可供骑乘的毒液掠食龙。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46457, 'Field Repair Bot 75B', '', '', '', '现场维修机器人75B', '', '', '', '', '', '', '', '', '', 'Unfolds into a Field Repair Bot that can repair damaged items and purchase unwanted goods', '', '', '', '展开为现场修复机器人，可以修复损坏的物品并购买不需要的物品', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46458, 'Mini Krampus', '', '', '', '迷你坎普斯', '', '', '', '', '', '', '', '', '', 'Keep him away from presents!', '', '', '', '让他远离礼物！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46459, 'Forworn Mule', '', '', '', '疲倦的骡子', '', '', '', '', '', '', '', '', '', 'Carries all your worldly possessions, there and back.', '', '', '', '随身携带您所有的世俗财产。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46460, 'Mechanical Auctioneer', '', '', '', '机械拍卖师', '', '', '', '', '', '', '', '', '', 'Right click to summon C.L.U.C.K.', '', '', '', '右键召唤 CLUCK', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46461, 'Bone Golem', '', '', '', '白骨魔像', '', '', '', '', '', '', '', '', '', 'Bone golems are deadly undead constructs made entirely of bones and fueled by ichor of Undeath.', '', '', '', '骨傀儡是致命的不死生物，完全由骨头制成，并以不死灵脓为燃料。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46462, 'Blitzen', '', '', '', '闪电', '', '', '', '', '', '', '', '', '', 'Happy Winter Veil!', '', '', '', '冬幕快乐！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46463, 'Moonkin Hatchling', '', '', '', '枭兽幼崽', '', '', '', '', '', '', '', '', '', 'Moonkins are blessed by Elune and spread nature\'s grace wherever they travel. The festive fowls are always in the mood for a dance.', '', '', '', '枭兽受到艾露恩的祝福，无论走到哪里都会传播大自然的恩惠。节日里的鸟儿总是心情愉悦地跳舞。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46464, 'Black Piglet', '', '', '', '黑猪', '', '', '', '', '', '', '', '', '', 'An easy-going traveling companion.', '', '', '', '一个随和的旅行伴侣。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46465, 'Kirin Tor Familiar', '', '', '', '肯瑞托魔宠', '', '', '', '', '', '', '', '', '', 'Who knew he was so into books?', '', '', '', '谁知道他这么喜欢读书？', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46466, 'Frostwolf Ghostpup', '', '', '', '霜狼幽灵犬', '', '', '', '', '', '', '', '', '', 'The little wolf told to stay. Watching, waiting, for vacant prey. Too proud to leave, she slipped away. Unburdened now, forever free to play.', '', '', '', '小狼叫他留下来。观察、等待，寻找空缺的猎物。她太骄傲了，不愿离开，于是就溜走了。现在毫无负担，永远自由玩耍。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46467, 'Darkmoon Steam Tonk', '', '', '', '暗月蒸汽坦克', '', '', '', '', '', '', '', '', '', 'A favorite of children across Azeroth, this tough little toy can withstand even the most aggressive imagination.', '', '', '', '这款坚固的小玩具是艾泽拉斯各地孩子们的最爱，甚至可以承受最激进的想象力。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46468, 'Son of Turtlhu', '', '', '', '图尔特鲁之子', '', '', '', '', '', '', '', '', '', 'This poor turtle got a bit corrupted, but his heart is still lovely.', '', '', '', '这只可怜的乌龟虽然有点堕落，但他的心仍然很可爱。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46469, 'Kodo Calfling', '', '', '', '科多幼崽', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your kodo calfling.', '', '', '', '右键单击以召唤或解散你的科多幼崽。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46470, 'Sniptip', '', '', '', '斯耐普特', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your personal Barber.', '', '', '', '右键单击以召唤或解散你的个人理发师。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46471, 'Dr. Topnose', '', '', '', '特普诺斯博士', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your personal Surgeon.', '', '', '', '右键单击以召唤或解散你的私人外科医生。', '', '', '\"I\'m a surgeon, not a companion.\"', '', '', '', '“我是外科医生，不是同伴。”', '', '');
INSERT INTO `locales_spell` VALUES (46472, 'Auctioneer Drezbit', '', '', '', '拍卖师德雷兹比特', '', '', '', '', '', '', '', '', '', 'Summon your local Goblin entrepreneur. Buy, sell, bid — he’s got the best deals anywhere!', '', '', '', '召唤当地的妖精企业家。购买、出售、出价——他在任何地方都能获得最优惠的价格！', '', '', '\"I got the best deals anywhere!\"', '', '', '', '“我在任何地方都得到了最好的合约！”', '', '');
INSERT INTO `locales_spell` VALUES (46473, 'Green Steam Tonk', '', '', '', '绿色蒸汽坦克', '', '', '', '', '', '', '', '', '', 'A favorite of children across Azeroth, this tough little toy can withstand even the most aggressive imagination.', '', '', '', '这款坚固的小玩具是艾泽拉斯各地孩子们的最爱，甚至可以承受最激进的想象力。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46474, 'Purple Steam Tonk', '', '', '', '紫色蒸汽坦克', '', '', '', '', '', '', '', '', '', 'Summon and control your steam tonk.', '', '', '', '召唤并控制你的蒸汽坦克。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46475, 'Teldrassil Sproutling', '', '', '', '泰达希尔幼苗', '', '', '', '', '', '', '', '', '', 'What a happy little tree!', '', '', '', '多么幸福的小树呀！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46476, 'Lost Farm Sheep', '', '', '', '走丢的农场绵羊', '', '', '', '', '', '', '', '', '', 'A friendly farm sheep that wandered away from its flock, it now follows you faithfully, providing a comforting presence in the midst of your adventures.', '', '', '', '一只友好的农场羊离开了羊群，现在它忠实地跟随你，在你的冒险中提供安慰的存在。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46477, 'Lulu', '', '', '', '露露', '', '', '', '', '', '', '', '', '', 'A friendly farm sheep that wandered away from its flock, it now follows you faithfully, providing a comforting presence in the midst of your adventures.', '', '', '', '一只友好的农场羊离开了羊群，现在它忠实地跟随你，在你的冒险中提供安慰的存在。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46478, 'Onyxian Whelpling', '', '', '', '奥尼克西亚雏龙', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your black Whelpling.', '', '', '', '右键单击以召唤或解散你的黑色雏龙。', '', '', 'I beat Onyxia and all I got was this lousy tabard!', '', '', '', '我打败了奥妮克希亚，而我得到的只是这件糟糕的战袍！', '', '');
INSERT INTO `locales_spell` VALUES (46479, 'Hedwig', '', '', '', '海德薇', '', '', '', '', '', '', '', '', '', 'Happy Winter Veil!', '', '', '', '冬幕快乐！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46480, 'Little Pony', '', '', '', '小马驹', '', '', '', '', '', '', '', '', '', 'Adopted during Valentine\'s Day.', '', '', '', '情人节期间收养的。', '', '', 'Stored in a glass jar.', '', '', '', '存放在玻璃罐中.', '', '');
INSERT INTO `locales_spell` VALUES (46481, 'Prince Herman II', '', '', '', '赫尔曼亲王二世', '', '', '', '', '', '', '', '', '', 'In loving memory of our favourite raiding kitty.', '', '', '', '为了纪念我们最喜欢的袭击小猫。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46482, 'Little Cow', '', '', '', '小奶牛', '', '', '', '', '', '', '', '', '', 'Adopted during Valentine\'s Day.', '', '', '', '情人节期间收养的。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46483, 'Caravan Kodo', '', '', '', '科多兽篷车', '', '', '', '', '', '', '', '', '', 'Carries all your worldly possessions, there and back.', '', '', '', '随身携带您所有的世俗财产。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46484, 'Little Fawn', '', '', '', '小鹿', '', '', '', '', '', '', '', '', '', 'She likes the company of friends. Seventy-five of them, to be precise.', '', '', '', '她喜欢朋友的陪伴。准确地说，有七十五个。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46485, 'Li\'l Foot', '', '', '', '小脚', '', '', '', '', '', '', '', '', '', 'It\'s about to hatch! What could be inside?', '', '', '', '它快要孵化了！里面可能是什么？', '', '', '\"I hate being little!\"', '', '', '', '“我讨厌变小！”', '', '');
INSERT INTO `locales_spell` VALUES (46486, 'Nerubling', '', '', '', '诺如布灵', '', '', '', '', '', '', '', '', '', 'It\'s moving!', '', '', '', '它在动！', '', '', 'Spooder', '', '', '', '蜘蛛侠', '', '');
INSERT INTO `locales_spell` VALUES (46487, 'Beaky', '', '', '', '贝基', '', '', '', '', '', '', '', '', '', 'A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol.', '', '', '', '这些幼崽是蛮锤矮人送给联盟英雄的礼物，它们是弗斯塔德和他的随从进入格瑞姆巴托时骑乘的同一只狮鹫的后代。', '', '', 'Loves collecting shiny coins.', '', '', '', '喜欢收集闪亮的硬币。', '', '');
INSERT INTO `locales_spell` VALUES (46488, 'Chromatic Whelp', '', '', '', '彩色雏龙', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your Chromatic Whelp.', '', '', '', '右键单击以召唤或解散你的彩色雏龙。', '', '', '\"Let the cuddles begin.\"', '', '', '', '“让拥抱开始吧。”', '', '');
INSERT INTO `locales_spell` VALUES (46489, 'Plagued Whelpling', '', '', '', '瘟疫雏龙', '', '', '', '', '', '', '', '', '', 'This foreboding creature stalks the night skies of the Eastern Plaguelands, feeding on carrion.', '', '', '', '这种不祥的生物在东瘟疫之地的夜空中徘徊，以腐肉为食。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46490, 'Ro\'Paw', '', '', '', '罗帕', '', '', '', '', '', '', '', '', '', 'Extremely trustworthy individual.', '', '', '', '非常值得信赖的人。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46491, 'Tirisfal Batling', '', '', '', '提瑞斯法蝙蝠', '', '', '', '', '', '', '', '', '', 'This foreboding creature stalks the night skies of the Eastern Plaguelands, feeding on carrion.', '', '', '', '这种不祥的生物在东瘟疫之地的夜空中徘徊，以腐肉为食。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46492, 'Infinite Whelpling', '', '', '', '无限雏龙', '', '', '', '', '', '', '', '', '', 'You better believe he knows what time it is.', '', '', '', '你最好相信他知道现在几点了。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46493, 'Phoenix Hatchling', '', '', '', '凤凰雏鸟', '', '', '', '', '', '', '', '', '', 'A child of phoenix god Al\'ar, the hatchling takes flight immediately after birth.', '', '', '', '作为凤凰神阿尔的孩子，幼体出生后立即飞行。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46494, 'Spectral Faeling', '', '', '', '光谱法灵', '', '', '', '', '', '', '', '', '', 'This unique species of faerie dragon is not usually found on Azeroth.', '', '', '', '这种独特的精灵龙在艾泽拉斯上并不常见。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46495, 'Tiny Pterrodax', '', '', '', '小翼手龙', '', '', '', '', '', '', '', '', '', 'In older age, these little terrors eat everything they want to and are prey to almost no other species.', '', '', '', '到了老年，这些小恐怖分子想吃什么就吃什么，并且几乎不成为其他物种的猎物。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46496, 'Pinchy', '', '', '', '平奇', '', '', '', '', '', '', '', '', '', 'These arthropods line many Azerothian shores and seek to fulfill their one true desire: to pinch.', '', '', '', '这些节肢动物分布在艾泽拉斯的许多海岸上，并寻求实现它们唯一的真正愿望：掐食。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46497, 'Sunscale Hatchling', '', '', '', '日鳞雏龙', '', '', '', '', '', '', '', '', '', 'The bright scales of this rare wind serpent soak up the sunlight to keep it warm, even in shade.', '', '', '', '这种罕见的风蛇的明亮鳞片吸收阳光，即使在阴凉处也能保持温暖。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46498, 'Add Companion to Collection', '', '', '', '将同伴添加到集合', '', '', 'Collection', '', '', '', '采集', '', '', 'Adds a companion to the player\'s companion collection.', '', '', '', '在玩家的同伴收藏中增加一个新同伴。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46499, 'Add Mount to Collection', '', '', '', '将坐骑添加到收藏夹', '', '', 'Collection', '', '', '', '采集', '', '', 'Adds a mount to the player\'s mount collection.', '', '', '', '在玩家的坐骑收藏中增加一个新坐骑。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46500, 'Scale of the Blue Drake', '', '', '', '蓝龙之鳞', '', '', '', '', '', '', '', '', '', 'Your Frostbolts do $s1 extra damage.', '', '', '', '你的寒冰箭造成$s1点额外伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (46501, 'Armored Violet War Raptor', '', '', '', '装甲紫罗兰战争迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46502, 'Red War Raptor', '', '', '', '红色战争迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46503, 'Obsidian War Raptor', '', '', '', '黑曜石战争迅猛龙', '', '', '', '', '', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', '', '', '', '这些丛林猎人是巨魔的长期盟友，与他们的主人建立了特殊的联系。他们成为战马、守护者和朋友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46504, 'Red Goblin Shredder', '', '', '', '红色地精伐木机', '', '', '', '', '', '', '', '', '', 'Fueled by a desire to extract and exploit the natural wonders of Azeroth.', '', '', '', '受到提取和开发艾泽拉斯自然奇观的渴望的推动。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46505, 'Green Goblin Shredder', '', '', '', '绿色地精伐木机', '', '', '', '', '', '', '', '', '', 'The destructive nature of goblins is best characterized by their shredders.', '', '', '', '地精的破坏性本质最能体现在它们的粉碎机上。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46506, 'Red Spidertank', '', '', '', '红色蜘蛛坦克', '', '', '', '', '', '', '', '', '', 'Four-legged machine of destruction, for your riding pleasure.', '', '', '', '四足毁灭机器，为你带来骑行乐趣。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46507, 'Black Spidertank', '', '', '', '黑色蜘蛛坦克', '', '', '', '', '', '', '', '', '', 'Smoky, sparky, and loud.', '', '', '', '烟雾缭绕、闪闪发光、响亮。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46508, 'Blue Spidertank', '', '', '', '蓝色蜘蛛坦克', '', '', '', '', '', '', '', '', '', 'The check engine light is always on, it\'s when it goes off that you should be worried.', '', '', '', '检查发动机灯始终亮起，只有当它熄灭时您才应该担心。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46509, 'Green Spidertank', '', '', '', '绿色蜘蛛坦克', '', '', '', '', '', '', '', '', '', 'This mechaspider specializes in drilling, clamping, and shooting at the same time. A typical gnome invention.', '', '', '', '这款机械蜘蛛擅长同时钻孔、夹紧和射击。典型的侏儒发明。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
