INSERT INTO `locales_spell` VALUES (46518, 'Magic Broom', '', '', '', '魔法扫帚', '', '', '', '', '', '', '', '', '', 'Summons and dismisses a rideable broomstick. Speed is increased based on your Riding skill.', '', '', '', '召唤或解散一把可供骑乘的扫帚。根据您的骑行技能提高速度。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46519, 'Happy Whimsyshire Cloud', '', '', '', '快乐的奇思妙想云', '', '', '', '', '', '', '', '', '', 'The fluffiest little cloud in Azeroth.', '', '', '', '艾泽拉斯最蓬松的小云。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46520, 'Sad Whimsyshire Cloud', '', '', '', '悲伤的奇思妙想云', '', '', '', '', '', '', '', '', '', 'Now the sun is in the sky, and for no reason why, the sad cloud is crying itself away.', '', '', '', '现在太阳当空，无缘无故地，悲伤的云彩自己哭走了。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46521, 'Lovely Pink Pony', '', '', '', '可爱的粉红小马', '', '', '', '', '', '', '', '', '', 'A delightful companion, bringing joy and happiness wherever it goes.', '', '', '', '一个令人愉快的伴侣，无论走到哪里都会带来欢乐和幸福。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (46522, 'Lovely Pink Furline', '', '', '', '可爱的粉红毛球', '', '', '', '', '', '', '', '', '', 'A cuddly and adorable creature, enchanting all who lay eyes upon it.', '', '', '', '一个可爱又可爱的生物，让所有看到它的人都着迷。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据骑术技能提高速度。', '', '');
