INSERT INTO `locales_spell` VALUES (47350, 'Legion Strike', '', '', '', '军团打击', '', '', '', '', '', '', '', '', '', 'A sweeping attack that does $s1% of the Felguard\'s weapon damage divided among all targets within 5 yards. The Felguard\'s current target is also wounded, reducing the effectiveness of any healing received by $s2% for $d.', '', '', '', '一次横扫攻击，造成$s1%武器伤害，由5码内的所有目标分摊。恶魔守卫的当前目标也受伤，减少$s2%受到的任何治疗效果，持续$d。', '', '', 'Healing effects reduced by $s2%.', '', '', '', '治疗效果降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (47351, 'Pursuit', '', '', '', '追击', '', '', '', '', '', '', '', '', '', 'Charge an enemy, instantly causing $s3% weapon damage and increasing the Felguard\'s movement speed by $s2% for $d.', '', '', '', '向敌人冲锋，立即造成$s3%的武器伤害，并使恶魔守卫的移动速度提高$s2%，持续$d。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (47352, 'Axe Toss', '', '', '', '投斧', '', '', '', '', '', '', '', '', '', 'The Felguard hurls his axe, stunning the target for $d.', '', '', '', '恶魔守卫投掷他的斧头，击晕目标$d。', '', '', 'Stunned.', '', '', '', '昏迷。', '', '');
INSERT INTO `locales_spell` VALUES (47353, 'Felstorm', '', '', '', '邪能风暴', '', '', '', '', '', '', '', '', '', 'The Felguard recklessly swings its weapon, striking all nearby targets for $d causing weapon damage plus an additional $9633s1 every $t1 sec.', '', '', '', '恶魔守卫鲁莽地挥舞着它的武器，攻击所有附近目标，在$d内每$t1秒造成武器伤害和$9633s1点附加伤害。', '', '', 'Attacking all nearby enemies for weapon damage + $9633s1.', '', '', '', '攻击附近所有敌人造成武器伤害和$9633s1点附加伤害。', '', '');
INSERT INTO `locales_spell` VALUES (47354, 'Beast Mastery', '', '', '', '驯兽', '', '', '', '', '', '', '', '', '', 'Increases your pet\'s damage by $s1%, maximum health by $s2% and critical strike chance by $s3%.', '', '', '', '使宠物的伤害提高 $s1%，最大生命值提高 $s2%，爆击几率提高 $s3%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (47355, 'Beast Mastery', '', '', '', '驯兽', '', '', '', '', '', '', '', '', '', 'Increases your pet\'s damage by 3%, maximum health by 5% and critical strike chance by 2%.', '', '', '', '使宠物的伤害提高 3%，最大生命值提高 5%，暴击率提高 2%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (47356, 'Improved Bleeds', '', '', '', '改善出血', '', '', '', '', '', '', '', '', '', 'Reduces the time between periodic ticks and duration of Rake and Rip by $s1%.', '', '', '', '使周期性伤害间隔时间以及扫击和撕扯的持续时间减少 $s1%。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (47357, 'Calming River', '', '', '', '平静的河流', '', '', '', '', '', '', '', '', '', 'Your Water Shield ability grants an additional 8 mana per 5 sec. while active. In addition the amount of mana restored by your Water Shield when attacked is increased by $s2.', '', '', '', '你的水盾能力每 5 秒额外获得 6 点法力。活跃时。', '', '', '', '', '', '', '', '', '');
