INSERT INTO `locales_spell` VALUES (47359, 'Improved Barkskin', '', '', '', '改良树皮', '', '', '', '', '', '', '', '', '', 'Increases the duration of Barkskin by $/1000;s1 secs.', '', '', '', '使树皮的持续时间增加 $/1000;s1 秒。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (47360, 'Dragon Breath', '', '', '', '龙的呼吸', '', '', '', '', '', '', '', '', '', 'Inflicts $s1 Fire damage to enemies in a cone in front of the caster.', '', '', '', '对施法者前方锥形范围内的敌人造成 $s1 火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48000, 'Lifebinding', '', '', '', '生命束缚', '', '', '', '', '', '', '', '', '', 'Your direct healing spells have a chance to place a heal over time on your target, healing $48001o1 over $48001d.', '', '', '', '你的直接治疗法术有机会对目标进行持续治疗，在$48001d内恢复$48001o1点生命值。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48001, 'Lifebinding', '', '', '', '生命束缚', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Heals the target for $o1 damage over $d.', '', '', '', '使目标在$d内恢复$o1点生命值。', '', '', 'Healing $s1 damage every $t1 sec.', '', '', '', '每$t1秒恢复$s1点生命值。', '', '');
INSERT INTO `locales_spell` VALUES (48002, 'Dark Accord', '', '', '', '黑暗协奏曲', '', '', '', '', '', '', '', '', '', 'Restores $s1 mana at the cost of $s2 life.', '', '', '', '消耗$s2点生命值恢复$s1点法力值。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48003, 'Burning Hatred', '', '', '', '燃烧的仇恨', '', '', '', '', '', '', '', '', '', 'Chance on landing a damaging spell to deal 250 Fire damage while sacrificing 250 health.', '', '', '', '你的伤害法术命中时有几率消耗$s1点生命值造成$s2点火焰伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48004, 'Dream\'s Herald', '', '', '', '梦想先驱', '', '', '', '', '', '', '', '', '', 'Blasts all targets in front of you with debilitating poison gas, dealing $o1 Nature damage over 12 sec, reducing attack and movement speed by 20%.', '', '', '', '用虚弱毒气冲击你面前的所有目标，在12秒内造成$o1点自然伤害，并使其攻击速度和移动速度降低20%。', '', '', 'Movement and attack speed lowered by 20% and taking periodic Nature damage.', '', '', '', '移动速度和攻击速度降低20%，并周期性受到自然伤害。', '', '');
INSERT INTO `locales_spell` VALUES (48005, 'Frostbolt', '', '', '', '寒冰箭', '', '', '', '', '', '', '', '', '', 'Launches a bolt of frost at the enemy causing $s2 Frost damage and slowing movement speed by $s1% for $d.', '', '', '', '向目标射出一支寒冰箭，对其造成$s2点冰霜伤害，并使其移动速度降低$s1%，持续$d。', '', '', 'Movement slowed by $s1%.', '', '', '', '移动速度降低$s1%。', '', '');
INSERT INTO `locales_spell` VALUES (48006, 'Strike', '', '', '', '打击', '', '', '', '', '', '', '', '', '', 'Strikes at an enemy, inflicting 50% weapon damage.', '', '', '', '攻击敌人，造成50%武器伤害。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48007, 'Counter-Strike', '', '', '', '反击', '', '', '', '', '', '', '', '', '', 'When struck in combat has a $h% chance to return with a counterattack.', '', '', '', '被攻击时有$h%几率进行反击。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48008, 'Bloodletting', '', '', '', '放血', '', '', 'Rank 1', '', '', '', '等级 1', '', '', 'Wounds the target for 100 damage over $d and reduces healing taken by $s2%.', '', '', '', '使目标在$d受到$o1点伤害，并降低$s2%治疗效果。', '', '', 'Bleeding for $o1 damage and healing effectiveness reduced by $s2%.', '', '', '', '$o1点流血伤害和治疗效果降低$s2%。', '', '');
INSERT INTO `locales_spell` VALUES (48009, 'Nature Mana Reduction 10', '', '', '', '自然法力消耗降低10', '', '', '', '', '', '', '', '', '', 'Reduces the mana cost of your nature spells by $s.', '', '', '', '使你的自然法术的法力消耗降低$s。', '', '', '', '', '', '', '', '', '');
