INSERT INTO `locales_spell` VALUES (48304, 'Teresa\'s Copper Coin', '', '', '', '特蕾莎的铜币', '', '', '', '', '', '', '', '', '', 'Throw this coin into the fountain in the Stormwind City Trade District.', '', '', '', '将这枚硬币扔进暴风城贸易区的喷泉中。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (48305, 'Bromley\'s Dispelling Scroll', '', '', '', '布罗姆利的驱散卷轴', '', '', '', '', '', '', '', '', '', 'Dispel the dampening enchantment upon the Spitelash Shrine in Ruins of Eldarath.', '', '', '', '消除艾尔达拉斯废墟中恶鞭神殿上的抑制结界。', '', '', '', '', '', '', '', '', '');
