INSERT INTO `locales_spell` VALUES (49366, 'Portal: Theramore', '', '', '', '传送门：塞拉摩', '', '', '', '', '', '', '', '', '', 'Creates a portal, teleporting group members that use it to Theramore.', '', '', '', '创建一个传送门，将使用它的团体成员传送到塞拉摩。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49500, 'Dalaran Cloud Familiar', '', '', '', '达拉然云朵魔宠', '', '', '', '', '', '', '', '', '', 'A mage from Dalaran always seem so serious, until their messages are delivered by these emotive familiars.', '', '', '', '来自达拉然的法师总是显得那么严肃，直到他们的信息被这些情绪激动的魔宠传递出去。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49501, 'Finn the Shark', '', '', '', '鲨鱼芬恩', '', '', '', '', '', '', '', '', '', 'Big and safe to have at your side if you want to discover the world underneath the sea.', '', '', '', '如果您想探索海底世界，那么它又大又安全，就在您身边。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49502, 'Water Waveling', '', '', '', '水波', '', '', '', '', '', '', '', '', '', 'This Elemental has been formed personally by Duke Hydraxis as thanks for your help in fighting the Sulfuran Firelords.', '', '', '', '该元素由海达克西斯公爵亲自打造，以感谢您在对抗萨弗兰炎魔时提供的帮助。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49503, 'Mr. Bigglesworth', '', '', '', '比格沃斯先生', '', '', '', '', '', '', '', '', '', 'Upon exiting the freezing necropolis of Naxxramas, Mr. Bigglesworth promptly found a warm spot in the sun to take a long nap in.', '', '', '', '离开纳克萨玛斯冰冷的墓地后，比格斯沃思先生立即在阳光下找到了一个温暖的地方小憩了一会儿。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49504, 'Squeak', '', '', '', '吱吱', '', '', '', '', '', '', '', '', '', 'Annoying and destructive, they can be coaxed with enough cheese to become a tolerable companion.', '', '', '', '它们既烦人又具有破坏性，可以用足够的奶酪来哄它们，使其成为一个可以忍受的伴侣。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49505, 'Lil\' Tinyfin', '', '', '', '鱼人宝宝', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss Tinyfin!', '', '', '', '右键单击以召唤或解散鱼人宝宝!', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49506, 'Mr. Tails', '', '', '', '尾巴先生', '', '', '', '', '', '', '', '', '', 'Save up on acorns along the way and share some undivided attention & love with Mr.Tails and he\'ll be the best companion on your long journey through Azeroth.', '', '', '', '一路上节省一些橡子，并与尾巴先生分享一些全心全意的关注和爱，他将成为你穿越艾泽拉斯的漫长旅程中最好的伴侣。', '', '', 'Save up on acorns along the way and share some undivided attention & love with Mr.Tails and he\'ll be the best companion on your long journey through Azeroth.', '', '', '', '在旅途中收集橡子与尾巴先生分享并给予他关注和爱护，他将成为你穿越艾泽拉斯的漫长旅程中的最佳伴侣。', '', '');
INSERT INTO `locales_spell` VALUES (49507, 'Sammy!', '', '', '', '萨米！', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss Sammy!', '', '', '', '右键单击以召唤或解散山米！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49508, 'Gilnean Raven', '', '', '', '乌鸦', '', '', '', '', '', '', '', '', '', 'For generations, the ravens of Gilneas have served as a timeless symbol of regal authority, reminding all of the lasting influence of House Greymane, even in the darkest of nights.', '', '', '', '世世代代以来，吉尔尼斯的乌鸦一直是王权的永恒象征，提醒所有人格雷迈恩家族的持久影响，即使在最黑暗的夜晚也是如此。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49509, 'Tiny Warp Stalker', '', '', '', '小迁跃捕猎者', '', '', '', '', '', '', '', '', '', 'Not only is it quick, it\'s loud too!', '', '', '', '不仅速度快，而且声音也很大！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49510, 'SC-0-TT1', '', '', '', 'SC-0-TT1', '', '', '', '', '', '', '', '', '', 'Unique and intelligent piece of genius engineering!', '', '', '', '独特而智能的天才工程！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49511, 'Flipper', '', '', '', '菲利普', '', '', '', '', '', '', '', '', '', 'Notable for its wide eyes and sassy slide.', '', '', '', '以其大眼睛和时髦的幻灯片而闻名。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49512, 'Pengu', '', '', '', '企鹅', '', '', '', '', '', '', '', '', '', 'It\'s appearance evokes a more civilized era, when duelists battled in tuxedos.', '', '', '', '它的外观让人想起一个更加文明的时代，当时决斗者穿着燕尾服进行战斗。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49513, 'Midnight', '', '', '', '午夜', '', '', '', '', '', '', '', '', '', 'Ride with the moon (and this furry, whiskered witch) in the dead of night!', '', '', '', '在夜深人静的时候与月亮（还有这个毛茸茸的、长着胡须的女巫）一起骑行！', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49514, 'Glitterwing', '', '', '', '闪光之翼', '', '', '', '', '', '', '', '', '', 'These flying creatures do not leave feathers out in the wild. If a feather happens to ever detach from their body, the feather glows brilliantly for a moment and then vanishes from sight.', '', '', '', '这些飞行的生物不会在野外留下羽毛。如果一根羽毛碰巧从他们的身体上脱落，羽毛会发出短暂的光芒，然后从视线中消失。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49515, 'Spectral Cub', '', '', '', '光谱幼崽', '', '', '', '', '', '', '', '', '', 'Affectionate and curious, these kittens seem to find the most peculiar hiding places.', '', '', '', '这些小猫充满感情和好奇，似乎找到了最奇特的藏身之处。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49516, 'Kruxis', '', '', '', '克鲁西斯', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss Kruxis.', '', '', '', '右键单击以召唤或解散克鲁西斯。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49517, 'Lovely Pink Fox', '', '', '', '可爱的粉红色狐狸', '', '', '', '', '', '', '', '', '', 'A shy creature, the pink fox will only make its presence known to those that have befriended it.', '', '', '', '粉红狐狸是一种害羞的生物，只会让那些与它成为朋友的人知道它的存在。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49518, 'Unholy Toy Staff', '', '', '', '邪恶的玩具法杖', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your unholy toy weapon.', '', '', '', '右键单击以召唤或解散你的邪恶的玩具武器。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49519, 'Unholy Toy Axe', '', '', '', '邪恶的玩具斧头', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your unholy toy weapon.', '', '', '', '右键单击以召唤或解散你的邪恶的玩具武器。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49520, 'Young Mutant Warturtle', '', '', '', '小变异疣龟', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your warturtle.', '', '', '', '右键单击以召唤或解散你的疣龟。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49521, 'Wyvern Roost Hatchling', '', '', '', '双足飞龙幼崽', '', '', '', '', '', '', '', '', '', 'Even in this tiny form, the wyvern is fierce.', '', '', '', '即使是这种微小的形态，双足飞龙也很凶猛。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49522, 'Companion Pet [PH]', '', '', '', 'Companion Pet [PH]', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your companion.', '', '', '', '右键单击以召唤或解散你的companion。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49523, 'Lazy Peon', '', '', '', '懒惰的苦工', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your lazy peon.', '', '', '', '右键单击以召唤或解散你的懒惰的苦工。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49524, 'Call of Sul\'thraze', '', '', '', '苏萨雷兹的召唤', '', '', '', '', '', '', '', '', '', 'Combines Jang\'thraze and Sang\'thraze to form the mighty sword, Sul\'thraze.', '', '', '', '将 Jang\\\'thraze 和 Sang\\\'thraze 结合形成强大的剑 Sul\\\'thraze。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49525, 'Call of Blades', '', '', '', '刀锋召唤', '', '', '', '', '', '', '', '', '', 'Conjures the dual blades of Sul\'thraze.', '', '', '', '召唤出苏萨泽的双刃。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (49526, 'Schematic: Thorium Grenade', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
