INSERT INTO `locales_spell` VALUES (50000, 'Slow & Steady', '', '', '', '龟速模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Gaining 50% fewer experience points from defeating enemies. Lose 5% of accumulated experience from current level upon being defeated by enemies.', '', '', '', '击杀敌人获得的经验减少50%。被敌人击败时，损失当前等级5%的经验值。', '', '', 'Taking it easy.', '', '', '', '放轻松。', '', '');
INSERT INTO `locales_spell` VALUES (50001, 'Hardcore', '', '', '', '硬核模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Upon death your spirit is lost to the Twisting Nether, unable to ever return to the Material Plane.', '', '', '', '死亡后，你的灵魂将迷失在扭曲虚空，无法再回到物质位面。', '', '', 'Consider yourself born again hardcore!', '', '', '', '把自己视为一条命的硬核模式！', '', '');
INSERT INTO `locales_spell` VALUES (50002, 'Survivalist', '', '', '', '生存主义者', '', '', 'Challenge', '', '', '', '挑战', '', '', 'More easily wethered by the elements.  Must overcome hunger, thirst, encumbrance, temperature, tiredness, sickness, and injury in order to survive.', '', '', '', '更容易受环境影响。必须克服饥饿、口渴、负重、温度、疲劳、疾病和伤痛才能生存。', '', '', 'Roughing it.', '', '', '', '艰苦求生。', '', '');
INSERT INTO `locales_spell` VALUES (50003, 'Twinking', '', '', '', '锁级', '', '', 'Challenge', '', '', '', '挑战', '', '', 'No longer gaining experience points from any source.', '', '', '', '不再从任何来源获得经验值。', '', '', 'Not gaining experience.', '', '', '', '没有经验获取。', '', '');
INSERT INTO `locales_spell` VALUES (50004, 'Exhaustion', '', '', '', '疲倦', '', '', 'Challenge', '', '', '', '挑战', '', '', 'No longer gaining rested experience.', '', '', '', '不再获得休息经验。', '', '', 'You feel normal. All the time.', '', '', '', '你将一直保持正常状态。', '', '');
INSERT INTO `locales_spell` VALUES (50005, 'Diplomat', '', '', '', '外交官', '', '', 'Perk', '', '', '', 'Perk', '', '', 'As a diplomat, you have proved to be aware of the real issues. You now know how to speak with the other faction and are allowed to trade and group with them.', '', '', '', '可以与其他势力交谈，并与他们进行交易和组队。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50006, 'Hardcore', '', '', '', '硬核模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Upon death your spirit is lost to the Twisting Nether, unable to ever return to the Material Plane.', '', '', '', '死亡后，你的灵魂将迷失在扭曲虚空，无法再回到物质位面。', '', '', 'Enables the Hardcore challenge.', '', '', '', '开启硬核模式挑战。', '', '');
INSERT INTO `locales_spell` VALUES (50007, 'Lone Wolf', '', '', '', '独狼', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Trading with players and use of the Auction House are disabled.\n\nRestricted  from grouping with other players. \n\nCannot craft gear.\n\nCannot use consumables other than health potions.\n\nAutomatically revive at a graveyard upon death.', '', '', '', '禁止与玩家交易和使用拍卖行。\n\n限制与其他玩家组队。 \n\n无法制作装备。\n\n不能使用生命药水以外的消耗品。\n\n死后自动在墓地复活。', '', '', 'Going your own way.', '', '', '', '孤身上路。', '', '');
INSERT INTO `locales_spell` VALUES (50008, 'War Mode', '', '', '', '战争模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You can no longer disable PvP mode but experience and honor gains from all sources are increased by 20%.', '', '', '', '你不能再禁用PvP，但增加了从所有来源获得的经验。', '', '', 'Permanently flagged for PvP.', '', '', '', '永久标记为PvP。', '', '');
INSERT INTO `locales_spell` VALUES (50009, 'Baxxil', '', '', '', '巴克西尔', '', '', '', '', '', '', '', '', '', 'Right Click to summon and dismiss your Baxxil.', '', '', '', '右键单击召唤或解散你的 Baxxil。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50010, 'Wanted!', '', '', '', '通缉！', '', '', 'Role', '', '', '', 'Role', '', '', 'A bounty of $s1 gold has been put on your head.', '', '', '', '你被通缉了，赏金价值$s1金币。', '', '', 'Bounty worth $s1 gold.', '', '', '', '赏金价值$s1金币。', '', '');
INSERT INTO `locales_spell` VALUES (50011, 'Bounty Hunter', '', '', '', '赏金猎人', '', '', 'Role', '', '', '', 'Role', '', '', 'Tasked with hunting down Outlaws and claiming their bounties.', '', '', '', '任务是追捕亡命之徒并索取他们的赏金。', '', '', 'On the lookout for outlaws.', '', '', '', '寻找悬赏目标。', '', '');
INSERT INTO `locales_spell` VALUES (50012, 'Waste of Skin', '', '', '', '浪费皮囊', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You are nothing. Talentless. You shouldn\'t have been born.', '', '', '', '你不是东西，无才才德，根本就不该出生。', '', '', 'Hideous.', '', '', '', '可怕。', '', '');
INSERT INTO `locales_spell` VALUES (50013, 'Day Trader', '', '', '', '操盘手', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Time is money, friend!\n\n-Cannot trade with or receive mail from other players.\n\n-Items sold to vendors have no value.', '', '', '', '时间就是金钱，朋友！\n\n-不能与其他玩家交易或接收来自其他玩家的邮件。\n\n-卖给商贩的物品没有价值。', '', '', 'Greed is good.', '', '', '', '贪婪是好的。', '', '');
INSERT INTO `locales_spell` VALUES (50014, 'Vagrant\'s Endeavor', '', '', '', '流浪者模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You can only use poor and common quality equipment. Enchanting items is not allowed.', '', '', '', '你只能使用劣质和普通的装备。不允许使用附魔物品。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50015, 'Pacifist', '', '', '', '和平主义者', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Cannot attack or take actions that would harm a target. Gain increased experience from crafting and gathering items.', '', '', '', '无法攻击或采取会伤害目标的行动。通过制作和收集物品获得更多经验。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50016, 'Dual Specialization', '', '', '', '双天赋', '', '', 'Perk', '', '', '', 'Perk', '', '', 'Able to save a second specialization to the Goblin Brainwashing Machine.', '', '', '', '可以保存第二套天赋到地精洗脑机。', '', '', '', '', '', '', '', '', '');
