INSERT INTO `locales_spell` VALUES (50032, '[Aura] Hardcore', '', '', '', '[光环] 硬核模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Upon death your spirit is lost to the Twisting Nether, unable to ever return to the Material Plane.', '', '', '', '死亡后，你的灵魂将迷失在扭曲的虚空中，永远无法回到物质世界。', '', '', 'Consider yourself born again hardcore! TESTING', '', '', '', 'Consider yourself born again hardcore! TESTING', '', '');
INSERT INTO `locales_spell` VALUES (50033, '[AURA] War Mode', '', '', '', '[光环] 战争模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You can no longer disable PvP but experience gain from all sources is increased.', '', '', '', '您无法再禁用PvP，但会增加任意来源的经验值。', '', '', 'Permanently flagged for PvP. TEST', '', '', '', 'Permanently flagged for PvP。 TEST', '', '');
INSERT INTO `locales_spell` VALUES (50034, 'Inferno', '', '', '', '地狱', '', '', 'Challenge', '', '', '', '挑战', '', '', 'The fire within you stoked by overcoming hardship has grown into a raging inferno. Should you die, it will be snuffed out forever.', '', '', '', '你内心因克服困难而燃起的火焰已变成熊熊烈火。如果你死了，它就会永远消失。', '', '', 'Burning bright.', '', '', '', '燃烧明亮。', '', '');
INSERT INTO `locales_spell` VALUES (50035, 'Hardcore', '', '', '', '硬核', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Upon death your spirit is lost to the Twisting Nether, unable to ever return to the Material Plane.', '', '', '', '死亡后，你的灵魂会消失在扭曲虚空，无法返回主物质位面。', '', '', 'Consider yourself born again hardcore!', '', '', '', '认为自己是重生的铁杆！', '', '');
INSERT INTO `locales_spell` VALUES (50036, 'Survivalist', '', '', '', '生存主义者', '', '', 'Challenge', '', '', '', '挑战', '', '', 'More easily wethered by the elements.  Must overcome hunger, thirst, encumbrance, temperature, tiredness, sickness, and injury in order to survive.', '', '', '', '更容易受到自然因素的影响。为了生存，必须克服饥饿、口渴、负担、温度、疲劳、疾病和伤害。', '', '', 'Roughing it.', '', '', '', '粗加工它。', '', '');
