INSERT INTO `locales_spell` VALUES (50039, 'Lone Wolf', '', '', '', '独狼', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Trading with players and use of the Auction House are disabled.\n\nRestricted  from grouping with other players. \n\nCannot craft gear.\n\nCannot use consumables other than health potions.\n\nAutomatically revive at a graveyard upon death.', '', '', '', '与玩家的交易和拍卖行的使用被禁用。禁止与其他玩家组队。无法制作装备。不能使用除生命药水以外的消耗品。死亡后自动在墓地复活。', '', '', 'Going your own way.', '', '', '', '走自己的路。', '', '');
INSERT INTO `locales_spell` VALUES (50040, 'War Mode', '', '', '', '战争模式', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You can no longer disable PvP but experience gain from all sources is increased.', '', '', '', '您无法再禁用 PvP，但所有来源的经验增益都会增加。', '', '', 'Permanently flagged for PvP.', '', '', '', '永久标记为 PvP。', '', '');
INSERT INTO `locales_spell` VALUES (50041, 'Wanted!', '', '', '', '通缉！', '', '', 'Role', '', '', '', 'Role', '', '', 'A bounty of $s1 gold has been put on your head.', '', '', '', '悬赏金 $s1 悬赏给你的人头。', '', '', 'Bounty worth $s1 gold.', '', '', '', '赏金价值 $s1 金币。', '', '');
INSERT INTO `locales_spell` VALUES (50042, 'Bounty Hunter', '', '', '', '赏金猎人', '', '', 'Role', '', '', '', 'Role', '', '', 'Tasked with hunting down Outlaws and claiming their bounties.', '', '', '', '其任务是追捕亡命之徒并索取他们的赏金。', '', '', 'On the lookout for outlaws.', '', '', '', '寻找不法之徒。', '', '');
INSERT INTO `locales_spell` VALUES (50043, 'Waste of Skin', '', '', '', '浪费皮肤', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You are nothing. Talentless. You shouldn\'t have been born.', '', '', '', '你什么都不是。无才。你不应该出生。', '', '', 'Hideous.', '', '', '', '可怕。', '', '');
INSERT INTO `locales_spell` VALUES (50044, 'Day Trader', '', '', '', '日间交易者', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Time is money, friend!\n\n-Cannot trade with or receive mail from other players.\n\n-Items sold to vendors have no value.', '', '', '', '时间就是金钱，朋友！ - 无法与其他玩家交易或接收来自其他玩家的邮件。 - 卖给供应商的物品没有价值。', '', '', 'Greed is good.', '', '', '', '贪婪是好的。', '', '');
INSERT INTO `locales_spell` VALUES (50045, 'Vagrant\'s Endeavor', '', '', '', '流浪者的奋斗', '', '', 'Challenge', '', '', '', '挑战', '', '', 'You can only use poor and common quality equipment. Enchanting items is not allowed.', '', '', '', '你只能使用劣质和普通的设备。不允许使用附魔物品。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50046, 'Pacifist', '', '', '', '和平主义者', '', '', 'Challenge', '', '', '', '挑战', '', '', 'Cannot attack or take actions that would harm a target. Gain increased experience from crafting and gathering items.', '', '', '', '无法攻击或采取会伤害目标的行动。通过制作和收集物品获得更多经验。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (50050, 'Big Turtle WoW Bear', '', '', '', '大乌龟魔兽熊', '', '', '', '', '', '', '', '', '', 'The Murloc rider on its back is a skilled warrior! He is a proud member of the Turtle WoW community, and he is always ready to defend his server against any threat.', '', '', '', '它背上的鱼人骑手是一位技术精湛的战士！他是 Turtle WoW 社区的一名自豪的成员，他随时准备保护他的服务器免受任何威胁。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50051, 'Black Spectral Tiger', '', '', '', '黑幽灵虎', '', '', '', '', '', '', '', '', '', 'This fierce tiger is shrouded in dark energy, making it a fearsome sight on the battlefield. Those who ride it are said to embody the power of the shadows.', '', '', '', '这只猛虎浑身笼罩着黑暗能量，在战场上显得十分可怕。据说乘坐它的人体现了阴影的力量。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50052, 'Green Spectral Tiger', '', '', '', '绿幽灵虎', '', '', '', '', '', '', '', '', '', 'A rare and elusive mount, the Green Spectral Tiger is said to be blessed by the spirits of the forest. Those who ride it are said to have a connection to nature itself.', '', '', '', '绿幽灵虎是一种罕见且难以捉摸的坐骑，据说受到森林之灵的祝福。据说乘坐它的人与大自然本身有着联系。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50053, 'Ice Raptor', '', '', '', '冰猛禽', '', '', '', '', '', '', '', '', '', 'This sleek and agile raptor is adapted to the harsh, icy environments of the north. Its sharp claws and teeth make it a formidable mount in battle.', '', '', '', '这种光滑而敏捷的猛禽适应了北方严酷、冰冷的环境。它锋利的爪子和牙齿使其成为战斗中令人畏惧的坐骑。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50054, 'Armored Ice Raptor', '', '', '', '装甲冰猛禽', '', '', '', '', '', '', '', '', '', 'It is a fearsome sight, covered in thick plates of icy armor. Those who ride it are said to be as tough as the raptor itself.', '', '', '', '这是一个可怕的景象，覆盖着厚厚的冰甲。据说那些骑着它的人就像猛禽本身一样坚韧。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50055, 'Scarlet Charger', '', '', '', '猩红战马', '', '', '', '', '', '', '', '', '', 'It is often ridden by those who seek to inspire fear in their enemies.', '', '', '', '那些试图激起敌人恐惧的人经常骑乘它。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50056, 'Kul Tiran Warhorse', '', '', '', '库尔提拉斯战马', '', '', '', '', '', '', '', '', '', 'The Kul Tiran Warhorse is a sturdy and reliable mount, bred for battle and unafraid of danger. Its massive size and strength make it a formidable ally in combat.', '', '', '', '库尔提拉斯战马是一匹坚固可靠的坐骑，专为战斗而生，不惧危险。其巨大的体型和力量使其成为战斗中强大的盟友。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50057, 'Greymane Charger', '', '', '', '格雷迈恩战马', '', '', '', '', '', '', '', '', '', 'The Greymane Charger is a symbol of the Gilnean strength and resilience. Its sleek, silver coat and lightning-fast speed make it a favorite among Gilnean soldiers.', '', '', '', '格雷迈恩战马是吉尔尼斯力量和韧性的象征。它光滑的银色皮毛和闪电般的速度使其成为吉尔尼斯士兵的最爱。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50058, 'Brown Zhevra', '', '', '', '棕斑斑羚', '', '', '', '', '', '', '', '', '', 'The Brown Zhevra is a swift and sure-footed mount, able to navigate even the roughest terrain with ease. Its striped coat and graceful movements make it a popular choice among adventurers.', '', '', '', '棕斑斑马是一种敏捷且脚步稳健的坐骑，即使在最崎岖的地形上也能轻松穿行。它的条纹皮毛和优美的动作使其成为冒险家们的热门选择。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50059, 'Grim Totem Kodo', '', '', '', '冷酷图腾科多兽', '', '', '', '', '', '', '', '', '', 'The Grim Totem Kodo is a massive, hulking beast, feared by many for its sheer size and strength. Those who ride it are said to have the power of the earth at their command.', '', '', '', '冷酷图腾科多兽是一种巨大而笨重的野兽，因其庞大的体型和力量而令许多人感到恐惧。据说那些骑着它的人可以掌控大地的力量。', '', '', 'Increases speed based on your Riding skill.', '', '', '', '根据您的骑行技能提高速度。', '', '');
INSERT INTO `locales_spell` VALUES (50060, 'Baxxil Dummy', '', '', '', '巴克希尔假人', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
