INSERT INTO `locales_spell` VALUES (50901, 'Tame Decrepit Darkhound', '', '', '', '驯服衰老的黑暗犬', '', '', '', '', '', '', '', '', '', 'Begins taming a Decrepit Darkhound to be your companion for 10 minutes.  If you lose the beast\'s attention for any reason, the taming process will fail.', '', '', '', '尝试驯服一只衰老的黑暗犬，使其成为你的宠物，持续10分钟。如果你因为任何原因失去了它的注意力，则驯服过程失败。', '', '', 'Taming Decrepit Darkhound.', '', '', '', '驯服衰老的黑暗犬', '', '');
INSERT INTO `locales_spell` VALUES (50902, 'Tame Greater Dusk Bat', '', '', '', '驯服巨型夜行蝙蝠', '', '', '', '', '', '', '', '', '', 'Begins taming a Greater Dusk Bat to be your companion for 10 minutes.  If you lose the beast\'s attention for any reason, the taming process will fail.', '', '', '', '尝试驯服一只巨型夜行蝙蝠，使其成为你的宠物，持续10分钟。如果你因为任何原因失去了它的注意力，则驯服过程失败。', '', '', 'Taming Greater Dusk Bat.', '', '', '', '驯服巨型夜行蝙蝠', '', '');
