INSERT INTO `locales_spell` VALUES (57039, 'Lil\' K.T.', '', '', '', '小K.T', '', '', '', '', '', '', '', '', '', 'In life, Kel\'Thuzad betrayed the Kirin Tor and created the Cult of the Damned. In death, he serves the Scourge as the Archlich Lord of Naxxramas.', '', '', '', '在生前，克尔苏加德背叛了肯瑞托并创建了诅咒教派。死后，他作为纳克萨玛斯的大巫妖领主为天灾军团服务。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57040, 'Core Hound Pup', '', '', '', '核心猎犬幼崽', '', '', '', '', '', '', '', '', '', 'Found in the Firelands and the Molten Core, core hounds can trace their lineage back to the alpha male, Magmadar.', '', '', '', '核心猎犬出现在火焰之地和熔火之心，它们的血统可以追溯到雄性领袖玛格玛达尔。', '', '', '', '', '', '', '', '', '');
