INSERT INTO `locales_spell` VALUES (57186, 'Bloody Belt Buckle', '', '', '', '血淋淋的皮带扣', '', '', '', '', '', '', '', '', '', 'Attaches a buckle to your belt that reduces the chance you are critically hit by melee and ranged attacks by 1%.', '', '', '', '在你的腰带上安装一个带扣，可以将你受到近战和远程攻击重击的几率降低 1%。', '', '', '', '', '', '', '', '', '');
