INSERT INTO `locales_spell` VALUES (57197, 'Shadow Sight', '', '', '', '暗影视觉', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Stealth Detection.\r\nInvisibility Detection.\r\nIncreases damage taken by 5%.', '', '', '', '隐形检测。隐形检测。受到的伤害增加 5%。', '', '');
INSERT INTO `locales_spell` VALUES (57200, 'Azure Frog', '', '', '', '青蛙', '', '', '', '', '', '', '', '', '', 'A mystical amphibian known for its soothing croaks, said to bring tranquility to those who listen.', '', '', '', '一种神秘的两栖动物，以其舒缓的叫声而闻名，据说可以给倾听的人带来平静。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57201, 'Dream Frog', '', '', '', '梦青蛙', '', '', '', '', '', '', '', '', '', 'This ethereal creature is believed to possess the ability to enter the dreams of sleeping adventurers, offering them guidance and wisdom.', '', '', '', '人们相信这种空灵的生物有能力进入沉睡的冒险家的梦境，为他们提供指导和智慧。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57202, 'Bullfrog', '', '', '', '牛蛙', '', '', '', '', '', '', '', '', '', 'A robust amphibian with a powerful croak, often found near bodies of water, revered by some as a symbol of strength and resilience.', '', '', '', '一种强壮的两栖动物，发出强有力的鸣叫声，经常在水体附近发现，被一些人视为力量和韧性的象征。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57203, 'Infinite Frog', '', '', '', '无限青蛙', '', '', '', '', '', '', '', '', '', 'A peculiar frog that seems to defy the laws of time and space, hopping effortlessly between dimensions.', '', '', '', '一只奇特的青蛙，似乎违背了时间和空间的法则，毫不费力地在维度之间跳跃。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57204, 'Poison Frog', '', '', '', '毒蛙', '', '', '', '', '', '', '', '', '', 'Beware the vibrant hues of this deadly amphibian, as its skin secretes a potent toxin capable of incapacitating even the mightiest of foes.', '', '', '', '小心这种致命的两栖动物鲜艳的色彩，因为它的皮肤会分泌一种强效毒素，即使是最强大的敌人也能丧失能力。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57205, 'Snow Frog', '', '', '', '雪蛙', '', '', '', '', '', '', '', '', '', 'Native to the frigid regions of Azeroth, this hardy frog has adapted to survive in icy environments, its azure skin camouflaging it against the snowy landscapes.', '', '', '', '这种耐寒的青蛙原产于艾泽拉斯的寒冷地区，已经适应了在冰冷的环境中生存，它蔚蓝的皮肤在白雪皑皑的环境中显得很隐蔽。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57206, 'Pink Frog', '', '', '', '粉红青蛙', '', '', '', '', '', '', '', '', '', 'Delicate and enchanting, this rare frog species captivates with its vibrant pink hue, believed to bring good fortune and prosperity to its owner.', '', '', '', '这种稀有的青蛙品种精致而迷人，以其充满活力的粉红色调而令人着迷，相信可以为其主人带来好运和繁荣。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57207, 'Golden Frog', '', '', '', '金蛙', '', '', '', '', '', '', '', '', '', 'Legend has it that this shimmering amphibian is a harbinger of wealth and abundance.', '', '', '', '传说这种闪闪发光的两栖动物是财富和丰富的预兆。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57208, 'Pond Frog', '', '', '', '池塘青蛙', '', '', '', '', '', '', '', '', '', 'A common sight in tranquil ponds and marshes, this unassuming frog is a reminder of the simple joys found in nature\'s embrace.', '', '', '', '这种谦逊的青蛙在宁静的池塘和沼泽中很常见，它提醒人们在大自然的怀抱中发现简单的快乐。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57518, 'Eternal Dreamstone Shard', '', '', '', '永恒梦境碎片', '', '', '', '', '', '', '', '', '', 'The combining of dream fragments can only be done at a moonwell, and only ocassionally will the waters permit themselves to be used in such a way.', '', '', '', '梦境碎片的结合只能在月井中完成，而水也只是偶尔才会允许自己以这种方式使用。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57519, 'Formula: Eternal Dreamstone Shard', '', '', '', '公式：永恒梦境碎片', '', '', '', '', '', '', '', '', '', 'Teaches you how to create an Eternal Dreamstate Essence.', '', '', '', '教你如何制作永恒梦境精华。', '', '', '', '', '', '', '', '', '');
INSERT INTO `locales_spell` VALUES (57530, 'Add Recording to Collection', '', '', '', '', '', '', 'Collection', '', '', '', '', '', '', 'Adds a record to the player\'s record collection.', '', '', '', '', '', '', '', '', '', '', '', '', '');
